def get_logo_bytes():
    """يرجع بيانات الشعار (PNG) كـ bytes، أو None لو حصل خطأ"""
    try:
        import base64
        return base64.b64decode(COMPANY_LOGO_B64)
    except Exception:
        return None

def get_logo_pdf_image(height=1.15 * 28.3464567):
    """يرجع عنصر Image من reportlab جاهز للإضافة في أي تقرير PDF، بالحفاظ على أبعاد الشعار الأصلية.
    height بالنقاط (points)؛ الافتراضي هنا يساوي تقريبًا 1.15 سم."""
    try:
        import io
        from reportlab.platypus import Image
        from reportlab.lib.utils import ImageReader
        data = get_logo_bytes()
        if not data:
            return None
        reader = ImageReader(io.BytesIO(data))
        iw, ih = reader.getSize()
        width = height * (iw / float(ih))
        img = Image(io.BytesIO(data), width=width, height=height)
        img.hAlign = 'CENTER'
        return img
    except Exception:
        return None

def add_logo_to_pdf(elements_list, height=1.15 * 28.3464567, spacer_after=6):
    """يضيف شعار الفندق في أول قائمة عناصر تقرير PDF (elements/elems)، مع مسافة صغيرة تحته.
    لا يفعل شيئًا لو تعذّر تحميل الشعار (بدون التسبب في أي خطأ بالتقرير)."""
    try:
        from reportlab.platypus import Spacer
        logo = get_logo_pdf_image(height=height)
        if logo:
            elements_list.append(logo)
            if spacer_after:
                elements_list.append(Spacer(1, spacer_after))
    except Exception:
        pass

def get_logo_tk_photo(size=54):
    """يرجع صورة PhotoImage (Tkinter) للشعار بمقاس مربع تقريبي size×size، أو None لو حصل خطأ"""
    try:
        import io
        from PIL import Image as PILImage, ImageTk
        data = get_logo_bytes()
        if not data:
            return None
        pil_img = PILImage.open(io.BytesIO(data)).convert("RGBA")
        pil_img.thumbnail((size, size), PILImage.LANCZOS)
        return ImageTk.PhotoImage(pil_img)
    except Exception:
        return None


# ── الترتيب الثابت للأقسام في التقارير (Monthly Report Excel/PDF) ─────────────
#    Departments appear in this exact order in the monthly report exports.
#    أي قسم غير موجود في هذه القائمة يظهر في النهاية بترتيبه الأصلي.
DEPARTMENT_ORDER = [
    "Front Office",
    "Housekeeping",
    "Financial",
    "Service",
    "Kitchen",
    "Maintenance",
    "Laundry",
    "Steward",
    "Security",
    "Human Resources",
    "Spa",
    "Recreation",
    "Reservation and Marketing",
    "Concierge and Trips",
    "Farm Workers",
    "Upholstery workshop",
    "Carpentrey Workshop",
    "Maintinance Farm",
    "GM Farm",
    "Gardener Farm",
]
# فهرس مرتبة كل قسم (بعد التطبيع: حروف صغيرة + إزالة المسافات الزائدة)
_DEPT_ORDER_INDEX = {
    name.strip().lower(): i for i, name in enumerate(DEPARTMENT_ORDER)
}

# ── توزيع الإجازة السنوية على رصيد Day Off ────────────────────────────────────
#   لكل (ANNUAL_LEAVE_DAYS_PER_DAYOFF) يوم من الإجازة السنوية يُخصم يوم واحد من
#   رصيد Day Off، والباقي من الرصيد السنوي.
#   القيمة 7 تعني: أسبوع كامل ⇒ 1 Day Off  (شهر ≈ 30 يوم ⇒ 30 // 7 = 4 Day Off).
#   غيّر هذا الرقم فقط لو أردت قاعدة مختلفة.
ANNUAL_LEAVE_DAYS_PER_DAYOFF = 7


def _dept_rank(name):
    """ترتيب القسم حسب القائمة الثابتة. غير الموجود يُوضع في النهاية."""
    key = (str(name).strip().lower() if name is not None else "")
    return _DEPT_ORDER_INDEX.get(key, len(DEPARTMENT_ORDER))


def order_dept_group(dg):
    """
    يعيد ترتيب OrderedDict مجمّع حسب القسم ليطابق DEPARTMENT_ORDER.
    الأقسام المعروفة تظهر بالترتيب المحدد، وأي قسم غير معروف يظهر بعدها
    محافظًا على ترتيب ظهوره الأصلي (ترتيب مستقر).
    """
    from collections import OrderedDict
    items = list(dg.items())
    items.sort(key=lambda kv: _dept_rank(kv[0]))  # sort مستقر يحافظ على ترتيب المتساوين
    return OrderedDict(items)

