# قاموس عكسي: عربي ⇒ إنجليزي (للتبديل من العربية إلى الإنجليزية)
AR2EN = {v: k for k, v in EN2AR.items() if v not in {vv for vv in EN2AR.values() if list(EN2AR.values()).count(vv) > 1}}
# أعِد بناء العكسي بأمان (آخر مفتاح يفوز للقيم المكررة)
AR2EN = {}
for _k, _v in EN2AR.items():
    AR2EN.setdefault(_v, _k)


def _split_affixes(text):
    """يفصل البادئة (إيموجي/رموز/مسافات) واللاحقة (نقطتان/مسافات) عن النص الأساسي."""
    pre = _re_i18n.match(r'^[^\w\u0600-\u06FF]*', text).group(0)
    rest = text[len(pre):]
    suf_m = _re_i18n.search(r'[\s:：\-–—]*$', rest)
    suf = suf_m.group(0) if suf_m else ""
    core = rest[:len(rest) - len(suf)] if suf else rest
    return pre, core, suf


def _translate_text(text):
    """يترجم نص الواجهة إلى اللغة الحالية. يُعيد النص كما هو إن لم توجد ترجمة."""
    if not isinstance(text, str) or not text.strip():
        return text
    lang = _APP_LANG.get("lang", "en")

    # 1) الجمل ثنائية اللغة الكاملة
    if text in EXACT:
        ar_v, en_v = EXACT[text]
        return ar_v if lang == "ar" else en_v

    pre, core, suf = _split_affixes(text)
    if not core:
        return text
    table = EN2AR if lang == "ar" else AR2EN
    tr = table.get(core) or table.get(core.strip())
    if tr is None:
        return text
    return pre + tr + suf


# ══════════ تركيب طبقة الترجمة على عناصر tkinter (مرة واحدة) ═════════
_I18N_INSTALLED = {"done": False}


def install_auto_translation():
    """يعترض إنشاء/تحديث عناصر tkinter لترجمة نص الواجهة تلقائيًا."""
    if _I18N_INSTALLED["done"]:
        return
    _I18N_INSTALLED["done"] = True

    import tkinter as _tk
    from tkinter import ttk as _ttk
    from tkinter import messagebox as _mb

    def _patch_text_kwarg(kwargs):
        if "text" in kwargs and isinstance(kwargs["text"], str):
            try:
                kwargs["text"] = _translate_text(kwargs["text"])
            except Exception:
                pass
        return kwargs

    # عناصر العرض التي تحمل خاصية text
    for _cls in (_tk.Label, _tk.Button, _tk.Checkbutton, _tk.Radiobutton,
                 _tk.LabelFrame, _ttk.Label, _ttk.Button, _ttk.Checkbutton,
                 _ttk.Radiobutton, _ttk.LabelFrame):
        _orig_init = _cls.__init__

        def _make_init(orig):
            def _new_init(self, *a, **kw):
                _patch_text_kwarg(kw)
                return orig(self, *a, **kw)
            return _new_init
        _cls.__init__ = _make_init(_orig_init)

        _orig_cfg = _cls.configure

        def _make_cfg(orig):
            def _new_cfg(self, cnf=None, **kw):
                if cnf and isinstance(cnf, dict):
                    cnf = dict(cnf)
                    _patch_text_kwarg(cnf)
                _patch_text_kwarg(kw)
                return orig(self, cnf, **kw) if cnf is not None else orig(self, **kw)
            return _new_cfg
        try:
            _cls.configure = _make_cfg(_orig_cfg)
            _cls.config = _cls.configure
        except Exception:
            pass

    # تبويبات Notebook
    _orig_add = _ttk.Notebook.add

    def _nb_add(self, child, **kw):
        _patch_text_kwarg(kw)
        return _orig_add(self, child, **kw)
    _ttk.Notebook.add = _nb_add

    _orig_tab = _ttk.Notebook.tab

    def _nb_tab(self, tab_id, option=None, **kw):
        _patch_text_kwarg(kw)
        if option is not None:
            return _orig_tab(self, tab_id, option, **kw)
        return _orig_tab(self, tab_id, **kw)
    _ttk.Notebook.tab = _nb_tab

    # عناوين أعمدة Treeview
    _orig_head = _ttk.Treeview.heading

    def _tv_heading(self, column, option=None, **kw):
        _patch_text_kwarg(kw)
        if option is not None:
            return _orig_head(self, column, option, **kw)
        return _orig_head(self, column, **kw)
    _ttk.Treeview.heading = _tv_heading

    # ترجمة قيم البيانات داخل صفوف الجداول (الأقسام/الحالات/الأنواع فقط)
    _orig_insert = _ttk.Treeview.insert

    def _tv_insert(self, parent, index, iid=None, **kw):
        try:
            if "values" in kw and kw["values"] is not None:
                kw["values"] = [_translate_data(v) for v in kw["values"]]
            if "text" in kw and isinstance(kw["text"], str):
                kw["text"] = _translate_data(kw["text"])
        except Exception:
            pass
        if iid is not None:
            return _orig_insert(self, parent, index, iid=iid, **kw)
        return _orig_insert(self, parent, index, **kw)
    _ttk.Treeview.insert = _tv_insert

    # عنوان النافذة
    _orig_title = _tk.Tk.title

    def _tk_title(self, string=None):
        if string is not None and isinstance(string, str):
            string = _translate_text(string)
        return _orig_title(self, string) if string is not None else _orig_title(self)
    _tk.Tk.title = _tk_title

    # عناوين نوافذ الحوار (Toplevel)
    _orig_top_title = _tk.Toplevel.title

    def _top_title(self, string=None):
        if string is not None and isinstance(string, str):
            string = _translate_text(string)
        return _orig_top_title(self, string) if string is not None else _orig_top_title(self)
    _tk.Toplevel.title = _top_title

    # عناصر القوائم (قوائم النقر بالزر الأيمن: قص/نسخ/لصق/تحديد الكل …)
    def _patch_label_kwarg(kwargs):
        if "label" in kwargs and isinstance(kwargs["label"], str):
            try:
                kwargs["label"] = _translate_text(kwargs["label"])
            except Exception:
                pass
        return kwargs

    for _mname in ("add_command", "add_cascade", "add_checkbutton", "add_radiobutton"):
        _orig_m = getattr(_tk.Menu, _mname, None)
        if _orig_m is None:
            continue

        def _make_menu(orig):
            def _new_menu(self, cnf={}, **kw):
                _patch_label_kwarg(kw)
                return orig(self, cnf, **kw)
            return _new_menu
        setattr(_tk.Menu, _mname, _make_menu(_orig_m))

    # صناديق الرسائل (عنوان + رسالة)
    def _wrap_mb(fn):
        def _w(title=None, message=None, **kw):
            try:
                if isinstance(title, str):
                    title = _translate_text(title)
                if isinstance(message, str):
                    message = _translate_text(message)
            except Exception:
                pass
            return fn(title, message, **kw)
        return _w
    for _name in ("showinfo", "showwarning", "showerror", "askyesno",
                  "askokcancel", "askquestion", "askyesnocancel", "askretrycancel"):
        if hasattr(_mb, _name):
            setattr(_mb, _name, _wrap_mb(getattr(_mb, _name)))


def set_app_language(lang):
    """تحديد لغة التطبيق الحالية ('ar' أو 'en')."""
    _APP_LANG["lang"] = "ar" if str(lang).lower().startswith("ar") else "en"
