# ── Hide any console window (Windows / frozen EXE / pythonw) ─────────────────
if sys.platform == 'win32':
    try:
        import ctypes
        ctypes.windll.user32.ShowWindow(ctypes.windll.kernel32.GetConsoleWindow(), 0)
    except Exception:
        pass
    devnull_w = open(os.devnull, 'w')
    sys.stdout = devnull_w
    sys.stderr = devnull_w
    sys.stdin  = open(os.devnull, 'r')
    try:
        ctypes.windll.kernel32.FreeConsole()
    except Exception:
        pass

# ── When PyInstaller onefile extracts files to _MEIPASS, both the main script
#    and --add-data files end up in that temp directory.
#    Add _MEIPASS (or the EXE folder in onedir/source mode) to sys.path so
#    that import machinery can find any sibling modules. ─────────────────────
_extra_path = getattr(sys, '_MEIPASS', None) \
    or os.path.dirname(os.path.abspath(sys.executable))
if _extra_path and os.path.isdir(_extra_path) and _extra_path not in sys.path:
    sys.path.insert(0, _extra_path)

_ICON_FILE = "hr_icon.ico"
if getattr(sys, 'frozen', False):
    _icon_path = getattr(sys, '_MEIPASS', os.path.dirname(sys.executable))
else:
    _icon_path = os.path.dirname(os.path.abspath(__file__))
_icon_valid = os.path.isfile(os.path.join(_icon_path, _ICON_FILE))
_icon_path = os.path.join(_icon_path, _ICON_FILE) if _icon_valid else None


def is_valid_image_path(path):
    if not path:
        return False
    try:
        if not os.path.isfile(path):
            return False
        from PIL import Image
        with Image.open(path) as img:
            img.verify()
        return True
    except Exception:
        return False


def safe_employee_photo_path(path):
    return path if is_valid_image_path(path) else ""


def get_pythonw_executable():
    exe = getattr(sys, "_base_executable", sys.executable)
    if os.path.basename(exe).lower().endswith("python.exe"):
        return os.path.join(os.path.dirname(exe), "pythonw.exe")
    return exe


def format_date_display(date_str):
    """تحويل Date من أي صيغة إلى d/m/Y للعرض"""
    if not date_str:
        return ""
    # إذا كان datetime object
    if hasattr(date_str, 'strftime'):
        return date_str.strftime("%d/%m/%Y")
    s = str(date_str).strip()
    if not s or s.lower() in ("none", "nan", "-", ""):
        return ""
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
        try:
            return datetime.strptime(s, fmt).strftime("%d/%m/%Y")
        except:
            pass
    return s


def parse_date_any(date_str):
    """تحويل التاريخ من أي صيغة معروفة إلى كائن date (أو None عند الفشل)"""
    if not date_str:
        return None
    if isinstance(date_str, datetime):
        return date_str.date()
    if isinstance(date_str, date):
        return date_str
    s = str(date_str).strip()
    if not s or s.lower() in ("none", "nan", "-", ""):
        return None
    for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y", "%Y/%m/%d",
                "%m/%d/%Y", "%d/%m/%y", "%Y-%m-%d %H:%M:%S"):
        try:
            return datetime.strptime(s, fmt).date()
        except:
            pass
    return None


def parse_date_input(date_str):
    """تحويل Date من أي صيغة إلى Y-m-d للتخزين"""
    if not date_str:
        return ""
    d = parse_date_any(date_str)
    if d:
        return d.strftime("%Y-%m-%d")
    return date_str


