#  الدورة الشهرية للرواتب  ──  الشهر يبدأ يوم 25 وينتهي يوم 24 من الشهر التالي
#  ───────────────────────────────────────────────────────────────────────────
#  أي معاملة (إجازة / سلفة / جزاء / خصم / استقالة …) يقع تاريخها في يوم 25 أو
#  بعده تُحسب على الشهر التالي. مثال: جزاء يوم 26 يناير يُحسب على شهر فبراير،
#  وجزاء يوم 24 يناير يُحسب على شهر يناير.
#  لتغيير يوم القطع لاحقاً يكفي تعديل القيمة الواحدة PAYROLL_CYCLE_END_DAY.
# ════════════════════════════════════════════════════════════════════════════
PAYROLL_CYCLE_END_DAY = 24   # آخر يوم في الدورة الشهرية (اليوم التالي = بداية شهر جديد)


def payroll_period_of(d):
    """ترجع (الشهر, السنة) للدورة المالية التي يقع فيها التاريخ d.
    أي يوم > PAYROLL_CYCLE_END_DAY يُرحَّل إلى الشهر التالي."""
    d = parse_date_any(d)
    if not d:
        return (None, None)
    m, y = d.month, d.year
    if d.day > PAYROLL_CYCLE_END_DAY:
        m += 1
        if m > 12:
            m = 1
            y += 1
    return (m, y)


def payroll_period_bounds(month, year):
    """ترجع (تاريخ_البداية, تاريخ_النهاية) للدورة المالية للشهر/السنة المحددة.
    البداية = يوم 25 من الشهر السابق، النهاية = يوم 24 من الشهر الحالي."""
    month = int(month)
    year = int(year)
    end = date(year, month, PAYROLL_CYCLE_END_DAY)
    pm, py = month - 1, year
    if pm < 1:
        pm = 12
        py -= 1
    start = date(py, pm, PAYROLL_CYCLE_END_DAY + 1)
    return (start, end)


def date_in_payroll_period(d, month, year):
    """هل يقع التاريخ d داخل الدورة المالية للشهر/السنة المحددة؟
    (يكافئ التحقق من أن payroll_period_of(d) == (month, year))."""
    if not month or not year:
        return True
    d = parse_date_any(d)
    if not d:
        return False
    try:
        start, end = payroll_period_bounds(month, year)
    except Exception:
        return False
    return start <= d <= end


def leave_overlaps_payroll_period(start_date, end_date, month, year):
    """هل تتقاطع فترة الإجازة (start..end) مع الدورة المالية للشهر/السنة؟"""
    if not month or not year:
        return True
    s = parse_date_any(start_date)
    e = parse_date_any(end_date)
    if not s or not e:
        return False
    if e < s:
        s, e = e, s
    try:
        p_start, p_end = payroll_period_bounds(month, year)
    except Exception:
        return False
    return s <= p_end and e >= p_start


def leave_days_in_payroll_period(start_date, end_date, month, year):
    """عدد أيام الإجازة الواقعة داخل الدورة المالية للشهر/السنة (لحساب الخصومات)."""
    s = parse_date_any(start_date)
    e = parse_date_any(end_date)
    if not s or not e:
        return 0
    if e < s:
        s, e = e, s
    if not month or not year:
        return (e - s).days + 1
    try:
        p_start, p_end = payroll_period_bounds(month, year)
    except Exception:
        return 0
    ov_start = max(s, p_start)
    ov_end = min(e, p_end)
    if ov_start > ov_end:
        return 0
    return (ov_end - ov_start).days + 1


def format_number(value):
    """تنسيق الأرقام لعرض رقمين عشريين"""
    try:
        return f"{float(value):.2f}"
    except:
        return str(value)


def ask_save_path(default_filename, title="حفظ الملف / Save File", parent=None):
    """نافذة حفظ موحّدة لكل تصدير: يختار المستخدم مكان واسم الملف يدويًا.
    ترجع المسار المختار، أو None إذا ألغى المستخدم.
    نوع الملف وامتداده يُستنتجان تلقائيًا من امتداد default_filename."""
    ext = os.path.splitext(default_filename)[1].lstrip(".").lower()
    ftypes_map = {
        "xlsx": [("Excel Files", "*.xlsx")],
        "xls":  [("Excel Files", "*.xls;*.xlsx")],
        "pdf":  [("PDF Files", "*.pdf")],
        "csv":  [("CSV Files", "*.csv")],
        "json": [("JSON Files", "*.json")],
        "txt":  [("Text Files", "*.txt")],
    }
    filetypes = ftypes_map.get(ext, [("All Files", "*.*")])
    if ("All Files", "*.*") not in filetypes:
        filetypes = filetypes + [("All Files", "*.*")]
    default_ext = ("." + ext) if ext else ""
    try:
        path = filedialog.asksaveasfilename(
            parent=parent,
            title=title,
            defaultextension=default_ext,
            filetypes=filetypes,
            initialfile=default_filename,
        )
    except Exception:
        path = filedialog.asksaveasfilename(
            title=title,
            defaultextension=default_ext,
            filetypes=filetypes,
            initialfile=default_filename,
        )
    return path or None


def get_month_year_filter_gui(parent):
    """Dialog to select month and year for filtering reports - like employee status"""


    dialog = tk.Toplevel(parent)
    dialog.title("Filter by Month and Year")
    dialog.geometry("440x250")
    dialog.resizable(False, False)
    dialog.configure(bg='white')
    dialog.transient(parent)
    dialog.grab_set()

    center_x = dialog.winfo_screenwidth() // 2 - 220
    center_y = dialog.winfo_screenheight() // 2 - 125
    dialog.geometry(f"+{center_x}+{center_y}")

    month_map = {
        "January": 1, "February": 2, "March": 3, "April": 4, "May": 5, "June": 6,
        "July": 7, "August": 8, "September": 9, "October": 10, "November": 11, "December": 12
    }

    current_year = date.today().year

    filter_frame = tk.Frame(dialog, bg='white')
    filter_frame.pack(fill=tk.BOTH, expand=True, padx=20, pady=20)

    tk.Label(filter_frame, text="Filter Reports", font=('Segoe UI', 14, 'bold'), bg='white').pack(pady=15)

    combo_frame = tk.Frame(filter_frame, bg='white')
    combo_frame.pack()

    tk.Label(combo_frame, text="Month:", font=('Segoe UI', 11), bg='white').pack(side=tk.LEFT, padx=5)

    months = ["All", "January", "February", "March", "April", "May", "June",
              "July", "August", "September", "October", "November", "December"]

    month_var = tk.StringVar(value="All")
    month_combo = ttk.Combobox(combo_frame, textvariable=month_var, values=months,
                               font=('Segoe UI', 10), width=12, state='readonly')
    month_combo.set("All")
    month_combo.pack(side=tk.LEFT, padx=5)

    tk.Label(combo_frame, text="Year:", font=('Segoe UI', 11), bg='white').pack(side=tk.LEFT, padx=(15, 5))

    years = [str(y) for y in range(current_year - 5, current_year + 2)]
    year_var = tk.StringVar(value=str(current_year))
    year_combo = ttk.Combobox(combo_frame, textvariable=year_var, values=years,
                              font=('Segoe UI', 10), width=8, state='readonly')
    year_combo.pack(side=tk.LEFT, padx=5)

    btn_frame = tk.Frame(filter_frame, bg='white')
    btn_frame.pack(side=tk.BOTTOM, pady=(10, 18))

    result = {'month': None, 'year': None}

    def on_apply():
        selected_month = month_var.get()
        selected_year = year_var.get()
        if selected_month == "All":
            result['month'] = "All"
        else:
            result['month'] = month_map.get(selected_month, 1)
        result['year'] = selected_year
        dialog.destroy()

    tk.Button(btn_frame, text="🔍  Apply", font=('Segoe UI', 11, 'bold'),
              bg='#6366F1', fg='white', relief=tk.FLAT, bd=0, cursor='hand2',
              padx=26, pady=8, command=on_apply).pack(side=tk.LEFT, padx=12)
    tk.Button(btn_frame, text="Cancel", font=('Segoe UI', 11), bg='#64748B', fg='white',
              relief=tk.FLAT, bd=0, cursor='hand2',
              padx=26, pady=8, command=dialog.destroy).pack(side=tk.LEFT, padx=12)

    dialog.wait_window()

    return result['month'], result['year']


try:
    from tkcalendar import DateEntry as _TkDateEntry
    CALENDAR_AVAILABLE = True
except ImportError:
    CALENDAR_AVAILABLE = False


class LiteDateEntry(tk.Frame):
    """Lightweight drop-in replacement for tkcalendar.DateEntry.

    tkcalendar's DateEntry builds a FULL calendar widget inside its
    constructor. A form like 'Add Employee' creates ~10 date fields, so the
    page was slow to open because 10 calendars were built up front.

    LiteDateEntry shows a normal text entry plus a small button, and builds
    the calendar popup ONLY when the button is clicked. Creating many of these
    is effectively instant. It is bound entirely through ``textvariable`` and
    exposes get()/set()/get_date()/set_date() for API compatibility.
    """
    def __init__(self, master, textvariable=None, font=('Segoe UI', 10),
                 width=15, date_pattern='dd/mm/yyyy', background=None,
                 foreground=None, state='normal', **kwargs):
        try:
            _bg = kwargs.pop('bg', None) or master.cget('bg')
        except Exception:
            _bg = 'white'
        super().__init__(master, bg=_bg)
        self._pattern = date_pattern or 'dd/mm/yyyy'
        self._fmt = (self._pattern.replace('dd', '%d')
                                   .replace('mm', '%m')
                                   .replace('yyyy', '%Y'))
        self._var = textvariable if textvariable is not None else tk.StringVar()
        # Match previous behaviour: empty field shows today's date.
        if not str(self._var.get()).strip():
            try:
                self._var.set(datetime.now().strftime(self._fmt))
            except Exception:
                pass
        self._entry = tk.Entry(self, textvariable=self._var, font=font,
                               width=width, relief='solid', bd=1)
        self._entry.pack(side=tk.LEFT, fill=tk.Y)
        if state == 'readonly':
            self._entry.config(state='readonly')
        self._btn = tk.Button(self, text='📅', font=('Segoe UI', 9), width=2,
                              bg='#E5E7EB', fg='#111827', relief='flat',
                              cursor='hand2', command=self._open_calendar)
        self._btn.pack(side=tk.LEFT, fill=tk.Y)

    def _open_calendar(self):
        # Build the (heavy) calendar lazily — only when actually requested.
        try:
            from tkcalendar import Calendar
        except Exception:
            return  # tkcalendar missing → entry still works as a text field

        # Close any popup that may already be open for this widget
        old = getattr(self, "_popup", None)
        if old is not None:
            try: old.destroy()
            except Exception: pass
            self._popup = None

        top = tk.Toplevel(self)
        self._popup = top
        try: top.wm_overrideredirect(True)   # borderless, clean look
        except Exception: pass
        try: top.attributes("-topmost", True)
        except Exception: pass
        try:
            top.geometry(f"+{self.winfo_rootx()}+{self.winfo_rooty() + self.winfo_height()}")
        except Exception:
            pass

        # thin blue border around the popup
        border = tk.Frame(top, bg="#2563EB")
        border.pack()
        inner = tk.Frame(border, bg="white")
        inner.pack(padx=1, pady=1)

        cal_kwargs = dict(date_pattern=self._pattern, showweeknumbers=False)
        try:
            d = datetime.strptime(str(self._var.get()).strip(), self._fmt)
            cal_kwargs.update(year=d.year, month=d.month, day=d.day)
        except Exception:
            pass
        try:
            cal = Calendar(inner, **cal_kwargs)
        except Exception:
            cal = Calendar(inner, date_pattern=self._pattern)
        cal.pack(padx=6, pady=6)

        def _close(_=None):
            try: top.grab_release()
            except Exception: pass
            try: top.destroy()
            except Exception: pass
            self._popup = None

        def _pick(_=None):
            try:
                self._var.set(cal.selection_get().strftime(self._fmt))
            except Exception:
                try: self._var.set(cal.get_date())
                except Exception: pass
            _close()

        btns = tk.Frame(inner, bg="white")
        btns.pack(fill="x", padx=6, pady=(0, 6))
        tk.Button(btns, text="OK", command=_pick, bg='#2563EB', fg='white',
                  relief='flat', padx=18, pady=3, cursor='hand2').pack(side="right")
        tk.Button(btns, text="Cancel", command=_close, bg='#E5E7EB', fg='#111827',
                  relief='flat', padx=12, pady=3, cursor='hand2').pack(side="right", padx=(0, 6))

        cal.bind("<<CalendarSelected>>", lambda e: None)
        cal.bind("<Double-Button-1>", _pick)   # double-click a day to confirm
        top.bind("<Escape>", _close)

        # Make it modal so the calendar reliably receives clicks and stays open
        top.update_idletasks()
        try: top.grab_set()
        except Exception: pass
        try: top.focus_force()
        except Exception: pass

    # ── API compatibility ────────────────────────────────────────────────
    def get(self):
        return self._var.get()

    def set(self, value):
        self._var.set(value)

    def get_date(self):
        try:
            return datetime.strptime(str(self._var.get()).strip(), self._fmt).date()
        except Exception:
            return None

    def set_date(self, d):
        try:
            self._var.set(d.strftime(self._fmt))
        except Exception:
            self._var.set(str(d))

    def configure(self, **kw):
        if 'state' in kw:
            try: self._entry.config(state=kw.pop('state'))
            except Exception: kw.pop('state', None)
        if kw:
            try: super().configure(**kw)
            except Exception: pass
    config = configure


# Use the lightweight, lazy date picker everywhere. This is what removes the
# slow page-load: date forms no longer build a calendar per field on open.
if CALENDAR_AVAILABLE:
    DateEntry = LiteDateEntry

