# ==================== PDF & Excel Report Generator ====================

def generate_pdf_report(title, headers, data, file_path, orientation='landscape', paper='A4'):
    """Generate a professionally formatted PDF report with header and footer"""
    if not PDF_AVAILABLE:
        return False, "PDF library not installed. Run: pip install reportlab"

    try:
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, A3, letter, legal, landscape, portrait
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak
        from reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_RIGHT
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont

        paper_sizes = {'A4': A4, 'A3': A3, 'Letter': letter, 'Legal': legal}
        page_size = paper_sizes.get(paper, A4)
        page_orientation = landscape if orientation == 'landscape' else portrait

        doc = SimpleDocTemplate(file_path, pagesize=page_orientation(page_size),
                               rightMargin=40, leftMargin=40,
                               topMargin=50, bottomMargin=50)

        elements = []
        add_logo_to_pdf(elements)
        styles = getSampleStyleSheet()

        header_style = ParagraphStyle(
            'HeaderTitle',
            fontSize=20,
            textColor=colors.HexColor('#1E3A5F'),
            spaceBefore=0,
            spaceAfter=6,
            leading=24,
            alignment=TA_CENTER,
            fontName='Helvetica-Bold'
        )

        subtitle_style = ParagraphStyle(
            'Subtitle',
            fontSize=13,
            textColor=colors.HexColor('#64748B'),
            spaceBefore=0,
            spaceAfter=4,
            leading=16,
            alignment=TA_CENTER
        )

        company_style = ParagraphStyle(
            'CompanyName',
            fontSize=9,
            textColor=colors.HexColor('#94A3B8'),
            spaceBefore=0,
            spaceAfter=8,
            leading=12,
            alignment=TA_CENTER
        )

        elements.append(Paragraph("MODO HR", header_style))
        elements.append(Paragraph(title, subtitle_style))
        elements.append(Paragraph("Human Resources Management", company_style))

        meta_style = ParagraphStyle(
            'MetaInfo',
            fontSize=9,
            textColor=colors.gray,
            spaceAfter=15,
            alignment=TA_RIGHT
        )
        elements.append(Paragraph(f"Generated: {datetime.now().strftime('%d/%m/%Y %H:%M')}", meta_style))

        if data:
            col_count = len(headers)
            available_width = doc.pagesize[0] - 80

            # Prepend headers as first row of table data
            full_data = [list(headers)] + list(data)
            data = full_data

            # Smart column widths: give more space to text columns, less to number columns
            def calc_col_widths(headers, data, total_width):
                import re
                num_pattern = re.compile(r'^\s*-?\d+(\.\d+)?%?\s*$')
                weights = []
                for ci in range(len(headers)):
                    max_len = len(str(headers[ci]) if headers[ci] is not None else '')
                    for row in data:
                        if ci < len(row):
                            cell_str = str(row[ci]) if row[ci] is not None else ''
                            if len(cell_str) > max_len:
                                max_len = len(cell_str)
                    # Determine if column is mostly numeric (small) or text (large)
                    is_num = True
                    for row in data:
                        if ci < len(row):
                            cell_str = str(row[ci]) if row[ci] is not None else ''
                            if not (bool(num_pattern.match(cell_str)) or cell_str.strip() in ('', '0', '-')):
                                is_num = False
                                break
                    # Index column (#) gets minimum width
                    if ci == 0:
                        weights.append(0.5)
                    elif is_num:
                        weights.append(max(1.0, min(max_len * 0.18, 2.0)))
                    else:
                        weights.append(max(2.5, min(max_len * 0.22, 6.0)))
                total_weight = sum(weights) or 1
                return [total_width * w / total_weight for w in weights]

            col_widths = calc_col_widths(headers, data, available_width)

            # Build table rows - use Paragraph only for long text cells (headers always)
            from reportlab.platypus import Paragraph
            from reportlab.lib.styles import ParagraphStyle
            from reportlab.lib.enums import TA_CENTER
            header_cell_style = ParagraphStyle(
                'HeaderCellStyle', fontSize=8, leading=10,
                alignment=TA_CENTER, wordWrap='LTR',
                textColor=colors.white, fontName='Helvetica-Bold'
            )
            cell_style = ParagraphStyle(
                'CellStyle', fontSize=9, leading=11,
                alignment=TA_CENTER, wordWrap='LTR'
            )
            def _wrap(cell, style, col_w=999):
                text = str(cell) if cell is not None else ' '
                if not text.strip():
                    text = ' '
                # Always return Paragraph to avoid NoneType comparison errors in platypus
                return Paragraph(text, style)

            wrapped_data = []
            for ri, row in enumerate(data):
                wrapped_row = []
                for ci, cell in enumerate(row):
                    cw = col_widths[ci] if ci < len(col_widths) else 999
                    style = header_cell_style if ri == 0 else cell_style
                    wrapped_row.append(_wrap(cell, style, col_w=cw))
                wrapped_data.append(wrapped_row)
            data = wrapped_data

            # Create table with data
            table = Table(data, colWidths=col_widths, repeatRows=1)

            header_bg = colors.HexColor('#1E3A5F')
            table_style = TableStyle([
                ('BACKGROUND', (0, 0), (-1, 0), header_bg),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('ALIGN', (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, 0), 8),
                ('BOTTOMPADDING', (0, 0), (-1, 0), 6),
                ('TOPPADDING', (0, 0), (-1, 0), 6),
                ('BACKGROUND', (0, 1), (-1, -1), colors.white),
                ('TEXTCOLOR', (0, 1), (-1, -1), colors.HexColor('#1E293B')),
                ('FONTNAME', (0, 1), (-1, -1), 'Helvetica'),
                ('FONTSIZE', (0, 1), (-1, -1), 9),
                ('BOTTOMPADDING', (0, 1), (-1, -1), 8),
                ('TOPPADDING', (0, 1), (-1, -1), 8),
                ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#E2E8F0')),
                ('LINEABOVE', (0, 0), (-1, 0), 2, colors.HexColor('#1E3A5F')),
                ('LINEBELOW', (0, 0), (-1, 0), 2, colors.HexColor('#1E3A5F')),
            ])
            # Alternating row colors (explicit loop - avoids NoneType error with Paragraph cells)
            for row_idx in range(1, len(data)):
                bg = colors.white if row_idx % 2 == 1 else colors.HexColor('#F8FAFC')
                table_style.add('BACKGROUND', (0, row_idx), (-1, row_idx), bg)
            table.setStyle(table_style)
            elements.append(table)

            elements.append(Spacer(1, 25))

            summary_style = ParagraphStyle(
                'SummaryStyle',
                fontSize=10,
                textColor=colors.HexColor('#64748B'),
                alignment=TA_LEFT
            )
            elements.append(Paragraph(f"Total Records: {len(data)-2}", summary_style))

        elements.append(Spacer(1, 30))

        footer_style = ParagraphStyle(
            'FooterStyle',
            fontSize=8,
            textColor=colors.gray,
            alignment=TA_CENTER
        )
        elements.append(Paragraph("MODO HR - Generated automatically", footer_style))

        doc.build(elements)
        return True, f"Report saved to:\n{file_path}"

    except Exception as e:
        import traceback
        return False, f"Error generating PDF: {str(e)}\n\n{traceback.format_exc()}"


def generate_excel_report(title, headers, data, file_path):
    """Generate a professionally formatted Excel report with header and footer"""
    if not EXCEL_AVAILABLE:
        return False, "Excel library not installed. Run: pip install openpyxl"

    try:
        from openpyxl import Workbook
        from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
        from openpyxl.utils import get_column_letter

        wb = Workbook()
        ws = wb.active
        ws.title = "Report"

        header_font = Font(bold=True, color='FFFFFF', size=14)
        header_fill = PatternFill(start_color='1E3A5F', end_color='1E3A5F', fill_type='solid')
        header_alignment = Alignment(horizontal='center', vertical='center')

        title_font = Font(bold=True, size=22, color='1E3A5F')
        title_alignment = Alignment(horizontal='center', vertical='center')

        subtitle_font = Font(size=12, color='64748B')

        cell_alignment = Alignment(horizontal='center', vertical='center')
        border = Border(
            left=Side(style='thin', color='E2E8F0'),
            right=Side(style='thin', color='E2E8F0'),
            top=Side(style='thin', color='E2E8F0'),
            bottom=Side(style='thin', color='E2E8F0')
        )

        ws.merge_cells('A1:N1')
        ws['A1'].value = title
        ws['A1'].font = title_font
        ws['A1'].alignment = title_alignment
        ws.row_dimensions[1].height = 35

        ws.merge_cells('A2:N2')
        ws['A2'].value = "MODO HR - Human Resources"
        ws['A2'].font = subtitle_font
        ws['A2'].alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[2].height = 25

        ws.merge_cells('A3:N3')
        ws['A3'].value = f"Generated: {datetime.now().strftime('%d/%m/%Y %H:%M')}"
        ws['A3'].font = Font(size=10, color='94A3B8')
        ws['A3'].alignment = Alignment(horizontal='center', vertical='center')
        ws.row_dimensions[3].height = 20

        ws.append([])

        for col, header in enumerate(headers, 1):
            cell = ws.cell(row=5, column=col)
            cell.value = header
            cell.font = header_font
            cell.fill = header_fill
            cell.alignment = header_alignment
            cell.border = border

        for row_idx, row_data in enumerate(data, 6):
            for col_idx, value in enumerate(row_data, 1):
                cell = ws.cell(row=row_idx, column=col_idx)
                cell.value = value
                cell.alignment = cell_alignment
                cell.border = border

                if row_idx % 2 == 0:
                    cell.fill = PatternFill(start_color='F8FAFC', end_color='F8FAFC', fill_type='solid')

        ws.append([])

        summary_row = ws.max_row + 1
        ws.merge_cells(f'A{summary_row}:H{summary_row}')
        ws[f'A{summary_row}'].value = f"Total Records: {len(data)-2}"
        ws[f'A{summary_row}'].font = Font(size=10, color='64748B', italic=True)
        ws[f'A{summary_row}'].alignment = Alignment(horizontal='center')

        for col in range(1, len(headers) + 1):
            ws.column_dimensions[get_column_letter(col)].width = 18

        ws.page_setup.orientation = 'landscape'
        ws.page_setup.fitToPage = True
        ws.page_setup.fitToWidth = 1
        ws.page_setup.fitToHeight = 0

        wb.save(file_path)
        return True, f"Report saved to:\n{file_path}"

    except Exception as e:
        return False, f"Error generating Excel: {str(e)}"

# ==================== Arabic Name Transliteration ====================
#
# Converts an English (Latin-script) employee name into an Arabic
# equivalent. Two layers, strongest first:
#   1) ARABIC_NAME_MAP  – a large curated dictionary of real Egyptian /
#      Arab first, family and Coptic-Christian names (covers the vast
#      majority of real-world HR records).
#   2) _phonetic_transliterate_word – a rule-based phonetic engine used
#      only when a word isn't found in the dictionary, so the Arabic
#      Name field is never left empty.

# Common Egyptian/Arab first, family and Coptic-Christian names
# (English -> Arabic). Multi-word keys (e.g. "abdel rahman") are matched
# greedily before single-word keys.
