def _normalize_word(w):
    """Lowercase + strip punctuation + collapse doubled consonants, so
    phonetic English spellings ('Mostafaa', 'Hassann') map more cleanly
    onto single Arabic letters."""
    w = w.lower().strip(".,'-")
    out = []
    prev = ""
    for ch in w:
        if ch == prev and ch.isalpha() and ch not in "aeiou":
            continue  # collapse doubled consonants: 'ss' -> 's'
        out.append(ch)
        prev = ch
    return "".join(out)


def _phonetic_transliterate_word(word):
    """Rule-based phonetic English->Arabic transliteration, used only as a
    fallback when a word isn't found in ARABIC_NAME_MAP. Handles common
    digraphs/trigraphs, El/Al/Abu prefixes, doubled-consonant collapsing,
    and silent trailing 'e', so the Arabic Name field is never left empty
    even for names outside the dictionary."""
    if not word:
        return ""

    w = _normalize_word(word)
    if not w:
        return ""

    prefix = ""
    if w.startswith("abu") and len(w) > 3:
        prefix = "أبو"
        w = w[3:]
    elif w.startswith(("el", "al")) and len(w) > 2:
        prefix = "ال"
        w = w[2:]

    # Silent trailing 'e' after a consonant (e.g. 'George' -> 'georg')
    if len(w) > 2 and w.endswith("e") and w[-2] not in "aeiou":
        w = w[:-1]

    trigraphs = [
        ("tch", "تش"), ("igh", "اي"),
    ]
    digraphs = [
        ("kh", "خ"), ("gh", "غ"), ("sh", "ش"), ("th", "ث"), ("dh", "ذ"),
        ("ch", "تش"), ("ph", "ف"), ("ck", "ك"), ("qu", "ق"),
        ("ee", "ي"), ("oo", "و"), ("ou", "و"), ("oa", "و"),
        ("ei", "ي"), ("ie", "ي"), ("ai", "اي"), ("ay", "اي"), ("ey", "اي"),
        ("aa", "ا"), ("aw", "او"), ("ny", "ني"),
    ]
    singles = {
        'a': 'ا', 'b': 'ب', 'c': 'ك', 'd': 'د', 'e': 'ي', 'f': 'ف',
        'g': 'ج', 'h': 'ه', 'i': 'ي', 'j': 'ج', 'k': 'ك', 'l': 'ل',
        'm': 'م', 'n': 'ن', 'o': 'و', 'p': 'ب', 'q': 'ق', 'r': 'ر',
        's': 'س', 't': 'ت', 'u': 'و', 'v': 'ف', 'w': 'و', 'x': 'كس',
        'y': 'ي', 'z': 'ز',
    }

    result = []
    idx = 0
    n = len(w)
    while idx < n:
        matched = False
        for pattern, ar in trigraphs:
            if w[idx:idx + len(pattern)] == pattern:
                result.append(ar)
                idx += len(pattern)
                matched = True
                break
        if not matched:
            for pattern, ar in digraphs:
                if w[idx:idx + len(pattern)] == pattern:
                    result.append(ar)
                    idx += len(pattern)
                    matched = True
                    break
        if not matched:
            ch = w[idx]
            if ch.isalpha():
                result.append(singles.get(ch, ""))
            elif ch != " ":
                result.append(ch)
            idx += 1

    arabic = prefix + "".join(result)
    # Feminine-name heuristic: a bare trailing alef from '...a' commonly
    # renders as ta-marbuta in Arabic spelling (e.g. 'Amira' -> ...ة)
    if w.endswith("a") and not w.endswith(("ia", "ya")) and arabic.endswith("ا") and len(arabic) > 1:
        arabic = arabic[:-1] + "ة"
    return arabic


def transliterate_name_to_arabic(full_name):
    """Convert an English (Latin-script) employee name to an Arabic
    equivalent. Tries 3-word then 2-word compounds (e.g. 'Abd El Rahman')
    against ARABIC_NAME_MAP first, then single words, then falls back to
    phonetic transliteration for anything unmatched. If the name already
    contains Arabic characters, it's returned unchanged."""
    if not full_name:
        return ""
    full_name = full_name.strip()
    if not full_name:
        return ""

    # If it already contains Arabic characters, don't touch it
    if any('\u0600' <= ch <= '\u06FF' for ch in full_name):
        return full_name

    # Treat hyphens like spaces (e.g. "Abdel-Rahman")
    words = full_name.replace("-", " ").split()
    result_words = []
    i = 0
    while i < len(words):
        matched = False
        # Try a 3-word compound match (e.g. "Abd El Rahman")
        if i + 2 < len(words):
            three_word = f"{words[i]} {words[i+1]} {words[i+2]}".lower().strip(".,")
            if three_word in ARABIC_NAME_MAP:
                result_words.append(ARABIC_NAME_MAP[three_word])
                i += 3
                matched = True
        # Try a 2-word compound match (e.g. "Abdel Rahman")
        if not matched and i + 1 < len(words):
            two_word = f"{words[i]} {words[i + 1]}".lower().strip(".,")
            if two_word in ARABIC_NAME_MAP:
                result_words.append(ARABIC_NAME_MAP[two_word])
                i += 2
                matched = True
        if not matched:
            one_word = words[i].lower().strip(".,")
            if one_word in ARABIC_NAME_MAP:
                result_words.append(ARABIC_NAME_MAP[one_word])
            else:
                result_words.append(_phonetic_transliterate_word(words[i]))
            i += 1

    return " ".join(w for w in result_words if w)

def emp_display_name(emp, fallback="N/A"):
    """Return an employee's display name including the Arabic name (when
    available) in parentheses, e.g. 'Mohamed Ahmed (محمد أحمد)'.
    Used for read-only labels, lists, exports, and printed documents.
    `emp` may be an Employee object or None."""
    if not emp:
        return fallback
    name = getattr(emp, "name", "") or fallback
    ar = getattr(emp, "arabic_name", "") or ""
    if ar and ar.strip() and ar.strip() != (name or "").strip():
        return f"{name} ({ar})"
    return name

