class Attendance:
    """Attendance class"""
    def __init__(self, emp_id, date, check_in="", check_out="", status="Present", source=""):
        self.emp_id = emp_id
        self.date = date
        self.check_in = check_in
        self.check_out = check_out
        self.status = status
        self.source = source or ""   # "device" | "mobile" | "device+mobile" | "" (manual)

    def add_source(self, src):
        """يسجّل مصدر البصمة (جهاز/موبايل) دون فقدان المصدر الآخر"""
        cur = [x for x in (self.source or "").split("+") if x]
        if src and src not in cur:
            cur.append(src)
        self.source = "+".join(cur)

    def source_label(self):
        m = {"device": "📟 Device", "mobile": "📱 Mobile", "device+mobile": "📟📱 Both", "mobile+device": "📟📱 Both"}
        return m.get(self.source or "", "✍️ Manual")

    @staticmethod
    def _parse_time(t_str):
        """Parse time supporting HH:MM (24h) and legacy HH:MM AM/PM (12h) records.
        ملاحظة: النظام أصبح يخزّن الأوقات بصيغة 24 ساعة (HH:MM) حصريًا اعتبارًا
        من هذا الإصدار. صيغة AM/PM لا تزال مدعومة هنا فقط لقراءة السجلات
        القديمة المخزَّنة قبل التحديث، حتى لا تنكسر بياناتهم."""
        if not t_str:
            return None
        t_str = t_str.strip()
        for fmt in ("%H:%M", "%I:%M %p", "%I:%M%p"):
            try:
                return datetime.strptime(t_str.upper(), fmt)
            except ValueError:
                pass
        return None

    @staticmethod
    def to_24h(t_str):
        """توحيد أي صيغة وقت مخزّنة (24h أو AM/PM قديمة) إلى صيغة عرض 24 ساعة HH:MM."""
        if not t_str:
            return t_str
        t = Attendance._parse_time(t_str)
        if t:
            return t.strftime("%H:%M")
        return t_str

    # اسم قديم محفوظ للتوافق الخلفي فقط — يُرجع الآن صيغة 24 ساعة وليس AM/PM
    to_ampm = to_24h

    def date_key(self):
        """Return a real datetime for chronological sorting.
        Supports DD/MM/YYYY and a few other common formats.
        Unparseable dates sort to the end."""
        d = (self.date or "").strip()
        for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y", "%m/%d/%Y", "%d/%m/%y"):
            try:
                return datetime.strptime(d, fmt)
            except ValueError:
                pass
        return datetime.max

    def get_duration(self):
        """Calculate duration between check-in and check-out.
        Supports HH:MM (24h) and HH:MM AM/PM (12h).
        Handles midnight crossover: if check_out < check_in, adds 24h."""
        if not self.check_in or not self.check_out:
            return ""
        try:
            t_in  = self._parse_time(self.check_in)
            t_out = self._parse_time(self.check_out)
            if not t_in or not t_out:
                return ""
            # استخدم timedelta بدلاً من datetime لتفادي مشكلة اليوم
            in_minutes  = t_in.hour  * 60 + t_in.minute
            out_minutes = t_out.hour * 60 + t_out.minute
            diff_minutes = out_minutes - in_minutes
            # إذا كان الخروج قبل الدخول → عبور منتصف الليل
            if diff_minutes < 0:
                diff_minutes += 24 * 60
            # نتيجة غير منطقية (أكثر من 24 ساعة)
            if diff_minutes == 0 or diff_minutes > 24 * 60:
                return ""
            hours   = diff_minutes // 60
            minutes = diff_minutes % 60
            return f"{hours:02d}:{minutes:02d}"
        except Exception:
            return ""

    def get_duration_hours(self):
        """حساب Duration بالساعات (عشري) - يدعم AM/PM وعبور منتصف الليل"""
        if not self.check_in or not self.check_out:
            return 0.0
        try:
            t_in  = self._parse_time(self.check_in)
            t_out = self._parse_time(self.check_out)
            if not t_in or not t_out:
                return 0.0
            in_minutes  = t_in.hour  * 60 + t_in.minute
            out_minutes = t_out.hour * 60 + t_out.minute
            diff_minutes = out_minutes - in_minutes
            if diff_minutes < 0:
                diff_minutes += 24 * 60
            if diff_minutes == 0 or diff_minutes > 24 * 60:
                return 0.0
            return round(diff_minutes / 60, 2)
        except Exception:
            return 0.0

    def to_dict(self):
        return {
            "emp_id": self.emp_id,
            "date": self.date,
            "check_in": self.check_in,
            "check_out": self.check_out,
            "status": self.status,
            "source": getattr(self, "source", "") or ""
        }

    @classmethod
    def from_dict(cls, data):
        return cls(
            data.get("emp_id", ""),
            data.get("date", ""),
            data.get("check_in", ""),
            data.get("check_out", ""),
            data.get("status", "Present"),
            data.get("source", "")
        )


