class Evaluation:
    """فئة Evaluations - Employee Performance Evaluation Level 5"""

    # Job factors with their weights and max points
    JOB_FACTORS = [
        {"key": "attitude",          "label": "ATTITUDE",             "weight": 5, "max": 25},
        {"key": "job_knowledge",     "label": "JOB KNOWLEDGE",        "weight": 3, "max": 15},
        {"key": "quantity_of_work",  "label": "QUANTITY OF WORK",     "weight": 3, "max": 15},
        {"key": "quality_of_work",   "label": "QUALITY OF WORK",      "weight": 4, "max": 20},
        {"key": "team_work",         "label": "TEAM WORK",            "weight": 5, "max": 25},
        {"key": "attendance",        "label": "ATTENDANCE/PUNCTUALITY","weight": 4, "max": 20},
        {"key": "hospitality",       "label": "HOSPITALITY/COURTESY", "weight": 5, "max": 25},
        {"key": "appearance",        "label": "APPEARANCE/GROOMING",  "weight": 5, "max": 25},
        {"key": "initiative",        "label": "INITIATIVE",           "weight": 4, "max": 20},
        {"key": "communication",     "label": "COMMUNICATION",        "weight": 4, "max": 20},
    ]
    TOTAL_WEIGHT = 50
    TOTAL_MAX    = 210
    # Score columns: 1=Importance, 2=Poor, 3=Needs Improvement, 4=Satisfactory, 5=Very Good, 6=Excellent
    SCORE_LABELS = ["1\nIMPORTANCE", "2\nPOOR", "3\nNEEDS\nIMPROVEMENT", "4\nSATISFACTORY", "5\nVERY\nGOOD", "6\nEXCELLENT"]

    def __init__(self, eval_id, emp_id, grade, eval_date, comments="",
                 eval_type="standard", probation_period=False, after_6_months=False, after_1_year=True,
                 supervisor_notes="", scores=None):
        self.eval_id = eval_id
        self.emp_id = emp_id
        self.grade = grade
        self.eval_date = eval_date
        self.comments = comments
        # Level 5 form fields
        self.eval_type = eval_type          # "standard" or "level5"
        self.probation_period = probation_period
        self.after_6_months = after_6_months
        self.after_1_year = after_1_year
        self.supervisor_notes = supervisor_notes
        # scores: dict {factor_key: score_column (1-6)}
        self.scores = scores if scores else {}

    def get_achieved_points(self):
        """Calculate total achieved points based on scores"""
        total = 0
        for factor in self.JOB_FACTORS:
            key = factor["key"]
            score_col = self.scores.get(key, 0)
            if score_col and score_col > 0:
                # score 1=Poor .. 5=Excellent ; multiplier = score value
                total += factor["weight"] * score_col
        return total

    def get_percentage(self):
        achieved = self.get_achieved_points()
        return round((achieved / self.TOTAL_MAX) * 100, 1) if self.TOTAL_MAX > 0 else 0

    def to_dict(self):
        return {
            "eval_id": self.eval_id,
            "emp_id": self.emp_id,
            "grade": self.grade,
            "eval_date": self.eval_date,
            "comments": self.comments,
            "eval_type": self.eval_type,
            "probation_period": self.probation_period,
            "after_6_months": self.after_6_months,
            "after_1_year": self.after_1_year,
            "supervisor_notes": self.supervisor_notes,
            "scores": self.scores,
        }

    @classmethod
    def from_dict(cls, data):
        return cls(
            data.get("eval_id", ""),
            data.get("emp_id", ""),
            data.get("grade", ""),
            data.get("eval_date", ""),
            data.get("comments", ""),
            data.get("eval_type", "standard"),
            data.get("probation_period", False),
            data.get("after_6_months", False),
            data.get("after_1_year", True),
            data.get("supervisor_notes", ""),
            data.get("scores", {}),
        )


