class HRDatabase:
    """قاعدة بيانات نظام الموارد البشرية"""

    def __init__(self, data_file="hr_data.json"):
        # Always store data next to the script/executable, never in the temp _MEIPASS folder
        if getattr(sys, 'frozen', False):
            # Running as compiled exe: save next to the exe file
            base_path = os.path.dirname(sys.executable)
        else:
            # Running as plain .py script: save next to the .py file
            # Use sys.argv[0] as fallback if __file__ is not reliable
            try:
                script_path = os.path.abspath(__file__)
            except NameError:
                script_path = os.path.abspath(sys.argv[0])
            base_path = os.path.dirname(script_path)

        # Store base_path as class attribute so LoginScreen can use same path
        HRDatabase._base_path = base_path
        self.data_file = os.path.join(base_path, "hr_data.json")

        self.employees = {}
        self.departments = {}
        self.attendance = []
        self.leaves = []
        self.payrolls = []
        self.advances = []
        self.cl_staff = []
        self.penalties = []
        self.password = ""  # default password (legacy / global)
        self.user_passwords = {}     # {username: password}  كلمات مرور لكل مستخدم
        self.activity_log = []       # سجل النشاطات [{timestamp, user, category, action, details}]
        self.current_user = "system" # يُضبط من التطبيق بعد تسجيل الدخول
        self.evaluations = []
        self.contract_renewals = []
        self.change_of_status = []
        self.language = "en"  # Default language
        self.job_titles = []  # Custom job titles list

        self.zk_device_ip = ""
        self.zk_device_port = 4370
        self.zk_device_password = 0
        # Multi-device support: list of dicts {name, ip, port, password}
        self.zk_devices = []
        self.disabled_users = []  # List of disabled/stopped usernames
        self.user_permissions = {}  # {username: [allowed_nav_keys]} - absent = use role default
        self.monthly_snapshots = {}  # Archive: {"{month}-{year}": [rows]}
        self.archived_employees = {}  # أرشيف المستقيلين: {emp_id: {"employee": dict, "records": {...}, "archived_at": str}}
        self.insurance_settings = {"min": 2700, "max": 16700}  # Insurance limits
        self.settings = {}   # إعدادات عامة (آخر مزامنة تلقائية، فترة سحب الجهاز، ...)
        self._bulk_mode = False  # When True, save_data() is skipped during bulk imports
        self._init_mobile_punch()  # البصمة عبر الموبايل (Google Sheets)

        # ── ZKTeco silent connection keep-alive ───────────────────────────────
        # مراقب اتصال صامت بأجهزة البصمة: يعمل في الخلفية للتأكد من بقاء الاتصال
        # حيًا وإعادة الاتصال تلقائيًا عند الانقطاع دون أي تأثير على الواجهة.
        self._zk_lock = threading.Lock()      # يمنع تعارض المراقب مع المزامنة الفعلية
        self._zk_live_conns = {}              # {"ip:port": connection}  اتصالات حية يحتفظ بها المراقب
        self._zk_status = {}                  # {"ip:port": bool}  آخر حالة اتصال معروفة (للاستخدام الداخلي)

        # ── Shared Network Path (multi-user sync) ─────────────────────────────
        # Path to a shared folder that all users can read/write.
        # Stored in a small config file next to the script so it survives updates.
        self._sync_config_file = os.path.join(base_path, "hr_sync_config.json")
        self.shared_data_path = self._load_sync_config()
        self._last_shared_mtime = 0   # track file modification time for auto-refresh

        self.load_data()

    def load_data(self):
        """تحميل البيانات من الFile"""
        # ── Prefer shared network file if configured and accessible ──────────
        eff = self.get_effective_data_file()
        _eff_exists = (eff != self.data_file) and self._safe_fs_check(eff, 'exists', timeout=1.2, default=False)
        _read_file = eff if _eff_exists else self.data_file
        # Update mtime tracker so initial load doesn't trigger auto-refresh
        if _read_file == eff and eff != self.data_file:
            _mt = self._safe_fs_check(eff, 'mtime', timeout=1.2, default=None)
            if _mt is not None:
                self._last_shared_mtime = _mt
        backup_file = self.data_file + ".bak"
        log_path = os.path.join(os.environ.get("TEMP", os.path.dirname(self.data_file)), "hr_load_error.log")

        if os.path.exists(_read_file):
            try:
                with open(_read_file, 'r', encoding='utf-8') as f:
                    raw = f.read().strip()
                    if not raw:
                        # Empty file — just fill in default departments, keep everything else empty
                        self.initialize_default_departments()
                        return
                    data = json.loads(raw)

                    # ── Employees ──────────────────────────────────────────────
                    emp_data = data.get("employees", {})
                    loaded_employees = {}
                    if isinstance(emp_data, list):
                        for emp in emp_data:
                            try:
                                e = Employee.from_dict(emp)
                                loaded_employees[e.emp_id] = e
                            except Exception as ex:
                                try:
                                    open(log_path, "a", encoding="utf-8").write("Employee load error: " + str(ex) + "\n")
                                except Exception: pass
                    else:
                        for k, v in emp_data.items():
                            try:
                                loaded_employees[k] = Employee.from_dict(v)
                            except Exception as ex:
                                try:
                                    open(log_path, "a", encoding="utf-8").write("Employee load error key=" + str(k) + ": " + str(ex) + "\n")
                                except Exception: pass
                    self.employees = loaded_employees
                    try:
                        for emp in self.employees.values():
                            if emp.employee_photo and not is_valid_image_path(emp.employee_photo):
                                emp.employee_photo = ""
                    except Exception:
                        pass

                    # ── Departments ────────────────────────────────────────────
                    dept_data = data.get("departments", {})
                    loaded_departments = {}
                    if isinstance(dept_data, list):
                        for dept in dept_data:
                            try:
                                d = Department.from_dict(dept)
                                loaded_departments[d.dept_id] = d
                            except Exception: pass
                    else:
                        for k, v in dept_data.items():
                            try:
                                loaded_departments[k] = Department.from_dict(v)
                            except Exception: pass
                    self.departments = loaded_departments
                    # Fill in any missing default departments (never overwrite existing ones)
                    self.initialize_default_departments()

                    # ── Other collections — load each record individually ──────
                    def _load_list(key, cls):
                        result = []
                        for item in data.get(key, []):
                            try:
                                result.append(cls.from_dict(item))
                            except Exception as ex:
                                try:
                                    open(log_path, "a", encoding="utf-8").write(str(key) + " item error: " + str(ex) + "\n")
                                except Exception: pass
                        return result

                    self.attendance       = _load_list("attendance",       Attendance)
                    self.leaves           = _load_list("leaves",           Leave)
                    self.payrolls         = _load_list("payrolls",         Payroll)
                    self.advances         = _load_list("advances",         Advance)
                    self.cl_staff         = _load_list("cl_staff",         CLStaff)
                    self.penalties        = _load_list("penalties",        Penalty)
                    self.evaluations      = _load_list("evaluations",      Evaluation)
                    self.contract_renewals = _load_list("contract_renewals", ContractRenewal)
                    self.change_of_status  = _load_list("change_of_status",  ChangeOfStatus)

                    self.password          = data.get("password", "admin123")
                    self.user_passwords    = data.get("user_passwords", {}) or {}
                    self.activity_log      = data.get("activity_log", []) or []
                    self.language          = data.get("language", "en")
                    self.job_titles        = data.get("job_titles", [])
                    self.disabled_users    = data.get("disabled_users", [])
                    self.user_permissions  = data.get("user_permissions", {}) or {}
                    self.monthly_snapshots = data.get("monthly_snapshots", {})
                    self.archived_employees = data.get("archived_employees", {}) or {}
                    self.insurance_settings = data.get("insurance_settings", {"min": 2700, "max": 16700})
                    self.settings = data.get("settings", {}) or {}
                    _mp = dict(HRDatabase.MOBILE_PUNCH_DEFAULTS); _mp.update(data.get("mobile_punch", {}) or {})
                    self.mobile_punch      = _mp
                    self.mobile_punch_pins = data.get("mobile_punch_pins", {}) or {}
                    self.mobile_punch_log  = data.get("mobile_punch_log", []) or []
                    self.mobile_leave_map  = data.get("mobile_leave_map", {}) or {}

                    # Multi-device ZK support: load list; migrate legacy single-device config
                    self.zk_devices = data.get("zk_devices", [])
                    if not self.zk_devices:
                        # Migrate old single-device config if present
                        old_ip = data.get("zk_device_ip", "")
                        if old_ip:
                            self.zk_devices = [{
                                "name": "Device 1",
                                "ip": old_ip,
                                "port": data.get("zk_device_port", 4370),
                                "password": data.get("zk_device_password", 0)
                            }]
                    # Keep legacy single-device fields in sync with first device for compatibility
                    if self.zk_devices:
                        self.zk_device_ip       = self.zk_devices[0]["ip"]
                        self.zk_device_port     = self.zk_devices[0]["port"]
                        self.zk_device_password = self.zk_devices[0]["password"]

                    # Auto-heal attendance records corrupted by the old restore bug
                    try:
                        self.repair_attendance_data()
                    except Exception:
                        pass

                    # Keep a backup of last successful load
                    try:
                        import shutil
                        shutil.copy2(self.data_file, backup_file)
                    except Exception:
                        pass

            except Exception as e:
                # Log the error for diagnosis
                try:
                    with open(log_path, "w", encoding="utf-8") as lg:
                        import traceback
                        lg.write("load_data FAILED: " + str(e) + "\n" + traceback.format_exc() + "\n")
                        lg.write("Data file: " + self.data_file + "\n")
                except Exception:
                    pass

                # Try the backup file before giving up
                if os.path.exists(backup_file):
                    try:
                        import shutil
                        shutil.copy2(backup_file, self.data_file)
                        self.load_data()   # retry with backup
                        return
                    except Exception:
                        pass
                # Last resort: add default departments only, do NOT save (avoid wiping data file)
                self.initialize_default_departments()
        else:
            # No data file at all — fresh install
            self.initialize_sample_data()

    def initialize_sample_data(self):
        """Fresh install — start with empty data, no default departments"""
        self.save_data()

    def initialize_default_departments(self):
        """No default departments — user adds their own departments manually"""
        pass  # Do not auto-create any departments

    # ── Shared-path sync helpers ───────────────────────────────────────────

    def _safe_fs_check(self, path, kind='exists', timeout=1.2, default=False):
        """Run a filesystem check (exists/isdir/mtime) on a background thread
        with a hard timeout, so an unreachable network/shared path can never
        freeze the UI (this used to hang the whole app on startup and every
        30 seconds during the auto-sync check when the shared folder wasn't
        reachable). Results are cached briefly to avoid spawning a new
        thread on every call."""
        now = time.time()
        cache = getattr(self, '_fs_check_cache', None)
        if cache is None:
            cache = self._fs_check_cache = {}
        key = (path, kind)
        cached = cache.get(key)
        if cached is not None and (now - cached[1]) < 5:
            return cached[0]

        result_holder = {}
        def _worker():
            try:
                if kind == 'exists':
                    result_holder['v'] = os.path.exists(path)
                elif kind == 'isdir':
                    result_holder['v'] = os.path.isdir(path)
                elif kind == 'mtime':
                    result_holder['v'] = os.path.getmtime(path)
            except Exception:
                result_holder['v'] = default

        t = threading.Thread(target=_worker, daemon=True)
        t.start()
        t.join(timeout)
        if t.is_alive():
            # Still stuck (e.g. dead network share) — don't wait any longer.
            # Cache a short "unavailable" result so we retry again soon
            # instead of blocking on every subsequent call.
            cache[key] = (default, now)
            return default
        val = result_holder.get('v', default)
        cache[key] = (val, now)
        return val

    def _load_sync_config(self):
        """Load shared data path from hr_sync_config.json (returns '' if absent)."""
        try:
            if os.path.exists(self._sync_config_file):
                with open(self._sync_config_file, 'r', encoding='utf-8') as f:
                    cfg = json.load(f)
                    return cfg.get("shared_data_path", "")
        except Exception:
            pass
        return ""

    def save_sync_config(self, path):
        """Persist the shared data path to hr_sync_config.json."""
        self.shared_data_path = path
        try:
            with open(self._sync_config_file, 'w', encoding='utf-8') as f:
                json.dump({"shared_data_path": path}, f, ensure_ascii=False)
        except Exception:
            pass

    def get_effective_data_file(self):
        """Return the shared path if configured & accessible, else the local path."""
        sp = (self.shared_data_path or "").strip()
        if sp:
            # The shared path may be a folder or a full file path.
            # Use the timeout-protected check so a disconnected network
            # drive falls back to the local file instantly instead of
            # freezing the app while Windows waits on the network.
            if self._safe_fs_check(sp, 'isdir', timeout=1.2, default=False):
                return os.path.join(sp, "hr_data.json")
            return sp
        return self.data_file

    def check_shared_changed(self):
        """Return True if the shared file has been modified since last check."""
        eff = self.get_effective_data_file()
        if eff == self.data_file:
            return False  # no shared path configured
        mtime = self._safe_fs_check(eff, 'mtime', timeout=1.2, default=None)
        if mtime is not None and mtime != self._last_shared_mtime:
            self._last_shared_mtime = mtime
            return True
        return False

    def reload_from_shared(self):
        """Reload all data from the shared file without changing data_file path."""
        eff = self.get_effective_data_file()
        if eff == self.data_file:
            self.load_data()
            return
        old = self.data_file
        self.data_file = eff
        try:
            self.load_data()
        finally:
            self.data_file = old

    def repair_attendance_data(self):
        """Self-heal attendance records that were corrupted by an old restore bug
        which shifted columns by one (the employee Name column was not skipped).

        Corruption signature for a single record:
            date      -> held the employee NAME (not a date)
            check_in  -> held the real DATE
            check_out -> held the real check-in time
            status    -> held the real check-out time

        This method un-shifts such records back to their correct fields, then
        de-duplicates records that share the same (emp_id, date)."""
        def _is_date(s):
            s = (s or "").strip()
            for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y", "%m/%d/%Y"):
                try:
                    datetime.strptime(s, fmt)
                    return True
                except ValueError:
                    pass
            return False

        def _clean_time(v):
            v = (v or "").strip()
            # keep only values that parse as a time; otherwise blank them
            if v and Attendance._parse_time(v) is None:
                return ""
            return v

        repaired = 0
        for att in self.attendance:
            # Signature: date is NOT a real date, but check_in IS a real date
            if not _is_date(att.date) and _is_date(att.check_in):
                real_date      = att.check_in
                real_check_in  = att.check_out   # had been the real check-in
                real_check_out = att.status      # had been the real check-out
                att.date      = real_date
                att.check_in  = _clean_time(real_check_in)
                att.check_out = _clean_time(real_check_out)
                att.status    = "Present"        # original status was lost on restore
                repaired += 1

        # ── De-duplicate by (emp_id, date), merging check-in/out ─────────────
        merged = {}
        order = []
        for att in self.attendance:
            key = (att.emp_id, att.date)
            if key not in merged:
                merged[key] = att
                order.append(key)
            else:
                base = merged[key]
                if not base.check_in and att.check_in:
                    base.check_in = att.check_in
                if not base.check_out and att.check_out:
                    base.check_out = att.check_out
                # ترجيح الحالة: الحضور الفعلي (Present) أو وجود بصمة يَغلب أي حالة أخرى
                base_has_punch = bool(base.check_in) or bool(base.check_out)
                if base_has_punch:
                    base.status = "Present"
                elif base.status in ("", "Present") and att.status not in ("", "Present"):
                    base.status = att.status
        deduped = [merged[k] for k in order]

        if repaired or len(deduped) != len(self.attendance):
            self.attendance = deduped

        # ── إصلاح حالة Day Off الخاطئة لمن لديه بصمة فعلية ─────────────────
        # سجل مخزَّن كـ Day Off/Absent لكنه يملك دخولًا أو انصرافًا ⇒ الموظف حضر
        # فعلًا، فنحوّله إلى Present ونُعيد اليوم المخصوم مسبقًا من رصيد Day Off.
        status_fixed = self._normalize_worked_dayoffs()

        if repaired or status_fixed or len(deduped) != len(self.attendance):
            try:
                self.save_data()
            except Exception:
                pass
        return repaired

    def _normalize_worked_dayoffs(self):
        """لكل سجل حضور حالته Day Off (أو Absent) لكنه يملك دخولًا أو انصرافًا:
            (١) يحوّل الحالة إلى Present (الحضور الفعلي يَغلب الحالة المخزّنة).
            (٢) إن كانت الحالة Day Off يُعيد يومًا واحدًا إلى رصيد Day Off
                (لأن الخصم كان سابقًا لأوانه).
        idempotent: بعد التحويل تصبح الحالة Present فلا يتكرر الإصلاح أو الاسترجاع.
        يُرجع عدد السجلات التي تم تصحيحها."""
        fixed = 0
        for att in self.attendance:
            has_punch = bool((att.check_in or "").strip()) or bool((att.check_out or "").strip())
            if has_punch and att.status in ("Day Off", "Absent"):
                if att.status == "Day Off":
                    emp_obj = self.employees.get(att.emp_id)
                    if emp_obj is not None:
                        cur = float(emp_obj.dof_override) if emp_obj.dof_override is not None else 52.0
                        emp_obj.dof_override = round(cur + 1, 1)
                att.status = "Present"
                fixed += 1
        return fixed

    def _approved_leave_type_on(self, emp_id, date_str):
        """يُرجع نوع الإجازة المعتمدة (Approved) التي تغطّي هذا التاريخ لهذا الموظف،
        أو None إن لم توجد. يدعم صيغ التاريخ DD/MM/YYYY و YYYY-MM-DD."""
        target = None
        for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y"):
            try:
                target = datetime.strptime((date_str or "").strip(), fmt).date()
                break
            except (ValueError, TypeError):
                continue
        if target is None:
            return None
        for lv in self.leaves:
            if str(lv.emp_id) != str(emp_id):
                continue
            if str(lv.status).strip().lower() != "approved":
                continue
            s = e = None
            for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%d-%m-%Y"):
                try:
                    s = datetime.strptime((lv.start_date or "").strip(), fmt).date()
                    e = datetime.strptime((lv.end_date   or "").strip(), fmt).date()
                    break
                except (ValueError, TypeError):
                    continue
            if s and e and s <= target <= e:
                return lv.leave_type
        return None

    def get_attendance_display_status(self, att):
        """يحسب الحالة المعروضة في تقرير الحضور:
            • وجود دخول أو انصراف ⇒ Present (حتى لو كانت الحالة المخزّنة Day Off).
            • لا توجد بصمة + توجد إجازة معتمدة تغطّي اليوم ⇒ نوع الإجازة.
            • غير ذلك ⇒ الحالة المخزّنة كما هي."""
        if (att.check_in or "").strip() or (att.check_out or "").strip():
            return "Present"
        leave_type = self._approved_leave_type_on(att.emp_id, att.date)
        if leave_type:
            return LEAVE_TYPE_DISPLAY.get(leave_type, leave_type)
        return att.status

    # ═════════════════════════════════════════════════════════════════════════
    # ── أرشيف الاستقالات: المستقيل يُنقل من الموظفين إلى الأرشيف (قابل للإرجاع)
    # ═════════════════════════════════════════════════════════════════════════
    _ARCHIVE_COLLECTIONS = ("attendance", "leaves", "payrolls", "advances", "penalties",
                            "evaluations", "contract_renewals", "change_of_status")

    def migrate_resigned_to_archive(self):
        """ترحيل تلقائي (مرة واحدة) لأي موظف مسجّل له تاريخ استقالة إلى الأرشيف"""
        moved = 0
        for eid in list(self.employees.keys()):
            e = self.employees[eid]
            if self._mp_is_resigned(e):
                self.archive_employee(eid, e.resignation_date, getattr(e, "resignation_reason", ""), save=False, user="migration")
                moved += 1
        if moved:
            self.save_data()
        return moved

    def archive_employee(self, emp_id, resignation_date, reason="", save=True, user="system"):
        """نقل الموظف وكل سجلاته إلى الأرشيف وحذفه من البيانات الحية"""
        emp = self.employees.get(emp_id)
        if emp is None:
            return False, "Employee not found"
        emp.resignation_date = resignation_date or date.today().strftime("%d/%m/%Y")
        emp.resignation_reason = reason or ""
        leave_summary = "N/A"
        try:
            rd = datetime.strptime(emp.resignation_date, "%d/%m/%Y").date()
            balance, _st = self.calculate_leave_balance(emp_id, rd)
            used = self.calculate_used_leaves(emp_id, "Annual")
            remaining = balance - used
            leave_summary = "%.1f (%s EGP)" % (remaining, "{:,.2f}".format(remaining * (float(emp.salary or 0) / 30)))
        except Exception:
            pass
        records = {}
        for coll in self._ARCHIVE_COLLECTIONS:
            items = getattr(self, coll, None)
            if not isinstance(items, list):
                continue
            mine = [r for r in items if getattr(r, "emp_id", None) == emp_id]
            if mine:
                records[coll] = [r.to_dict() for r in mine]
                setattr(self, coll, [r for r in items if getattr(r, "emp_id", None) != emp_id])
        if not hasattr(self, "archived_employees") or self.archived_employees is None:
            self.archived_employees = {}
        self.archived_employees[emp_id] = {
            "employee": emp.to_dict(),
            "records": records,
            "leave_summary": leave_summary,
            "archived_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        }
        # الأرقام السرية للموبايل
        try:
            (getattr(self, "mobile_punch_pins", {}) or {}).pop(str(emp_id), None)
        except Exception:
            pass
        del self.employees[emp_id]
        try:
            self.log_activity("Employee resigned → archived", "%s (%s) on %s" % (emp.name, emp_id, emp.resignation_date),
                              category="employees", user=user)
        except Exception:
            pass
        if save:
            self.save_data()
        return True, "Archived"

    def restore_employee(self, emp_id, user="system"):
        """إرجاع الموظف من الأرشيف إلى الموظفين النشطين مع كل سجلاته"""
        entry = (getattr(self, "archived_employees", {}) or {}).get(emp_id)
        if not entry:
            return False, "Not in archive"
        if emp_id in self.employees:
            return False, "An active employee already has this ID"
        emp = Employee.from_dict(entry.get("employee", {}))
        emp.resignation_date = ""
        emp.resignation_reason = ""
        self.employees[emp_id] = emp
        classes = {"attendance": Attendance, "leaves": Leave, "payrolls": Payroll, "advances": Advance,
                   "penalties": Penalty, "evaluations": Evaluation, "contract_renewals": ContractRenewal,
                   "change_of_status": ChangeOfStatus}
        for coll, rows in (entry.get("records") or {}).items():
            cls = classes.get(coll)
            if cls is None:
                continue
            lst = getattr(self, coll, None)
            if isinstance(lst, list):
                for d in rows:
                    try:
                        lst.append(cls.from_dict(d))
                    except Exception:
                        pass
        del self.archived_employees[emp_id]
        try:
            self.log_activity("Employee restored from archive", "%s (%s)" % (emp.name, emp_id), category="employees", user=user)
        except Exception:
            pass
        self.save_data()
        return True, "Restored"

    def archived_employee_obj(self, emp_id):
        """كائن Employee مؤقت من الأرشيف (للعرض/التعديل)"""
        entry = (getattr(self, "archived_employees", {}) or {}).get(emp_id)
        return Employee.from_dict(entry["employee"]) if entry else None

    def resigned_in_month(self, year, month):
        out = []
        for eid, entry in (getattr(self, "archived_employees", {}) or {}).items():
            rd = str((entry.get("employee") or {}).get("resignation_date", ""))
            try:
                d = datetime.strptime(rd, "%d/%m/%Y").date()
                if d.year == year and d.month == month:
                    out.append(eid)
            except ValueError:
                pass
        return out

    def save_data(self):
        """حفظ البيانات في الFile"""
        if self._bulk_mode:
            return  # Skip disk write during bulk operations; call save_data() manually when done
        data = {
            "employees": {k: v.to_dict() for k, v in self.employees.items()},
            "departments": {k: v.to_dict() for k, v in self.departments.items()},
            "attendance": [a.to_dict() for a in self.attendance],
            "leaves": [l.to_dict() for l in self.leaves],
            "payrolls": [p.to_dict() for p in self.payrolls],
            "advances": [a.to_dict() for a in self.advances],
            "cl_staff": [c.to_dict() for c in self.cl_staff],
            "penalties": [p.to_dict() for p in self.penalties],
            "password": self.password,
            "user_passwords": getattr(self, "user_passwords", {}),
            "activity_log": getattr(self, "activity_log", []),
            "evaluations": [e.to_dict() for e in self.evaluations],
            "contract_renewals": [c.to_dict() for c in self.contract_renewals],
            "change_of_status": [c.to_dict() for c in self.change_of_status],
            "language": self.language,
            "job_titles": getattr(self, "job_titles", []),
            "disabled_users": getattr(self, "disabled_users", []),
            "user_permissions": getattr(self, "user_permissions", {}),
            "monthly_snapshots": getattr(self, "monthly_snapshots", {}),
            "archived_employees": getattr(self, "archived_employees", {}),
            "zk_devices": getattr(self, "zk_devices", []),
            "mobile_punch": getattr(self, "mobile_punch", {}),
            "mobile_punch_pins": getattr(self, "mobile_punch_pins", {}),
            "mobile_punch_log": getattr(self, "mobile_punch_log", []),
            "mobile_leave_map": getattr(self, "mobile_leave_map", {}),
            "insurance_settings": getattr(self, "insurance_settings", {"min": 2700, "max": 16700}),
            "settings": getattr(self, "settings", {}) or {}
        }

        # Atomic write: write to temp file then rename to prevent data corruption
        tmp_file = self.data_file + ".tmp"
        try:
            with open(tmp_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
                f.flush()
                os.fsync(f.fileno())
            import shutil
            shutil.move(tmp_file, self.data_file)
        except Exception:
            # Fallback: direct write
            try:
                os.remove(tmp_file)
            except Exception:
                pass
            with open(self.data_file, 'w', encoding='utf-8') as f:
                json.dump(data, f, ensure_ascii=False, separators=(",", ":"))

        # ── Also write to shared network path if configured ────────────────
        eff = self.get_effective_data_file()
        if eff != self.data_file:
            try:
                import shutil as _sh
                shared_dir = os.path.dirname(eff)
                if shared_dir and not os.path.isdir(shared_dir):
                    os.makedirs(shared_dir, exist_ok=True)
                tmp_shared = eff + ".tmp"
                with open(tmp_shared, 'w', encoding='utf-8') as f:
                    json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
                    f.flush()
                    try:
                        os.fsync(f.fileno())
                    except Exception:
                        pass
                _sh.move(tmp_shared, eff)
                # Update our tracked mtime so auto-refresh won't fire on our own save
                try:
                    self._last_shared_mtime = os.path.getmtime(eff)
                except Exception:
                    pass
            except Exception:
                pass  # Shared write errors must never block local save

    # Employee operations
    def add_employee(self, employee):
        """Add new employee"""
        if employee.emp_id in self.employees:
            return False, "Employee ID already exists"
        self.employees[employee.emp_id] = employee
        self.log_activity("Add employee",
                          details=f"Employee #{employee.emp_id} - {getattr(employee, 'name', '')}",
                          category="employee")
        self.save_data()
        return True, "Employee added successfully"

    def add_employee_no_save(self, employee):
        """Add employee to memory only — caller must call save_data() when done"""
        if employee.emp_id in self.employees:
            return False, "Employee ID already exists"
        self.employees[employee.emp_id] = employee
        return True, "Employee added successfully"

    def update_employee(self, employee):
        """Update employee data"""
        if employee.emp_id not in self.employees:
            return False, "Employee not found"
        self.employees[employee.emp_id] = employee
        self.log_activity("Edit employee",
                          details=f"Employee #{employee.emp_id} - {getattr(employee, 'name', '')}",
                          category="employee")
        self.save_data()
        return True, "Employee updated successfully"

    def delete_employee(self, emp_id):
        """Delete employee"""
        if emp_id not in self.employees:
            return False, "Employee not found"
        _emp = self.employees.get(emp_id)
        _name = getattr(_emp, 'name', '') if _emp else ''
        del self.employees[emp_id]
        self.log_activity("Delete employee",
                          details=f"Employee #{emp_id} - {_name}",
                          category="employee")
        self.save_data()
        return True, "Employee deleted successfully"

    def get_employee(self, emp_id):
        """Get employee — tolerant of emp_id type / zero-padding mismatches.

        Records (CL Staff, Advances, Attendance, …) may store an employee code
        as "10" while the employee is keyed as "010" (or as an int) elsewhere.
        A naive dict.get() then returns None and the UI shows N/A.  We first try
        the exact key (fast path) and only fall back to normalised variants when
        that fails, so correct lookups are never altered.
        """
        if emp_id is None:
            return None
        # 1) Exact match (fast path — preserves original behaviour)
        emp = self.employees.get(emp_id)
        if emp is not None:
            return emp
        # 2) String-normalised match
        key = str(emp_id).strip()
        emp = self.employees.get(key)
        if emp is not None:
            return emp
        # 3) Zero-padding / stripping variants ("10" <-> "010" <-> "0010")
        digits = key.lstrip("0") or "0"
        for cand in (digits, key.zfill(2), key.zfill(3),
                     key.zfill(4), key.zfill(5)):
            emp = self.employees.get(cand)
            if emp is not None:
                return emp
        # 4) Last resort: numeric equality against every stored ID
        try:
            target = int(digits)
        except (ValueError, TypeError):
            return None
        for eid, e in self.employees.items():
            try:
                if int(str(eid).strip().lstrip("0") or "0") == target:
                    return e
            except (ValueError, AttributeError):
                continue
        return None

    def get_all_employees(self):
        """Get all employees"""
        return list(self.employees.values())

    def next_seq_id(self, prefix, records, id_attr, width=3):
        """Return the next sequential ID 'PREFIX###' for a record collection.

        Uses (highest existing numeric suffix + 1) instead of len()+1, so IDs
        never collide after a record has been deleted.  It reads the live
        `records` iterable, so it is also correct when called repeatedly inside
        a loop that appends each new record before the next call.

        Different prefixes that share a leading letter stay independent because
        a non-numeric tail (e.g. "RN0001" under prefix "R" -> tail "N0001",
        or "PE001" under prefix "P" -> tail "E001") is ignored.
        """
        prefix = str(prefix)
        plen = len(prefix)
        up = prefix.upper()
        mx = 0
        for r in records:
            rid = str(getattr(r, id_attr, "")).strip().upper()
            if rid.startswith(up):
                tail = rid[plen:]
                if tail.isdigit():
                    n = int(tail)
                    if n > mx:
                        mx = n
        return f"{prefix}{mx + 1:0{width}d}"

    # Department operations
    def add_department(self, department):
        """Add new department"""
        if department.dept_id in self.departments:
            return False, "Department ID already exists"
        self.departments[department.dept_id] = department
        self.log_activity("Add department",
                          details=f"Department: {getattr(department, 'name', department.dept_id)}",
                          category="department")
        self.save_data()
        return True, "Department added successfully"

    def update_department(self, department):
        """Update department"""
        if department.dept_id not in self.departments:
            return False, "Department not found"
        self.departments[department.dept_id] = department
        self.log_activity("Edit department",
                          details=f"Department: {getattr(department, 'name', department.dept_id)}",
                          category="department")
        self.save_data()
        return True, "Department updated successfully"

    def renumber_departments(self):
        """يعيد ترقيم الأقسام تسلسليًا (D001, D002, ...) بدون فجوات، ويحدّث
        كل الموظفين المرتبطين بالقسم القديم إلى الرقم الجديد تلقائيًا."""
        def _num(d):
            rid = str(getattr(d, 'dept_id', '') or '')
            digits = ''.join(ch for ch in rid if ch.isdigit())
            try:
                return int(digits) if digits else 0
            except ValueError:
                return 0

        ordered = sorted(self.departments.values(), key=_num)
        mapping = {}
        new_departments = {}
        for i, dept in enumerate(ordered, start=1):
            old_id = dept.dept_id
            new_id = f"D{i:03d}"
            mapping[old_id] = new_id
            dept.dept_id = new_id
            new_departments[new_id] = dept
        self.departments = new_departments

        # تحديث الموظفين المرتبطين بالأقسام اللي تغيّر رقمها
        changed = {old: new for old, new in mapping.items() if old != new}
        if changed:
            for emp in self.employees.values():
                old_dept = getattr(emp, 'department', '')
                if old_dept in changed:
                    emp.department = changed[old_dept]
        return mapping

    def delete_department(self, dept_id):
        """Delete department"""
        if dept_id not in self.departments:
            return False, "Department not found"
        _d = self.departments.get(dept_id)
        _dn = getattr(_d, 'name', dept_id) if _d else dept_id
        del self.departments[dept_id]
        # تفريغ قسم الموظفين اللي كانوا تابعين للقسم المحذوف قبل إعادة الترقيم،
        # حتى لا يُعاد ربطهم بالخطأ بقسم آخر أخذ نفس الرقم بعد إعادة الترقيم
        for emp in self.employees.values():
            if getattr(emp, 'department', '') == dept_id:
                emp.department = ""
        self.renumber_departments()
        self.log_activity("Delete department",
                          details=f"Department: {_dn}",
                          category="department")
        self.save_data()
        return True, "Department deleted successfully"

