    def calculate_leave_balance(self, emp_id, calc_date=None):
        """
        حساب Leave Balance السنوية للموظف حسب قانون العمل المصرى
        وEmp Type (employee_type):
          - Regular  : أقل من 10 سنوات تأمينية وعمره تحت 50 سنة
                       15 عيد رسمي + 52 day off + 21 day سنوي = 88 day
          - 10years  : أكمل 10 سنوات تأمينية أو عمره 50 فأكثر
                       15 + 52 + 30 = 97 day
          - 50years  : نفس 10years
          - 5%       : ذوي الهمم  15 + 52 + 45 = 112 day
        قبل 6 months: رصيد سنوي = 0، يُحسب فقط day off (4 أو 5 أيام/شهر)
        """
        emp = self.get_employee(emp_id)
        if not emp:
            return 0, "Employee not found"

        if calc_date is None:
            calc_date = date.today()

        if isinstance(calc_date, str):
            try:
                calc_date = datetime.strptime(calc_date, "%d/%m/%Y").date()
            except:
                try:
                    calc_date = datetime.strptime(calc_date, "%Y-%m-%d").date()
                except:
                    calc_date = date.today()

        hire_date = emp.hire_date
        if isinstance(hire_date, str):
            try:
                hire_date = datetime.strptime(hire_date, "%d/%m/%Y").date()
            except:
                try:
                    hire_date = datetime.strptime(hire_date, "%Y-%m-%d").date()
                except:
                    hire_date = date.today()

        months_worked = (calc_date.year - hire_date.year) * 12 + (calc_date.month - hire_date.month)

        # تحديد Emp Type لتحديد رصيد الLeave السنوية
        emp_type = getattr(emp, 'employee_type', 'Regular') or 'Regular'
        if emp_type in ('10years', '50years'):
            annual_days = 30
            total_balance = 97   # 15 + 52 + 30
            type_label = "10 yrs insurance / 50+ age"
        elif emp_type == '5%':
            annual_days = 45
            total_balance = 112  # 15 + 52 + 45
            type_label = "Disability 5%"
        else:
            annual_days = 21
            total_balance = 88   # 15 + 52 + 21
            type_label = "Regular Employee"

        if months_worked < 6:
            # قبل 6 months: لا يوجد رصيد سنوي — فقط day off (4 أو 5 أيام/شهر)
            return 0, f"Probation (< 6 months) - No annual leave ({type_label})"

        if months_worked < 12:
            earned_months = months_worked - 5
            balance = (earned_months * annual_days) / 12
            return round(balance, 2), f"Prorated balance ({type_label}) - {earned_months} actual work months"

        return annual_days, f"Full annual balance ({type_label}) - {annual_days} day"

    def calculate_insurance_sick_leave_deduction(self, emp_id, days):
        """
        حساب خصم Insurance Sick Leave:
        يُخصم (أجر day / 4) × عدد الأيام from Basic Salary
        ويُرحَّل إلى deduction في Monthly Report
        """
        emp = self.get_employee(emp_id)
        if not emp:
            return 0
        daily_rate = emp.salary / 30 if emp.salary else 0
        return round((daily_rate / 4) * days, 2)

    def calculate_sick_leave_deduction(self, emp_id, days):
        """
        حساب خصم Sick Leave (Sick عادية):
        يُخصم ربع أجر dayي × عدد الأيام from Basic Salary
        """
        emp = self.get_employee(emp_id)
        if not emp:
            return 0
        daily_rate = emp.salary / 30 if emp.salary else 0
        return round((daily_rate / 4) * days, 2)

    def is_employee_insured(self, emp):
        """يحدد إن كان الموظف مؤمَّناً عليه اجتماعياً اعتماداً على tax_insurance_status.
        يُعتبر مؤمَّناً عليه إذا كانت الحالة 'both' أو 'insurance_only'."""
        if not emp:
            return False
        _raw = (getattr(emp, 'tax_insurance_status', 'both') or 'both').strip().lower()
        _map = {'both': 'both', 'tax only': 'tax_only', 'tax_only': 'tax_only',
                'insurance only': 'insurance_only', 'insurance_only': 'insurance_only',
                'neither': 'none', 'none': 'none'}
        return _map.get(_raw, 'both') in ('both', 'insurance_only')

    def compute_unpaid_deduction(self, emp, days):
        """النواة الموحَّدة لحساب خصم الإجازة غير المدفوعة (Unpaid Leave) لموظف.

        القاعدة (دمج الحصتين وفق القانون):
          إذا رغب الموظف في احتساب مدة الإجازة غير المدفوعة ضمن مدة اشتراكه
          التأميني، يتحمّل هو إجمالي النسبة المقررة (حصة الموظف + حصة صاحب
          العمل معاً)، بالإضافة إلى قيمة أجر أيام الإجازة نفسها:
          • أجر الأيام من الراتب الأساسي:            (Basic ÷ 30) × الأيام
          • + إجمالي حصتي التأمين (موظف + شركة = 29.75%): (Basic × 29.75% ÷ 30) × الأيام
          إذا لم يكن الموظف مؤمَّناً عليه → يُخصم أجر الأيام فقط (بدون تأمين).
        يُعاد المبلغ الكامل، ويُرحَّل بالكامل إلى عمود Deductions في التقرير الشهري."""
        try:
            sal = float(emp.salary) if emp and emp.salary else 0
            d = float(days) if days else 0
        except (TypeError, ValueError):
            return 0
        if not sal or not d:
            return 0
        day_value = (sal / 30) * d                                    # أجر الأيام من الراتب الأساسي
        ins_portion = (sal * 0.2975 / 30) * d if self.is_employee_insured(emp) else 0
        return round(day_value + ins_portion, 2)

    def calculate_unpaid_leave_deduction(self, emp_id, days):
        """حساب خصم Unpaid Leave لموظف عبر معرّفه — يستدعي النواة الموحَّدة."""
        emp = self.get_employee(emp_id)
        if not emp:
            return 0
        return self.compute_unpaid_deduction(emp, days)

    def calculate_absence_deduction(self, emp_id, days):
        """
        حساب خصم الabsence:
        يُخصم أجر day × عدد absence days from Salary
        """
        emp = self.get_employee(emp_id)
        if not emp:
            return 0
        daily_rate = emp.salary / 30 if emp.salary else 0
        return round(daily_rate * days, 2)

    def calculate_used_leaves(self, emp_id, leave_type="Annual"):
        """Calculate total approved leaves that consume balance.
        For Annual leave_type, also counts Day Off (both deduct from total balance)."""
        leaves = self.get_leaves_by_employee(emp_id)
        used = 0
        seen_ids = set()  # deduplicate by leave_id in case of duplicates in data
        # Both Annual and Day Off consume the total leave balance
        balance_consuming_types = {"Annual", "Day Off"}
        for leave in leaves:
            if leave.leave_id in seen_ids:
                continue
            seen_ids.add(leave.leave_id)
            # If querying Annual, count both Annual and Day Off
            match = (leave.leave_type == leave_type) or (
                leave_type == "Annual" and leave.leave_type in balance_consuming_types
            )
            if match and leave.status in ["Approved", "Confirmed"]:
                try:
                    try:
                        start = datetime.strptime(leave.start_date, "%d/%m/%Y").date()
                        end = datetime.strptime(leave.end_date, "%d/%m/%Y").date()
                    except:
                        start = datetime.strptime(leave.start_date, "%Y-%m-%d").date()
                        end = datetime.strptime(leave.end_date, "%Y-%m-%d").date()
                    used += (end - start).days + 1
                except:
                    pass
        return used

    def calculate_used_days_by_types(self, emp_id, leave_types):
        """عدد أيام الإجازات المعتمدة (Approved/Confirmed) لأنواع محددة فقط.
        leave_types: مجموعة/قائمة بأنواع الإجازات المطلوب حسابها (مثلاً {"Annual"})."""
        wanted = set(leave_types)
        leaves = self.get_leaves_by_employee(emp_id)
        used = 0
        seen_ids = set()
        for leave in leaves:
            if leave.leave_id in seen_ids:
                continue
            seen_ids.add(leave.leave_id)
            if (leave.leave_type in wanted
                    and leave.status in ["Approved", "Confirmed", "confirmed"]):
                try:
                    try:
                        start = datetime.strptime(leave.start_date, "%d/%m/%Y").date()
                        end = datetime.strptime(leave.end_date, "%d/%m/%Y").date()
                    except:
                        start = datetime.strptime(leave.start_date, "%Y-%m-%d").date()
                        end = datetime.strptime(leave.end_date, "%Y-%m-%d").date()
                    used += (end - start).days + 1
                except:
                    pass
        return used

    def calculate_leave_consumption_split(self, emp_id):
        """يفصل استهلاك الإجازات المعتمدة إلى رصيدين: Day Off والرصيد السنوي.
          • كل يوم من إجازة 'Day Off' يُخصم بالكامل من رصيد Day Off.
          • الإجازة السنوية: لكل (ANNUAL_LEAVE_DAYS_PER_DAYOFF = 7) أيام يُخصم يوم
            من رصيد Day Off، والباقي من الرصيد السنوي.
            مثال: إجازة 30 يوم ⇒ 30 // 7 = 4 أيام Day Off + 26 يوم سنوي.
        يُعيد dict:
          dayoff_leave_days : مجموع أيام إجازات نوع Day Off
          annual_total_days : مجموع أيام الإجازات السنوية
          annual_to_dayoff  : الجزء المخصوم من Day Off داخل الإجازات السنوية (Σ days // 7)
          annual_to_annual  : الجزء المخصوم من الرصيد السنوي (annual_total − annual_to_dayoff)
        """
        per = ANNUAL_LEAVE_DAYS_PER_DAYOFF if ANNUAL_LEAVE_DAYS_PER_DAYOFF else 7
        leaves = self.get_leaves_by_employee(emp_id)
        seen = set()
        dayoff_leave_days = 0
        annual_total_days = 0
        annual_to_dayoff  = 0
        for leave in leaves:
            if leave.leave_id in seen:
                continue
            seen.add(leave.leave_id)
            if leave.status not in ("Approved", "Confirmed", "confirmed"):
                continue
            try:
                try:
                    s = datetime.strptime(leave.start_date, "%d/%m/%Y").date()
                    e = datetime.strptime(leave.end_date,   "%d/%m/%Y").date()
                except Exception:
                    s = datetime.strptime(leave.start_date, "%Y-%m-%d").date()
                    e = datetime.strptime(leave.end_date,   "%Y-%m-%d").date()
                d = (e - s).days + 1
            except Exception:
                continue
            if d <= 0:
                continue
            if leave.leave_type == "Day Off":
                dayoff_leave_days += d
            elif leave.leave_type == "Annual":
                annual_total_days += d
                annual_to_dayoff  += d // per
        annual_to_annual = annual_total_days - annual_to_dayoff
        return {
            "dayoff_leave_days": dayoff_leave_days,
            "annual_total_days": annual_total_days,
            "annual_to_dayoff":  annual_to_dayoff,
            "annual_to_annual":  annual_to_annual,
        }

    @staticmethod
    def split_annual_leave_days(days):
        """يقسّم عدد أيام إجازة سنوية واحدة إلى (day_off_part, annual_part).
        day_off_part = days // 7  ،  annual_part = days − day_off_part."""
        per = ANNUAL_LEAVE_DAYS_PER_DAYOFF if ANNUAL_LEAVE_DAYS_PER_DAYOFF else 7
        try:
            d = int(days)
        except (TypeError, ValueError):
            return 0, 0
        if d <= 0:
            return 0, 0
        do = d // per
        return do, d - do
    def log_activity(self, action, details="", category="general", user=None):
        """تسجيل أي حدث داخل البرنامج مع التاريخ والوقت.
        لا يحفظ على القرص بنفسه — معظم المستدعين يستدعون save_data() بعده.
        استخدم save=True عبر استدعاء save_data() يدوياً للأحداث غير المرتبطة بحفظ."""
        try:
            entry = {
                "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "user": user if user else getattr(self, "current_user", "system"),
                "category": category,
                "action": action,
                "details": details if details is not None else "",
            }
            if not hasattr(self, "activity_log") or self.activity_log is None:
                self.activity_log = []
            self.activity_log.append(entry)
            # الحد الأقصى لمنع نمو الملف بلا حدود (الاحتفاظ بآخر 8000 حدث)
            if len(self.activity_log) > 8000:
                self.activity_log = self.activity_log[-8000:]
        except Exception:
            pass

    def log_activity_save(self, action, details="", category="general", user=None):
        """تسجيل حدث ثم الحفظ فوراً على القرص (للأحداث غير المرتبطة بعملية حفظ أخرى)."""
        self.log_activity(action, details=details, category=category, user=user)
        try:
            self.save_data()
        except Exception:
            pass

    def get_user_password(self, username, default_pw=""):
        """كلمة المرور الفعّالة للمستخدم: التعديل المحفوظ إن وُجد، وإلا الافتراضية."""
        try:
            up = getattr(self, "user_passwords", {}) or {}
            if username in up and up[username]:
                return up[username]
        except Exception:
            pass
        return default_pw

    def change_password(self, username, old_password, new_password):
        """تغيير كلمة المرور لمستخدم معيّن.
        يتحقق من كلمة المرور الحالية الفعّالة (التعديل المحفوظ أو الافتراضية)
        ثم يحفظ الجديدة في user_passwords ليأخذها تسجيل الدخول."""
        old_password = (old_password or "").strip()
        new_password = (new_password or "").strip()

        # كلمة المرور الافتراضية من قائمة المستخدمين المثبتة
        default_entry = DEFAULT_USER_CREDENTIALS.get(username)
        default_pw = default_entry[0] if default_entry else self.password

        current_pw = self.get_user_password(username, default_pw)

        if old_password != current_pw:
            return False, "Old password is incorrect"

        if not hasattr(self, "user_passwords") or self.user_passwords is None:
            self.user_passwords = {}
        self.user_passwords[username] = new_password

        # سجل الحدث (بدون كشف كلمات المرور)
        self.log_activity("Password changed",
                          details=f"User '{username}' changed their password",
                          category="security", user=username)
        self.save_data()
        return True, "Password changed successfully"

    def verify_password(self, username_or_password, password=None):
        """التحقق من كلمة السر.
        يدعم النمطين: verify_password(username, password) أو verify_password(password) القديم."""
        if password is None:
            # النمط القديم: مقارنة مع كلمة المرور العامة
            return self.password == username_or_password
        username = username_or_password
        default_entry = DEFAULT_USER_CREDENTIALS.get(username)
        default_pw = default_entry[0] if default_entry else self.password
        return self.get_user_password(username, default_pw) == password

    def set_language(self, language):
        """تعيين اللغة"""
        self.language = language
        self.save_data()
        return True, "Language changed successfully"

    def get_language(self):
        """الحصول على اللغة الحالية"""
        return self.language

    def set_zk_device(self, ip, port=4370, password=0, name="Device 1", index=None):
        """إضافة أو تعديل جهاز ZKTeco في قائمة الأجهزة"""
        device = {"name": name, "ip": ip, "port": port, "password": password}
        if index is not None and 0 <= index < len(self.zk_devices):
            self.zk_devices[index] = device
        else:
            self.zk_devices.append(device)
        # Keep legacy single-device fields in sync with first device
        if self.zk_devices:
            self.zk_device_ip       = self.zk_devices[0]["ip"]
            self.zk_device_port     = self.zk_devices[0]["port"]
            self.zk_device_password = self.zk_devices[0]["password"]
        self.save_data()
        return True, "ZKTeco device settings saved successfully"

    def remove_zk_device(self, index):
        """حذف جهاز ZKTeco من القائمة"""
        if 0 <= index < len(self.zk_devices):
            self.zk_devices.pop(index)
            if self.zk_devices:
                self.zk_device_ip       = self.zk_devices[0]["ip"]
                self.zk_device_port     = self.zk_devices[0]["port"]
                self.zk_device_password = self.zk_devices[0]["password"]
            else:
                self.zk_device_ip       = ""
                self.zk_device_port     = 4370
                self.zk_device_password = 0
            self.save_data()
            return True, "Device removed successfully"
        return False, "Device not found"

    # ═════════════════════════════════════════════════════════════════════════
    # ── Mobile GPS Punch via Google Sheets (بدون سيرفر محلي)
    #    صفحة البصمة مستضافة على Google Apps Script، والبرنامج يسحب البصمات من الشيت
    # ═════════════════════════════════════════════════════════════════════════
    MOBILE_PUNCH_DEFAULTS = {
        "gsheet_url": "",          # رابط Google Apps Script Web App
        "gsheet_key": "",          # مفتاح سري مشترك بين البرنامج والسكريبت
        "punch_page_url": "",      # رابط صفحة البصمة الخارجية (GitHub Pages) — لو فارغ يُستخدم رابط السكريبت
        "hotel_lat": 0.0,
        "hotel_lng": 0.0,
        "radius_m": 150,
        "max_accuracy_m": 100,
        "require_pin": True,
        "require_photo": True,     # التقاط صورة الوجه (سيلفي) مع كل بصمة
        "require_face": False,     # مطابقة الوجه تلقائيًا مع الوجه المسجّل (يمنع البصمة بالنيابة)
        "min_gap_minutes": 2,
        "auto_sync_minutes": 5,    # سحب البصمات تلقائيًا كل N دقيقة (0 = إيقاف)
        "last_row": 0,             # آخر صف تم سحبه من الشيت
        "leaves_last_row": 0,      # آخر صف طلبات إجازة تم سحبه
    }

    def _mp_dept_name(self, e):
        """اسم القسم بدل الكود (D001 → Accounting)"""
        code = getattr(e, "department", "") or ""
        d = (getattr(self, "departments", {}) or {}).get(code)
        return getattr(d, "name", "") or code

    @staticmethod
    def _mp_norm_date(v):
        """يوحّد أي شكل تاريخ قادم من الشيت إلى dd/mm/yyyy"""
        import re as _re
        sv = str(v or "").strip()
        m = _re.match(r"^(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})", sv)
        if m:
            return "%02d/%02d/%s" % (int(m.group(1)), int(m.group(2)), m.group(3))
        m = _re.match(r"^(\d{4})-(\d{2})-(\d{2})", sv)
        if m:
            return "%s/%s/%s" % (m.group(3), m.group(2), m.group(1))
        m = _re.match(r"^[A-Za-z]{3} ([A-Za-z]{3}) (\d{1,2}) (\d{4})", sv)   # Thu Sep 17 2026 ...
        if m:
            try:
                return datetime.strptime("%s %s %s" % (m.group(1), m.group(2), m.group(3)), "%b %d %Y").strftime("%d/%m/%Y")
            except ValueError:
                pass
        return sv

    @staticmethod
    def _mp_norm_time(v):
        import re as _re
        m = _re.search(r"(\d{1,2}):(\d{2})", str(v or ""))
        return "%02d:%s" % (int(m.group(1)), m.group(2)) if m else str(v or "").strip()

    @staticmethod
    def _mp_is_resigned(e):
        v = str(getattr(e, "resignation_date", "") or "").strip().lower()
        return v not in ("", "none", "nan", "-", "null", "0")

    def _init_mobile_punch(self):
        self.mobile_punch = dict(HRDatabase.MOBILE_PUNCH_DEFAULTS)
        self.mobile_punch_pins = {}
        self.mobile_punch_log = []
        self.mobile_leave_map = {}         # {leave_id: req_id} طلبات الإجازة القادمة من الموبايل
        self._mobile_lock = threading.Lock()

    def get_mobile_punch_settings(self):
        cfg = dict(HRDatabase.MOBILE_PUNCH_DEFAULTS)
        cfg.update(getattr(self, "mobile_punch", {}) or {})
        return cfg

    def set_mobile_punch_settings(self, **kwargs):
        cfg = self.get_mobile_punch_settings()
        for k, v in kwargs.items():
            if k in HRDatabase.MOBILE_PUNCH_DEFAULTS:
                cfg[k] = v
        self.mobile_punch = cfg
        self.save_data()
        return True, "Mobile punch settings saved"

    def set_mobile_pin(self, emp_id, pin):
        pin = str(pin or "").strip()
        emp_id = self.resolve_emp_id_from_clock(emp_id) or str(emp_id)
        if not hasattr(self, "mobile_punch_pins") or self.mobile_punch_pins is None:
            self.mobile_punch_pins = {}
        if pin:
            self.mobile_punch_pins[str(emp_id)] = pin
        else:
            self.mobile_punch_pins.pop(str(emp_id), None)
        self.save_data()

    def generate_mobile_pins(self, only_missing=True):
        import random as _rnd
        if not hasattr(self, "mobile_punch_pins") or self.mobile_punch_pins is None:
            self.mobile_punch_pins = {}
        count = 0
        for eid, e in self.employees.items():
            if HRDatabase._mp_is_resigned(e):
                continue
            if only_missing and self.mobile_punch_pins.get(str(eid)):
                continue
            self.mobile_punch_pins[str(eid)] = "%04d" % _rnd.randint(0, 9999)
            count += 1
        self.save_data()
        return count

    def resolve_emp_id_from_clock(self, raw_id):
        """يحوّل رقم البصمة إلى emp_id الفعلي (نفس منطق أجهزة ZKTeco)"""
        raw_id = str(raw_id or "").strip()
        if not raw_id:
            return None
        numeric_val = raw_id.lstrip("0") or "0"
        seen = set()
        for c in [raw_id, numeric_val, raw_id.zfill(2), raw_id.zfill(3), raw_id.zfill(4), raw_id.zfill(5)]:
            if c in seen:
                continue
            seen.add(c)
            if c in self.employees:
                return c
        try:
            n = int(numeric_val)
            for eid in self.employees:
                try:
                    if int(str(eid).lstrip("0") or "0") == n:
                        return eid
                except (ValueError, AttributeError):
                    pass
        except ValueError:
            pass
        return None

    def _mobile_log(self, **entry):
        if not hasattr(self, "mobile_punch_log") or self.mobile_punch_log is None:
            self.mobile_punch_log = []
        entry.setdefault("timestamp", datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
        self.mobile_punch_log.append(entry)
        if len(self.mobile_punch_log) > 5000:
            self.mobile_punch_log = self.mobile_punch_log[-5000:]

    # ── طلبات الإجازة من الموبايل ────────────────────────────────────────────
    def _pull_mobile_leave_requests(self, full=False):
        """سحب طلبات الإجازة الجديدة من الشيت وإنشاء Leave بحالة Pending. يرجع عدد الطلبات الجديدة"""
        cfg = self.get_mobile_punch_settings()
        since = 0 if full else int(cfg.get("leaves_last_row") or 0)
        res = self.gsheet_request("pull_leaves", {"since_row": since})
        if not hasattr(self, "mobile_leave_map") or self.mobile_leave_map is None:
            self.mobile_leave_map = {}
        known = set(self.mobile_leave_map.values())
        added = 0
        for r in res.get("rows", []) or []:
            req_id = str(r.get("req_id", "")).strip()
            if not req_id or req_id in known:
                continue
            emp_id = self.resolve_emp_id_from_clock(r.get("emp_id"))
            if not emp_id:
                continue
            leave_id = self.next_seq_id("L", self.leaves, "leave_id", 3)
            reason = ("📱 " + str(r.get("reason", "") or "")).strip() + "  [" + req_id + "]"
            status = str(r.get("status", "Pending") or "Pending")
            self.leaves.append(Leave(leave_id, emp_id, r.get("type", "Annual"), self._mp_norm_date(r.get("from")),
                                     self._mp_norm_date(r.get("to")), reason, status))
            self.mobile_leave_map[leave_id] = req_id
            known.add(req_id)
            added += 1
            try:
                self.log_activity("Mobile leave request", "%s (%s) %s %s→%s [%s]" % (
                    r.get("name", ""), emp_id, r.get("type", ""), r.get("from", ""), r.get("to", ""), req_id),
                    category="leave", user="mobile")
            except Exception:
                pass
        last = int(res.get("last_row") or since)
        self.mobile_punch = dict(self.get_mobile_punch_settings(), leaves_last_row=max(last, 0 if full else since))
        return added

    def _push_mobile_leave_status(self, leave_id, status, note=""):
        """إرسال قرار الموافقة/الرفض إلى الشيت ليراه الموظف في هاتفه (في الخلفية)"""
        req_id = (getattr(self, "mobile_leave_map", {}) or {}).get(leave_id)
        if not req_id or not (self.get_mobile_punch_settings().get("gsheet_url") or ""):
            return
        def _send():
            try:
                self.gsheet_request("set_leave_status", {"req_id": req_id, "status": status, "note": note})
            except Exception:
                pass
        threading.Thread(target=_send, daemon=True).start()

    def publish_payslips_to_gsheet(self, month, year, rows):
        """نشر قسائم راتب شهر: rows = [[clock_no, name, dept, basic, transport, allowances, service, gross,
        insurance, health, penalty, absent, sick, advance, deductions, cl_staff, tax, net], ...]"""
        total = 0
        for i in range(0, max(len(rows), 1), 25):
            part = rows[i:i + 25]
            # أول دفعة تستبدل الشهر كاملًا؛ الدفعات التالية تُضاف
            res = self.gsheet_request("set_payslips" if i == 0 else "append_payslips",
                                      {"month": int(month), "year": int(year), "rows": part})
            total += int(res.get("count") or 0)
        return total

    @staticmethod
    def _clean_exec_url(u):
        """ينظّف رابط الـ Web App: يزيل المسافات/علامات الاقتباس ويقطع أي شيء بعد أول /exec (لصق مكرر)"""
        u = str(u or "").strip().strip('"').strip("'").replace("\n", "").replace(" ", "")
        i = u.find("/exec")
        if i != -1:
            u = u[:i + 5]
        return u

    # ── الاتصال بـ Google Apps Script ────────────────────────────────────────
    def gsheet_request(self, action, payload=None, timeout=90):
        """يرسل طلبًا إلى الـ Web App ويرجع dict. يجرّب POST ثم GET تلقائيًا. يرفع Exception عند الفشل."""
        import urllib.request, urllib.parse, urllib.error
        cfg = self.get_mobile_punch_settings()
        url = HRDatabase._clean_exec_url(cfg.get("gsheet_url"))
        if not url:
            raise RuntimeError("لم يتم إدخال رابط Google Apps Script | Web App URL not set")
        if "…" in url or " " in url:
            raise RuntimeError("الرابط يحتوي على «…» أو مسافة — انسخه بزر النسخ من نافذة النشر:\n" + url)
        body = {"action": action, "key": cfg.get("gsheet_key", "")}
        body.update(payload or {})
        payload_json = json.dumps(body, ensure_ascii=False)

        def _parse(raw):
            try:
                res = json.loads(raw)
            except ValueError:
                raise RuntimeError("رد غير متوقع من جوجل (تأكد أن النشر Anyone وأن الرابط ينتهي بـ /exec):\n" + raw[:200])
            if not res.get("ok"):
                raise RuntimeError(res.get("error", "Unknown error"))
            return res

        errors = []
        # 0) محاولتان: أخطاء جوجل المؤقتة (HTML بدل JSON) تُعاد بعد ثانيتين
        for _attempt in (1, 2, 3):
            try:
                req = urllib.request.Request(url, data=payload_json.encode("utf-8"),
                                             headers={"Content-Type": "application/json", "User-Agent": "MODO-HR"}, method="POST")
                raw = urllib.request.urlopen(req, timeout=timeout).read().decode("utf-8", "ignore")
                try:
                    return _parse(raw)
                except RuntimeError as ex:
                    if _attempt < 3 and "رد غير متوقع" in str(ex):
                        time.sleep(2 * _attempt); continue
                    raise
            except urllib.error.HTTPError as ex:
                errors.append("POST: HTTP %s" % ex.code); break
            except (urllib.error.URLError, OSError) as ex:
                errors.append("POST: %s" % ex); break
        # 1) POST (JSON)
        try:
            req = urllib.request.Request(url, data=payload_json.encode("utf-8"),
                                         headers={"Content-Type": "application/json", "User-Agent": "MODO-HR"}, method="POST")
            raw = urllib.request.urlopen(req, timeout=timeout).read().decode("utf-8", "ignore")
            return _parse(raw)
        except urllib.error.HTTPError as ex:
            errors.append("POST: HTTP %s" % ex.code)
        except (urllib.error.URLError, OSError) as ex:
            errors.append("POST: %s" % ex)
        # 2) GET (payload in query string) — للطلبات الصغيرة
        if len(payload_json) < 6000:
            try:
                get_url = url + ("&" if "?" in url else "?") + urllib.parse.urlencode({"payload": payload_json})
                req = urllib.request.Request(get_url, headers={"User-Agent": "MODO-HR"})
                raw = urllib.request.urlopen(req, timeout=timeout).read().decode("utf-8", "ignore")
                return _parse(raw)
            except urllib.error.HTTPError as ex:
                errors.append("GET: HTTP %s" % ex.code)
            except (urllib.error.URLError, OSError) as ex:
                errors.append("GET: %s" % ex)
        raise RuntimeError("%s\nURL used: %s" % (" | ".join(errors), url))

    def push_mobile_config_to_gsheet(self):
        """إرسال إعدادات الفندق (الإحداثيات/النطاق/PIN) إلى الشيت حتى يفحصها السكريبت عند البصمة"""
        cfg = self.get_mobile_punch_settings()
        return self.gsheet_request("set_config", {"config": {
            "hotel_lat": cfg["hotel_lat"], "hotel_lng": cfg["hotel_lng"], "radius_m": cfg["radius_m"],
            "max_accuracy_m": cfg["max_accuracy_m"], "require_pin": bool(cfg["require_pin"]),
            "require_photo": bool(cfg.get("require_photo", True)), "require_face": bool(cfg.get("require_face", False)),
            "min_gap_minutes": cfg["min_gap_minutes"]}})

    def push_mobile_pins_to_gsheet(self):
        """إرسال قائمة الموظفين النشطين + الأرقام السرية إلى الشيت (على دفعات)"""
        pins = getattr(self, "mobile_punch_pins", {}) or {}
        rows = []
        for eid, e in self.employees.items():
            if HRDatabase._mp_is_resigned(e):
                continue
            rows.append({"emp_id": str(eid), "name": emp_display_name(e, str(eid)),
                         "dept": self._mp_dept_name(e), "pin": pins.get(str(eid), "")})
        total = 0
        chunk = 40
        for i in range(0, max(len(rows), 1), chunk):
            part = rows[i:i + chunk]
            res = self.gsheet_request("set_pins", {"pins": part, "mode": "replace" if i == 0 else "append"})
            total += int(res.get("count") or 0)
        return {"ok": True, "count": total}

    def sync_mobile_punches_from_gsheet(self, full=False):
        """سحب البصمات المقبولة الجديدة من الشيت وتسجيلها في الحضور. يرجع (ok, msg, count)"""
        lock = getattr(self, "_mobile_lock", None) or threading.Lock()
        if not lock.acquire(blocking=False):
            return False, "مزامنة أخرى جارية | Sync already running", 0
        try:
            cfg = self.get_mobile_punch_settings()
            # إصلاح أي سجلات سابقة وصل تاريخها بصيغة جوجل الطويلة
            for a in self.attendance:
                if "GMT" in str(a.date) or "-" in str(a.date):
                    a.date = self._mp_norm_date(a.date)
                    a.check_in = self._mp_norm_time(a.check_in) if a.check_in else a.check_in
                    a.check_out = self._mp_norm_time(a.check_out) if a.check_out else a.check_out
            for e in getattr(self, "mobile_punch_log", []) or []:
                if "GMT" in str(e.get("timestamp", "")):
                    e["timestamp"] = self._mp_norm_date(e["timestamp"]) + " " + str(e.get("time", "") or "")
            since = 0 if full else int(cfg.get("last_row") or 0)
            res = self.gsheet_request("pull", {"since_row": since})
            rows = res.get("rows", []) or []
            added = 0
            for r in rows:
                try:
                    emp_id = self.resolve_emp_id_from_clock(r.get("emp_id"))
                    emp = self.employees.get(emp_id) if emp_id else None
                    if emp is None:
                        self._mobile_log(result="rejected", reason="رقم غير مسجل في البرنامج", code="no_emp",
                                         clock_no=r.get("emp_id"), name=r.get("name", ""), type=r.get("type"),
                                         distance_m=r.get("distance_m"), accuracy=r.get("accuracy"), row=r.get("row"),
                                         timestamp="%s %s" % (r.get("date", ""), r.get("time", "")))
                        continue
                    punch_date = self._mp_norm_date(r.get("date", ""))
                    punch_time = self._mp_norm_time(r.get("time", ""))
                    ptype = "in" if str(r.get("type", "in")).lower().startswith("in") else "out"
                    existing = [a for a in self.attendance if a.emp_id == emp_id and a.date == punch_date]
                    if existing:
                        att = existing[0]
                        if ptype == "in":
                            if not att.check_in or (Attendance._parse_time(punch_time) and Attendance._parse_time(att.check_in)
                                                    and Attendance._parse_time(punch_time) < Attendance._parse_time(att.check_in)):
                                att.check_in = punch_time
                        else:
                            if not att.check_out or (Attendance._parse_time(punch_time) and Attendance._parse_time(att.check_out)
                                                     and Attendance._parse_time(punch_time) > Attendance._parse_time(att.check_out)):
                                att.check_out = punch_time
                        att.add_source("mobile")
                        if att.status in ("Day Off", "Absent"):
                            if att.status == "Day Off":
                                cur = float(emp.dof_override) if emp.dof_override is not None else 52.0
                                emp.dof_override = round(cur + 1, 1)
                            att.status = "Present"
                    else:
                        self.attendance.append(Attendance(emp_id, punch_date,
                                                          punch_time if ptype == "in" else "",
                                                          punch_time if ptype == "out" else "", "Present", "mobile"))
                    self._mobile_log(result="ok", reason="", code="ok", clock_no=r.get("emp_id"), emp_id=emp_id,
                                     name=emp_display_name(emp, emp_id), type=ptype, distance_m=r.get("distance_m"),
                                     accuracy=r.get("accuracy"), lat=r.get("lat"), lng=r.get("lng"), row=r.get("row"),
                                     date=punch_date, time=punch_time, dept=self._mp_dept_name(emp), photo=r.get("photo", ""),
                                     timestamp="%s %s" % (punch_date, punch_time))
                    added += 1
                except Exception:
                    pass
            last_row = int(res.get("last_row") or since)
            self.mobile_punch = dict(cfg, last_row=max(last_row, since if not full else 0))
            if rows:
                self.log_activity("Mobile GPS punch sync", "Pulled %d punch(es) from Google Sheet" % added,
                                  category="attendance", user="mobile")
            # ── طلبات الإجازة من الموبايل ──
            new_leaves = 0
            try:
                new_leaves = self._pull_mobile_leave_requests(full)
            except Exception:
                pass
            self.save_data()
            msg = "تم سحب %d بصمة جديدة من جوجل شيت | Pulled %d new punch(es)" % (added, added)
            if new_leaves:
                msg += "\n📨 %d طلب إجازة جديد بانتظار الموافقة (صفحة Leaves) | %d new leave request(s)" % (new_leaves, new_leaves)
            return True, msg, added
        except Exception as ex:
            return False, str(ex), 0
        finally:
            lock.release()

    # ── ZKTeco silent keep-alive helpers ──────────────────────────────────────
    def _release_live_zk_conns(self):
        """إغلاق أي اتصالات حية يحتفظ بها المراقب وتحرير جلسات الأجهزة.
        يُستدعى قبل المزامنة الفعلية حتى لا يتعارض اتصالان مع نفس الجهاز."""
        for k in list(self._zk_live_conns.keys()):
            c = self._zk_live_conns.get(k)
            if c is not None:
                try:
                    c.disconnect()
                except Exception:
                    pass
            self._zk_live_conns[k] = None

    def ensure_zk_connections(self):
        """فحص اتصال صامت بأجهزة البصمة (يُستدعى من خيط الخلفية كل 3 ثوانٍ).

        - يتأكد أن كل جهاز مُعرَّف لديه اتصال حي.
        - إذا كان الاتصال قائمًا يتحقق بسرعة أنه ما زال حيًا (قراءة وقت الجهاز).
        - إذا انقطع أو لم يكن موجودًا يحاول إعادة الاتصال تلقائيًا.
        - لا يُظهر أي شيء للمستخدم ولا يلمس الواجهة إطلاقًا.
        - timeout قصير حتى لا يتعطل الخيط طويلًا إذا كان الجهاز غير متصل.
        """
        if not ZKTEICO_AVAILABLE or not self.zk_devices:
            return
        # لا تتعارض مع مزامنة جارية: إذا كان القفل مشغولًا تخطَّ هذه الدورة
        if not self._zk_lock.acquire(blocking=False):
            return
        try:
            for dev in self.zk_devices:
                ip = dev.get("ip")
                if not ip:
                    continue
                port = dev.get("port", 4370)
                key = f"{ip}:{port}"
                conn = self._zk_live_conns.get(key)

                # (1) لدينا اتصال بالفعل → نتأكد أنه ما زال حيًا بفحص خفيف
                if conn is not None:
                    try:
                        conn.get_time()          # أمر خفيف يثبت أن الجلسة حية
                        self._zk_status[key] = True
                        continue                 # ما زال متصلًا → لا حاجة لفعل شيء
                    except Exception:
                        # الاتصال سقط → نظّفه ثم أعد الاتصال أدناه
                        try:
                            conn.disconnect()
                        except Exception:
                            pass
                        self._zk_live_conns[key] = None

                # (2) لا يوجد اتصال حي → حاول الاتصال بصمت مع timeout قصير
                try:
                    zk = ZK(ip, port=port,
                            password=dev.get("password", 0),
                            timeout=3, ommit_ping=True)
                    new_conn = zk.connect()
                    self._zk_live_conns[key] = new_conn
                    self._zk_status[key] = True
                except Exception:
                    self._zk_live_conns[key] = None
                    self._zk_status[key] = False
        finally:
            self._zk_lock.release()

    def is_zk_connected(self, ip=None, port=4370):
        """إرجاع حالة اتصال جهاز (أو أي جهاز) كما رصدها المراقب — للاستخدام الداخلي/المستقبلي."""
        if ip is not None:
            return bool(self._zk_status.get(f"{ip}:{port}", False))
        return any(self._zk_status.values())

    def sync_attendance_from_zk(self, device_index=None, start_date=None, deduct_dayoff=None):
        """مزامنة Attendance من أجهزة ZKTeco - يدعم أكثر من جهاز
        start_date: كائن date اختياري — يتم تجاهل أي بصمة قبل هذا التاريخ.
        deduct_dayoff:
            None  → السلوك الافتراضي: يُخصم Day Off عند المزامنة اليومية (start_date is None) فقط.
            True  → فرض خصم Day Off (يُستخدم في السحب التلقائي بعد ٨ مساءً).
            False → منع خصم Day Off نهائيًا (يُستخدم في السحب التلقائي الصباحي).
        لا يُخصم Day Off إطلاقًا إلا إذا نجح الاتصال فعليًا بجهاز واحد على الأقل."""
        if not ZKTEICO_AVAILABLE:
            return False, "مكتبة pyzk غير مثبتة. لتثبيتها شغّل: pip install pyzk | pyzk library is not installed. Run: pip install pyzk"

        if not self.zk_devices:
            return False, "No devices configured. Please add devices in Settings."

        # Determine which devices to sync
        if device_index is not None:
            if 0 <= device_index < len(self.zk_devices):
                devices_to_sync = [self.zk_devices[device_index]]
            else:
                return False, "Invalid device index"
        else:
            devices_to_sync = self.zk_devices

        total_synced = 0
        errors = []
        any_device_connected = False   # هل نجح الاتصال بأي جهاز؟ (شرط لخصم Day Off)

        # احجز أجهزة البصمة طوال المزامنة، وحرّر اتصالات المراقب الصامت أولًا،
        # حتى لا يتعارض اتصالان مع نفس الجهاز في آنٍ واحد.
        self._zk_lock.acquire()
        self._release_live_zk_conns()

        for dev in devices_to_sync:
            dev_name = dev.get("name", dev.get("ip", ""))
            try:
                zk = ZK(dev["ip"], port=dev.get("port", 4370), password=dev.get("password", 0), ommit_ping=True)
                conn = zk.connect()
                any_device_connected = True   # نجح الاتصال بهذا الجهاز
                conn.disable_device()

                attendance_records = conn.get_attendance()

                device_synced = 0
                for record in attendance_records:
                    # تجاهل أي بصمة قبل تاريخ البداية المطلوب
                    if start_date is not None:
                        try:
                            if record.timestamp.date() < start_date:
                                continue
                        except Exception:
                            pass
                    # Try multiple ID formats to match system employees
                    raw_id = str(record.user_id).strip()
                    numeric_val = raw_id.lstrip("0") or "0"
                    # Build all plausible candidate formats
                    id_candidates = [
                        raw_id,
                        numeric_val,
                        raw_id.zfill(2),
                        raw_id.zfill(3),
                        raw_id.zfill(4),
                        raw_id.zfill(5),
                    ]
                    # Remove duplicates while preserving order
                    seen = set()
                    id_candidates = [c for c in id_candidates if not (c in seen or seen.add(c))]
                    emp_id = None
                    for candidate in id_candidates:
                        if candidate in self.employees:
                            emp_id = candidate
                            break
                    if emp_id is None:
                        # Last resort: compare numeric values of all employee IDs
                        try:
                            numeric_raw = int(numeric_val)
                            for eid in self.employees:
                                try:
                                    if int(eid.lstrip("0") or "0") == numeric_raw:
                                        emp_id = eid
                                        break
                                except (ValueError, AttributeError):
                                    pass
                        except ValueError:
                            pass
                    if emp_id is None:
                        emp_id = raw_id.zfill(3)  # fallback: store as-is

                    punch_time = record.timestamp
                    punch_date = punch_time.strftime("%d/%m/%Y")
                    punch_time_str = punch_time.strftime("%H:%M")  # صيغة 24 ساعة

                    punch = record.punch

                    if punch == 0:
                        check_in = punch_time_str
                        check_out = ""
                    else:
                        check_in = ""
                        check_out = punch_time_str

                    existing = [a for a in self.attendance if a.emp_id == emp_id and a.date == punch_date]

                    if existing:
                        for att in existing:
                            updated = False
                            if punch == 0 and not att.check_in:
                                att.check_in = check_in
                                updated = True
                            elif punch != 0 and not att.check_out:
                                att.check_out = check_out
                                updated = True
                            # إصلاح: لو السجل كان Day Off/Absent ووصلته بصمة الآن ⇒ حضور فعلي
                            if updated:
                                att.add_source("device")
                            if updated and att.status in ("Day Off", "Absent"):
                                if att.status == "Day Off":
                                    # استرجاع اليوم المخصوم مسبقًا من رصيد Day Off
                                    emp_obj = self.employees.get(att.emp_id)
                                    if emp_obj is not None:
                                        cur = float(emp_obj.dof_override) if emp_obj.dof_override is not None else 52.0
                                        emp_obj.dof_override = round(cur + 1, 1)
                                att.status = "Present"
                    else:
                        att = Attendance(emp_id, punch_date, check_in, check_out, "Present", "device")
                        self.attendance.append(att)

                    device_synced += 1

                total_synced += device_synced
                conn.enable_device()
                conn.disconnect()

            except Exception as e:
                errors.append(f"{dev_name}: {str(e)}")

        # حرّر الجهاز بعد انتهاء المزامنة ليستأنف المراقب الصامت عمله
        try:
            self._zk_lock.release()
        except Exception:
            pass

        # ── خصم Day Off (المسار اليدوي فقط) ──────────────────────────────────
        # ملاحظة مهمة: السحب التلقائي اليومي لم يعد يخصم من هنا إطلاقًا — بل يعالج
        # «اليوم السابق المكتمل» عبر apply_dayoff_deduction() (انظر _auto_sync_zk_daily).
        # هنا نخصم فقط عند الجلب اليدوي الشامل (start_date فارغ) وبشرط نجاح الاتصال.
        if deduct_dayoff is None:
            should_deduct = (start_date is None)
        else:
            should_deduct = bool(deduct_dayoff)

        deducted_employees = []
        if should_deduct and any_device_connected:
            deducted_employees = self.apply_dayoff_deduction(date.today(), save=False)
        # ───────────────────────────────────────────────────────────────────────

        self._bulk_mode = False
        self.save_data()

        if errors and total_synced == 0:
            return False, "Failed to sync all devices:\n" + "\n".join(errors)
        elif errors:
            return True, f"Synced {total_synced} records.\nWarnings:\n" + "\n".join(errors)
        else:
            deducted_note = f"\n⚠️ Day Off recorded for {len(deducted_employees)} employee(s) with no check-in." if deducted_employees else ""
            return True, f"Synced {total_synced} attendance records from {len(devices_to_sync)} device(s) successfully{deducted_note}"

    def apply_dayoff_deduction(self, target_date, save=True):
        """يعالج «يومًا كاملاً» محدَّدًا: لكل موظف ليس له أي بصمة/سجل في ذلك اليوم:
            (١) يُنشئ سجل حضور بحالة "Day Off" بتاريخ ذلك اليوم.
            (٢) يخصم يومًا واحدًا من رصيد Day Off.
        target_date: كائن date (أو نص بصيغة DD/MM/YYYY أو YYYY-MM-DD).
        idempotent: إنشاء سجل Day Off يجعل اليوم غير فارغ، فلا يتكرر الخصم أبدًا.
        يُرجع قائمة بأسماء الموظفين الذين تم خصمهم."""
        # طبّع التاريخ إلى صيغة العرض DD/MM/YYYY المستخدمة في سجلات الحضور
        if isinstance(target_date, str):
            parsed = None
            for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y"):
                try:
                    parsed = datetime.strptime(target_date.strip(), fmt).date()
                    break
                except ValueError:
                    pass
            if parsed is None:
                return []
            target_date = parsed
        target_str = target_date.strftime("%d/%m/%Y")

        deducted_employees = []
        for emp_id, emp in self.employees.items():
            day_att = [a for a in self.attendance if a.emp_id == emp_id and a.date == target_str]
            if day_att:
                continue
            # ── استثناء: لا يُخصم Day Off إذا كان الموظف في إجازة معتمدة هذا اليوم ──
            #   الموظف في إجازة (سنوية/مرضية/…إلخ) لا يبصم بطبيعة الحال، فلا يجوز
            #   خصم يوم من رصيد Day Off (الإجازة محسوبة بالفعل من رصيدها الخاص).
            #   لكن يجب مع ذلك إنشاء سجل حضور لليوم بحالة تساوي نوع الإجازة، حتى
            #   يظهر اليوم في شاشات/تقارير الحضور بدلًا من أن يختفي تمامًا.
            leave_type_today = self._approved_leave_type_on(emp_id, target_str)
            if leave_type_today:
                self.attendance.append(Attendance(emp_id, target_str, "", "", leave_type_today))
                continue
            self.attendance.append(Attendance(emp_id, target_str, "", "", "Day Off"))
            current_dof = float(emp.dof_override) if emp.dof_override is not None else 52.0
            emp.dof_override = max(0.0, round(current_dof - 1, 1))
            deducted_employees.append(emp.name)
        if save and deducted_employees:
            self.save_data()
        return deducted_employees


