    def t(self, key):
        """Get translated text based on current language - Default English"""
        lang = self.db.get_language() if hasattr(self, 'db') else "en"
        return self.TRANSLATIONS.get(lang, self.TRANSLATIONS["en"]).get(key, key)

    def __init__(self, root, username="admin", role="admin", db=None):
        self.root = root
        self.current_user = username   # current user name
        self.user_role = role          # admin | hr | leaves_payroll_eval | leaves_eval
        self.root.title("MODO HR")
        self.root.state('zoomed')  # Full screen

        # Modern Professional Colors - Enhanced Visibility
        self.colors = {
            'primary': '#1e293b',      # Slate 800
            'secondary': '#334155',    # Slate 700
            'accent': '#0ea5e9',       # Sky 500
            'highlight': '#06b6d4',    # Cyan 500
            'success': '#22c55e',      # Green 500
            'warning': '#f59e0b',      # Amber 500
            'danger': '#ef4444',       # Red 500
            'white': '#ffffff',
            'light': '#e2e8f0',        # Slate 200 - More visible
            'card_bg': '#f8fafc',      # Slate 50
            'bg': '#f1f5f9',           # Slate 100
            'sidebar': '#0f172a',      # Slate 900
            'sidebar_hover': '#1e293b',
            'sidebar_active': '#06b6d4',
            'text': '#0f172a',         # Slate 900 - Darker text
            'text_light': '#475569',   # Slate 600
            'text_sidebar': '#94a3b8',
            'border': '#cbd5e1',       # Slate 300 - Visible border
            'gradient_1': '#06b6d4',
            'gradient_2': '#3b82f6',
            'gradient_start': '#06b6d4',
            'gradient_end': '#3b82f6',
            'input_bg': '#ffffff',     # White input background
            'input_border': '#94a3b8', # Slate 400 - Visible input border
            'form_bg': '#ffffff',      # Form background
        }

        # Current page tracker
        self.current_page = None
        self.current_sidebar_btn = None

        # Create database
        self.db = db if db is not None else HRDatabase()
        # تأكد أن قاعدة البيانات تعرف المستخدم الحالي (لأغراض سجل النشاطات)
        try:
            self.db.current_user = username
        except Exception:
            pass

        # ── تفعيل طبقة الترجمة الفورية + ضبط اللغة المحفوظة قبل بناء الواجهة ──
        try:
            set_app_language(self.db.get_language())
            install_auto_translation()
        except Exception:
            pass

        # Create GUI
        self.create_gui()

        # ── مزامنة تلقائية يومية من أجهزة البصمة عند بدء التشغيل ────────────
        self.root.after(2000, self._auto_sync_zk_daily)

        # ── مراقب اتصال صامت بأجهزة البصمة كل 3 ثوانٍ (في الخلفية) ──────────
        self._start_zk_connection_monitor()

        # ── ترحيل المستقيلين القدامى إلى الأرشيف (مرة واحدة) ─────────────
        try:
            _moved = self.db.migrate_resigned_to_archive()
            if _moved:
                self.root.after(1500, lambda: messagebox.showinfo(
                    "Resignations Archive",
                    "تم نقل %d موظفًا مستقيلًا إلى أرشيف الاستقالات وحذفهم من البيانات النشطة.\n"
                    "%d resigned employee(s) moved to the Resignations archive." % (_moved, _moved)))
        except Exception:
            pass

        # ── فحص التحديث التلقائي عند التشغيل ────────────────────────────
        if self.db.settings.get("update_auto", True) and self.db.settings.get("update_url"):
            self.root.after(5000, self.run_update_check)

        # ── سحب بصمات الموبايل من جوجل شيت تلقائيًا ─────────────────────
        self.root.after(15000, self._start_mobile_punch_autosync)
        # ── سحب بصمات جهاز ZKTeco تلقائيًا كل N دقيقة (بدون خصم Day Off) ──
        self.root.after(45000, self._auto_pull_zk_periodic)

    def _is_admin(self):
        """Return True if the current user has admin or hr role."""
        return getattr(self, 'user_role', '') in ('admin', 'hr')

    def _can_approve_advances(self):
        """اعتماد السلف / CL Staff / الجزاءات: صلاحية HR فقط (بغض النظر عن اسم المستخدم)."""
        return getattr(self, 'user_role', '') == 'hr'

    def _ensure_excel(self):
        """Return True if openpyxl is available, auto-installing if needed."""
        global EXCEL_AVAILABLE
        if EXCEL_AVAILABLE:
            return True
        # Try silent install
        try:
            import subprocess, sys
            result = subprocess.run(
                [sys.executable, "-m", "pip", "install", "openpyxl"],
                capture_output=True, text=True, timeout=120,
                creationflags=0x08000000 if __import__('sys').platform == 'win32' else 0
            )
            if result.returncode == 0:
                from openpyxl import Workbook  # noqa: F401
                import openpyxl  # noqa: F401
                EXCEL_AVAILABLE = True
                messagebox.showinfo(
                    "✅ Installed",
                    "openpyxl installed successfully!\nPlease try the export again."
                )
                return True
        except Exception:
            pass
        # Ask user to install manually
        if messagebox.askyesno(
            "Install Required",
            "The Excel library (openpyxl) is not installed.\n\n"
            "Click YES to install it automatically now."
        ):
            try:
                import subprocess, sys
                subprocess.run(
                    [sys.executable, "-m", "pip", "install", "openpyxl"],
                    capture_output=True,
                    timeout=120,
                    creationflags=0x08000000 if __import__('sys').platform == 'win32' else 0
                )
                EXCEL_AVAILABLE = True
                messagebox.showinfo("✅ Done", "openpyxl installed!\nPlease try the export again.")
                return True
            except Exception as e:
                messagebox.showerror("Error", f"Installation failed:\n{e}")
        return False

    def _require_admin(self, action_name="delete this record"):
        """Show an error and return False if user is not admin/hr. Use at top of every delete action."""
        if not self._is_admin():
            messagebox.showerror(
                "🔒 Access Denied",
                f"You do not have permission to {action_name}.\n\nOnly the Administrator or HR can perform delete operations.\n\nPlease contact your system administrator."
            )
            return False
        return True

    def _archive_monthly_snapshot(self, month, year):
        """
        Capture a snapshot of the current monthly report data and save it
        permanently in hr_data.json under the key "MM-YYYY".
        If a snapshot for this month already exists it is NEVER overwritten —
        the old data is preserved and a new key with a timestamp suffix is used
        so no historical record is ever lost.
        """
        try:
            month_names = {
                1: "January", 2: "February", 3: "March", 4: "April",
                5: "May", 6: "June", 7: "July", 8: "August",
                9: "September", 10: "October", 11: "November", 12: "December"
            }
            m = int(month)
            y = int(year)
            month_name = month_names.get(m, str(m))
            base_key = f"{str(m).zfill(2)}-{y}"

            if not hasattr(self.db, 'monthly_snapshots') or self.db.monthly_snapshots is None:
                self.db.monthly_snapshots = {}

            # Never overwrite an existing snapshot — use a timestamp suffix if key exists
            key = base_key
            if key in self.db.monthly_snapshots:
                # Already archived for this month — do not overwrite
                return

            headers = ["Bank Code", "Name", "Department", "Basic", "Transport", "Allowances",
                       "Service", "Amount", "Insurance", "Health Ins.", "Penalty",
                       "Absent", "Sick Leave", "Advance", "Deductions", "CL Staff", "Tax", "Net"]

            rows = self.get_monthly_report_data(month=m, year=y)

            self.db.monthly_snapshots[key] = {
                "month": str(m).zfill(2),
                "year": str(y),
                "month_name": month_name,
                "generated_at": datetime.now().strftime("%d/%m/%Y %H:%M"),
                "headers": headers,
                "rows": [list(r) for r in rows]
            }
            self.db.save_data()
        except Exception:
            pass  # Archive errors must never block payroll operations

