    def create_gui(self):
        """Create Modern GUI with Sidebar"""
        self.setup_styles()

        # ── تفعيل Copy/Paste في جميع حقول الإدخال عبر كل النظام ──────────
        def _enable_copy_paste(widget, event=None):
            """Enable right-click context menu + Ctrl+C/V/X/A on Entry and Text widgets"""
            try:
                wtype = type(widget).__name__
                if wtype in ("Entry", "Text", "Spinbox"):
                    # Ctrl shortcuts
                    widget.bind("<Control-c>", lambda e: widget.event_generate("<<Copy>>"))
                    widget.bind("<Control-v>", lambda e: widget.event_generate("<<Paste>>"))
                    widget.bind("<Control-x>", lambda e: widget.event_generate("<<Cut>>"))
                    widget.bind("<Control-a>", lambda e: (widget.select_range(0, tk.END)
                                                          if wtype != "Text"
                                                          else widget.tag_add(tk.SEL, "1.0", tk.END)) or "break")
                    # Right-click context menu
                    def _ctx(e, w=widget):
                        m = tk.Menu(w, tearoff=0)
                        m.add_command(label="Cut",   command=lambda: w.event_generate("<<Cut>>"))
                        m.add_command(label="Copy",  command=lambda: w.event_generate("<<Copy>>"))
                        m.add_command(label="Paste", command=lambda: w.event_generate("<<Paste>>"))
                        m.add_separator()
                        m.add_command(label="Select All", command=lambda: (
                            w.select_range(0, tk.END) if type(w).__name__ != "Text"
                            else w.tag_add(tk.SEL, "1.0", tk.END)))
                        try:
                            m.tk_popup(e.x_root, e.y_root)
                        finally:
                            m.grab_release()
                    widget.bind("<Button-3>", _ctx)
            except Exception:
                pass
            for child in widget.winfo_children():
                _enable_copy_paste(child)

        # ربط تلقائي على كل widget جديد يُضاف للنافذة
        self.root.bind_all("<FocusIn>", lambda e: _enable_copy_paste(e.widget))

        # Main container
        self.main_container = tk.Frame(self.root, bg=self.colors['light'])
        self.main_container.pack(fill=tk.BOTH, expand=True)

        # Create sidebar
        self.create_sidebar()

        # Create content area
        self.content_frame = tk.Frame(self.main_container, bg=self.colors['light'])
        self.content_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        # الصفحة الافتراضية حسب الصلاحية
        try:
            _r = getattr(self, 'user_role', 'admin')
            if _r in ('admin', 'hr'):
                self.show_departments_page()
            else:
                self.show_leaves_page()
        except Exception as e:
            import traceback
            traceback.print_exc()
            tk.Label(self.content_frame, text=f"Error loading page:\n{e}",
                     font=('Arial', 12), fg='red', bg=self.colors['light']).pack(expand=True)

    def create_sidebar(self):
        """Create Modern Sidebar Navigation"""
        # تدمير الشريط الجانبي القديم إن وُجد (يحدث عند تغيير اللغة) لتفادي التكرار
        try:
            if getattr(self, 'sidebar', None) is not None:
                self.sidebar.destroy()
        except Exception:
            pass
        # Sidebar frame with canvas and scrollbar
        sidebar = tk.Frame(self.main_container, bg=self.colors['sidebar'], width=260)
        _content = getattr(self, 'content_frame', None)
        if _content is not None and _content.winfo_exists():
            # أعِد الشريط الجانبي إلى يسار منطقة المحتوى (مهم عند إعادة البناء)
            sidebar.pack(side=tk.LEFT, fill=tk.Y, before=_content)
        else:
            sidebar.pack(side=tk.LEFT, fill=tk.Y)
        self.sidebar = sidebar
        sidebar.pack_propagate(False)

        # Create canvas for scrolling
        sidebar_canvas = tk.Canvas(sidebar, bg=self.colors['sidebar'], highlightthickness=0)
        sidebar_canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        sidebar_scrollbar = ttk.Scrollbar(sidebar, orient="vertical", command=sidebar_canvas.yview)
        sidebar_scrollbar.pack(side=tk.RIGHT, fill=tk.Y)

        sidebar_canvas.configure(yscrollcommand=sidebar_scrollbar.set)

        # Create frame inside canvas
        sidebar_content = tk.Frame(sidebar_canvas, bg=self.colors['sidebar'])
        sidebar_canvas.create_window((0, 0), window=sidebar_content, anchor='nw')

        # Logo section
        logo_frame = tk.Frame(sidebar_content, bg=self.colors['sidebar'], height=100)
        logo_frame.pack(fill=tk.X, pady=(20, 10))
        logo_frame.pack_propagate(False)

        # Logo canvas
        logo_canvas = tk.Canvas(logo_frame, width=60, height=60,
                                bg=self.colors['sidebar'], highlightthickness=0)
        logo_canvas.pack()
        self._sidebar_logo_img = get_logo_tk_photo(size=58)
        if self._sidebar_logo_img:
            logo_canvas.create_image(30, 30, image=self._sidebar_logo_img)
        else:
            logo_canvas.create_oval(5, 5, 55, 55, fill=self.colors['highlight'], outline='')
            logo_canvas.create_text(30, 30, text="HR", font=('Segoe UI', 14, 'bold'),
                                    fill=self.colors['primary'])

        # System title with translation
        tk.Label(sidebar_content, text=self.t("window_title"), font=('Segoe UI', 16, 'bold'),
                bg=self.colors['sidebar'], fg=self.colors['white']).pack(pady=(0, 5))
        tk.Label(sidebar_content, text="System v1.0", font=('Segoe UI', 10),
                bg=self.colors['sidebar'], fg=self.colors['text_sidebar']).pack(pady=(0, 20))

        # Separator
        tk.Frame(sidebar_content, bg=self.colors['accent'], height=1).pack(fill=tk.X, padx=20)

        # Navigation buttons with translations
        all_nav = [
            ("📊", "Dashboard",                   self.show_dashboard,              "all",     "dashboard"),
            ("👥", self.t("employees"),            self.show_employees_page,         "all",     "employees"),
            ("🏢", self.t("departments"),          self.show_departments_page,       "all",     "departments"),
            ("🔀", "Change of Status",             self.show_change_of_status_page,  "all",     "change_of_status"),
            ("📄", self.t("contracts"),            self.show_contracts_page,         "all",     "contracts"),
            ("🚪", self.t("resignations"),         self.show_resignations_page,      "all",     "resignations"),
            ("📅", self.t("attendance"),           self.show_attendance_page,        "all",     "attendance"),
            ("🌴", self.t("leaves"),               self.show_leaves_page,            "leaves",  "leaves"),
            ("💰", self.t("payroll"),              self.show_payroll_page,           "payroll", "payroll"),
            ("🧾", "Salary Slip",                  self.show_salary_slip_page,       "payroll", "salary_slip"),
            ("💵", self.t("advances"),             self.show_advances_page,          "advances","advances"),
            ("🧮", self.t("cl_staff"),             self.show_cl_staff_page,          "all",     "cl_staff"),
            ("⚠️", self.t("penalties"),            self.show_penalties_page,         "all",     "penalties"),
            ("📈", self.t("reports"),              self.show_reports_page,           "all",     "reports"),
            ("👤", "Employee Situations",              self.show_employee_status_page,   "all", "employee_situations"),
            ("📝", self.t("evaluation"),           self.show_evaluation_page,        "eval",    "evaluation"),
            ("🔄", self.t("contract_renewal"),     self.show_contract_renewal_page,  "all",     "contract_renewal"),
            ("⚙️", self.t("settings"),             self.show_settings_page,          "all",     "settings"),
        ]

        _role = getattr(self, 'user_role', 'admin')
        _user = getattr(self, 'current_user', '')
        _user_perms_map = getattr(self.db, 'user_permissions', {}) or {}
        _user_perms = _user_perms_map.get(_user)

        def _role_allowed(tag):
            if _role in ('admin', 'hr'):
                return True
            if _role == 'leaves_payroll_eval':
                return tag in ('leaves', 'payroll', 'eval', 'advances')
            if _role == 'leaves_eval':
                return tag in ('leaves', 'eval')
            return True

        def _allowed(tag, key):
            # Admins always see everything, so they can't accidentally lock
            # themselves out of Settings/Permissions.
            if _role == 'admin':
                return True
            # If a custom per-user permission list exists for this user,
            # it fully overrides the role-based defaults.
            if _user_perms is not None:
                return key in _user_perms
            return _role_allowed(tag)

        nav_items = [(icon, text, cmd) for icon, text, cmd, tag, key in all_nav if _allowed(tag, key)]

        self.sidebar_buttons = []
        for icon, text, command in nav_items:
            btn_frame = tk.Frame(sidebar_content, bg=self.colors['sidebar'])
            btn_frame.pack(fill=tk.X, padx=10, pady=2)

            btn = tk.Button(btn_frame, text=f"  {icon}  {text}",
                           font=('Segoe UI', 12),
                           bg=self.colors['sidebar'],
                           fg=self.colors['text_sidebar'],
                           activebackground=self.colors['sidebar_hover'],
                           activeforeground=self.colors['highlight'],
                           relief=tk.FLAT, bd=0,
                           anchor='w',
                           padx=20, pady=12,
                           cursor="hand2",
                           command=lambda c=command, b=None: self.nav_click(c, b))
            btn.pack(fill=tk.X)
            btn.config(command=lambda c=command, b=btn: self.nav_click(c, b))
            self.sidebar_buttons.append(btn)

        # Spacer
        tk.Frame(sidebar_content, bg=self.colors['sidebar']).pack(fill=tk.BOTH, expand=True)

        # Bottom section - Logout with translation
        tk.Frame(sidebar_content, bg=self.colors['accent'], height=1).pack(fill=tk.X, padx=20)

        # Start background auto-sync loop (every 30 seconds)
        self._refresh_status_var = tk.StringVar(value="")
        self._start_auto_sync()

        logout_btn = tk.Button(sidebar_content, text="  🚪  " + self.t("logout"),
                              font=('Segoe UI', 12),
                              bg=self.colors['sidebar'],
                              fg=self.colors['danger'],
                              activebackground=self.colors['sidebar_hover'],
                              activeforeground=self.colors['danger'],
                              relief=tk.FLAT, bd=0,
                              anchor='w',
                              padx=20, pady=15,
                              cursor="hand2",
                              command=self.logout)
        logout_btn.pack(fill=tk.X, padx=10, pady=10)

        # Configure scroll region
        sidebar_content.update_idletasks()
        sidebar_canvas.configure(scrollregion=sidebar_canvas.bbox('all'))

        # Mouse wheel support for sidebar
        def _on_mousewheel(event):
            sidebar_canvas.yview_scroll(int(-1*(event.delta/120)), "units")
        def _on_mousewheel_linux(event):
            if event.num == 4:
                sidebar_canvas.yview_scroll(-1, "units")
            elif event.num == 5:
                sidebar_canvas.yview_scroll(1, "units")

        def _bind_sidebar_wheel(event):
            sidebar_canvas.bind_all("<MouseWheel>", _on_mousewheel)
            sidebar_canvas.bind_all("<Button-4>",   _on_mousewheel_linux)
            sidebar_canvas.bind_all("<Button-5>",   _on_mousewheel_linux)
        def _unbind_sidebar_wheel(event):
            sidebar_canvas.unbind_all("<MouseWheel>")
            sidebar_canvas.unbind_all("<Button-4>")
            sidebar_canvas.unbind_all("<Button-5>")

        sidebar_canvas.bind("<Enter>", _bind_sidebar_wheel)
        sidebar_canvas.bind("<Leave>", _unbind_sidebar_wheel)
        sidebar_content.bind("<Enter>", _bind_sidebar_wheel)
        sidebar_content.bind("<Leave>", _unbind_sidebar_wheel)

        # Bind on all sidebar buttons too so wheel works anywhere in sidebar
        def _bind_all_sidebar_children(widget):
            widget.bind("<Enter>", _bind_sidebar_wheel)
            widget.bind("<Leave>", _unbind_sidebar_wheel)
            for child in widget.winfo_children():
                _bind_all_sidebar_children(child)

        sidebar_content.after(100, lambda: _bind_all_sidebar_children(sidebar_content))

        # Update scrollregion whenever sidebar content changes size
        def _update_sidebar_scroll(event=None):
            sidebar_canvas.configure(scrollregion=sidebar_canvas.bbox('all'))
        sidebar_content.bind("<Configure>", _update_sidebar_scroll)

    def nav_click(self, command, btn):
        """Handle navigation click"""
        # Reset all buttons
        for b in self.sidebar_buttons:
            b.config(bg=self.colors['sidebar'], fg=self.colors['text_sidebar'])

        # Highlight clicked button
        if btn:
            btn.config(bg=self.colors['sidebar_hover'], fg=self.colors['highlight'])

        # Track current page name for auto-refresh (use method __name__ — stable,
        # unlike id() of bound methods which changes on each access)
        _page_name_map = {
            'show_dashboard':            'dashboard',
            'show_employees_page':       'employees',
            'show_departments_page':     'departments',
            'show_attendance_page':      'attendance',
            'show_leaves_page':          'leaves',
            'show_payroll_page':         'payroll',
            'show_advances_page':        'advances',
            'show_cl_staff_page':        'cl_staff',
            'show_penalties_page':       'penalties',
            'show_reports_page':         'reports',
            'show_contracts_page':       'contracts',
            'show_resignations_page':    'resignations',
            'show_settings_page':        'settings',
            'show_employee_status_page': 'employee_status',
            'show_salary_slip_page':     'salary_slip',
            'show_evaluation_page':      'evaluation',
            'show_contract_renewal_page':'contract_renewal',
            'show_change_of_status_page':'change_of_status',
        }
        _cmd_name = getattr(command, '__name__', None)
        self.current_page = _page_name_map.get(_cmd_name, self.current_page)

        # مسح نص البحث المحفوظ لكل صفحة عند الانتقال لصفحة مختلفة
        _page_search_map = {
            self.show_employees_page:          '_emp_search_text',
            self.show_departments_page:        '_dept_search_text',
            self.show_attendance_page:         '_att_search_text',
            self.show_leaves_page:             '_lv_search_text',
            self.show_payroll_page:            '_pay_search_text',
            self.show_advances_page:           '_adv_search_text',
            self.show_cl_staff_page:           '_cl_search_text',
            self.show_penalties_page:          '_pen_search_text',
            self.show_contracts_page:          '_con_search_text',
            self.show_resignations_page:       '_res_search_text',
            self.show_employee_status_page:    '_es_search_text',
            self.show_evaluation_page:         '_eval_search_text',
            self.show_contract_renewal_page:   '_ren_search_text',
            self.show_change_of_status_page:   '_cos_search_text',
        }
        for page_func, attr in _page_search_map.items():
            if command is not page_func:
                setattr(self, attr, "")

        # Execute command
        command()

    def clear_content(self):
        """Clear content area"""
        self._page_name = None
        for widget in self.content_frame.winfo_children():
            widget.destroy()

    # ── Refresh / Auto-sync ────────────────────────────────────────────────

    def _manual_refresh(self):
        """Reload data from shared file and redraw current page."""
        try:
            self.db.reload_from_shared()
            now = datetime.now().strftime("%H:%M:%S")
            if hasattr(self, '_refresh_status_var'):
                self._refresh_status_var.set(f"✅ Updated {now}")
            # Re-navigate to current page
            self._refresh_current_page()
        except Exception as e:
            if hasattr(self, '_refresh_status_var'):
                self._refresh_status_var.set(f"⚠ Error: {str(e)[:30]}")

    def _refresh_current_page(self):
        """Re-render whichever page is currently visible."""
        page = getattr(self, 'current_page', None)
        page_map = {
            'dashboard':         self.show_dashboard,
            'employees':         self.show_employees_page,
            'departments':       self.show_departments_page,
            'attendance':        self.show_attendance_page,
            'leaves':            self.show_leaves_page,
            'payroll':           self.show_payroll_page,
            'advances':          self.show_advances_page,
            'cl_staff':          self.show_cl_staff_page,
            'penalties':         self.show_penalties_page,
            'reports':           self.show_reports_page,
            'contracts':         self.show_contracts_page,
            'resignations':      self.show_resignations_page,
            'settings':          self.show_settings_page,
            'employee_status':   self.show_employee_status_page,
            'salary_slip':       self.show_salary_slip_page,
            'evaluation':        self.show_evaluation_page,
            'contract_renewal':  self.show_contract_renewal_page,
            'change_of_status':  self.show_change_of_status_page,
        }
        fn = page_map.get(page)
        if fn:
            try:
                fn()
            except Exception:
                pass

    def _start_auto_sync(self):
        """Start a background timer that checks for shared file changes every 30 s."""
        self._auto_sync_running = True
        self._auto_sync_loop()

    def _start_zk_connection_monitor(self):
        """تشغيل مراقب اتصال صامت بأجهزة البصمة في خيط خلفي مستقل.

        يتأكد كل 3 ثوانٍ أن أجهزة البصمة متصلة، ويعيد الاتصال تلقائيًا عند الانقطاع،
        دون إظهار أي شيء للمستخدم ودون تجميد الواجهة (لأنه يعمل في خيط منفصل عن واجهة Tk).
        """
        if getattr(self, '_zk_monitor_running', False):
            return  # يعمل بالفعل
        self._zk_monitor_running = True
        self._zk_monitor_stop = threading.Event()
        t = threading.Thread(target=self._zk_connection_monitor_worker,
                             daemon=True, name="zk-conn-monitor")
        t.start()

    def _zk_connection_monitor_worker(self):
        """حلقة الخلفية: تفحص/تعيد اتصال أجهزة البصمة كل 3 ثوانٍ بصمت تام."""
        while getattr(self, '_zk_monitor_running', False):
            try:
                self.db.ensure_zk_connections()
            except Exception:
                pass  # لا نُظهر أي خطأ ولا نوقف الحلقة مهما حدث
            # ننتظر 3 ثوانٍ (أو نخرج فورًا عند إيقاف البرنامج)
            try:
                if self._zk_monitor_stop.wait(3.0):
                    break
            except Exception:
                break

    def _stop_zk_connection_monitor(self):
        """إيقاف مراقب الاتصال وتحرير أي اتصالات حية (يُستدعى عند الإغلاق)."""
        self._zk_monitor_running = False
        try:
            if getattr(self, '_zk_monitor_stop', None) is not None:
                self._zk_monitor_stop.set()
        except Exception:
            pass
        try:
            self.db._release_live_zk_conns()
        except Exception:
            pass

    def _auto_sync_loop(self):
        """Called every 30 seconds; reloads data if shared file changed."""
        if not getattr(self, '_auto_sync_running', False):
            return
        try:
            if self.db.check_shared_changed():
                self.db.reload_from_shared()
                now = datetime.now().strftime("%H:%M:%S")
                if hasattr(self, '_refresh_status_var'):
                    self._refresh_status_var.set(f"🔄 Auto-synced {now}")
                self._refresh_current_page()
        except Exception:
            pass
        # Schedule next check in 30 seconds via Tk after()
        try:
            self.root.after(30000, self._auto_sync_loop)
        except Exception:
            pass

    def show_dashboard(self):
        """Show Dashboard Page"""
        self.clear_content()

        # ── حساب الإحصائيات ──────────────────────────────────────────────────
        today_str  = date.today().strftime("%d/%m/%Y")
        today_md   = (date.today().month, date.today().day)   # (month, day) for birthday match

        # ── الشهر الحالي: تتحدث الأرقام تلقائيًا مع بداية كل شهر ──────────────
        cur_y, cur_m = date.today().year, date.today().month
        month_label  = date.today().strftime("%B %Y")

        def _in_month(dstr):
            for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y"):
                try:
                    d = datetime.strptime(str(dstr or "").strip(), fmt).date()
                    return d.year == cur_y and d.month == cur_m
                except ValueError:
                    continue
            return False

        month_advances  = [a for a in self.db.advances  if _in_month(a.date)]
        month_penalties = [p for p in self.db.penalties if _in_month(p.date)]
        month_adv_amt   = sum(float(a.amount or 0) for a in month_advances)
        month_pen_amt   = sum(float(p.amount or 0) + float(getattr(p, "additional_penalty", 0) or 0) for p in month_penalties)
        month_new_hires = [e for e in self.db.employees.values() if _in_month(e.hire_date)]
        month_resigned  = self.db.resigned_in_month(cur_y, cur_m) if hasattr(self.db, "resigned_in_month") else []
        month_leaves    = [l for l in self.db.leaves if l.status == "Approved" and (_in_month(l.start_date) or _in_month(l.end_date))]
        month_att       = [a for a in self.db.attendance if _in_month(a.date)]
        month_present   = len({(a.emp_id, a.date) for a in month_att if a.check_in})
        month_absent    = len({(a.emp_id, a.date) for a in month_att if a.status == "Absent"})

        total_employees   = len(self.db.employees)          # النشطون فقط (المستقيلون في الأرشيف)
        total_departments = len(self.db.departments)
        total_advances    = len(month_advances)
        total_penalties   = len(month_penalties)
        total_stopped_salaries = sum(1 for e in self.db.employees.values()
                                      if not getattr(e, 'salary_active', True))

        # موظفون سجّلوا دخولاً اليوم (check_in موجود في سجل اليوم)
        today_iso = date.today().strftime("%Y-%m-%d")
        today_attendance  = [a for a in self.db.attendance
                             if a.date in (today_str, today_iso) and a.check_in]
        checked_in_ids    = {a.emp_id for a in today_attendance}
        checked_in_count  = len(checked_in_ids)

        # موظفون في إجازة اليوم (Approved & تشمل اليوم)
        def _leave_covers_today(lv):
            try:
                for fmt in ("%d/%m/%Y", "%Y-%m-%d"):
                    try:
                        s = datetime.strptime(lv.start_date, fmt).date()
                        e = datetime.strptime(lv.end_date,   fmt).date()
                        return s <= date.today() <= e
                    except ValueError:
                        continue
            except Exception:
                pass
            return False

        on_leave_today = [l for l in self.db.leaves
                          if l.status == "Approved"
                          and l.leave_type not in ("Day Off",)
                          and _leave_covers_today(l)]
        on_leave_count = len({l.emp_id for l in on_leave_today})

        # موظفون Day Off اليوم (Approved Day Off يشمل اليوم)
        day_off_today  = [l for l in self.db.leaves
                          if l.status == "Approved"
                          and l.leave_type == "Day Off"
                          and _leave_covers_today(l)]
        day_off_count  = len({l.emp_id for l in day_off_today})

        # موظفون أعياد ميلادهم اليوم
        birthday_emps  = []
        for emp in self.db.employees.values():
            if not emp.birth_date:
                continue
            for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y"):
                try:
                    bd = datetime.strptime(emp.birth_date, fmt).date()
                    if (bd.month, bd.day) == today_md:
                        birthday_emps.append(emp)
                    break
                except ValueError:
                    continue
        birthday_count = len(birthday_emps)
        # ─────────────────────────────────────────────────────────────────────

        # Page header
        header = tk.Frame(self.content_frame, bg=self.colors['white'], height=80)
        header.pack(fill=tk.X)
        header.pack_propagate(False)

        tk.Label(header, text="📊 Dashboard", font=('Segoe UI', 24, 'bold'),
                bg=self.colors['white'], fg=self.colors['primary']).pack(side=tk.LEFT, padx=30, pady=20)

        today_label_str = date.today().strftime("%d/%m/%Y")
        tk.Label(header, text="%s   |   📅 %s" % (today_label_str, month_label), font=('Segoe UI', 11),
                bg=self.colors['white'], fg=self.colors['text_light']).pack(side=tk.RIGHT, padx=30, pady=20)

        # ── ROW 1: الإحصائيات الأساسية ───────────────────────────────────────
        row1_frame = tk.Frame(self.content_frame, bg=self.colors['light'])
        row1_frame.pack(fill=tk.X, padx=30, pady=(20, 5))

        row1_stats = [
            ("👥", "Total Employees",  total_employees,   self.colors['highlight']),
            ("🏢", "Departments",       total_departments, self.colors['success']),
            ("💵", "Advances (this month)",  total_advances,    self.colors['warning']),
            ("⚠️", "Penalties (this month)", total_penalties,   self.colors['danger']),
            ("🚫", "Stopped Salaries",  total_stopped_salaries, '#64748B'),
        ]

        def _make_stat_card(parent, icon, title, value, color, click_cmd=None):
            card = tk.Frame(parent, bg=self.colors['white'],
                            highlightbackground=self.colors['border'],
                            highlightthickness=1)
            card.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=10, pady=10)
            if click_cmd:
                card.config(cursor='hand2')
                card.bind('<Button-1>', lambda e: click_cmd())

            icon_frame = tk.Frame(card, bg=color, width=60, height=60)
            icon_frame.pack(side=tk.LEFT, padx=15, pady=15)
            icon_frame.pack_propagate(False)
            lbl_icon = tk.Label(icon_frame, text=icon, font=('Segoe UI', 24),
                    bg=color, fg=self.colors['white'])
            lbl_icon.pack(expand=True)
            if click_cmd:
                lbl_icon.config(cursor='hand2')
                lbl_icon.bind('<Button-1>', lambda e: click_cmd())

            info_frame = tk.Frame(card, bg=self.colors['white'])
            info_frame.pack(side=tk.LEFT, fill=tk.BOTH, expand=True, padx=10, pady=15)
            lbl_title = tk.Label(info_frame, text=title, font=('Segoe UI', 11),
                    bg=self.colors['white'], fg=self.colors['text_light'])
            lbl_title.pack(anchor='w')
            lbl_val = tk.Label(info_frame, text=str(value), font=('Segoe UI', 28, 'bold'),
                    bg=self.colors['white'], fg=self.colors['primary'])
            lbl_val.pack(anchor='w')
            if click_cmd:
                for w in (info_frame, lbl_title, lbl_val):
                    w.config(cursor='hand2')
                    w.bind('<Button-1>', lambda e: click_cmd())
            return card

        def _show_all_employees():
            self.show_employees_page()

        def _show_all_departments():
            self.show_departments_page()

        def _show_all_advances():
            self.show_advances_page()

