    # ── helpers ────────────────────────────────────────────────────────────────

    @staticmethod
    def _fmt_service(total_months):
        """Convert total months → '6y 4m' style string."""
        if total_months <= 0:
            return "0m"
        yrs = total_months // 12
        mths = total_months % 12
        if yrs == 0:
            return f"{mths}m"
        if mths == 0:
            return f"{yrs}y"
        return f"{yrs}y {mths}m"

    def _lb_get_rows(self):
        """Build all leave-balance rows for every employee."""
        employees = self.db.get_all_employees()
        today = date.today()
        rows = []
        for emp in employees:
            # Parse hire date
            hire_raw = emp.hire_date or ""
            try:
                hd = datetime.strptime(hire_raw, "%d/%m/%Y").date()
            except Exception:
                try:
                    hd = datetime.strptime(hire_raw, "%Y-%m-%d").date()
                except Exception:
                    hd = None

            months_worked = 0
            if hd:
                months_worked = (today.year - hd.year) * 12 + (today.month - hd.month)

            # Service duration as "Xy Ym" string
            service_dur = self._fmt_service(months_worked)

            # Employee type
            emp_type_raw = getattr(emp, 'employee_type', 'Regular') or 'Regular'
            if emp_type_raw in ('10years', '50years'):
                type_label   = "10 yrs / 50+ age"
                official_hol = 15
                day_off_days = 52
                annual_days  = 30
                total_full   = 97
            elif emp_type_raw == '5%':
                type_label   = "Disability (5%)"
                official_hol = 15
                day_off_days = 52
                annual_days  = 45
                total_full   = 112
            else:
                type_label   = "Regular Employee"
                official_hol = 15
                day_off_days = 52
                annual_days  = 21
                total_full   = 88

            # Probation: < 6 months → only day-off
            if months_worked < 6:
                day_off_earned = months_worked * 4
                annual_bal     = 0
                total_bal      = day_off_earned
                notes          = f"Probation ({service_dur}) — Day Off only: {day_off_earned} days"
            elif months_worked < 12:
                earned_months = months_worked - 5
                annual_bal    = round((earned_months * annual_days) / 12, 1)
                total_bal     = official_hol + day_off_days + annual_bal
                notes         = f"Prorated — {earned_months} actual months"
            else:
                annual_bal = annual_days
                total_bal  = total_full
                notes      = "Full annual balance"

            manual_adj = float(getattr(emp, 'leave_balance_adjustment', 0) or 0)

            # ── تطبيق التعديلات اليدوية من صفحة Update (تُمثّل الرصيد الأساسي) ──
            if getattr(emp, 'svc_override', None) is not None:
                service_dur = str(emp.svc_override)
            if getattr(emp, 'hol_override', None) is not None:
                official_hol = float(emp.hol_override)
            if getattr(emp, 'ann_override', None) is not None:
                annual_bal = float(emp.ann_override)

            # ── فصل استهلاك الإجازات بين رصيد Day Off والرصيد السنوي ───────────
            #   • إجازة Day Off  → تُخصم بالكامل من رصيد Day Off
            #   • إجازة سنوية N يوم → (N ÷ 7) أيام من Day Off والباقي من السنوي
            split          = self.db.calculate_leave_consumption_split(emp.emp_id)
            dayoff_lv_used = split['dayoff_leave_days']    # أيام إجازات Day Off
            do_from_annual = split['annual_to_dayoff']     # جزء الأسبوع من الإجازة السنوية
            an_consumed    = split['annual_to_annual']     # باقي الإجازة السنوية → سنوي

            # ── رصيد Day Off الأساس + أيام Day Off المأخوذة عبر الحضور ─────────
            #   dof_override يحمل المتبقّي بعد خصم الحضور (الأساس الكامل = 52).
            #   أيام الحضور المخصومة = 52 − dof_override، وتُحتسب ضمن الاستهلاك.
            DAY_OFF_FULL = 52.0
            if getattr(emp, 'dof_override', None) is not None:
                _dof_remaining   = float(emp.dof_override)
                attendance_taken = max(0.0, round(DAY_OFF_FULL - min(_dof_remaining, DAY_OFF_FULL), 1))
                day_off_base     = DAY_OFF_FULL
            else:
                attendance_taken = 0.0
                day_off_base     = float(day_off_days)   # 52 عادةً أو (الشهور×4) في فترة الاختبار

            annual_full = float(annual_bal)

            # إجمالي المخصوم من كل رصيد
            day_off_consumed = round(attendance_taken + dayoff_lv_used + do_from_annual, 1)
            used = round(day_off_consumed + an_consumed, 1)

            # الاستحقاق الكامل قبل أي خصم (15 + Day Off + سنوي)
            total_bal = round(official_hol + day_off_base + annual_full, 1)

            # ── خصم الإجازات/الحضور من كل عمود على حدة (للعرض) ────────────────
            day_off_days = max(0.0, round(day_off_base - day_off_consumed, 1))
            annual_bal   = max(0.0, round(annual_full  - an_consumed, 1))

            # Remaining الإجمالي = الاستحقاق + التعديل − المستهلَك
            remaining = round(max(0, total_bal + manual_adj - used), 1)

            # Resolve department name from ID
            dept_raw = emp.department or ""
            dept_obj = self.db.get_department(dept_raw)
            dept_display = dept_obj.name if dept_obj else dept_raw

            rows.append({
                "emp_id":            emp.emp_id,
                "name":              emp.name,
                "department":        dept_display,
                "position":          (emp.position or "").lower(),
                "emp_type":          type_label,
                "hire_date":         format_date_display(hire_raw),
                "service_duration":  service_dur,
                "months_worked":     months_worked,       # kept for internal logic
                "official_holidays": official_hol,
                "day_off":           day_off_days,
                "annual_balance":    annual_bal,
                "total_balance":     round(total_bal, 1),
                "used_leaves":       used,
                "remaining":         remaining,
                "notes":             notes,
                "manual_adj":        manual_adj,
                "is_probation":      months_worked < 6,
            })
        return rows

    def _lb_load_table(self):
        """Reload treeview with current search / filter."""
        search  = self._lb_search_var.get().strip().lower()
        # Ignore placeholder text
        if search == "search by name, department or position...":
            search = ""
        f_type  = self._lb_type_var.get()

        rows = self._lb_get_rows()

        # Filter
        filtered = []
        for r in rows:
            if search and \
               search not in r["emp_id"].lower() and \
               search not in r["name"].lower() and \
               search not in r["department"].lower() and \
               search not in r["position"]:
                continue
            if f_type != "All":
                if f_type == "Regular Employee"  and r["emp_type"] != "Regular Employee":  continue
                if f_type == "10 yrs / 50+ age"  and r["emp_type"] != "10 yrs / 50+ age": continue
                if f_type == "Disability (5%)"   and r["emp_type"] != "Disability (5%)":  continue
            filtered.append(r)

        # Clear
        for item in self._lb_tree.get_children():
            self._lb_tree.delete(item)

        # Table columns (service_duration shown instead of months_worked)
        cols = ("emp_id","name","department","emp_type","hire_date","service_duration",
                "official_holidays","day_off","annual_balance","total_balance",
                "used_leaves","remaining","notes")

        for i, r in enumerate(filtered):
            vals = tuple(r[c] for c in cols)
            if r["is_probation"]:
                tag = 'probation'
            elif r["remaining"] <= 0:
                tag = 'danger'
            elif r["remaining"] <= 5:
                tag = 'warning'
            elif i % 2 == 1:
                tag = 'alt'
            else:
                tag = ''
            self._lb_tree.insert("", tk.END, values=vals, tags=(tag,))

        self._lb_status.config(
            text=f"Total: {len(filtered)} employees    |    Date: {date.today().strftime('%d/%m/%Y')}"
        )

    def _lb_update_selected(self):
        """Navigate to full-page editor for the selected employee row."""
        sel = self._lb_tree.selection()
        if not sel:
            messagebox.showwarning("Update", "Please select an employee row first.")
            return

        vals   = self._lb_tree.item(sel[0])['values']
        # vals[0] is emp_id — Treeview may return int or str, try both
        raw_id = vals[0]
        emp    = (self.db.get_employee(str(raw_id)) or
                  self.db.get_employee(raw_id))

        # Fallback: search by name (vals[1]) if ID lookup failed
        if not emp:
            raw_name = str(vals[1]).strip().lower()
            for e in self.db.get_all_employees():
                if (e.name or "").strip().lower() == raw_name:
                    emp = e
                    break

        if not emp:
            messagebox.showerror("Error",
                f"Employee '{raw_id}' not found.\n"
                "Please refresh the table and try again.")
            return

        self._lb_show_update_page(emp)

    def _lb_show_update_page(self, emp):
        """Full-page leave-balance employee editor (no popup)."""
        self.clear_content()
        HDR = '#0284C7'

        # ── Header ──────────────────────────────────────────────────────────
        header = tk.Frame(self.content_frame, bg=HDR, height=110)
        header.pack(fill=tk.X); header.pack_propagate(False)

        tf = tk.Frame(header, bg=HDR)
        tf.pack(side=tk.LEFT, padx=30, pady=18)
        tk.Label(tf, text="✏️", font=('Segoe UI', 28), bg=HDR).pack(side=tk.LEFT, padx=(0, 14))
        tt = tk.Frame(tf, bg=HDR)
        tt.pack(side=tk.LEFT)
        tk.Label(tt, text="Update Employee — Leave Balance",
                 font=('Segoe UI', 20, 'bold'), bg=HDR, fg='white').pack(anchor='w')
        tk.Label(tt, text=f"{emp.emp_id}  ·  {emp.name}",
                 font=('Segoe UI', 11), bg=HDR, fg='#BAE6FD').pack(anchor='w', pady=(3, 0))

        tk.Button(header, text="  🔙 Back  ", font=('Segoe UI', 9, 'bold'),
                  bg='#0369A1', fg='white', relief=tk.FLAT, padx=14, pady=8,
                  bd=0, cursor='hand2',
                  command=self.show_leave_balance_page
                  ).pack(side=tk.RIGHT, padx=25, pady=20)

        # ── Scrollable content ───────────────────────────────────────────────
        outer = tk.Frame(self.content_frame, bg='#F0F9FF')
        outer.pack(fill=tk.BOTH, expand=True, padx=40, pady=25)

        card = tk.Frame(outer, bg='white',
                        highlightbackground='#BAE6FD', highlightthickness=2)
        card.pack(fill=tk.BOTH, expand=True)

        # Card title bar
        ctb = tk.Frame(card, bg=HDR, height=36)
        ctb.pack(fill=tk.X); ctb.pack_propagate(False)
        tk.Label(ctb, text="Employee Information", font=('Segoe UI', 11, 'bold'),
                 bg=HDR, fg='white').pack(side=tk.LEFT, padx=18, pady=7)

        form = tk.Frame(card, bg='white', padx=50, pady=30)
        form.pack(fill=tk.BOTH, expand=True)
        form.columnconfigure(0, minsize=180)
        form.columnconfigure(1, minsize=280)
        form.columnconfigure(2, minsize=180)
        form.columnconfigure(3, minsize=280)

        # ── Helper to add a field ────────────────────────────────────────────
        def field(label, var, row, col=0, readonly=False, combo_vals=None, show=""):
            tk.Label(form, text=label, font=('Segoe UI', 10, 'bold'),
                     bg='white', fg='#334155', anchor='e'
                     ).grid(row=row, column=col, sticky='e', padx=(0, 12), pady=10)
            if combo_vals:
                w = ttk.Combobox(form, textvariable=var, values=combo_vals,
                                 font=('Segoe UI', 11), width=22, state='readonly')
            else:
                state = 'disabled' if readonly else 'normal'
                fg    = '#6D28D9'  if readonly else '#0F172A'
                w = tk.Entry(form, textvariable=var, font=('Segoe UI', 11),
                             width=24, relief='solid', bd=1,
                             state=state, fg=fg,
                             disabledforeground='#6D28D9',
                             show=show)
            w.grid(row=row, column=col + 1, sticky='w', pady=10)
            return w

        r = 0
        # ── Section 1: Identity ──────────────────────────────────────────────
        sec = tk.Frame(form, bg='#EFF6FF')
        sec.grid(row=r, column=0, columnspan=4, sticky='ew', pady=(0, 10))
        tk.Label(sec, text="👤  Identity", font=('Segoe UI', 10, 'bold'),
                 bg='#EFF6FF', fg='#1E40AF').pack(anchor='w', padx=14, pady=7)
        r += 1

        id_var   = tk.StringVar(value=emp.emp_id)
        name_var = tk.StringVar(value=emp.name or "")
        dept_var = tk.StringVar(value=emp.department or "")
        pos_var  = tk.StringVar(value=emp.position or "")

        field("Emp Code:",   id_var,   r, col=0, readonly=True)
        field("Name:",       name_var, r, col=2)
        r += 1
        field("Department:", dept_var, r, col=0)
        field("Position:",   pos_var,  r, col=2)
        r += 1

        # ── Section 2: Employment ────────────────────────────────────────────
        sec2 = tk.Frame(form, bg='#FEF3C7')
        sec2.grid(row=r, column=0, columnspan=4, sticky='ew', pady=(10, 10))
        tk.Label(sec2, text="📋  Employment", font=('Segoe UI', 10, 'bold'),
                 bg='#FEF3C7', fg='#92400E').pack(anchor='w', padx=14, pady=7)
        r += 1

        hire_var  = tk.StringVar(value=format_date_display(emp.hire_date or ""))
        ins_var   = tk.StringVar(value=str(getattr(emp, 'insurance_years', 0) or 0))
        etype_var = tk.StringVar(value=getattr(emp, 'employee_type', 'Regular') or 'Regular')

        field("Hire Date:",     hire_var,  r, col=0)
        field("Ins. Years:",    ins_var,   r, col=2)
        r += 1
        field("Employee Type:", etype_var, r, col=0,
              combo_vals=["Regular", "10years", "50years", "5%"])
        r += 1

        # ── Section 3: Leave Balance — fully editable ────────────────────────
        sec3 = tk.Frame(form, bg='#F0FDF4')
        sec3.grid(row=r, column=0, columnspan=4, sticky='ew', pady=(10, 10))
        tk.Label(sec3, text="📅  Leave Balance",
                 font=('Segoe UI', 10, 'bold'),
                 bg='#F0FDF4', fg='#166534').pack(anchor='w', padx=14, pady=7)
        r += 1

        today = date.today()
        hire_raw = emp.hire_date or ""
        try:
            hd = datetime.strptime(hire_raw, "%d/%m/%Y").date()
        except Exception:
            try:
                hd = datetime.strptime(hire_raw, "%Y-%m-%d").date()
            except Exception:
                hd = None
        months_w = (today.year - hd.year)*12 + (today.month - hd.month) if hd else 0
        svc_dur  = self._fmt_service(months_w)

        et_raw = getattr(emp, 'employee_type', 'Regular') or 'Regular'
        if et_raw in ('10years', '50years'):
            ann_days, total_full = 30, 97
        elif et_raw == '5%':
            ann_days, total_full = 45, 112
        else:
            ann_days, total_full = 21, 88

        if months_w < 6:
            ann_bal   = 0
            total_bal = months_w * 4
        elif months_w < 12:
            ann_bal   = round(((months_w - 5) * ann_days) / 12, 1)
            total_bal = 15 + 52 + ann_bal
        else:
            ann_bal   = ann_days
            total_bal = total_full

        used_lv   = self.db.calculate_used_leaves(emp.emp_id, "Annual")
        manual_adj_val = float(getattr(emp, 'leave_balance_adjustment', 0) or 0)
        remaining = round(max(0, total_bal + manual_adj_val - used_lv), 1)
        official_hol = 15
        day_off_days = 52

        # Use stored override if present, else show computed value
        def _ov(attr, computed):
            v = getattr(emp, attr, None)
            return str(v) if v is not None else str(computed)

        svc_v   = tk.StringVar(value=_ov('svc_override',  svc_dur))
        hol_v   = tk.StringVar(value=_ov('hol_override',  official_hol))
        dof_v   = tk.StringVar(value=_ov('dof_override',  day_off_days))
        ann_v   = tk.StringVar(value=_ov('ann_override',  ann_bal))
        adj_v   = tk.StringVar(value=str(int(manual_adj_val)))

        # used always = actual approved leaves (read-only)
        used_v = tk.StringVar(value=str(used_lv))

        # Total Balance & Remaining are computed — read only
        tot_v = tk.StringVar()
        rem_v = tk.StringVar()

        def _recalc(*_):
            try: h = float(hol_v.get())
            except: h = official_hol
            try: d = float(dof_v.get())
            except: d = day_off_days
            try: a = float(ann_v.get())
            except: a = ann_bal
            # فصل استهلاك الإجازات بين Day Off والسنوي (نفس منطق صفحة Leave Balance)
            _sp = self.db.calculate_leave_consumption_split(emp.emp_id)
            _dayoff_lv  = _sp['dayoff_leave_days']
            _do_annual  = _sp['annual_to_dayoff']
            _an_consume = _sp['annual_to_annual']
            # d = الرصيد المتبقّي من Day Off (الأساس الكامل 52) → المأخوذ بالحضور = 52 − المتبقّي
            DAY_OFF_FULL = 52.0
            attendance_taken = max(0.0, round(DAY_OFF_FULL - min(d, DAY_OFF_FULL), 1))
            day_off_consumed = round(attendance_taken + _dayoff_lv + _do_annual, 1)
            u   = round(day_off_consumed + _an_consume, 1)
            tot = round(h + DAY_OFF_FULL + a, 1)
            rem = round(max(0, tot + manual_adj_val - u), 1)
            tot_v.set(str(tot))
            rem_v.set(str(rem))
            used_v.set(str(u))

        hol_v.trace_add('write', _recalc)
        dof_v.trace_add('write', _recalc)
        ann_v.trace_add('write', _recalc)
        _recalc()  # initial calculation

        field("Service Duration:",  svc_v,  r, col=0)
        field("Official Holidays:", hol_v,  r, col=2)
        r += 1
        field("Day Off:",           dof_v,  r, col=0)
        field("Annual Balance:",    ann_v,  r, col=2)
        r += 1
        field("Total Balance:",     tot_v,  r, col=0, readonly=True)
        field("Used Leaves:",       used_v, r, col=2, readonly=True)
        r += 1
        field("Remaining:",         rem_v,  r, col=0, readonly=True)

        # ── Manual balance adjustment ─────────────────────────────────────
        # Section header
        sec_adj = tk.Frame(form, bg='#FFF7ED')
        sec_adj.grid(row=r, column=2, columnspan=2, sticky='ew', padx=(20,0))
        tk.Label(sec_adj, text="➕  Manual Balance Adjustment",
                 font=('Segoe UI', 9, 'bold'), bg='#FFF7ED', fg='#92400E'
                 ).pack(anchor='w', padx=10, pady=5)
        r += 1

        adj_widget = field("Add/Remove Days:", adj_v, r, col=2)
        tk.Label(form, text="(+ add days, − remove days)",
                 font=('Segoe UI', 8), bg='white', fg='#6B7280'
                 ).grid(row=r+1, column=2, columnspan=2, sticky='w', padx=(0,6))
        r += 1
        r += 1

        # ── Save ─────────────────────────────────────────────────────────────
        def save():
            emp.name       = name_var.get().strip()
            emp.department = dept_var.get().strip()
            emp.position   = pos_var.get().strip()
            hd_raw2 = hire_var.get().strip()
            try:
                emp.hire_date = datetime.strptime(hd_raw2, "%d/%m/%Y").strftime("%d/%m/%Y")
            except Exception:
                emp.hire_date = hd_raw2
            emp.employee_type = etype_var.get()
            try:
                setattr(emp, 'insurance_years', int(ins_var.get()))
            except Exception:
                pass
            try:
                emp.leave_balance_adjustment = float(adj_v.get())
            except Exception:
                pass
            # Save leave balance overrides (only if user changed the value)
            def _save_num(var, attr, computed_val):
                raw = var.get().strip()
                try:
                    v = float(raw)
                    setattr(emp, attr, v if str(v) != str(computed_val) else None)
                except Exception:
                    setattr(emp, attr, None)
            _save_num(hol_v, 'hol_override', official_hol)
            _save_num(dof_v, 'dof_override', day_off_days)
            _save_num(ann_v, 'ann_override', ann_bal)
            # used/tot/rem are computed — never saved as overrides
            emp.used_override = None
            emp.tot_override  = None
            emp.rem_override  = None
            # svc_override is text not float — handle separately
            svc_raw = svc_v.get().strip()
            emp.svc_override = svc_raw if svc_raw != svc_dur else None
            self.db.save_data()
            self.show_leave_balance_page()
            messagebox.showinfo("Saved", f"Employee  {emp.emp_id}  updated successfully.")

        btn_bar = tk.Frame(card, bg='#F8FAFC', height=64)
        btn_bar.pack(fill=tk.X, side=tk.BOTTOM); btn_bar.pack_propagate(False)
        tk.Frame(btn_bar, bg='#BAE6FD', height=1).pack(fill=tk.X, side=tk.TOP)
        btn_center = tk.Frame(btn_bar, bg='#F8FAFC')
        btn_center.place(relx=0.5, rely=0.5, anchor='center')
        tk.Button(btn_center, text="💾  Save Changes", font=('Segoe UI', 11, 'bold'),
                  bg='#059669', fg='white', bd=0, padx=32, pady=9,
                  cursor='hand2', command=save).pack(side=tk.LEFT, padx=10)
        tk.Button(btn_center, text="❌  Cancel", font=('Segoe UI', 11, 'bold'),
                  bg='#EF4444', fg='white', bd=0, padx=32, pady=9,
                  cursor='hand2', command=self.show_leave_balance_page).pack(side=tk.LEFT, padx=10)

    def _lb_current_data(self):
        """Return (headers, data_rows) for currently displayed rows."""
        headers = ["Emp Code","Name","Department","Emp Type","Hire Date","Service Duration",
                   "Official Holidays","Day Off","Annual Balance","Total Balance",
                   "Used","Remaining","Notes"]
        data_rows = []
        for item in self._lb_tree.get_children():
            data_rows.append(list(self._lb_tree.item(item)['values']))
        return headers, data_rows

    def _lb_export_excel(self):
        """Export leave balance table to Excel."""
        if not self._ensure_excel():
            return
        headers, data_rows = self._lb_current_data()
        if not data_rows:
            messagebox.showwarning("Notice", "No data to export")
            return

        path = filedialog.asksaveasfilename(
            defaultextension=".xlsx",
            filetypes=[("Excel Files", "*.xlsx")],
            initialfile=f"Leave_Balance_{date.today().strftime('%Y%m%d')}.xlsx",
            title="Save Excel File"
        )
        if not path:
            return

        try:
            from openpyxl import Workbook as OWB
            from openpyxl.styles import Font as OFont, PatternFill as OFill, Alignment as OAlign, Border as OBorder, Side as OSide

            wb = OWB()
            ws = wb.active
            ws.title = "Leave Balance"
            # عرض الأعمدة بالاتجاه الطبيعي (يسار→يمين): Emp Code في العمود A على اليسار
            ws.sheet_view.rightToLeft = False

            # Title row
            ws.merge_cells(f'A1:{chr(64+len(headers))}1')
            t = ws['A1']
            t.value = f"Leave Balance Report — {date.today().strftime('%d/%m/%Y')}"
            t.font = OFont(name='Arial', bold=True, size=14, color='FFFFFF')
            t.fill = OFill("solid", start_color="6D28D9")
            t.alignment = OAlign(horizontal='center', vertical='center')
            ws.row_dimensions[1].height = 32

            # Header row
            side = OSide(style='thin', color='BDD7EE')
            border = OBorder(left=side, right=side, top=side, bottom=side)
            for ci, h in enumerate(headers, 1):
                c = ws.cell(row=2, column=ci, value=h)
                c.font = OFont(name='Arial', bold=True, color='FFFFFF', size=10)
                c.fill = OFill("solid", start_color="7C3AED")
                c.alignment = OAlign(horizontal='center', vertical='center', wrap_text=True)
                c.border = border
            ws.row_dimensions[2].height = 28

            # Data rows
            for ri, row in enumerate(data_rows, 3):
                alt = (ri % 2 == 0)
                for ci, val in enumerate(row, 1):
                    c = ws.cell(row=ri, column=ci, value=val)
                    c.font = OFont(name='Arial', size=10)
                    c.fill = OFill("solid", start_color="EDE9FE" if alt else "FFFFFF")
                    c.alignment = OAlign(horizontal='center', vertical='center')
                    c.border = border
                ws.row_dimensions[ri].height = 22

            # Column widths
            widths = [10,22,14,18,12,10,10,10,12,12,10,10,28]
            for ci, w in enumerate(widths, 1):
                ws.column_dimensions[chr(64+ci)].width = w

            wb.save(path)
            messagebox.showinfo("Done", f"Excel file saved:\n{path}")
        except Exception as e:
            messagebox.showerror("Error", f"فشل التصدير:\n{str(e)}")

    def _lb_export_pdf(self):
        """Export leave balance table to PDF."""
        if not PDF_AVAILABLE:
            messagebox.showerror("Error", "مكتبة reportlab not installedة.\nشغّل: pip install reportlab")
            return
        headers, data_rows = self._lb_current_data()
        if not data_rows:
            messagebox.showwarning("Notice", "No data to export")
            return

        path = filedialog.asksaveasfilename(
            defaultextension=".pdf",
            filetypes=[("PDF Files", "*.pdf")],
            initialfile=f"Leave_Balance_{date.today().strftime('%Y%m%d')}.pdf",
            title="Save PDF File"
        )
        if not path:
            return

        title = f"Leave Balance Report — {date.today().strftime('%d/%m/%Y')}"
        ok, msg = generate_pdf_report(title, headers, data_rows, path, orientation='landscape', paper='A3')
        if ok:
            messagebox.showinfo("Done", f"PDF file saved:\n{path}")
        else:
            messagebox.showerror("Error", msg)

