        # Approve Advance Button (HR role only)
        _adv_tree_ref = [None]  # filled after tree is created below

        def approve_selected_advance():
            t = _adv_tree_ref[0]
            if t is None:
                messagebox.showwarning("Warning", "Please select an advance to approve")
                return
            selection = t.selection()
            if not selection:
                messagebox.showwarning("Warning", "Please select an advance to approve")
                return
            advance_id = selection[0]
            adv = next((a for a in self.db.advances if a.advance_id == advance_id), None)
            if not adv:
                return
            if adv.status == "Approved":
                messagebox.showinfo("Info", f"Advance {advance_id} is already Approved")
                return
            _emp = self.db.get_employee(adv.emp_id)
            _emp_name = (_emp.name if _emp else adv.emp_id)
            confirm = messagebox.askyesno(
                "✅ Approve Advance",
                f"Approve advance {advance_id}?\n\nEmployee: {_emp_name}\nAmount: {adv.amount}"
            )
            if confirm:
                adv.status = "Approved"
                self.db.save_data()
                messagebox.showinfo("✅ Approved", f"Advance {advance_id} has been approved successfully.")
                self.show_advances_page()

