    def save_contract_and_refresh(self, emp_var, type_var, start_var, end_var, renewal_var, is_edit=False, edit_employee=None):
        if is_edit and edit_employee:
            emp = edit_employee
        else:
            if not emp_var.get():
                messagebox.showerror("Error", "Please select an employee")
                return
            emp_id = emp_var.get().split(" - ")[0]
            emp = self.db.get_employee(emp_id)

        if emp:
            emp.contract_type = type_var.get()
            emp.contract_start_date = parse_date_input(start_var.get())
            emp.contract_end_date = parse_date_input(end_var.get())
            emp.contract_renewal_date = parse_date_input(renewal_var.get())
            self.db.save_data()
            if is_edit:
                messagebox.showinfo("Success", "Contract updated successfully!")
            else:
                messagebox.showinfo("Success", "Contract added successfully!")
            self.show_contracts_page()

    def find_tree_in_frame(self, parent):
        """Recursively find Treeview widget"""
        if not parent:
            return None
        for widget in parent.winfo_children():
            try:
                if isinstance(widget, ttk.Treeview):
                    return widget
                if isinstance(widget, tk.Frame):
                    tree = self.find_tree_in_frame(widget)
                    if tree:
                        return tree
            except:
                pass
        return None

    def edit_contract(self):
        """Edit selected contract - opens the same add contract form"""
        tree = None

        for widget in self.content_frame.winfo_children():
            if isinstance(widget, ttk.Treeview):
                tree = widget
                break
            if isinstance(widget, tk.Frame):
                for child in widget.winfo_children():
                    if isinstance(child, ttk.Treeview):
                        tree = child
                        break
                    if isinstance(child, tk.Frame):
                        for grandchild in child.winfo_children():
                            if isinstance(grandchild, ttk.Treeview):
                                tree = grandchild
                                break
                        if tree:
                            break
                if tree:
                    break

        if not tree:
            for widget in self.content_frame.winfo_children():
                try:
                    for child in widget.winfo_children():
                        try:
                            for grandchild in child.winfo_children():
                                if isinstance(grandchild, ttk.Treeview):
                                    tree = grandchild
                                    break
                            if tree:
                                break
                        except:
                            pass
                    if tree:
                        break
                except:
                    pass

        if not tree:
            messagebox.showwarning("Warning", "Please select an employee to edit contract")
            return

        selection = tree.selection()
        if not selection:
            messagebox.showwarning("Warning", "Please select an employee to edit contract")
            return

        values = tree.item(selection[0])['values']
        if not values:
            messagebox.showwarning("Warning", "Could not get employee data")
            return

        emp_id = str(values[0]).strip()

        emp = self.db.get_employee(emp_id)
        if not emp and emp_id.isdigit():
            emp = self.db.get_employee(emp_id.zfill(3))

        if emp:
            self.show_add_contract_page(edit_employee=emp)
        else:
            messagebox.showerror("Error", f"Employee {emp_id} not found")

    def delete_contract(self):
        """Delete selected contract from tree"""
        tree = None

        for widget in self.content_frame.winfo_children():
            if isinstance(widget, ttk.Treeview):
                tree = widget
                break
            if isinstance(widget, tk.Frame):
                for child in widget.winfo_children():
                    if isinstance(child, ttk.Treeview):
                        tree = child
                        break
                    if isinstance(child, tk.Frame):
                        for grandchild in child.winfo_children():
                            if isinstance(grandchild, ttk.Treeview):
                                tree = grandchild
                                break
                        if tree:
                            break
                if tree:
                    break

        if not tree:
            for widget in self.content_frame.winfo_children():
                try:
                    for child in widget.winfo_children():
                        try:
                            for grandchild in child.winfo_children():
                                if isinstance(grandchild, ttk.Treeview):
                                    tree = grandchild
                                    break
                            if tree:
                                break
                        except:
                            pass
                    if tree:
                        break
                except:
                    pass

        if not tree:
            messagebox.showwarning("Warning", "Please select an employee to delete contract")
            return

        selection = tree.selection()
        if not selection:
            messagebox.showwarning("Warning", "Please select an employee to delete contract")
            return

        values = tree.item(selection[0])['values']
        if not values:
            messagebox.showwarning("Warning", "Could not get employee data")
            return

        emp_id = str(values[0]).strip()

        emp = self.db.get_employee(emp_id)
        if not emp and emp_id.isdigit():
            emp = self.db.get_employee(emp_id.zfill(3))

        if emp:
            confirm = messagebox.askyesno("Confirm Delete", f"Are you sure you want to delete contract for {emp.name}?")
            if confirm:
                emp.contract_type = ""
                emp.contract_start_date = ""
                emp.contract_end_date = ""
                emp.contract_renewal_date = ""
                self.db.save_data()
                messagebox.showinfo("Success", "Contract deleted!")
                self.show_contracts_page()
        else:
            messagebox.showerror("Error", f"Employee {emp_id} not found")

