        res_search_var = tk.StringVar()
        res_search_entry = tk.Entry(res_search_frame, textvariable=res_search_var,
                                    font=('Segoe UI', 11), relief=tk.FLAT, bd=0,
                                    bg=self.colors['white'], fg='#334155')
        res_search_entry.pack(side=tk.LEFT, fill=tk.X, expand=True, padx=(0, 10), pady=8)
