        def res_fi(e):
            if res_search_entry.get() == "Search by ID, name, department or reason...":
                res_search_entry.delete(0, tk.END); res_search_entry.config(fg='#334155')
        def res_fo(e):
            if not res_search_entry.get():
                res_search_entry.insert(0, "Search by ID, name, department or reason..."); res_search_entry.config(fg='#94A3B8')
        res_search_entry.bind('<FocusIn>', res_fi)
        res_search_entry.bind('<FocusOut>', res_fo)

        table_frame = tk.Frame(content, bg='white', relief=tk.RIDGE, bd=2)
        table_frame.pack(fill=tk.BOTH, expand=True)

        scroll_y = ttk.Scrollbar(table_frame)
        scroll_y.pack(side=tk.RIGHT, fill=tk.Y)

        scroll_x = ttk.Scrollbar(table_frame, orient=tk.HORIZONTAL)
        scroll_x.pack(side=tk.BOTTOM, fill=tk.X)

        columns = ("emp_id", "name", "dept", "position", "salary", "leaves", "hire_date", "resignation_date", "reason")
        tree = ttk.Treeview(table_frame, columns=columns, show='headings',
                           yscrollcommand=scroll_y.set, xscrollcommand=scroll_x.set)
        tree.pack(fill=tk.BOTH, expand=True)

        scroll_y.config(command=tree.yview)
        scroll_x.config(command=tree.xview)

        tree.heading("emp_id", text="ID")
        tree.heading("name", text="Employee Name")
        tree.heading("dept", text="Department")
        tree.heading("position", text="Position")
        tree.heading("salary", text="Salary")
        tree.heading("leaves", text="Leaves")
        tree.heading("hire_date", text="Hire Date")
        tree.heading("resignation_date", text="Resignation Date")
        tree.heading("reason", text="Reason")

        tree.column("emp_id", width=50, anchor=tk.CENTER)
        tree.column("name", width=130, anchor=tk.CENTER)
        tree.column("dept", width=100, anchor=tk.CENTER)
        tree.column("position", width=100, anchor=tk.CENTER)
        tree.column("salary", width=80, anchor=tk.CENTER)
        tree.column("leaves", width=60, anchor=tk.CENTER)
        tree.column("hire_date", width=85, anchor=tk.CENTER)
        tree.column("resignation_date", width=100, anchor=tk.CENTER)
        tree.column("reason", width=150, anchor=tk.CENTER)

        def res_load_table(*args):
            q = res_search_var.get().strip().lower()
            if q != "search by id, name, department or reason...":
                self._res_search_text = q
            if q == "search by id, name, department or reason...":
                q = ""
            for row in tree.get_children():
                tree.delete(row)
            def _sort_key(item):
                try:
                    return datetime.strptime(str((item[1].get("employee") or {}).get("resignation_date", "")), "%d/%m/%Y")
                except ValueError:
                    return datetime.min
            for emp_id, entry in sorted((getattr(self.db, "archived_employees", {}) or {}).items(), key=_sort_key, reverse=True):
                emp = Employee.from_dict(entry.get("employee", {}))
                dept = self.db.departments.get(emp.department)
                dept_name = dept.name if dept else (emp.department or "N/A")
                leave_balance_str = entry.get("leave_summary", "N/A")
                if q and q not in str(emp.emp_id).lower() and q not in (emp.name or "").lower() \
                        and q not in dept_name.lower() and q not in (emp.resignation_reason or "").lower():
                    continue
                tree.insert("", tk.END, values=(
                    emp.emp_id, emp.name, dept_name, emp.position,
                    f"{float(emp.salary or 0):,.2f}", leave_balance_str,
                    emp.hire_date, emp.resignation_date,
                    emp.resignation_reason or "N/A"
                ))

        res_search_var.trace('w', res_load_table)
        if _restore_search:
            res_search_var.set(_restore_search)
        res_load_table()

