        _res_code_e.grid(row=1, column=1, sticky='w', padx=12, pady=8)

        emp_info_frm = tk.Frame(inner_form, bg='#F0FDF4',
                                highlightbackground='#86EFAC', highlightthickness=1)
        emp_info_frm.grid(row=2, column=0, columnspan=2, sticky='ew', pady=6)
