        csv_btn.pack(side=tk.LEFT, padx=5)

        # Settings frame
        settings_frame = tk.Frame(toolbar, bg='white')
        settings_frame.pack(side=tk.LEFT, padx=30)

        tk.Label(settings_frame, text="⚙️ Settings:", font=('Segoe UI', 10, 'bold'), bg='white', fg='#374151').pack(side=tk.LEFT, padx=5)

        orient_var = tk.StringVar(value="Landscape")
        orient_combo = ttk.Combobox(settings_frame, textvariable=orient_var, values=["Landscape", "Portrait"],
                                    state='readonly', width=11, font=('Segoe UI', 10))
        orient_combo.pack(side=tk.LEFT, padx=5)

        paper_var = tk.StringVar(value="A4")
        paper_combo = ttk.Combobox(settings_frame, textvariable=paper_var, values=["A4", "A3", "Letter", "Legal"],
                                   state='readonly', width=8, font=('Segoe UI', 10))
        paper_combo.pack(side=tk.LEFT, padx=5)

        # Close button
