    def display_report(self, report_type):
        """Display professional report - date range filter + table + 3 export buttons"""
        self.clear_content()

        config = self.get_professional_report_config(report_type)
        if not config:
            return

        color = config.get("color", self.colors['primary'])

        # ── Header bar ──────────────────────────────────────────────────────────
        header = tk.Frame(self.content_frame, bg=color, height=90)
        header.pack(fill=tk.X)
        header.pack_propagate(False)

        tk.Button(header, text="← Back", font=('Segoe UI', 9, 'bold'),
                  bg='white', fg=color, relief=tk.FLAT, padx=12, pady=6,
                  command=self.show_reports_page).pack(side=tk.LEFT, padx=18, pady=22)

        tk.Label(header, text=f"{config.get('icon','📊')}  {config.get('title','Report')}",
                 font=('Segoe UI', 22, 'bold'), bg=color, fg='white').pack(side=tk.LEFT, padx=8, pady=22)

        # 3 export buttons (right side)
        btn_frame = tk.Frame(header, bg=color)
        btn_frame.pack(side=tk.RIGHT, padx=18, pady=22)

        def do_print():
            self._report_print(report_type, tree)

        def do_pdf():
            self._report_export_pdf(report_type, tree, config)

        def do_excel():
            self._report_export_excel(report_type, tree, config)

        tk.Button(btn_frame, text="🖨️ Print",  font=('Segoe UI', 9, 'bold'),
                  bg='#F59E0B', fg='white', relief=tk.FLAT, padx=16, pady=6,
                  command=do_print).pack(side=tk.LEFT, padx=4)
        tk.Button(btn_frame, text="📄 PDF",   font=('Segoe UI', 9, 'bold'),
                  bg='#EF4444', fg='white', relief=tk.FLAT, padx=16, pady=6,
                  command=do_pdf).pack(side=tk.LEFT, padx=4)
        tk.Button(btn_frame, text="📊 Excel", font=('Segoe UI', 9, 'bold'),
                  bg='#22C55E', fg='white', relief=tk.FLAT, padx=16, pady=6,
                  command=do_excel).pack(side=tk.LEFT, padx=4)

        # ── Filter bar ──────────────────────────────────────────────────────────
        filter_outer = tk.Frame(self.content_frame, bg='white',
                                highlightbackground='#E2E8F0', highlightthickness=1)
        filter_outer.pack(fill=tk.X, padx=20, pady=(12, 0))

        inner = tk.Frame(filter_outer, bg='white', padx=16, pady=10)
        inner.pack(fill=tk.X)

        today = date.today()
        _date_ph = today.strftime("%d/%m/%Y")   # نص إرشادي: تاريخ اليوم
        from_var = tk.StringVar(value=_date_ph)
        to_var   = tk.StringVar(value=_date_ph)
        search_var = tk.StringVar(value="")

        # حالة التلميح (placeholder) لكل حقل تاريخ:
        #   True  = الحقل يعرض تاريخ اليوم كتلميح فقط (لا يُستخدم في التصفية)
        #   False = المستخدم كتب تاريخًا فعليًا يُستخدم في التصفية
        _date_ph_state = {"from": True, "to": True}
        _PH_FG, _REAL_FG = '#94A3B8', '#1E293B'

        def _make_date_placeholder(entry, var, key):
            """يعرض تاريخ اليوم بلون باهت داخل الحقل، ويُمسح تلقائيًا عند الكتابة."""
            entry.config(fg=_PH_FG)
            def _on_focus_in(_e=None):
                if _date_ph_state.get(key):
                    _date_ph_state[key] = False
                    var.set("")
                    entry.config(fg=_REAL_FG)
            def _on_focus_out(_e=None):
                if not var.get().strip():
                    _date_ph_state[key] = True
                    var.set(_date_ph)
                    entry.config(fg=_PH_FG)
                else:
                    entry.config(fg=_REAL_FG)
            entry.bind("<FocusIn>", _on_focus_in)
            entry.bind("<FocusOut>", _on_focus_out)

        tk.Label(inner, text="📅 From:", font=('Segoe UI', 9, 'bold'),
                 bg='white', fg='#1E293B').pack(side=tk.LEFT, padx=(0, 4))
        from_entry = tk.Entry(inner, textvariable=from_var, font=('Segoe UI', 11),
                 width=12, relief=tk.SOLID, bd=1)
        from_entry.pack(side=tk.LEFT, padx=(0, 12))
        _make_date_placeholder(from_entry, from_var, "from")

        tk.Label(inner, text="To:", font=('Segoe UI', 9, 'bold'),
                 bg='white', fg='#1E293B').pack(side=tk.LEFT, padx=(0, 4))
        to_entry = tk.Entry(inner, textvariable=to_var, font=('Segoe UI', 11),
                 width=12, relief=tk.SOLID, bd=1)
        to_entry.pack(side=tk.LEFT, padx=(0, 12))
        _make_date_placeholder(to_entry, to_var, "to")

        tk.Label(inner, text="(dd/mm/yyyy)", font=('Segoe UI', 9),
                 bg='white', fg='#94A3B8').pack(side=tk.LEFT, padx=(0, 18))

        # ── Month/Year selector for the per-department Excel export (attendance) ──
        if report_type == "attendance":
            _months_lbl = ["All", "January", "February", "March", "April", "May", "June",
                           "July", "August", "September", "October", "November", "December"]
            _cy = date.today().year
            self._rep_att_month_var = tk.StringVar(value=_months_lbl[date.today().month])
            self._rep_att_year_var = tk.StringVar(value=str(_cy))

            sep0 = tk.Frame(inner, bg='#E2E8F0', width=1)
            sep0.pack(side=tk.LEFT, fill=tk.Y, padx=(0, 12), pady=2)
            tk.Label(inner, text="📊 Export Month:", font=('Segoe UI', 9, 'bold'),
                     bg='white', fg='#1E293B').pack(side=tk.LEFT, padx=(0, 4))
            ttk.Combobox(inner, textvariable=self._rep_att_month_var, values=_months_lbl,
                         font=('Segoe UI', 10), width=11, state='readonly').pack(side=tk.LEFT, padx=(0, 6))
            ttk.Combobox(inner, textvariable=self._rep_att_year_var,
                         values=[str(y) for y in range(_cy - 5, _cy + 2)],
                         font=('Segoe UI', 10), width=7, state='readonly').pack(side=tk.LEFT, padx=(0, 18))

        # Search box for all reports
        tk.Label(inner, text="🔍 Search:", font=('Segoe UI', 9, 'bold'),
                 bg='white', fg='#1E293B').pack(side=tk.LEFT, padx=(0, 4))
        search_entry = tk.Entry(inner, textvariable=search_var, font=('Segoe UI', 11),
                 width=20, relief=tk.SOLID, bd=1)
        search_entry.pack(side=tk.LEFT, padx=(0, 4))
        tk.Label(inner, text="Name / ID / Dept", font=('Segoe UI', 8),
                 bg='white', fg='#94A3B8').pack(side=tk.LEFT, padx=(0, 12))

        count_var = tk.StringVar(value="")
        tk.Label(inner, textvariable=count_var, font=('Segoe UI', 10, 'bold'),
                 bg='white', fg='#475569').pack(side=tk.RIGHT, padx=8)

        # ── Totals footer (shows total work hours for the Attendance report) ────
        footer_bar = tk.Frame(self.content_frame, bg='#F1F5F9')
        footer_bar.pack(side=tk.BOTTOM, fill=tk.X)
        total_var = tk.StringVar(value="")
        total_lbl = tk.Label(footer_bar, textvariable=total_var,
                             font=('Segoe UI', 12, 'bold'),
                             bg='#F1F5F9', fg=color, anchor='e', padx=24, pady=12)

        # ── Treeview ────────────────────────────────────────────────────────────
        table_outer = tk.Frame(self.content_frame, bg='white')
        table_outer.pack(fill=tk.BOTH, expand=True, padx=20, pady=(0, 16))

        columns = tuple(config["columns"])
        style = ttk.Style()
        style.configure("Report.Treeview",
                        font=('Segoe UI', 10), rowheight=36,
                        background='white', foreground='#1E293B',
                        fieldbackground='white')
        style.configure("Report.Treeview.Heading",
                        font=('Segoe UI', 9, 'bold'), padding=8)
        style.map("Report.Treeview",
                  background=[('selected', color)],
                  foreground=[('selected', 'white')])

        tree = ttk.Treeview(table_outer, columns=columns,
                            show='headings', style="Report.Treeview")

        for col, width in zip(config["columns"], config["widths"]):
            tree.heading(col, text=col)
            tree.column(col, width=width, anchor=tk.CENTER, minwidth=60)

        vsb = ttk.Scrollbar(table_outer, orient=tk.VERTICAL,   command=tree.yview)
        hsb = ttk.Scrollbar(table_outer, orient=tk.HORIZONTAL, command=tree.xview)
        tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)

        vsb.pack(side=tk.RIGHT,  fill=tk.Y)
        hsb.pack(side=tk.BOTTOM, fill=tk.X)
        tree.pack(side=tk.LEFT,  fill=tk.BOTH, expand=True)

        # ── Helper: flexible date parsing ────────────────────────────────────
        def _parse(s):
            if not s:
                return None
            s = s.strip()
            for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y", "%Y/%m/%d",
                        "%-d/%-m/%Y", "%d/%m/%y", "%Y-%m-%d"):
                try:
                    return datetime.strptime(s, fmt).date()
                except (ValueError, TypeError):
                    pass
            # Handle single-digit day/month like "1/1/2026" or "2026/10/1"
            parts = s.replace('-', '/').split('/')
            if len(parts) == 3:
                try:
                    p0, p1, p2 = int(parts[0]), int(parts[1]), int(parts[2])
                    # yyyy/mm/dd if first part is 4 digits
                    if p0 > 1900:
                        return date(p0, p1, p2)
                    # dd/mm/yyyy if last part is 4 digits
                    elif p2 > 1900:
                        return date(p2, p1, p0)
                except (ValueError, TypeError):
                    pass
            return None

        def _in_range(date_str, d_from, d_to):
            """True when date is within [d_from, d_to] (inclusive). None dates pass."""
            if d_from is None and d_to is None:
                return True
            d = _parse(date_str)
            if d is None:
                return True          # keep records with unknown dates
            if d_from and d < d_from:
                return False
            if d_to   and d > d_to:
                return False
            return True

        # ── Apply filter ─────────────────────────────────────────────────────
        def apply_filter():
            # تجاهل تاريخ اليوم الإرشادي (placeholder) حتى لا يُصفّى السجل افتراضيًا
            _from_raw = "" if _date_ph_state.get("from") else from_var.get().strip()
            _to_raw   = "" if _date_ph_state.get("to")   else to_var.get().strip()
            d_from = _parse(_from_raw)
            d_to   = _parse(_to_raw)
            search_term = search_var.get().strip().lower()

            rows = []
            att_total_hours = 0.0   # sum of work hours (attendance report)
            att_hours_days  = 0     # number of days that have work hours

            if report_type == "employees":
                for emp in self.db.employees.values():
                    if not _in_range(emp.hire_date, d_from, d_to):
                        continue
                    dept = self.db.departments.get(emp.department)
                    dept_name = dept.name if dept else "N/A"
                    if search_term:
                        searchable = f"{emp.emp_id} {emp.name} {dept_name}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((emp.emp_id, emp.name,
                                 dept_name,
                                 emp.position, f"{float(emp.salary or 0):,.2f}", emp.hire_date))

            elif report_type == "departments":
                for dept in self.db.departments.values():
                    mgr = self.db.employees.get(dept.manager_id)
                    cnt = sum(1 for e in self.db.employees.values()
                              if e.department == dept.dept_id)
                    if search_term:
                        searchable = f"{dept.dept_id} {dept.name} {mgr.name if mgr else ''}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((dept.dept_id, dept.name,
                                 mgr.name if mgr else "N/A", cnt))

            elif report_type == "attendance":
                def _emp_sort(eid):
                    try:
                        return (0, int(eid))
                    except (ValueError, TypeError):
                        return (1, str(eid))
                for att in sorted(self.db.attendance,
                                  key=lambda a: (_emp_sort(a.emp_id), a.date_key())):
                    if not _in_range(att.date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(att.emp_id)
                    dept = self.db.departments.get(emp.department) if emp else None
                    dept_name = dept.name if dept else "N/A"
                    work_hours = att.get_duration() if att.check_in and att.check_out else "-"
                    # search filter
                    if search_term:
                        searchable = f"{att.emp_id} {emp.name if emp else ''} {dept_name}".lower()
                        if search_term not in searchable:
                            continue
                    # accumulate work hours for the totals footer
                    h = att.get_duration_hours()
                    if h > 0:
                        att_total_hours += h
                        att_hours_days += 1
                    rows.append((att.emp_id,
                                 (emp.name if emp else "N/A"),
                                 dept_name,
                                 att.date,
                                 Attendance.to_24h(att.check_in)  if att.check_in  else "-",
                                 Attendance.to_24h(att.check_out) if att.check_out else "-",
                                 work_hours,
                                 self.db.get_attendance_display_status(att)))

            elif report_type == "leaves":
                for lv in self.db.leaves:
                    if not _in_range(lv.start_date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(lv.emp_id)
                    dept = self.db.departments.get(emp.department) if emp else None
                    if search_term:
                        searchable = f"{lv.emp_id} {emp.name if emp else ''} {dept.name if dept else ''}".lower()
                        if search_term not in searchable:
                            continue
                    try:
                        s  = _parse(lv.start_date)
                        e_ = _parse(lv.end_date)
                        leave_days_count = (e_ - s).days + 1 if s and e_ else ""
                    except Exception:
                        leave_days_count = ""
                    rows.append((lv.leave_id, lv.emp_id,
                                 (emp.name if emp else "N/A"),
                                 lv.leave_type, lv.start_date,
                                 lv.end_date, leave_days_count, lv.status))

            elif report_type == "payroll":
                for p in self.db.payrolls:
                    emp = self.db.employees.get(p.emp_id)
                    dept = self.db.departments.get(emp.department) if emp else None
                    if search_term:
                        searchable = f"{p.emp_id} {emp.name if emp else ''} {dept.name if dept else ''}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((p.payroll_id, p.emp_id,
                                 (emp.name if emp else "N/A"),
                                 p.month, p.year,
                                 f"{p.basic_salary:,.2f}",
                                 f"{p.allowances:,.2f}",
                                 f"{p.net_salary:,.2f}"))

            elif report_type == "advances":
                for adv in self.db.advances:
                    if not _in_range(adv.date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(adv.emp_id)
                    dept = self.db.departments.get(emp.department) if emp else None
                    if search_term:
                        searchable = f"{adv.emp_id} {emp.name if emp else ''} {dept.name if dept else ''}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((adv.advance_id, adv.emp_id,
                                 (emp.name if emp else "N/A"),
                                 f"{adv.amount:,.2f}", adv.date, adv.status))

            elif report_type == "cl_staff":
                for cl in self.db.cl_staff:
                    if not _in_range(cl.date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(cl.emp_id)
                    dept = self.db.departments.get(emp.department) if emp else None
                    if search_term:
                        searchable = f"{cl.emp_id} {emp.name if emp else ''} {dept.name if dept else ''}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((cl.cl_id, cl.emp_id,
                                 (emp.name if emp else "N/A"),
                                 dept.name if dept else "N/A",
                                 f"{cl.amount:,.2f}", cl.date, cl.status))

            elif report_type == "penalties":
                for pen in self.db.penalties:
                    if not _in_range(pen.date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(pen.emp_id)
                    dept = self.db.departments.get(emp.department) if emp else None
                    dept_name_p = dept.name if dept else (
                        next((d.name for d in self.db.departments.values()
                              if d.name == (emp.department if emp else '') or
                              d.dept_id == (emp.department if emp else '')), 
                             emp.department if emp else "N/A") if emp else "N/A")
                    if search_term:
                        searchable = f"{pen.emp_id} {emp.name if emp else ''} {dept_name_p}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((pen.penalty_id, pen.emp_id,
                                 (emp.name if emp else "N/A"),
                                 f"{pen.amount:,.2f}", pen.date,
                                 pen.reason, pen.status))

            elif report_type == "birthdays":
                cy = date.today().year
                today_d = date.today()
                for emp in self.db.employees.values():
                    dept = self.db.departments.get(emp.department)
                    dept_name = dept.name if dept else "N/A"
                    if search_term:
                        searchable = f"{emp.emp_id} {emp.name} {dept_name}".lower()
                        if search_term not in searchable:
                            continue
                    bd = _parse(emp.birth_date)
                    if bd:
                        age = cy - bd.year
                        try:
                            next_bd = bd.replace(year=cy)
                        except ValueError:
                            next_bd = date(cy, 3, 1)
                        if next_bd < today_d:
                            try:
                                next_bd = bd.replace(year=cy + 1)
                            except ValueError:
                                next_bd = date(cy + 1, 3, 1)
                        days = (next_bd - today_d).days
                        display_date = emp.birth_date
                    else:
                        age = "—"
                        days = 9999  # يظهر في النهاية
                        display_date = emp.birth_date or "—"
                    rows.append((emp.emp_id, emp.name,
                                 dept_name,
                                 display_date, age, days))
                # ترتيب تلقائي: من عيد ميلاده اليوم أولاً، ثم الأقرب، من لا تاريخ له في النهاية
                rows.sort(key=lambda r: r[5] if isinstance(r[5], int) else 9999)

            elif report_type == "contracts":
                for emp in self.db.employees.values():
                    if not (emp.contract_type or emp.contract_start_date):
                        continue
                    if not _in_range(emp.contract_start_date, d_from, d_to):
                        continue
                    dept = self.db.departments.get(emp.department)
                    dept_name = dept.name if dept else "N/A"
                    if search_term:
                        searchable = f"{emp.emp_id} {emp.name} {dept_name}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((emp.emp_id, emp.name,
                                 dept_name,
                                 emp.contract_type or "N/A",
                                 format_date_display(emp.contract_start_date) or "N/A",
                                 format_date_display(emp.contract_end_date)   or "N/A",
                                 format_date_display(emp.contract_renewal_date) or "N/A"))

            elif report_type == "resignations":
                for emp in self.db.employees.values():
                    if not emp.resignation_date:
                        continue
                    if not _in_range(emp.resignation_date, d_from, d_to):
                        continue
                    dept = self.db.departments.get(emp.department)
                    dept_name = dept.name if dept else "N/A"
                    if search_term:
                        searchable = f"{emp.emp_id} {emp.name} {dept_name}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((emp.emp_id, emp.name,
                                 dept_name,
                                 emp.position,
                                 format_date_display(emp.resignation_date),
                                 emp.resignation_reason or "N/A"))

            elif report_type == "monthly":
                all_rows = self.get_monthly_report_data()
                if search_term:
                    rows = [r for r in all_rows if search_term in f"{r[0]} {r[1]} {r[2]}".lower()]
                else:
                    rows = all_rows

            elif report_type == "evaluations":
                for ev in self.db.evaluations:
                    if not _in_range(ev.eval_date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(ev.emp_id)
                    dept_name = "N/A"
                    if emp and self.db.departments.get(emp.department):
                        dept_name = self.db.departments[emp.department].name
                    if search_term:
                        searchable = f"{ev.emp_id} {emp.name if emp else ''} {dept_name}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((ev.eval_id, ev.emp_id,
                                 (emp.name if emp else "N/A"),
                                 dept_name,
                                 ev.grade, f"{ev.get_percentage()}%",
                                 ev.eval_date, ev.eval_type, ev.comments))

            elif report_type == "change_of_status":
                for cos in self.db.change_of_status:
                    if not _in_range(cos.effective_date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(cos.emp_id)
                    if search_term:
                        dept = self.db.departments.get(emp.department) if emp else None
                        searchable = f"{cos.emp_id} {emp.name if emp else ''} {dept.name if dept else ''}".lower()
                        if search_term not in searchable:
                            continue
                    reason_parts = []
                    if cos.reason_transfer: reason_parts.append("Transfer")
                    if cos.reason_promotion: reason_parts.append("Promotion")
                    if cos.reason_increase: reason_parts.append("Increase")
                    reason = ", ".join(reason_parts) if reason_parts else "N/A"
                    rows.append((cos.cos_id, cos.emp_id,
                                 (emp.name if emp else "N/A"),
                                 cos.effective_date,
                                 cos.from_department, cos.from_position,
                                 f"{float(cos.from_salary):,.2f}" if cos.from_salary else "N/A",
                                 cos.to_department, cos.to_position,
                                 f"{float(cos.to_salary):,.2f}" if cos.to_salary else "N/A",
                                 reason, cos.notes or ""))

            elif report_type == "contract_renewals":
                for cr in self.db.contract_renewals:
                    if not _in_range(cr.renewal_date, d_from, d_to):
                        continue
                    emp = self.db.employees.get(cr.emp_id)
                    dept_name = "N/A"
                    if emp and self.db.departments.get(emp.department):
                        dept_name = self.db.departments[emp.department].name
                    if search_term:
                        searchable = f"{cr.emp_id} {emp.name if emp else ''} {dept_name}".lower()
                        if search_term not in searchable:
                            continue
                    rows.append((cr.renewal_id, cr.emp_id,
                                 (emp.name if emp else "N/A"),
                                 dept_name,
                                 format_date_display(cr.old_start) if cr.old_start else "N/A",
                                 format_date_display(cr.old_end) if cr.old_end else "N/A",
                                 format_date_display(cr.new_start) if cr.new_start else "N/A",
                                 format_date_display(cr.new_end) if cr.new_end else "N/A",
                                 format_date_display(cr.renewal_date) if cr.renewal_date else "N/A",
                                 cr.notes or ""))

            # fill treeview
            tree.delete(*tree.get_children())
            if report_type == "birthdays":
                tree.tag_configure('birthday_today',  background='#FCE7F3', foreground='#9D174D', font=('Segoe UI', 10, 'bold'))
                tree.tag_configure('birthday_soon',   background='#FEF9C3', foreground='#78350F')
                tree.tag_configure('birthday_normal', background='#F8FAFC')
                for row in rows:
                    days_left = row[5]  # عمود "Days Until Birthday"
                    if days_left == 0:
                        tag = 'birthday_today'
                        # أضف 🎂 بجانب الاسم إذا كان اليوم
                        row = (row[0], f"🎂 {row[1]}", row[2], row[3], row[4], "Today! 🎉")
                    elif days_left <= 7:
                        tag = 'birthday_soon'
                    else:
                        tag = 'birthday_normal'
                    tree.insert("", tk.END, values=row, tags=(tag,))
            else:
                for i, row in enumerate(rows):
                    tag = 'even' if i % 2 == 0 else 'odd'
                    tree.insert("", tk.END, values=row, tags=(tag,))
                tree.tag_configure('even', background='#F8FAFC')
                tree.tag_configure('odd',  background='white')
            count_var.set(f"Records: {len(rows)}")

            # ── Totals footer: total work hours for the Attendance report ──────
            if report_type == "attendance":
                th = int(att_total_hours)
                tm = int(round((att_total_hours - th) * 60))
                if tm == 60:
                    th += 1; tm = 0
                avg = round(att_total_hours / att_hours_days, 2) if att_hours_days else 0
                total_var.set(
                    f"🕒 Total Work Hours: {th}h {tm:02d}m   "
                    f"({att_total_hours:.2f} hrs)   |   Avg/Day: {avg} hrs"
                )
                total_lbl.pack(side=tk.RIGHT)
            else:
                total_var.set("")
                total_lbl.pack_forget()

        def safe_apply_filter():
            try:
                apply_filter()
            except Exception as _e:
                tree.delete(*tree.get_children())
                tree.insert("", tk.END, values=("⚠️ Error: " + str(_e),) + ("",) * (len(config["columns"]) - 1))
                count_var.set("Error loading data")

        # Apply button (after tree is defined)
        tk.Button(inner, text="🔍 Apply", font=('Segoe UI', 9, 'bold'),
                  bg=color, fg='white', relief=tk.FLAT, padx=18, pady=4,
                  command=safe_apply_filter).pack(side=tk.LEFT)

        # Bind Enter key on search/date fields
        search_var.trace_add("write", lambda *a: safe_apply_filter())
        from_var.trace_add("write", lambda *a: None)  # keep existing behaviour

        # load all data on open
        try:
            apply_filter()
        except Exception as _e:
            import traceback as _tb
            tree.insert("", tk.END, values=("⚠️ Error loading data: " + str(_e),) + ("",) * (len(config["columns"]) - 1))
            count_var.set("Error loading data")

    def _payroll_employees_sorted(self):
        """Employees eligible for the payroll / monthly salary report.

        Excludes employees whose salary is stopped (salary_active=False) AND
        employees who have resigned (resignation_date set) — a resigned
        employee is treated exactly like a stopped salary and never appears in
        the salaries report.

        Sorted by department, then by bank code in ascending order (numeric
        bank codes sort numerically; employees without a bank code sort last).
        """
        def _bank_key(e):
            bc = (getattr(e, 'bank_code', '') or '').strip()
            if bc:
                try:
                    return (0, int(bc), '')
                except (ValueError, TypeError):
                    return (1, 0, bc.lower())
            return (2, 0, '')

        def _included(e):
            if not getattr(e, 'salary_active', True):
                return False
            if (getattr(e, 'resignation_date', '') or '').strip():
                return False
            return True

        emps = [e for e in self.db.employees.values() if _included(e)]
        return sorted(emps, key=lambda e: ((e.department or ""), _bank_key(e)))

    def get_monthly_report_data(self, month=None, year=None):
        """Get monthly report data with service charge calculation - 17 columns
        month: int (1-12) or None for all months
        year:  int or None for all years
        """
        data = []
        self._last_report_emp_ids = []   # emp_id لكل صف (بنفس الترتيب) — تُستخدم لنشر قسائم الراتب للموبايل
        # Employees grouped by department, bank code ascending; excludes
        # salary-stopped and resigned employees.
        sorted_employees = self._payroll_employees_sorted()
        for emp in sorted_employees:
            # Skip employee if salary is stopped (موقف) or resigned (مستقيل)
            if not getattr(emp, 'salary_active', True):
                continue
            if (getattr(emp, 'resignation_date', '') or '').strip():
                continue
            dept_name = self.db.departments.get(emp.department, Department("", "N/A")).name if self.db.departments.get(emp.department) else "N/A"

            # Only include service charge if employee is eligible
            service_charge = emp.service_allowance if getattr(emp, 'service_charge_eligible', True) else 0
            salary_after_service = emp.salary + emp.transportation + emp.allowances + service_charge

            # --- Read tax/insurance status from employee data ---
            _raw_tis = (getattr(emp, 'tax_insurance_status', 'both') or 'both').strip().lower()
            _tis_map = {'both': 'both', 'tax only': 'tax_only', 'tax_only': 'tax_only',
                        'insurance only': 'insurance_only', 'insurance_only': 'insurance_only',
                        'neither': 'none', 'none': 'none'}
            tax_ins_status = _tis_map.get(_raw_tis, 'both')
            apply_insurance = tax_ins_status in ('both', 'insurance_only')
            apply_tax = tax_ins_status in ('both', 'tax_only')

            # Insurance - always uses the configured max base (11% of max)
            _s = getattr(self.db, 'insurance_settings', {"min": 2700, "max": 16700})
            _ins_max = float(_s.get("max", 16700) or 16700)
            _salary_raw = float(emp.salary or 0)
            insurance_base = min(_salary_raw, _ins_max)
            if apply_insurance:
                insurance = round(insurance_base * 0.11, 2)
                num_spouses = int(emp.number_of_spouses) if emp.number_of_spouses else 0
                num_children = int(emp.number_of_children) if emp.number_of_children else 0
                marital = (emp.marital_status or "Single").strip().lower()
                if marital in ("single",):
                    health_insurance = 0.0
                else:
                    health_insurance = round(insurance_base * (num_spouses * 0.03 + num_children * 0.01), 2)
            else:
                insurance = 0.0
                health_insurance = 0.0

            # Penalties: نوع Absence يرحل لعمود Absent، باقي الأنواع لعمود Penalty
            # الخصم الإضافي المتدرج للغياب (additional_penalty) يرحل لعمود Penalty
            # عند تحديد شهر/سنة تُفلتر السجلات حسب الدورة المالية (من 25 إلى 24)
            penalties = sum(
                p.amount for p in self.db.penalties
                if p.emp_id == emp.emp_id
                and p.status in ["Approved", "Confirmed", "confirmed", "Pending"]
                and (p.penalty_type or "").strip().lower() not in ("absence", "absence")
                and date_in_payroll_period(p.date, month, year)
            )
            # إضافة الخصم الإضافي المتدرج للغياب إلى عمود Penalty
            absence_additional_penalty = sum(
                float(getattr(p, 'additional_penalty', 0) or 0) for p in self.db.penalties
                if p.emp_id == emp.emp_id
                and p.status in ["Approved", "Confirmed", "confirmed", "Pending"]
                and (p.penalty_type or "").strip().lower() in ("absence", "absence")
                and date_in_payroll_period(p.date, month, year)
            )
            penalties = round(penalties + absence_additional_penalty, 2)

            absence_penalty = sum(
                p.amount for p in self.db.penalties
                if p.emp_id == emp.emp_id
                and p.status in ["Approved", "Confirmed", "confirmed", "Pending"]
                and (p.penalty_type or "").strip().lower() in ("absence", "absence")
                and date_in_payroll_period(p.date, month, year)
            )

            advances = sum(a.amount for a in self.db.advances
                         if a.emp_id == emp.emp_id and a.status in ["Approved", "Confirmed", "confirmed", "Pending"]
                         and date_in_payroll_period(a.date, month, year))

            custom_deductions = float(emp.deductions) if emp.deductions else 0

            # --- Absent deduction: emp.absent_deduction + جزاءات الabsence ---
            absent_deduction = float(getattr(emp, 'absent_deduction', 0) or 0) + absence_penalty

            # --- Sick Leave deduction: يُحسب من إجازات Month المحدد فقط ---
            # المعادلة: (Salary ÷ 30 ÷ 4) × عدد الأيام → يرحل لعمود Sick Leave
            # يطابق Doneاماً قيمة Total Cut في Employee Situations لنفس الموظف
            _sick_days = 0
            for _lv in self.db.leaves:
                if (_lv.emp_id == emp.emp_id
                        and _lv.leave_type in ("Sick", "Sick", "Sick Leave", "Medical")
                        and _lv.status in ("Approved", "Confirmed", "confirmed")
                        and _lv.start_date and _lv.end_date):
                    try:
                        _ls = datetime.strptime(_lv.start_date, "%d/%m/%Y").date()
                        _le = datetime.strptime(_lv.end_date,   "%d/%m/%Y").date()
                        # فلترة بالدورة المالية المحددة (من 25 إلى 24)
                        if month and year:
                            # احسب الأيام التي تقع داخل دورة الشهر المحدد فقط
                            _sick_days += leave_days_in_payroll_period(_ls, _le, month, year)
                        else:
                            _sick_days += (_le - _ls).days + 1
                    except:
                        pass
            _daily_rate = float(emp.salary) / 30 if emp.salary else 0
            sick_leave_deduction = round((_daily_rate / 4) * _sick_days, 2)

            # --- Unpaid Leave deduction: يُحسب من إجازات Month المحدد فقط ---
            # المعادلة: أجر الأيام (Salary ÷ 30 × الأيام) دائماً + حصتا التأمين
            #           (Salary × 29.75% ÷ 30 × الأيام) إن كان مؤمَّناً عليه → يرحل بالكامل لعمود Deductions
            _unpaid_days = 0
            for _lv in self.db.leaves:
                if (_lv.emp_id == emp.emp_id
                        and _lv.leave_type in ("Unpaid", "Unpaid")
                        and _lv.status in ("Approved", "Confirmed", "confirmed")
                        and _lv.start_date and _lv.end_date):
                    try:
                        _ls = datetime.strptime(_lv.start_date, "%d/%m/%Y").date()
                        _le = datetime.strptime(_lv.end_date,   "%d/%m/%Y").date()
                        if month and year:
                            _unpaid_days += leave_days_in_payroll_period(_ls, _le, month, year)
                        else:
                            _unpaid_days += (_le - _ls).days + 1
                    except:
                        pass
            # ── الإجازة غير المدفوعة ──────────────────────────────────────────
            #  • قيمة أيام الإجازة (أجر الأيام) تُخصم من الأساسي مباشرةً، فيُحسب
            #    "الإجمالي" على المتبقي من الأساسي (لذلك لا تُطرح مرة أخرى من الصافي
            #    ولا تظهر في عمود Deductions حتى لا تُخصم مرتين).
            #  • حصتا التأمين (29.75%) — للمؤمَّن عليهم فقط — هي وحدها التي تظهر في
            #    عمود Deductions وتُطرح من الصافي.
            _unpaid_day_value = 0.0   # أجر أيام الإجازة من الأساسي (مخصوم من الأساسي مباشرةً)
            _unpaid_ins       = 0.0   # حصتا التأمين عن أيام الإجازة (للمؤمَّن عليهم)
            if emp.salary and _unpaid_days:
                _basic            = float(emp.salary)
                _unpaid_day_value = (_basic / 30) * _unpaid_days
                _unpaid_ins       = (_basic * 0.2975 / 30) * _unpaid_days if apply_insurance else 0.0
            # عمود Deductions: حصتا التأمين فقط (أجر الأيام مخصوم من الأساسي بالفعل)
            unpaid_deduction = round(_unpaid_ins, 2)

            # الإجمالي يُحسب على المتبقي من الأساسي بعد خصم أيام الإجازة:
            #   المتبقي = الأساسي − أجر الأيام،  والخدمة = المتبقي × نسبة الخدمة الحالية
            #   الإجمالي = المتبقي + النقل + البدلات + الخدمة
            # مثال: أساسي 6420، 10 أيام، نسبة خدمة 1 → المتبقي 4280، الخدمة 4280، الإجمالي 8560
            if _unpaid_days and emp.salary:
                _basic           = float(emp.salary)
                _remaining_basic = max(0.0, _basic - _unpaid_day_value)      # المتبقي من الأساسي
                if service_charge:
                    _service_rate = service_charge / _basic                  # نسبة الخدمة كما هي موجودة الآن
                    service_charge = round(_remaining_basic * _service_rate, 2)
                salary_after_service = _remaining_basic + emp.transportation + emp.allowances + service_charge

                # ── في حالة الإجازة غير المدفوعة: يُعاد حساب التأمين (11%) والتأمين
                #    الصحي والضريبة على أساس المتبقي من الأساسي (وليس الأساسي الكامل) ──
                #    مثال: أساسي 6420 و10 أيام → المتبقي 4280 → التأمين = 4280 × 11% = 470.80
                if apply_insurance:
                    _ins_base_eff = min(_remaining_basic, _ins_max)
                    insurance = round(_ins_base_eff * 0.11, 2)
                    _marital_l = (emp.marital_status or "Single").strip().lower()
                    if _marital_l in ("single",):
                        health_insurance = 0.0
                    else:
                        _ns = int(emp.number_of_spouses) if emp.number_of_spouses else 0
                        _nc = int(emp.number_of_children) if emp.number_of_children else 0
                        health_insurance = round(_ins_base_eff * (_ns * 0.03 + _nc * 0.01), 2)



            # --- Insurance Sick Leave: يُحسب من السجلات — (Salary ÷ 30) × الأيام ---
            # يرحل إلى Deductions في Monthly Report
            _ins_sick_days = 0
            for _lv in self.db.leaves:
                if (_lv.emp_id == emp.emp_id
                        and _lv.leave_type in ("Insurance Sick Leave", "Insurance Sick Leave")
                        and _lv.status in ("Approved", "Confirmed", "confirmed")
                        and _lv.start_date and _lv.end_date):
                    try:
                        _ls = datetime.strptime(_lv.start_date, "%d/%m/%Y").date()
                        _le = datetime.strptime(_lv.end_date,   "%d/%m/%Y").date()
                        if month and year:
                            _ins_sick_days += leave_days_in_payroll_period(_ls, _le, month, year)
                        else:
                            _ins_sick_days += (_le - _ls).days + 1
                    except:
                        pass
            ins_sick_deduction = round((float(emp.salary) / 30) * _ins_sick_days, 2) if emp.salary and _ins_sick_days else 0

            cl_staff = sum(c.amount for c in self.db.cl_staff if c.emp_id == emp.emp_id and c.status in ["Approved", "Confirmed", "confirmed", "Pending"] and date_in_payroll_period(c.date, month, year)); total_deductions = round(custom_deductions + unpaid_deduction + ins_sick_deduction, 2)

            # Tax - only if employee pays tax
            if apply_tax:
                taxable = salary_after_service - insurance - 5000
                tax = 0
                if taxable > 0:
                    if taxable <= 1250:
                        tax = taxable * 0.10
                    elif taxable <= 2500:
                        tax = 125 + (taxable - 1250) * 0.15
                    else:
                        tax = 125 + 187.5 + (taxable - 2500) * 0.20
            else:
                tax = 0.0

            # الصافي: أجر أيام الإجازة غير المدفوعة مخصوم بالفعل من الإجمالي
            # (المتبقي من الأساسي)، ولم يَعُد ضمن عمود Deductions، لذا نطرح
            # إجمالي الخصومات كما هو (الخصومات المخصصة + حصتا التأمين عن الإجازة
            # + إجازة التأمين المرضية) دون أي تعديل:
            _net_deductions = round(total_deductions, 2)
            net = round_to_nearest_5(salary_after_service - insurance - health_insurance
                   - penalties - absent_deduction - sick_leave_deduction
                   - advances - cl_staff - _net_deductions - tax)

            # Use bank_code if available, otherwise fall back to emp_id
            display_code = getattr(emp, 'bank_code', '') or emp.emp_id
            self._last_report_emp_ids.append(emp.emp_id)
            data.append((
                display_code,
                emp.name,
                dept_name,
                f"{emp.salary:.2f}",
                f"{emp.transportation:.2f}",
                f"{emp.allowances:.2f}",
                f"{round(service_charge, 2):.2f}",
                f"{round(salary_after_service, 2):.2f}",
                f"{round(insurance, 2):.2f}",
                f"{round(health_insurance, 2):.2f}",
                f"{round(penalties, 2):.2f}",
                f"{round(absent_deduction, 2):.2f}",
                f"{round(sick_leave_deduction, 2):.2f}",
                f"{round(advances, 2):.2f}",
                f"{round(total_deductions, 2):.2f}",
                f"{round(cl_staff, 2):.2f}",
                f"{round(tax, 2):.2f}",
                f"{round(net, 2):.2f}"
            ))
        return data

    # ── Report export helpers (use live tree data) ─────────────────────────

    def _report_print(self, report_type, tree):
        """Print report via PDF -> system print dialog"""
        import tempfile, os
        tmp = tempfile.NamedTemporaryFile(suffix=".pdf", delete=False)
        tmp.close()
        ok, msg = self._write_tree_pdf(report_type, tree, tmp.name)
        if ok:
            try:
                os.startfile(tmp.name, "print")
                messagebox.showinfo("Print", "Sent to printer ✅")
            except Exception as e:
                messagebox.showerror("Print Error", str(e))
        else:
            messagebox.showerror("Error", msg)

    def _report_export_pdf(self, report_type, tree, config):
        """Export tree data to PDF — user chooses location"""
        import os
        name = config.get("filename", report_type) + ".pdf"
        path = ask_save_path(name, "حفظ التقرير PDF / Save Report")
        if not path:
            return
        ok, msg = self._write_tree_pdf(report_type, tree, path)
        if ok:
            try:
                os.startfile(path)
            except Exception:
                pass
            messagebox.showinfo("PDF Saved", f"✅ تم الحفظ / Saved:\n{path}")
        else:
            messagebox.showerror("PDF Error", msg)

    def _report_export_excel(self, report_type, tree, config):
        """Export tree data to Excel — user chooses location"""
        import os

        # Attendance report → export as per-department grid (In/Out per day,
        # one sheet per department), matching the standard layout.
        if report_type == "attendance":
            # Prefer the inline Month/Year selector on the report page; fall back
            # to the popup dialog if it isn't available.
            month = year = None
            mvar = getattr(self, "_rep_att_month_var", None)
            yvar = getattr(self, "_rep_att_year_var", None)
            if mvar is not None and yvar is not None:
                _month_map = {"January": 1, "February": 2, "March": 3, "April": 4,
                              "May": 5, "June": 6, "July": 7, "August": 8,
                              "September": 9, "October": 10, "November": 11, "December": 12}
                mname = mvar.get()
                month = "All" if mname == "All" else _month_map.get(mname, 1)
                year = yvar.get()
            else:
                month, year = get_month_year_filter_gui(self.root)
            if month is None or not year:
                return
            mtag = f"{month}_{year}" if month != "All" else f"{year}"
            path = ask_save_path(f"Attendance_By_Department_{mtag}.xlsx", "حفظ التقرير Excel / Save Report")
            if not path:
                return
            ok, msg = self._export_attendance_by_department_excel(month, year, path)
            if ok:
                try:
                    os.startfile(path)
                except Exception:
                    pass
                messagebox.showinfo("Excel Saved", f"✅ تم الحفظ / Saved:\n{path}")
            else:
                messagebox.showerror("Excel Error", msg)
            return

        name = config.get("filename", report_type) + ".xlsx"
        path = ask_save_path(name, "حفظ التقرير Excel / Save Report")
        if not path:
            return
        ok, msg = self._write_tree_excel(report_type, tree, path, config)
        if ok:
            try:
                os.startfile(path)
            except Exception:
                pass
            messagebox.showinfo("Excel Saved", f"✅ تم الحفظ / Saved:\n{path}")
        else:
            messagebox.showerror("Excel Error", msg)

    def _tree_rows(self, tree):
        """Return all visible rows from treeview as list of tuples"""
        return [tree.item(iid)['values'] for iid in tree.get_children()]

    def _write_tree_pdf(self, report_type, tree, path):
        """Write current tree data to PDF file"""
        if not PDF_AVAILABLE:
            return False, "reportlab not installed.\nRun: pip install reportlab"
        try:
            from reportlab.lib import colors as rl_colors
            from reportlab.lib.pagesizes import A4, landscape
            from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph as rl_Paragraph, Spacer
            from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
            from reportlab.lib.enums import TA_CENTER

            config = self.get_professional_report_config(report_type)
            headers = config.get("columns", [])
            rows = self._tree_rows(tree)

            doc = SimpleDocTemplate(path, pagesize=landscape(A4),
                                    leftMargin=30, rightMargin=30,
                                    topMargin=30, bottomMargin=30)
            styles = getSampleStyleSheet()
            elems = []
            add_logo_to_pdf(elems)

            title_style = ParagraphStyle('T', fontSize=18, fontName='Helvetica-Bold',
                                         textColor=rl_colors.HexColor('#1E3A5F'),
                                         alignment=TA_CENTER, spaceAfter=4)
            sub_style = ParagraphStyle('S', fontSize=10,
                                       textColor=rl_colors.HexColor('#64748B'),
                                       alignment=TA_CENTER, spaceAfter=16)

            elems.append(Paragraph("MODO HR", title_style))
            elems.append(Paragraph(config.get("title", report_type), sub_style))
            elems.append(Paragraph(
                f"Generated: {datetime.now().strftime('%d/%m/%Y  %H:%M')}  |  Records: {len(rows)}",
                sub_style))
            elems.append(Spacer(1, 8))

            table_data_raw = [headers] + [[str(v) for v in r] for r in rows]
            avail = doc.pagesize[0] - 60
            col_w = avail / max(len(headers), 1)

            # Wrap every cell in Paragraph to avoid NoneType comparison errors
            _hs = ParagraphStyle('_hs', fontSize=9, leading=11, alignment=TA_CENTER,
                                 textColor=rl_colors.white, fontName='Helvetica-Bold', wordWrap='LTR')
            _cs = ParagraphStyle('_cs', fontSize=8, leading=10, alignment=TA_CENTER, wordWrap='LTR')
            def _p(text, style):
                t = str(text).strip() if text is not None else ' '
                return rl_Paragraph(t if t else ' ', style)

            table_data = []
            for ri2, row2 in enumerate(table_data_raw):
                st = _hs if ri2 == 0 else _cs
                table_data.append([_p(cell, st) for cell in row2])

            tbl = Table(table_data, colWidths=[col_w] * len(headers), repeatRows=1)
            ts_style = TableStyle([
                ('BACKGROUND',    (0, 0), (-1, 0),  rl_colors.HexColor('#1E3A5F')),
                ('TEXTCOLOR',     (0, 0), (-1, 0),  rl_colors.white),
                ('FONTNAME',      (0, 0), (-1, 0),  'Helvetica-Bold'),
                ('FONTSIZE',      (0, 0), (-1, 0),  9),
                ('ALIGN',         (0, 0), (-1, -1), 'CENTER'),
                ('VALIGN',        (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTSIZE',      (0, 1), (-1, -1), 8),
                ('GRID',          (0, 0), (-1, -1), 0.4, rl_colors.HexColor('#CBD5E1')),
                ('TOPPADDING',    (0, 0), (-1, -1), 5),
                ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
            ])
            for i2 in range(1, len(table_data)):
                bg2 = rl_colors.white if i2 % 2 == 1 else rl_colors.HexColor('#F8FAFC')
                ts_style.add('BACKGROUND', (0, i2), (-1, i2), bg2)
            tbl.setStyle(ts_style)
            elems.append(tbl)
            doc.build(elems)
            return True, path
        except Exception as e:
            return False, str(e)

    def _write_tree_excel(self, report_type, tree, path, config):
        """Write current tree data to Excel file"""
        if not EXCEL_AVAILABLE:
            if not self._ensure_excel():
                return False, "openpyxl not installed."
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
            from openpyxl.utils import get_column_letter

            headers = config.get("columns", [])
            rows = self._tree_rows(tree)

            wb = Workbook()
            ws = wb.active
            ws.title = config.get("title", "Report")[:31]

            # Title rows
            ncols = max(len(headers), 1)
            ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=ncols)
            ws['A1'] = f"MODO HR – {config.get('title', report_type)}"
            ws['A1'].font = Font(bold=True, size=16, color='FFFFFF')
            ws['A1'].fill = PatternFill(start_color='1E3A5F', end_color='1E3A5F', fill_type='solid')
            ws['A1'].alignment = Alignment(horizontal='center', vertical='center')
            ws.row_dimensions[1].height = 28

            ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=ncols)
            ws['A2'] = f"Generated: {datetime.now().strftime('%d/%m/%Y  %H:%M')}    Records: {len(rows)}"
            ws['A2'].font = Font(size=9, color='64748B', italic=True)
            ws['A2'].alignment = Alignment(horizontal='center')
            ws.row_dimensions[2].height = 18

            # Header row
            bdr = Border(
                left=Side(style='thin', color='CBD5E1'),
                right=Side(style='thin', color='CBD5E1'),
                top=Side(style='thin', color='CBD5E1'),
                bottom=Side(style='thin', color='CBD5E1'))
            hdr_font  = Font(bold=True, color='FFFFFF', size=10)
            hdr_fill  = PatternFill(start_color='1E3A5F', end_color='1E3A5F', fill_type='solid')
            hdr_align = Alignment(horizontal='center', vertical='center')

            for ci, h in enumerate(headers, 1):
                c = ws.cell(row=4, column=ci, value=h)
                c.font, c.fill, c.alignment, c.border = hdr_font, hdr_fill, hdr_align, bdr
            ws.row_dimensions[4].height = 22

            # Data rows
            for ri, row in enumerate(rows, 5):
                fill = PatternFill(start_color='F8FAFC', end_color='F8FAFC', fill_type='solid') \
                       if ri % 2 == 0 else None
                for ci, val in enumerate(row, 1):
                    c = ws.cell(row=ri, column=ci, value=val)
                    c.alignment = Alignment(horizontal='center')
                    c.border = bdr
                    if fill:
                        c.fill = fill

            for ci in range(1, ncols + 1):
                ws.column_dimensions[get_column_letter(ci)].width = 18

            ws.freeze_panes = 'A5'
            ws.page_setup.orientation = 'landscape'
            wb.save(path)
            return True, path
        except Exception as e:
            return False, str(e)

    def get_birthday_report_data(self):
        """Get birthday report data"""
        from datetime import date
        data = []
        today = date.today()
        current_year = today.year

        for emp in self.db.employees.values():
            if not emp.birth_date:
                continue

            birth_date = None
            for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y", "%Y/%m/%d"):
                try:
                    birth_date = datetime.strptime(emp.birth_date.strip(), fmt).date()
                    break
                except Exception:
                    continue
            if not birth_date:
                continue

            dept_name = self.db.departments.get(emp.department, Department("", "N/A")).name if self.db.departments.get(emp.department) else "N/A"

            try:
                this_year_birthday = birth_date.replace(year=current_year)
            except ValueError:
                this_year_birthday = date(current_year, 3, 1)  # 29 Feb → 1 Mar

            if this_year_birthday < today:
                try:
                    this_year_birthday = birth_date.replace(year=current_year + 1)
                except ValueError:
                    this_year_birthday = date(current_year + 1, 3, 1)

            age = current_year - birth_date.year

            days_until = (this_year_birthday - today).days

            data.append((emp.emp_id, emp.name, dept_name, emp.birth_date, age, days_until))

        data.sort(key=lambda x: x[5])
        return data

    def export_report(self, report_type):
        """Export report to CSV — user chooses location"""
        from datetime import datetime
        import os

        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")

        report_names = {
            "employees": "Employee_Report",
            "departments": "Department_Report",
            "attendance": "Attendance_Report",
            "leaves": "Leave_Report",
            "payroll": "Payroll_Report",
            "advances": "Advance_Report",
            "cl_staff": "CL_Staff_Report",
            "penalties": "Penalty_Report",
            "birthdays": "Birthday_Report",
            "monthly": "Monthly_Report"
        }

        filename = report_names.get(report_type, "Report")
        default_name = f"{filename}_{timestamp}.csv"
        file_path = ask_save_path(default_name, "حفظ التقرير CSV / Save Report")
        if not file_path:
            return

        try:
            with open(file_path, 'w', newline='', encoding='utf-8-sig') as f:
                writer = csv.writer(f)

                if report_type == "employees":
                    writer.writerow(["Employee ID", "Employee Name", "Department", "Position", "Basic Salary", "Hire Date"])
                    for emp in self.db.employees.values():
                        dept_name = self.db.departments.get(emp.department, Department("", "N/A")).name if self.db.departments.get(emp.department) else "N/A"
                        writer.writerow([emp.emp_id, emp.name, dept_name, emp.position, emp.salary, emp.hire_date])

                elif report_type == "departments":
                    writer.writerow(["Department ID", "Department Name", "Manager Name", "Employees Count"])
                    for dept in self.db.departments.values():
                        manager = self.db.employees.get(dept.manager_id)
                        manager_name = manager.name if manager else "N/A"
                        emp_count = len([e for e in self.db.employees.values() if e.department == dept.dept_id])
                        writer.writerow([dept.dept_id, dept.name, manager_name, emp_count])

                elif report_type == "attendance":
                    writer.writerow(["Employee ID", "Employee Name", "Date", "Check In", "Check Out", "Status"])
                    for att in self.db.attendance:
                        emp = self.db.employees.get(att.emp_id)
                        emp_name = emp.name if emp else "N/A"
                        writer.writerow([att.emp_id, emp_name, att.date, att.check_in, att.check_out, self.db.get_attendance_display_status(att)])

                elif report_type == "leaves":
                    writer.writerow(["Leave ID", "Employee ID", "Employee Name", "Leave Type", "Start Date", "End Date", "Days", "Status"])
                    for leave in self.db.leaves:
                        emp = self.db.employees.get(leave.emp_id)
                        emp_name = emp.name if emp else "N/A"
                        try:
                            s  = datetime.strptime(leave.start_date, "%d/%m/%Y").date() if "/" in (leave.start_date or "") else datetime.strptime(leave.start_date, "%Y-%m-%d").date()
                            e_ = datetime.strptime(leave.end_date,   "%d/%m/%Y").date() if "/" in (leave.end_date   or "") else datetime.strptime(leave.end_date,   "%Y-%m-%d").date()
                            ldays = (e_ - s).days + 1
                        except Exception:
                            ldays = ""
                        writer.writerow([leave.leave_id, leave.emp_id, emp_name, leave.leave_type, leave.start_date, leave.end_date, ldays, leave.status])

                elif report_type == "payroll":
                    writer.writerow(["Payroll ID", "Employee ID", "Employee Name", "Month", "Year", "Basic Salary", "Allowances", "Net Salary"])
                    for p in self.db.payrolls:
                        emp = self.db.employees.get(p.emp_id)
                        emp_name = emp.name if emp else "N/A"
                        writer.writerow([p.payroll_id, p.emp_id, emp_name, p.month, p.year, p.basic_salary, p.allowances, p.net_salary])

                elif report_type == "advances":
                    writer.writerow(["Advance ID", "Employee ID", "Employee Name", "Amount", "Date", "Status"])
                    for adv in self.db.advances:
                        emp = self.db.employees.get(adv.emp_id)
                        emp_name = emp.name if emp else "N/A"
                        writer.writerow([adv.advance_id, adv.emp_id, emp_name, adv.amount, adv.date, adv.status])

                elif report_type == "cl_staff":
                    writer.writerow(["CL ID", "Employee ID", "Employee Name", "Department", "Amount", "Date", "Status"])
                    for cl in self.db.cl_staff:
                        emp = self.db.employees.get(cl.emp_id)
                        emp_name = emp.name if emp else "N/A"
                        dept = self.db.departments.get(emp.department) if emp else None
                        dept_name = dept.name if dept else "N/A"
                        writer.writerow([cl.cl_id, cl.emp_id, emp_name, dept_name, cl.amount, cl.date, cl.status])

                elif report_type == "penalties":
                    writer.writerow(["Penalty ID", "Employee ID", "Employee Name", "Amount", "Date", "Reason", "Status"])
                    for pen in self.db.penalties:
                        emp = self.db.employees.get(pen.emp_id)
                        emp_name = emp.name if emp else "N/A"
                        writer.writerow([pen.penalty_id, pen.emp_id, emp_name, pen.amount, pen.date, pen.reason, pen.status])

                elif report_type == "monthly":
                    writer.writerow(["Bank Code", "Name", "Department", "Basic", "Transport", "Allowances", "Service", "Amount", "Insurance", "Health Ins.", "Penalty", "Absent", "Sick Leave", "Advance", "Deductions", "CL Staff", "Tax", "Net"])
                    for emp in self._payroll_employees_sorted():
                        # Skip inactive employees (موقفين)
                        if not getattr(emp, 'salary_active', True):
                            continue
                        if (getattr(emp, 'resignation_date', '') or '').strip():
                            continue
                        dept_name = self.db.departments.get(emp.department, Department("", "N/A")).name if self.db.departments.get(emp.department) else "N/A"

                        # Service charge: only if eligible
                        service_charge = emp.service_allowance if getattr(emp, 'service_charge_eligible', True) else 0
                        salary_after_service = emp.salary + emp.transportation + emp.allowances + service_charge

                        _raw_tis = (getattr(emp, 'tax_insurance_status', 'both') or 'both').strip().lower()
                        _tis_map = {'both': 'both', 'tax only': 'tax_only', 'tax_only': 'tax_only',
                                    'insurance only': 'insurance_only', 'insurance_only': 'insurance_only',
                                    'neither': 'none', 'none': 'none'}
                        tax_ins_status = _tis_map.get(_raw_tis, 'both')
                        apply_insurance = tax_ins_status in ('both', 'insurance_only')
                        apply_tax = tax_ins_status in ('both', 'tax_only')

                        if apply_insurance:
                            _s = getattr(self.db, 'insurance_settings', {"min": 2700, "max": 16700})
                            insurance_base = min(float(emp.salary or 0), float(_s.get("max", 16700) or 16700))
                            insurance = round(insurance_base * 0.11, 2)
                            # Health insurance: 3% per spouse + 1% per child from basic salary
                            num_spouses = int(emp.number_of_spouses) if emp.number_of_spouses else 0
                            num_children = int(emp.number_of_children) if emp.number_of_children else 0
                            marital = (emp.marital_status or "Single").strip().lower()
                            if marital in ("single",):
                                health_insurance = 0.0
                            else:
                                health_insurance = round(insurance_base * (num_spouses * 0.03 + num_children * 0.01), 2)
                        else:
                            insurance = 0.0
                            health_insurance = 0.0

                        penalties = sum(p.amount for p in self.db.penalties if p.emp_id == emp.emp_id and p.status in ["Approved", "Confirmed", "confirmed", "Pending"])
                        advances = sum(a.amount for a in self.db.advances if a.emp_id == emp.emp_id and a.status in ["Approved", "Confirmed", "confirmed", "Pending"])
                        cl_staff = sum(c.amount for c in self.db.cl_staff if c.emp_id == emp.emp_id and c.status in ["Approved", "Confirmed", "confirmed", "Pending"]); other_deductions = emp.deductions if emp.deductions else 0

                        if apply_tax:
                            taxable = salary_after_service - insurance - 5000
                            tax = 0
                            if taxable > 0:
                                if taxable <= 1250:
                                    tax = taxable * 0.10
                                elif taxable <= 2500:
                                    tax = 125 + (taxable - 1250) * 0.15
                                else:
                                    tax = 125 + 187.5 + (taxable - 2500) * 0.20
                        else:
                            tax = 0.0

                        net = round_to_nearest_5(salary_after_service - insurance - health_insurance - penalties - advances - cl_staff - other_deductions - tax)

                        writer.writerow([(getattr(emp, 'bank_code', '') or emp.emp_id), emp.name, dept_name, f"{emp.salary:.2f}", f"{emp.transportation:.2f}", f"{emp.allowances:.2f}",
                                   f"{round(service_charge, 2):.2f}", f"{round(salary_after_service, 2):.2f}", f"{round(insurance, 2):.2f}",
                                   f"{round(health_insurance, 2):.2f}", f"{round(penalties, 2):.2f}", f"{round(advances, 2):.2f}",
                                   f"{round(other_deductions, 2):.2f}", f"{round(cl_staff, 2):.2f}", f"{round(tax, 2):.2f}", f"{round(net, 2):.2f}"])

            messagebox.showinfo("Success", f"Report exported successfully to:\n{file_path}")
        except Exception as e:
            messagebox.showerror("Error", f"Error exporting report:\n{str(e)}")

