        # ── Date To ────────────────────────────────────────────────────────
        tk.Label(toolbar_inner, text="To", font=('Segoe UI', 9, 'bold'),
                 bg='white', fg='#475569').pack(side=tk.LEFT, padx=(0, 4))
        to_entry = tk.Entry(toolbar_inner, textvariable=es_to_var,
                            font=('Segoe UI', 10), width=11,
                            relief=tk.FLAT, bg='#F8FAFC', fg='#1E293B',
                            highlightbackground='#CBD5E1', highlightthickness=1)
        to_entry.pack(side=tk.LEFT, ipady=5, padx=(0, 4))

        tk.Label(toolbar_inner, text="dd/mm/yyyy", font=('Segoe UI', 8),
                 bg='white', fg='#94A3B8').pack(side=tk.LEFT, padx=(0, 10))

        # ── Apply button ───────────────────────────────────────────────────
        apply_btn = tk.Button(toolbar_inner, text="  🔍 Apply  ",
                              font=('Segoe UI', 9, 'bold'),
                              bg='#6366F1', fg='white',
                              relief=tk.FLAT, padx=10, pady=5, bd=0, cursor='hand2')
        apply_btn.pack(side=tk.LEFT, padx=(0, 16))

        # ── Separator ──────────────────────────────────────────────────────
        sep = tk.Frame(toolbar_inner, bg='#E2E8F0', width=1)
