        def print_selected_cos():
            def find_treeview(widget):
                if isinstance(widget, ttk.Treeview):
                    return widget
                for child in widget.winfo_children():
                    result = find_treeview(child)
                    if result:
                        return result
                return None
            tv = find_treeview(self.content_frame)
            if tv:
                selection = tv.selection()
                if selection:
                    cos_id = selection[0]
                    cos_obj = next((c for c in self.db.change_of_status if c.cos_id == cos_id), None)
                    if cos_obj:
                        self.print_cos_record(cos_obj)
                    return
