        all_cos_items = [tree.item(i)['values'] for i in tree.get_children()]

        def cos_apply_search(*_):
            q = cos_search_var.get().strip().lower()
            self._cos_search_text = q
            tree.delete(*tree.get_children())
            for vals in all_cos_items:
                if not q or any(q in str(v).lower() for v in vals):
                    tree.insert("", tk.END, iid=vals[0], values=vals)

        cos_search_var.trace_add('write', cos_apply_search)

