        def _cos_search(*args):
            query = emp_code_var.get().strip()
            if not query:
                return
            ql = query.lower()
            exact = [e for e in self.db.employees.values() if e.emp_id.lower() == ql]
            if exact:
                matches = exact
            else:
                matches = [e for e in self.db.employees.values() if ql in e.name.lower()]
            if len(matches) == 1:
                e = matches[0]
                emp_var.set(f"{e.emp_id} - {e.name}")
                emp_name_display.configure(text=f"✅  {e.name}", fg="#059669")
                emp_code_entry.configure(fg="#059669")
                dept = self.db.departments.get(e.department)
                from_dept_var.set(dept.name if dept else e.department)
                from_pos_var.set(e.position or "")
                from_clock_var.set(getattr(e, "work_card_number", ""))
                from_sal_var.set(str(e.salary))
                to_dept_var.set(dept.name if dept else e.department)
                to_pos_var.set(e.position or "")
                to_clock_var.set(getattr(e, "work_card_number", ""))
                to_sal_var.set(str(e.salary))
            elif len(matches) > 1:
                emp_name_display.configure(text=f"⚠ {len(matches)} matches – refine", fg="#D97706")
                emp_code_entry.configure(fg="#D97706")
                emp_var.set("")
            else:
                emp_name_display.configure(text="⚠  Not Found", fg="#DC2626")
                emp_code_entry.configure(fg="#DC2626")
                emp_var.set("")

