        def save_cos():
            if not emp_var.get():
                messagebox.showwarning("Warning", "Please select an employee")
                return
            emp_id = emp_var.get().split(" - ")[0]
            cos_id = self.db.next_seq_id("COS", self.db.change_of_status, "cos_id", 4)
            cos = ChangeOfStatus(
                cos_id=cos_id,
                emp_id=emp_id,
                effective_date=eff_date_var.get(),
                from_department=from_dept_var.get(),
                from_position=from_pos_var.get(),
                from_clock_no=from_clock_var.get(),
                from_salary=from_sal_var.get(),
                to_department=to_dept_var.get(),
                to_position=to_pos_var.get(),
                to_clock_no=to_clock_var.get(),
                to_salary=to_sal_var.get(),
                reason_transfer=transfer_var.get(),
                reason_promotion=promotion_var.get(),
                reason_increase=increase_var.get(),
                warning_record=warning_text.get("1.0", tk.END).strip(),
            )
            success, msg = self.db.add_change_of_status(cos)
            if success:
                # ── تحديث بيانات الموظف مباشرة بعد حفظ Change of Status ──
                emp_obj = self.db.get_employee(emp_id)
                if emp_obj:
                    if cos.to_position:
                        emp_obj.position = cos.to_position
                    if cos.to_salary:
                        try:
                            emp_obj.salary = float(cos.to_salary)
                        except (ValueError, TypeError):
                            pass
                    if cos.to_department:
                        emp_obj.department = cos.to_department
                    self.db.update_employee(emp_obj)
                messagebox.showinfo("Success", msg)
                self.show_change_of_status_page()
            else:
                messagebox.showerror("Error", msg)

        def _get_current_cos_obj():
            """بناء كائن COS مؤقت من البيانات الحالية في الفورم"""
            if not emp_var.get():
                return None, None
            emp_id = emp_var.get().split(" - ")[0]
            cos_id = "COS_PREVIEW"
            cos = ChangeOfStatus(
                cos_id=cos_id,
                emp_id=emp_id,
                effective_date=eff_date_var.get(),
                from_department=from_dept_var.get(),
                from_position=from_pos_var.get(),
                from_clock_no=from_clock_var.get(),
                from_salary=from_sal_var.get(),
                to_department=to_dept_var.get(),
                to_position=to_pos_var.get(),
                to_clock_no=to_clock_var.get(),
                to_salary=to_sal_var.get(),
                reason_transfer=transfer_var.get(),
                reason_promotion=promotion_var.get(),
                reason_increase=increase_var.get(),
                warning_record=warning_text.get("1.0", tk.END).strip(),
            )
            return cos, emp_id

        def print_cos_preview():
            """طباعة الفورم الحالي قبل الحفظ"""
            if not emp_var.get():
                messagebox.showwarning("Warning", "Please select an employee first")
                return
            cos, _ = _get_current_cos_obj()
            if cos:
                self.print_cos_record(cos)

        def import_cos_from_excel():
            """استيراد Change of Status من ملف Excel"""
            if not self._ensure_excel():
                return
            file_path = filedialog.askopenfilename(
                title="Select Excel File for Change of Status",
                filetypes=[("Excel Files", "*.xlsx *.xls"), ("All Files", "*.*")]
            )
            if not file_path:
                return
            try:
                from openpyxl import load_workbook
                wb = load_workbook(file_path, read_only=True)
                ws = wb.active
                rows = list(ws.iter_rows(values_only=True))
                if not rows:
                    messagebox.showerror("Error", "The file is empty.")
                    return

                # Skip header row(s)
                first = [str(c).strip().lower() if c else "" for c in rows[0]]
                data_rows = rows[1:] if first[0] in ("emp_id","employee id","employee code") else rows

                imported = 0
                skipped  = 0
                errors   = []

                def _cell(row, idx, default=""):
                    v = row[idx] if idx < len(row) else None
                    return str(v).strip() if v is not None and str(v).strip() not in ("None","nan","") else default

                def _date(row, idx):
                    v = row[idx] if idx < len(row) else None
                    if v is None: return ""
                    if hasattr(v, 'strftime'): return v.strftime("%d/%m/%Y")
                    s = str(v).strip()
                    if not s or s.lower() in ("none","nan","-",""): return ""
                    for fmt in ("%Y-%m-%d %H:%M:%S","%Y-%m-%d","%d/%m/%Y","%d-%m-%Y"):
                        try: return datetime.strptime(s, fmt).strftime("%d/%m/%Y")
                        except: pass
                    return s

                # Expected columns:
                # 0:emp_id, 1:effective_date, 2:from_dept, 3:from_pos, 4:from_clock, 5:from_salary
                # 6:to_dept, 7:to_pos, 8:to_clock, 9:to_salary
                # 10:reason_transfer(Y/N), 11:reason_promotion(Y/N), 12:reason_increase(Y/N), 13:warning
                for i, row in enumerate(data_rows, start=2):
                    if not row or not row[0]:
                        continue
                    try:
                        emp_id_r = _cell(row, 0)
                        emp_obj  = self.db.get_employee(emp_id_r)
                        if not emp_obj:
                            skipped += 1
                            errors.append(f"Row {i}: Employee '{emp_id_r}' not found")
                            continue

                        cos_id_r = self.db.next_seq_id("COS", self.db.change_of_status, "cos_id", 4)
                        cos_r = ChangeOfStatus(
                            cos_id=cos_id_r,
                            emp_id=emp_id_r,
                            effective_date=_date(row, 1) or datetime.now().strftime("%d/%m/%Y"),
                            from_department=_cell(row, 2),
                            from_position=_cell(row, 3),
                            from_clock_no=_cell(row, 4),
                            from_salary=_cell(row, 5),
                            to_department=_cell(row, 6),
                            to_position=_cell(row, 7),
                            to_clock_no=_cell(row, 8),
                            to_salary=_cell(row, 9),
                            reason_transfer=_cell(row, 10, "N").upper() in ("Y","YES","TRUE","1"),
                            reason_promotion=_cell(row, 11, "N").upper() in ("Y","YES","TRUE","1"),
                            reason_increase=_cell(row, 12, "N").upper() in ("Y","YES","TRUE","1"),
                            warning_record=_cell(row, 13),
                        )
                        success_r, msg_r = self.db.add_change_of_status(cos_r)
                        if success_r:
                            # تحديث بيانات الموظف
                            if cos_r.to_position:  emp_obj.position   = cos_r.to_position
                            if cos_r.to_salary:
                                try: emp_obj.salary = float(cos_r.to_salary)
                                except: pass
                            if cos_r.to_department: emp_obj.department = cos_r.to_department
                            self.db.update_employee(emp_obj)
                            imported += 1
                        else:
                            skipped += 1
                            errors.append(f"Row {i}: {msg_r}")
                    except Exception as ex:
                        skipped += 1
                        errors.append(f"Row {i}: {str(ex)}")

                wb.close()
                if imported > 0:
                    self.db.save_data()

                result = f"✅ Import Complete!\n\nImported: {imported}\nSkipped: {skipped}"
                if errors:
                    result += "\n\nErrors:\n" + "\n".join(errors[:5])
                messagebox.showinfo("Import Results", result)
                if imported > 0:
                    self.show_change_of_status_page()

            except Exception as e:
                messagebox.showerror("Import Error", f"Failed to read file:\n{str(e)}")

        def export_cos_template():
            """تصدير قالب Excel لاستيراد Change of Status"""
            if not self._ensure_excel():
                return
            try:
                from openpyxl import Workbook
                from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
                import os

                wb = Workbook()
                ws = wb.active
                ws.title = "COS Import"

                headers = [
                    "emp_id", "effective_date", "from_department", "from_position",
                    "from_clock_no", "from_salary", "to_department", "to_position",
                    "to_clock_no", "to_salary", "reason_transfer(Y/N)",
                    "reason_promotion(Y/N)", "reason_increase(Y/N)", "warning_record"
                ]
                descs = [
                    "Employee ID", "DD/MM/YYYY", "Current Dept", "Current Position",
                    "Current Clock No", "Current Salary", "New Dept", "New Position",
                    "New Clock No", "New Salary", "Y or N", "Y or N", "Y or N", "Optional"
                ]
                sample = [
                    "001", "11/06/2026", "Front Office", "Receptionist",
                    "101", "3500", "Housekeeping", "Supervisor",
                    "102", "4200", "N", "Y", "N", ""
                ]

                hdr_fill = PatternFill("solid", fgColor="D97706")
                hdr_font = Font(bold=True, color="FFFFFF", size=11)
                dsc_fill = PatternFill("solid", fgColor="FEF3C7")
                dsc_font = Font(italic=True, color="92400E", size=9)
                smp_fill = PatternFill("solid", fgColor="DCFCE7")
                smp_font = Font(color="166534", size=10)
                center   = Alignment(horizontal="center", vertical="center", wrap_text=True)
                thin     = Side(style="thin", color="CBD5E1")
                brd      = Border(left=thin, right=thin, top=thin, bottom=thin)

                for ci, h in enumerate(headers, 1):
                    c = ws.cell(1, ci, h)
                    c.font = hdr_font; c.fill = hdr_fill; c.alignment = center; c.border = brd
                    ws.column_dimensions[c.column_letter].width = max(len(h)+3, 14)
                ws.row_dimensions[1].height = 26

                for ci, d in enumerate(descs, 1):
                    c = ws.cell(2, ci, d)
                    c.font = dsc_font; c.fill = dsc_fill; c.alignment = center; c.border = brd
                ws.row_dimensions[2].height = 22

                for ci, s in enumerate(sample, 1):
                    c = ws.cell(3, ci, s)
                    c.font = smp_font; c.fill = smp_fill; c.alignment = center; c.border = brd
                ws.row_dimensions[3].height = 20

                ws.freeze_panes = "A3"

                desktop = os.path.join(os.path.expanduser("~"), "Desktop")
                os.makedirs(desktop, exist_ok=True)
                path = os.path.join(desktop, "COS_Import_Template.xlsx")
                wb.save(path)
                messagebox.showinfo("Template Saved",
                    "✅ Template saved to Desktop:\nCOS_Import_Template.xlsx\n\n"
                    "• Row 1: Column names\n• Row 2: Descriptions\n• Row 3: Sample\n\n"
                    "Add your records from Row 4 onwards.")
                try:
                    os.startfile(path)
                except Exception:
                    pass
            except Exception as e:
                messagebox.showerror("Error", f"Could not create template:\n{str(e)}")

        # ── أزرار الفورم ──────────────────────────────────────────────────────
        tk.Button(btn_frame2, text="💾 Save Record",
                  font=("Segoe UI", 12, "bold"),
                  bg=self.colors["success"], fg="white",
                  relief=tk.FLAT, padx=25, pady=10,
                  command=save_cos).pack(side=tk.LEFT, padx=8)

        tk.Button(btn_frame2, text="🖨️ Print",
                  font=("Segoe UI", 12, "bold"),
                  bg="#0EA5E9", fg="white",
                  relief=tk.FLAT, padx=25, pady=10,
                  command=print_cos_preview).pack(side=tk.LEFT, padx=8)

        # ── Excel Import section ──────────────────────────────────────────────
        excel_sep = tk.Frame(btn_frame2, bg="#E2E8F0", width=1, height=40)
        excel_sep.pack(side=tk.LEFT, fill=tk.Y, padx=12, pady=4)

        tk.Button(btn_frame2, text="📥 Import Excel",
                  font=("Segoe UI", 12, "bold"),
                  bg="#8B5CF6", fg="white",
                  relief=tk.FLAT, padx=25, pady=10,
                  command=import_cos_from_excel).pack(side=tk.LEFT, padx=8)

        tk.Button(btn_frame2, text="📋 Get Template",
                  font=("Segoe UI", 11, "bold"),
                  bg="#D97706", fg="white",
                  relief=tk.FLAT, padx=18, pady=10,
                  command=export_cos_template).pack(side=tk.LEFT, padx=8)

        tk.Button(btn_frame2, text="❌ Cancel",
                  font=("Segoe UI", 12, "bold"),
                  bg=self.colors["danger"], fg="white",
                  relief=tk.FLAT, padx=25, pady=10,
                  command=self.show_change_of_status_page).pack(side=tk.LEFT, padx=8)

