        canvas.bind("<Enter>", lambda e: [canvas.bind_all("<MouseWheel>",_canvas_mw), canvas.bind_all("<Button-4>",_canvas_mwl), canvas.bind_all("<Button-5>",_canvas_mwl)])
        canvas.bind("<Leave>", lambda e: [canvas.unbind_all("<MouseWheel>"), canvas.unbind_all("<Button-4>"), canvas.unbind_all("<Button-5>")])

        content = tk.Frame(card, bg="white", padx=40, pady=20)
