        emp_edit_code_entry = tk.Entry(emp_edit_code_frame, textvariable=emp_edit_code_var,
                                       font=("Arial", 11, "bold"), width=14,
                                       relief="solid", bd=1,
                                       fg="#059669" if _pre_emp else "#5B21B6")
        emp_edit_code_entry.pack(side=tk.LEFT)
