        def _save_sync():
            raw = _sync_var.get().strip()
            if raw:
                # Validate: must be an existing directory or a path where we can write
                if os.path.isdir(raw):
                    test_file = os.path.join(raw, "hr_data.json")
                elif os.path.isfile(raw) or (os.path.isdir(os.path.dirname(raw)) and raw.endswith(".json")):
                    test_file = raw
                else:
                    sync_status_var.set("⚠ Path not found — check the address")
                    sync_status_lbl.config(fg='#DC2626')
                    return
            self.db.save_sync_config(raw)
            if raw:
                # If the shared file already exists, load from it immediately
                eff = self.db.get_effective_data_file()
                if os.path.exists(eff):
                    self.db.reload_from_shared()
                    sync_status_var.set("✅ Saved & data loaded from shared path")
                else:
                    # First time — copy local data to shared location
                    try:
                        import shutil
                        shutil.copy2(self.db.data_file, eff)
                        sync_status_var.set("✅ Saved & local data copied to shared path")
                    except Exception as ex:
                        sync_status_var.set(f"⚠ Saved but copy failed: {str(ex)[:40]}")
                sync_status_lbl.config(fg='#059669')
            else:
                sync_status_var.set("✅ Shared path cleared — using local data")
                sync_status_lbl.config(fg='#059669')

