            tree_frame.pack(fill=tk.BOTH, expand=True, padx=30, pady=20)

            cols = ("username", "role", "status")
            users_tree = ttk.Treeview(tree_frame, columns=cols, show='headings', height=15)
            users_tree.heading("username", text="👤  Username")
            users_tree.heading("role",     text="🔑  Role")
            users_tree.heading("status",   text="🔘  Status")
            users_tree.column("username", width=280, anchor='w')
            users_tree.column("role",     width=200, anchor='center')
            users_tree.column("status",   width=120, anchor='center')

            # Scrollbar for tree
            tree_scroll = ttk.Scrollbar(tree_frame, orient="vertical", command=users_tree.yview)
            users_tree.configure(yscrollcommand=tree_scroll.set)
            tree_scroll.pack(side=tk.RIGHT, fill=tk.Y)
            users_tree.pack(fill=tk.BOTH, expand=True)

            # Tag colors for active / stopped rows
            users_tree.tag_configure('active',  background='#F0FDF4', foreground='#166534')
            users_tree.tag_configure('stopped', background='#FEF2F2', foreground='#991B1B')

            # All system users list
            ALL_USERS = self._get_all_system_users()

            disabled = getattr(self.db, "disabled_users", [])

            def populate_tree():
                users_tree.delete(*users_tree.get_children())
                dis = getattr(self.db, "disabled_users", [])
                for uname, urole in ALL_USERS:
                    is_stopped = uname in dis
                    status_txt = "⛔  Stopped" if is_stopped else "✅  Active"
                    tag = 'stopped' if is_stopped else 'active'
                    users_tree.insert('', 'end', iid=uname,
                                      values=(uname, urole, status_txt), tags=(tag,))

            populate_tree()

            # ── Action buttons ───────────────────────────────────────────────
            btn_bar = tk.Frame(users_outer, bg=self.colors['light'])
            btn_bar.pack(fill=tk.X, padx=30, pady=(0, 20))

            def toggle_user(action):
                sel = users_tree.selection()
                if not sel:
                    messagebox.showwarning("Select User", "Please select a user first.")
                    return
                uname = sel[0]
                # Prevent admin from disabling themselves
                if uname == self.current_user and action == 'stop':
                    messagebox.showerror("Not Allowed", "You cannot stop your own account.")
                    return
                dis = getattr(self.db, "disabled_users", [])
                if action == 'stop':
                    if uname not in dis:
                        dis.append(uname)
                    self.db.log_activity("User stopped", details=f"Account '{uname}' deactivated", category="security")
                    messagebox.showinfo("Done", f"User '{uname}' has been stopped.")
                else:
                    if uname in dis:
                        dis.remove(uname)
                    self.db.log_activity("User activated", details=f"Account '{uname}' activated", category="security")
                    messagebox.showinfo("Done", f"User '{uname}' is now active.")
                self.db.disabled_users = dis
                self.db.save_data()
                populate_tree()

            tk.Button(btn_bar, text="▶  Run (Activate)", font=('Segoe UI', 10, 'bold'),
                      bg='#22C55E', fg='white', relief=tk.FLAT, padx=20, pady=8, cursor='hand2',
                      command=lambda: toggle_user('run')).pack(side=tk.LEFT, padx=(0, 12))

            tk.Button(btn_bar, text="⛔  Stop (Deactivate)", font=('Segoe UI', 10, 'bold'),
                      bg='#EF4444', fg='white', relief=tk.FLAT, padx=20, pady=8, cursor='hand2',
                      command=lambda: toggle_user('stop')).pack(side=tk.LEFT)

            tk.Label(btn_bar,
                     text="ℹ️  Select a user from the table then click Run or Stop",
                     font=('Segoe UI', 9), bg=self.colors['light'],
                     fg=self.colors['text_light']).pack(side=tk.LEFT, padx=20)

