    def show_employee_details(self, emp_id):
        """عرض تفاصيل الموظف"""
        employee = self.db.get_employee(emp_id)
        if not employee:
            messagebox.showerror("Error", "Employee not found")
            return

        # إنشاء نافذة التفاصيل
        details_window = tk.Toplevel(self.root)
        details_window.title(f"Employee Details - {emp_display_name(employee)}")
        details_window.geometry("800x700")
        details_window.configure(bg="#f0f0f0")

        # إنشاء Canvas مع شريط Doneرير
        canvas = tk.Canvas(details_window)
        scrollbar = ttk.Scrollbar(details_window, orient="vertical", command=canvas.yview)
        scrollable_frame = ttk.Frame(canvas)

        scrollable_frame.bind(
            "<Configure>",
            lambda e: canvas.configure(scrollregion=canvas.bbox("all"))
        )

        canvas.create_window((0, 0), window=scrollable_frame, anchor="nw")
        canvas.configure(yscrollcommand=scrollbar.set)

        canvas.pack(side="left", fill="both", expand=True)
        scrollbar.pack(side="right", fill="y")

        # إطار التفاصيل
        frame = ttk.Frame(scrollable_frame, padding=20)
        frame.pack(fill=tk.BOTH, expand=True)

        # عرض البيانات الأساسية
        row = 0
        ttk.Label(frame, text="Employee ID:", font=("Arial", 10, "bold")).grid(row=row, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=employee.emp_id).grid(row=row, column=1, sticky=tk.W, pady=5)

        row += 1
        ttk.Label(frame, text="Name:", font=("Arial", 10, "bold")).grid(row=row, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=employee.name).grid(row=row, column=1, sticky=tk.W, pady=5)

        row += 1
        ttk.Label(frame, text="Arabic Name:", font=("Arial", 10, "bold")).grid(row=row, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=getattr(employee, "arabic_name", "") or "N/A").grid(row=row, column=1, sticky=tk.W, pady=5)

        row += 1
        ttk.Label(frame, text="Family Name:", font=("Arial", 10, "bold")).grid(row=row, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=employee.family_name or "N/A").grid(row=row, column=1, sticky=tk.W, pady=5)

        row += 1
        ttk.Label(frame, text="Mother's Name:", font=("Arial", 10, "bold")).grid(row=row, column=0, sticky=tk.W, pady=5)
