    def select_employee_photo(self, photo_var):
        """اختيار صورة الموظف"""
        file_path = filedialog.askopenfilename(
            filetypes=[("Image files", "*.jpg *.jpeg *.png *.gif *.bmp"), ("All files", "*.*")],
            title="اختيار صورة الموظف"
        )
        if file_path:
            photo_var.set(file_path)

    def upload_photo(self, photo_path, photo_label):
        """Upload employee photo"""
        file_path = filedialog.askopenfilename(
            filetypes=[("Image files", "*.jpg *.jpeg *.png *.gif *.bmp"), ("All files", "*.*")],
            title="Upload Employee Photo"
        )
        if file_path:
            photo_path[0] = file_path
            filename = os.path.basename(file_path)
            # عرض الصورة المصغرة
            try:
                from PIL import Image, ImageTk
                img = Image.open(file_path)
                img.thumbnail((80, 80))
                tk_img = ImageTk.PhotoImage(img)
                photo_label.config(image=tk_img, text="", bg='white')
                photo_label.image = tk_img  # منع garbage collection
            except Exception:
                # إذا لم تتوفر PIL نعرض اسم الملف فقط
                photo_label.config(text=filename[:20] + "..." if len(filename) > 20 else filename, fg='#10B981')

    def show_add_employee_dialog(self, edit_employee=None):
        """Show Add Employee Full Page Form with Modern Beautiful Styling"""
        is_edit = edit_employee is not None
        self.clear_content()

        # Modern Gradient Header
        header = tk.Frame(self.content_frame, bg='#6366F1', height=120)
        header.pack(fill=tk.X)
        header.pack_propagate(False)

        # Header content
        header_content = tk.Frame(header, bg='#6366F1')
        header_content.pack(fill=tk.BOTH, expand=True, padx=30, pady=20)

        back_btn = tk.Button(header_content, text="← Back",
                            font=('Segoe UI', 12, 'bold'),
                            bg='#8B5CF6', fg='white',
                            relief=tk.FLAT, padx=20, pady=10,
                            command=self.show_employees_page,
                            cursor='hand2')
        back_btn.pack(side=tk.LEFT)

        title_frame = tk.Frame(header_content, bg='#6366F1')
        title_frame.pack(side=tk.LEFT, padx=30)

        if is_edit:
            tk.Label(title_frame, text="✏️ Edit Employee", font=('Segoe UI', 26, 'bold'),
                    bg='#6366F1', fg='white').pack()
            tk.Label(title_frame, text="Update employee information in the system", font=('Segoe UI', 11),
                    bg='#6366F1', fg='#E0E7FF').pack()
        else:
            tk.Label(title_frame, text="👤 Add New Employee", font=('Segoe UI', 26, 'bold'),
                    bg='#6366F1', fg='white').pack()
            tk.Label(title_frame, text="Add new employee information to the system", font=('Segoe UI', 11),
                    bg='#6366F1', fg='#E0E7FF').pack()

        # Main container with Scrollbar
        canvas_container = tk.Frame(self.content_frame, bg='#F1F5F9')
        main_canvas = tk.Canvas(canvas_container, bg='#F1F5F9', highlightthickness=0)
        main_scrollbar = ttk.Scrollbar(canvas_container, orient="vertical", command=main_canvas.yview)
        main_container = tk.Frame(main_canvas, bg='#F1F5F9')

        main_container.bind(
            "<Configure>",
            lambda e: main_canvas.configure(scrollregion=main_canvas.bbox("all"))
        )

        main_canvas.create_window((0, 0), window=main_container, anchor="nw")
        main_canvas.configure(yscrollcommand=main_scrollbar.set)

        # Ensure inner frame expands to canvas width
        def _on_canvas_configure(event):
            canvas_width = event.width
            main_canvas.itemconfig("all", width=canvas_width)
            main_canvas.configure(scrollregion=main_canvas.bbox("all"))
        main_canvas.bind("<Configure>", _on_canvas_configure)

        # Update scrollregion after idle to catch all widget changes
        def _update_scrollregion(event=None):
            main_canvas.after_idle(lambda: main_canvas.configure(
                scrollregion=main_canvas.bbox("all")
            ))
        main_container.bind("<Configure>", _update_scrollregion)

        # Mouse wheel scrolling
        def _on_mousewheel(event):
            main_canvas.yview_scroll(int(-1 * (event.delta / 120)), "units")
        def _on_mousewheel_linux(event):
            if event.num == 4:
                main_canvas.yview_scroll(-1, "units")
            elif event.num == 5:
                main_canvas.yview_scroll(1, "units")

        def _bind_mousewheel(event):
            main_canvas.bind_all("<MouseWheel>", _on_mousewheel)
            main_canvas.bind_all("<Button-4>", _on_mousewheel_linux)
            main_canvas.bind_all("<Button-5>", _on_mousewheel_linux)
        def _unbind_mousewheel(event):
            main_canvas.unbind_all("<MouseWheel>")
            main_canvas.unbind_all("<Button-4>")
            main_canvas.unbind_all("<Button-5>")

        main_canvas.bind("<Enter>", _bind_mousewheel)
        main_canvas.bind("<Leave>", _unbind_mousewheel)
        main_container.bind("<Enter>", _bind_mousewheel)
        main_container.bind("<Leave>", _unbind_mousewheel)

        canvas_container.pack(side=tk.TOP, fill=tk.BOTH, expand=True)
        main_canvas.pack(side="left", fill="both", expand=True)
        main_scrollbar.pack(side="right", fill="y")


        # Create notebook for tabs
        style = ttk.Style()
        style.theme_use('clam')

        # Modern tab styling
        style.configure('TNotebook', background='#F1F5F9', borderwidth=0)
        style.configure('TNotebook.Tab',
                       background='white',
                       foreground='#64748B',
                       font=('Segoe UI', 12, 'bold'),
                       padding=(20, 12),
                       borderwidth=0)
        style.map('TNotebook.Tab',
                 background=[('selected', '#6366F1')],
                 foreground=[('selected', 'white')])

        notebook = ttk.Notebook(main_container)
        notebook.pack(fill=tk.BOTH, expand=True)

        # ==================== Basic Info Tab ====================
        basic_frame = tk.Frame(notebook, bg='white', relief=tk.GROOVE, borderwidth=1)
        notebook.add(basic_frame, text="  📋 Basic Information  ")

        # Card style for basic info
        basic_card = tk.Frame(basic_frame, bg='white', padx=30, pady=20)
        basic_card.pack(fill=tk.BOTH, expand=True)

        # Section header
        tk.Label(basic_card, text="Personal Information", font=('Segoe UI', 14, 'bold'),
                bg='white', fg='#6366F1').grid(row=0, column=0, columnspan=3, sticky='w', pady=(0, 20))

        # ========== Photo Section (Top Right) ==========
        photo_path = [None]
        photo_section = tk.Frame(basic_card, bg='white')
        photo_section.grid(row=0, column=4, rowspan=5, sticky='ne', padx=10, pady=(0, 10))

        # Photo display box
        photo_box = tk.Frame(photo_section, bg='#F1F5F9', width=150, height=170,
                             highlightbackground='#CBD5E1', highlightthickness=2, relief=tk.FLAT)
        photo_box.pack()
        photo_box.pack_propagate(False)

        photo_placeholder = tk.Label(photo_box, text="👤\nEmployee\nPhoto",
                                     font=('Segoe UI', 11), bg='#F1F5F9', fg='#94A3B8',
                                     justify='center')
        photo_placeholder.place(relx=0.5, rely=0.5, anchor='center')

        photo_display = tk.Label(photo_box, bg='#F1F5F9')
        photo_display.place(x=0, y=0, relwidth=1, relheight=1)

        # Buttons row
        btn_row = tk.Frame(photo_section, bg='white')
        btn_row.pack(fill=tk.X, pady=(6, 0))

        photo_rotation = [0]  # 0, 90, 180, 270

        def _apply_photo(file_path, rotation=0):
            try:
                if not is_valid_image_path(file_path):
                    raise ValueError("Invalid image file")
                from PIL import Image, ImageTk
                img = Image.open(file_path)
                if rotation != 0:
                    img = img.rotate(-rotation, expand=True)
                # Preserve aspect ratio - fit inside 150x170
                img.thumbnail((150, 170), Image.LANCZOS)
                # Paste on white background to keep box size fixed
                bg = Image.new("RGB", (150, 170), (241, 245, 249))
                offset_x = (150 - img.width) // 2
                offset_y = (170 - img.height) // 2
                bg.paste(img, (offset_x, offset_y))
                tk_img = ImageTk.PhotoImage(bg)
                photo_display.config(image=tk_img)
                photo_display.image = tk_img
                photo_placeholder.place_forget()
            except Exception:
                photo_placeholder.config(text="Employee\nPhoto", fg='#94A3B8')

        def _do_upload_photo():
            file_path = filedialog.askopenfilename(
                filetypes=[("Image files", "*.jpg *.jpeg *.png *.gif *.bmp"), ("All files", "*.*")],
                title="Upload Employee Photo"
            )
            if file_path:
                photo_path[0] = file_path
                photo_rotation[0] = 0
                _apply_photo(file_path, 0)

        def _do_rotate_photo():
            if not photo_path[0]:
                return
            photo_rotation[0] = (photo_rotation[0] + 90) % 360
            _apply_photo(photo_path[0], photo_rotation[0])

        def _do_delete_photo():
            photo_path[0] = None
            photo_rotation[0] = 0
            photo_display.config(image='')
            photo_display.image = None
            photo_placeholder.place(relx=0.5, rely=0.5, anchor='center')
            photo_placeholder.config(text="👤\nEmployee\nPhoto", fg='#94A3B8')

        tk.Button(btn_row, text="📷 Upload", font=('Segoe UI', 9, 'bold'),
                  bg='#3B82F6', fg='white', relief=tk.FLAT, padx=8, pady=4,
                  cursor='hand2', command=_do_upload_photo).pack(side=tk.LEFT, padx=(0, 4))

        tk.Button(btn_row, text="🔄", font=('Segoe UI', 9, 'bold'),
                  bg='#F59E0B', fg='white', relief=tk.FLAT, padx=8, pady=4,
                  cursor='hand2', command=_do_rotate_photo).pack(side=tk.LEFT, padx=(0, 4))

        tk.Button(btn_row, text="🗑 Delete", font=('Segoe UI', 9, 'bold'),
                  bg='#EF4444', fg='white', relief=tk.FLAT, padx=8, pady=4,
                  cursor='hand2', command=_do_delete_photo).pack(side=tk.LEFT)

        # تحميل الصورة تلقائياً عند التعديل (هنا في الأعلى)
        if is_edit and edit_employee.employee_photo and is_valid_image_path(edit_employee.employee_photo):
            photo_path[0] = edit_employee.employee_photo
            _apply_photo(edit_employee.employee_photo, photo_rotation[0])

        fields_basic = [
            ("Employee ID:", "emp_id", 20), ("Full Name:", "name", 25),
            ("Family Name:", "family_name", 20), ("Arabic Name:", "arabic_name", 25),
            ("Mother Name:", "mother_name", 20), ("Birth Date:", "birth_date", 20),
            ("Age:", "age", 10),
            ("Department:", "dept", 25), ("Position:", "position", 25),
            ("Basic Salary:", "salary", 20), ("Hire Date:", "hire_date", 20),
            ("Email:", "email", 25), ("Phone:", "phone", 20),
            ("Bank Code:", "bank_code", 20), ("", "_spacer", 1),
        ]

        vars_basic = {}
        vars_basic["age"] = tk.StringVar()
        vars_basic["national_id"] = tk.StringVar()
        vars_basic["insurance_number"] = tk.StringVar()
        vars_basic["national_id_issue"] = tk.StringVar()
        vars_basic["national_id_expiry"] = tk.StringVar()
        vars_basic["address"] = tk.StringVar()
        vars_basic["city"] = tk.StringVar()
        vars_basic["marital_status"] = tk.StringVar(value="Single")
        vars_basic["number_of_spouses"] = tk.StringVar(value="0")
        vars_basic["number_of_children"] = tk.StringVar(value="0")
        vars_basic["tax_insurance_status"] = tk.StringVar(value="both")
        vars_basic["bank_code"] = tk.StringVar()

        # Egyptian Governorates for City dropdown
        egypt_governorates = [
            "Cairo", "Giza", "Alexandria", "Beheira", "Menoufia", "Dakahlia",
            "Sharqia", "Qalyubia", "Kafr El Sheikh", "Gharbia", "Damietta", "Port Said",
            "Suez", "Ismailia", "Faiyum", "Beni Suef", "Minya",
            "Assiut", "Sohag", "Qena", "Luxor", "Aswan", "El Wadi El Gedeed",
            "البحر الأحمر", "جنوبسيناء", "شمالسيناء", "مرسى مطروح"
        ]

        for i, (label, key, width) in enumerate(fields_basic):
            row = (i // 2) + 1
            col = (i % 2) * 2

            # Skip spacer entries
            if key == "_spacer":
                continue

            # Label
            tk.Label(basic_card, text=label, font=('Segoe UI', 9, 'bold'),
                    bg='white', fg='#334155').grid(row=row, column=col, sticky='e', padx=15, pady=12)

            # Entry field with modern styling
            field_frame = tk.Frame(basic_card, bg='white', highlightbackground='#E2E8F0',
                                  highlightthickness=1)
            field_frame.grid(row=row, column=col+1, sticky='w', padx=15, pady=12)

            if key == "birth_date" or key == "hire_date":
                if CALENDAR_AVAILABLE:
                    vars_basic[key] = tk.StringVar()
                    try:
                        entry = DateEntry(field_frame, textvariable=vars_basic[key], font=('Segoe UI', 11),
                                         width=width-2, date_pattern='dd/mm/yyyy',
                                         background='#6366F1', foreground='white',
                                         headersbackground='#6366F1')
                    except:
                        entry = tk.Entry(field_frame, textvariable=vars_basic[key], font=('Segoe UI', 11), width=width)
                else:
                    vars_basic[key] = tk.StringVar()
                    entry = tk.Entry(field_frame, textvariable=vars_basic[key], font=('Segoe UI', 11), width=width)

                # إضافة حدث لحساب العمر عند تغيير Birth Date
                if key == "birth_date":
                    def on_birth_date_change(*args):
                        birth = parse_date_any(vars_basic["birth_date"].get())
                        if birth:
                            today = date.today()
                            age = today.year - birth.year - ((today.month, today.day) < (birth.month, birth.day))
                            if "age" in vars_basic:
                                vars_basic["age"].set(str(age))
                        else:
                            if "age" in vars_basic:
                                vars_basic["age"].set("")

                    vars_basic["birth_date"].trace('w', on_birth_date_change)
            elif key == "dept":
                vars_basic[key] = tk.StringVar()
                entry = ttk.Combobox(field_frame, textvariable=vars_basic[key], font=('Segoe UI', 11), width=width-2,
                                    values=[f"{d.dept_id} - {d.name}" for d in self.db.get_all_departments()], state="readonly")
            elif key == "salary":
                vars_basic[key] = tk.StringVar()
                entry = tk.Entry(field_frame, textvariable=vars_basic[key], font=('Segoe UI', 11), width=width)
            else:
                vars_basic[key] = tk.StringVar()
                entry = tk.Entry(field_frame, textvariable=vars_basic[key], font=('Segoe UI', 11), width=width)

            entry.pack(fill=tk.BOTH, expand=True, ipady=8, ipadx=5)

            if key == "hire_date" and not is_edit:
                vars_basic[key].set(date.today().strftime("%d/%m/%Y"))

        # ترجمة/تحويل الاسم تلقائياً إلى Arabic Name عند تغيير Full Name
        # يتم التحديث تلقائياً فقط طالما المستخدم لم يعدّل حقل Arabic Name يدوياً
        _last_auto_arabic_name = {"value": ""}

        def _on_full_name_change(*args):
            new_arabic = transliterate_name_to_arabic(vars_basic["name"].get())
            current_arabic = vars_basic["arabic_name"].get()
            if current_arabic == "" or current_arabic == _last_auto_arabic_name["value"]:
                vars_basic["arabic_name"].set(new_arabic)
                _last_auto_arabic_name["value"] = new_arabic

        if "name" in vars_basic and "arabic_name" in vars_basic:
            vars_basic["name"].trace('w', _on_full_name_change)

        # Pre-populate fields if editing
        if is_edit and edit_employee:
            vars_basic["emp_id"].set(edit_employee.emp_id)
            vars_basic["name"].set(edit_employee.name)
            vars_basic["family_name"].set(edit_employee.family_name or "")
            vars_basic["arabic_name"].set(edit_employee.arabic_name or "")
            _last_auto_arabic_name["value"] = vars_basic["arabic_name"].get()
