    def show_department_details(self, dept_id):
        """عرض تفاصيل Department"""
        department = self.db.get_department(dept_id)
        if not department:
            messagebox.showerror("Error", "Department not found")
            return

        # إنشاء نافذة التفاصيل
        details_window = tk.Toplevel(self.root)
        details_window.title(f"Department Details - {department.name}")
        details_window.geometry("500x400")
        details_window.configure(bg="#f0f0f0")

        # إطار التفاصيل
        frame = ttk.Frame(details_window, padding=20)
        frame.pack(fill=tk.BOTH, expand=True)

        # عرض البيانات
        ttk.Label(frame, text="Department ID:", font=("Arial", 10, "bold")).grid(row=0, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=department.dept_id).grid(row=0, column=1, sticky=tk.W, pady=5)

        ttk.Label(frame, text="Department Name:", font=("Arial", 10, "bold")).grid(row=1, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=department.name).grid(row=1, column=1, sticky=tk.W, pady=5)

        manager_name = "N/A"
        if department.manager_id:
            manager = self.db.get_employee(department.manager_id)
            if manager:
                manager_name = manager.name
        ttk.Label(frame, text="Manager:", font=("Arial", 10, "bold")).grid(row=2, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=manager_name).grid(row=2, column=1, sticky=tk.W, pady=5)

        # عدد Employees
        employees = self.db.get_all_employees()
        emp_count = len([e for e in employees if e.department == dept_id])
        ttk.Label(frame, text="Employee Count:", font=("Arial", 10, "bold")).grid(row=3, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=str(emp_count)).grid(row=3, column=1, sticky=tk.W, pady=5)

        # قائمة Employees في Department
        ttk.Label(frame, text="Employees in Department:", font=("Arial", 10, "bold")).grid(row=4, column=0, sticky=tk.W, pady=5)

        dept_employees = [e for e in employees if e.department == dept_id]
        if dept_employees:
            emp_list = "\n".join([f"• {e.name} - {e.position}" for e in dept_employees])
            ttk.Label(frame, text=emp_list, justify=tk.LEFT).grid(row=5, column=0, columnspan=2, sticky=tk.W, pady=5)
        else:
            ttk.Label(frame, text="No employees in this Department").grid(row=5, column=0, columnspan=2, sticky=tk.W, pady=5)

        # أزرار التحكم
        btn_frame = ttk.Frame(frame)
        btn_frame.grid(row=6, column=0, columnspan=2, pady=20)

        ttk.Button(btn_frame, text="Edit",
                  command=lambda: self.show_edit_department_dialog(department, details_window)).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text="Delete",
                  command=lambda: self.delete_department(dept_id, details_window)).pack(side=tk.LEFT, padx=5)
        ttk.Button(btn_frame, text="Close",
                  command=details_window.destroy).pack(side=tk.LEFT, padx=5)

