    def on_penalty_action(self, tree, event):
        """Handle edit/delete actions for penalties"""
        item_id = tree.identify_row(event.y)
        if not item_id:
            return

        column_id = tree.identify_column(event.x)
        if not column_id:
            return

        penalty_id = item_id  # iid = exact penalty_id string

        penalty = None
        for p in self.db.penalties:
            if p.penalty_id == penalty_id:
                penalty = p
                break

        if not penalty:
            return

        if column_id == '#8':  # Actions column
            action = messagebox.askquestion("Action", "Do you want to EDIT this penalty? (Click No to DELETE)")
            if action == 'yes':
                self.show_edit_penalty_page(penalty)
            else:
                self.delete_penalty(penalty_id)

    def delete_penalty(self, penalty_id):
        """Delete penalty record"""
        if messagebox.askyesno("Confirm", "Are you sure you want to delete this penalty?"):
            self.db.penalties = [p for p in self.db.penalties if p.penalty_id != penalty_id]
            self.db.log_activity("Delete penalty", details=f"Penalty #{penalty_id}", category="penalty")
            self.db.save_data()
            messagebox.showinfo("Success", "Penalty deleted successfully")
            self.show_penalties_page()

    def show_edit_penalty_page(self, penalty):
        """Show edit penalty — full page identical to Add Penalty, pre-filled"""
        self.clear_content()
        HDR = '#B91C1C'
        found_emp = {'obj': self.db.get_employee(penalty.emp_id)}

        # ── Header ──────────────────────────────────────────────────────────
