        card.pack(fill=tk.BOTH, expand=True)
        content = tk.Frame(card, bg='white', padx=50, pady=25)
        content.pack(fill=tk.BOTH, expand=True)
        content.columnconfigure(0, minsize=180)
        content.columnconfigure(1, minsize=300)

        r = 0

        # ── Section: Employee ────────────────────────────────────────────────
        sec1 = tk.Frame(content, bg='#EFF6FF')
        sec1.grid(row=r, column=0, columnspan=2, sticky='ew', pady=(0, 12))
        tk.Label(sec1, text="👤  EMPLOYEE  —  Search by Code", font=('Arial', 11, 'bold'),
                 bg='#EFF6FF', fg='#1E40AF').pack(anchor='w', padx=15, pady=8)
        r += 1

        tk.Label(content, text="Employee Code:", font=('Arial', 10, 'bold'), bg='white',
                 fg='#334155').grid(row=r, column=0, sticky='e', pady=8)
