        info_card.grid(row=r, column=0, columnspan=2, sticky='ew', pady=6)
        lbl_name = tk.Label(info_card, text="Name:  —", font=('Arial', 10), bg='#F0FDF4', fg='#166534', anchor='w')
        lbl_name.pack(fill=tk.X, padx=15, pady=(8, 2))
        lbl_dept = tk.Label(info_card, text="Department:  —", font=('Arial', 10), bg='#F0FDF4', fg='#166534', anchor='w')
        lbl_dept.pack(fill=tk.X, padx=15, pady=2)
        lbl_pos  = tk.Label(info_card, text="Position:  —", font=('Arial', 10), bg='#F0FDF4', fg='#166534', anchor='w')
        lbl_pos.pack(fill=tk.X, padx=15, pady=(2, 8))
        r += 1

        def _refresh_info(emp):
            if emp:
                dept_obj  = self.db.departments.get(emp.department)
                dept_name = dept_obj.name if dept_obj else (emp.department or "—")
                lbl_name.config(text=f"Name:  {emp.name}", fg='#166534')
                lbl_dept.config(text=f"Department:  {dept_name}", fg='#166534')
                lbl_pos.config(text=f"Position:  {emp.position or '—'}", fg='#166534')
                info_card.config(bg='#F0FDF4', highlightbackground='#86EFAC')
                for w in (lbl_name, lbl_dept, lbl_pos): w.config(bg='#F0FDF4')
            else:
                lbl_name.config(text="⚠  Code not found", fg='#991B1B')
                lbl_dept.config(text="Department:  —", fg='#991B1B')
                lbl_pos.config(text="Position:  —", fg='#991B1B')
                info_card.config(bg='#FFF1F2', highlightbackground='#FCA5A5')
                for w in (lbl_name, lbl_dept, lbl_pos): w.config(bg='#FFF1F2')

        # Pre-fill employee info
        _refresh_info(found_emp['obj'])

        def _search(*_):
            code = code_var.get().strip()
            emp  = self.db.get_employee(code) if code else None
            found_emp['obj'] = emp
            _refresh_info(emp)

        code_var.trace_add("write", _search)

        # ── Section: Penalty Details ─────────────────────────────────────────
        sec2 = tk.Frame(content, bg='#FEF3C7')
        sec2.grid(row=r, column=0, columnspan=2, sticky='ew', pady=(14, 10))
