        r += 1

        tk.Label(content, text="Absence Start Date:", font=('Arial', 10, 'bold'), bg='white',
                 fg='#334155').grid(row=r, column=0, sticky='e', pady=10)
        absence_start_var = tk.StringVar()
        tk.Entry(content, textvariable=absence_start_var, font=('Arial', 11), width=28,
                 relief='solid', bd=1).grid(row=r, column=1, sticky='w', padx=15, pady=10)
        r += 1

        tk.Label(content, text="Absence End Date:", font=('Arial', 10, 'bold'), bg='white',
                 fg='#334155').grid(row=r, column=0, sticky='e', pady=10)
        absence_end_var = tk.StringVar()
        tk.Entry(content, textvariable=absence_end_var, font=('Arial', 11), width=28,
                 relief='solid', bd=1).grid(row=r, column=1, sticky='w', padx=15, pady=10)
        r += 1

