    def load_attendance_data(self, attendance_records=None, filtered_by_employee=False):
        """تحميل بيانات Attendance في الجدول"""
        if not hasattr(self, 'attendance_tree'):
            return

        # مسح الجدول
        for item in self.attendance_tree.get_children():
            self.attendance_tree.delete(item)

        # تحميل البيانات
        if attendance_records is None:
            attendance_records = self.db.get_all_attendance()

        total_hours = 0
        count = 0

        def _emp_sort(eid):
            try:
                return (0, int(eid))
            except (ValueError, TypeError):
                return (1, str(eid))
        attendance_records = sorted(attendance_records, key=lambda a: a.date_key(), reverse=True)
        attendance_records = sorted(attendance_records, key=lambda a: _emp_sort(a.emp_id))

        for attendance in attendance_records:
            emp = self.db.get_employee(attendance.emp_id)
            emp_name = (emp.name if emp else "N/A")
            duration = attendance.get_duration()
            duration_hours = attendance.get_duration_hours()

            self.attendance_tree.insert("", tk.END, values=(
                attendance.emp_id, emp_name, attendance.date,
                attendance.check_in, attendance.check_out,
                duration if duration else "--:--",
                self.db.get_attendance_display_status(attendance)
            ))

            if duration_hours > 0:
                total_hours += duration_hours
                count += 1

        # تحديث الملخص
        avg_hours = round(total_hours / count, 2) if count > 0 else 0
        total_h = int(total_hours)
        total_m = int(round((total_hours - total_h) * 60))
        if hasattr(self, 'attendance_summary_label'):
            if filtered_by_employee and count > 0:
                # عرض إجمالي ساعات العمل عند البحث بموظف محدد
                self.attendance_summary_label.config(
                    text=f"Total Records: {len(attendance_records)} | "
                         f"✅ Total Work Hours: {total_h}h {total_m:02d}m | "
                         f"Avg/Day: {avg_hours} hrs"
                )
            else:
                self.attendance_summary_label.config(
                    text=f"Total Records: {len(attendance_records)} | Avg Duration: {avg_hours} hours"
                )

    def search_attendance_records(self):
        """بحث ذكي: الاسم، الكود، القسم، المنصب، التاريخ — منفردة أو مجتمعة
        أمثلة:
            Mohamed Alazab
            001
            HR
            Manager
            03/06/2026
            Mohamed 03/06/2026
            HR 03/06/2026
        """
        import re

        raw = getattr(self, 'attendance_search_var', tk.StringVar()).get().strip()
        hint = "Name / Code / Department / Position / Date (dd/mm/yyyy) — or combine"
        if raw == hint:
            raw = ""

        # استخراج التاريخ المضمّن في نص البحث
        date_pattern = re.compile(r'\b(\d{1,2}/\d{1,2}/\d{4})\b')
        date_match   = date_pattern.search(raw)
        inline_date  = date_match.group(1) if date_match else ""
        text_filter  = date_pattern.sub("", raw).strip().lower()

        # نطاق التاريخ من الحقلين المنفصلين
        date_from = getattr(self, 'attendance_date_from_var', tk.StringVar()).get().strip()
        date_to   = getattr(self, 'attendance_date_to_var',   tk.StringVar()).get().strip()

        records = self.db.get_all_attendance()

        # ── فلترة نصية: اسم أو كود أو قسم أو منصب ───────────────────────────
        if text_filter:
            filtered = []
            for a in records:
                emp = self.db.get_employee(a.emp_id)
                if emp:
                    searchable = " ".join([
                        (emp.name       or "").lower(),
                        (emp.emp_id     or "").lower(),
                        (emp.department or "").lower(),
                        (emp.position   or "").lower(),
                    ])
                    # فحص اسم القسم الكامل أيضاً
                    dept_obj = self.db.departments.get(emp.department)
                    if dept_obj:
                        searchable += " " + (dept_obj.name or "").lower()
                else:
                    searchable = a.emp_id.lower()

                if text_filter in searchable:
                    filtered.append(a)
            records = filtered

        # ── فلترة بتاريخ مضمّن في حقل البحث ─────────────────────────────────
        if inline_date:
            records = [a for a in records if a.date == inline_date]

        # ── فلترة بنطاق التاريخ From / To ────────────────────────────────────
        if date_from:
            records = [a for a in records if a.date >= date_from]
        if date_to:
            records = [a for a in records if a.date <= date_to]

        filtered_by_employee = bool(text_filter)
        self.load_attendance_data(records, filtered_by_employee=filtered_by_employee)

    # ── إعدادات السحب التلقائي ───────────────────────────────────────────────
    _ZK_RECHECK_MS = 30 * 60 * 1000   # يعيد الفحص كل ٣٠ دقيقة طوال التشغيل

    def _auto_pull_zk_periodic(self):
        """سحب دوري صامت من أجهزة البصمة كل N دقيقة (الإعداد zk_auto_pull_minutes) — لا يخصم Day Off"""
        try:
            mins = int(self.db.settings.get("zk_auto_pull_minutes", 15) or 0)
        except (TypeError, ValueError):
            mins = 15
        try:
            self.root.after(max(mins, 1) * 60 * 1000, self._auto_pull_zk_periodic)
        except Exception:
            pass
        if mins <= 0 or not ZKTEICO_AVAILABLE or not self.db.zk_devices:
            return
        def _run():
            added = 0
            try:
                before = len(self.db.attendance)
                start = (date.today() - timedelta(days=2))
                ok, _msg = self.db.sync_attendance_from_zk(start_date=start, deduct_dayoff=False)
                added = (len(self.db.attendance) - before) if ok else 0
                if ok:
                    added = max(added, 1)  # تحديث الواجهة حتى لو كانت التعديلات على سجلات موجودة
            except Exception:
                pass
            try:
                self.root.after(0, lambda: self._after_auto_sync(added))
            except Exception:
                pass
        threading.Thread(target=_run, daemon=True).start()

    def _auto_sync_zk_daily(self):
        """مزامنة تلقائية يومية من أجهزة البصمة.

        المنطق:
        • السحب: يسحب البصمات تلقائيًا مرة في اليوم. إن كانت الماكينة غير متصلة
          لا يُسجَّل النجاح، فيُعاد المحاولة كل ٣٠ دقيقة حتى ينجح.
        • Day Off: لا يوجد توقيت ثابت إطلاقًا. النظام يعالج «اليوم السابق المكتمل»
          فقط (وهو يوم انتهى بالكامل): أي موظف لم يبصم طوال ذلك اليوم يُسجَّل له
          Day Off ويُخصم يوم من رصيده. يتم ذلك مرة واحدة لكل يوم.
          هكذا لا يُحسم أي موظف قبل أن ينتهي يومه فعليًا.
        • تعيد جدولة نفسها دائمًا لضمان استمرار العمل طوال تشغيل البرنامج.
        """
        # أعد الجدولة أولًا ودائمًا — لا تتوقف الحلقة أبدًا
        try:
            self.root.after(self._ZK_RECHECK_MS, self._auto_sync_zk_daily)
        except Exception:
            pass

        if not ZKTEICO_AVAILABLE or not self.db.zk_devices:
            return

        today      = date.today()
        today_str  = today.strftime("%Y-%m-%d")
        yesterday  = today - timedelta(days=1)
        yest_str   = yesterday.strftime("%Y-%m-%d")

        pull_key   = "last_auto_zk_sync"        # آخر يوم تم فيه سحب ناجح
        finalize_key = "last_dayoff_deduction"  # آخر «يوم مكتمل» تمت معالجته

        need_pull     = self.db.settings.get(pull_key, "")     != today_str
        need_finalize = self.db.settings.get(finalize_key, "") != yest_str

        if not need_pull and not need_finalize:
            return  # لا شيء مطلوب في هذه الدورة

        def _do_sync():
            try:
                # (١) اسحب بصمات اليوم (بدون أي خصم) — لإبقاء البيانات محدّثة
                success, message = self.db.sync_attendance_from_zk(deduct_dayoff=False)
                if not success:
                    return  # فشل الاتصال → لا نسجّل شيئًا، يُعاد المحاولة لاحقًا

                self.db.settings[pull_key] = today_str

                # (٢) عالج «اليوم السابق المكتمل»: سجّل Day Off للغائبين عنه واخصم
                deducted = []
                if need_finalize:
                    deducted = self.db.apply_dayoff_deduction(yesterday, save=False)
                    self.db.settings[finalize_key] = yest_str

                self.db.save_data()

                if need_finalize:
                    note = (f"🗓️ {len(deducted)} Day Off recorded for "
                            f"{yesterday.strftime('%d/%m/%Y')}")
                    self.root.after(0, lambda: self._show_auto_sync_toast(
                        f"✅ Auto Sync Done\n{note}"))
                else:
                    self.root.after(0, lambda: self._show_auto_sync_toast(
                        f"✅ Auto Sync Done\n{message[:120]}"))
            except Exception:
                pass

        threading.Thread(target=_do_sync, daemon=True).start()

    def _show_auto_sync_toast(self, message):
        """إشعار بسيط بنتيجة المزامنة التلقائية في الزاوية"""
        try:
            toast = tk.Toplevel(self.root)
            toast.overrideredirect(True)
            toast.attributes("-topmost", True)
            toast.configure(bg="#0F172A")
            w, h = 360, 80
            sw = self.root.winfo_screenwidth()
            sh = self.root.winfo_screenheight()
            toast.geometry(f"{w}x{h}+{sw-w-20}+{sh-h-60}")
            tk.Label(toast, text=message, font=("Segoe UI", 9),
                     bg="#0F172A", fg="#94A3B8",
                     wraplength=340, justify="left", padx=12, pady=10).pack(fill=tk.BOTH)
            toast.after(5000, toast.destroy)
        except Exception:
            pass

    def sync_mobile_attendance(self):
        """سحب بصمات الموبايل (GPS) من جوجل شيت إلى Attendance"""
        cfg = self.db.get_mobile_punch_settings()
        if not cfg.get("gsheet_url"):
            messagebox.showwarning("Mobile Punch", "لم يتم ربط البصمة عبر الموبايل بعد.\nSettings → Mobile GPS Punch")
            return
        ok, msg, n = self.db.sync_mobile_punches_from_gsheet()
        (messagebox.showinfo if ok else messagebox.showerror)("Mobile Punch Sync", msg)
        self.show_attendance_page()

    def sync_zk_attendance(self):
        """مزامنة Attendance من أجهزة ZKTeco"""
        if not ZKTEICO_AVAILABLE:
            messagebox.showerror(
                "مكتبة غير مثبتة | Library Not Installed",
                "مكتبة pyzk غير مثبتة.\n\nلتثبيتها افتح موجه الأوامر (CMD) واكتب:\n    pip install pyzk\n\npyzk library is not installed.\nOpen Command Prompt and run:\n    pip install pyzk"
            )
            return
        if not self.db.zk_devices:
            messagebox.showwarning("Device Not Configured", "Please add at least one ZKTeco device in Settings first.")
            self.show_settings_page()
            return

        # اسأل المستخدم عن تاريخ بداية الجلب (افتراضياً 01/06/2026)
        from tkinter import simpledialog
        answer = simpledialog.askstring(
            "Sync from Device | جلب البصمة",
            "اجلب سجلات البصمة بدءاً من تاريخ (يوم/شهر/سنة)\n"
            "اتركه فارغاً لجلب كل السجلات:\n\n"
            "Fetch fingerprint records from date (DD/MM/YYYY).\n"
            "Leave empty to fetch ALL records:",
            initialvalue="01/06/2026",
            parent=self.root
        )
        if answer is None:
            return  # ألغى المستخدم العملية

        answer = answer.strip()
        start_date = None
        if answer:
            parsed = None
            for fmt in ("%d/%m/%Y", "%Y-%m-%d", "%d-%m-%Y"):
                try:
                    parsed = datetime.strptime(answer, fmt).date()
                    break
                except ValueError:
                    pass
            if parsed is None:
                messagebox.showerror(
                    "Invalid Date | تاريخ غير صحيح",
                    "أدخل التاريخ بصيغة يوم/شهر/سنة مثل: 01/06/2026"
                )
                return
            start_date = parsed

        success, message = self.db.sync_attendance_from_zk(start_date=start_date)
        if success:
            messagebox.showinfo("Sync Complete", message)
            self.show_attendance_page()
        else:
            messagebox.showerror("Sync Failed", message)

    # ═════════════════════════════════════════════════════════════════════════
    # Mobile GPS Punch (Google Sheets) — البصمة عبر الموبايل بدون سيرفر محلي
    # ═════════════════════════════════════════════════════════════════════════
    def run_update_check(self, manual=False):
        """فحص التحديث من الرابط المحفوظ؛ يسأل قبل التطبيق"""
        url = (self.db.settings.get("update_url") or "").strip()
        if not url:
            if manual:
                messagebox.showwarning("Update", "ضع رابط التحديث أولًا")
            return
        def _work():
            has, rb, payload = check_for_update(url)
            def _ui():
                if not has:
                    if manual:
                        messagebox.showinfo("Update", payload if rb is None else "أنت على أحدث نسخة (build %s)" % APP_BUILD)
                    return
                if messagebox.askyesno("تحديث متاح | Update available",
                                       "نسخة جديدة متاحة: build %s (الحالية %s)\n\nسيتم حفظ نسخة احتياطية ثم استبدال الملف وإعادة تشغيل البرنامج. متابعة؟" % (rb, APP_BUILD)):
                    try:
                        self.db.save_data()
                        apply_update(payload)
                    except Exception as ex:
                        messagebox.showerror("Update", str(ex))
            try:
                self.root.after(0, _ui)
            except Exception:
                pass
        threading.Thread(target=_work, daemon=True).start()

    def _start_mobile_punch_autosync(self):
        """سحب البصمات من جوجل شيت تلقائيًا كل N دقيقة (في خيط خلفي حتى لا تتجمد الواجهة)"""
        if getattr(self, "_mp_autosync_scheduled", False):
            return
        self._mp_autosync_scheduled = True
        self._mobile_punch_autosync_tick()

    def _after_auto_sync(self, added):
        """يُستدعى في خيط الواجهة بعد انتهاء مزامنة خلفية"""
        self._last_auto_sync_str = datetime.now().strftime("%H:%M")
        try:
            if getattr(self, "_att_auto_lbl", None) and self._att_auto_lbl.winfo_exists():
                txt = self._att_auto_lbl.cget("text")
                self._att_auto_lbl.config(text=txt.split(" · last:")[0] + " · last: " + self._last_auto_sync_str)
        except Exception:
            pass
        if added and getattr(self, "_page_name", None) == "attendance":
            try:
                self.show_attendance_page()   # تحديث الجدول تلقائيًا لظهور البصمات الجديدة
            except Exception:
                pass

    def _mobile_punch_autosync_tick(self):
        try:
            cfg = self.db.get_mobile_punch_settings()
            mins = int(cfg.get("auto_sync_minutes") or 0)
            if mins > 0 and cfg.get("gsheet_url"):
                def _run():
                    try:
                        ok, msg, n = self.db.sync_mobile_punches_from_gsheet()
                    except Exception:
                        ok, n = False, 0
                    try:
                        self.root.after(0, lambda: self._after_auto_sync(n if ok else 0))
                    except Exception:
                        pass
                threading.Thread(target=_run, daemon=True).start()
            delay = max(mins, 1) * 60 * 1000
        except Exception:
            delay = 5 * 60 * 1000
        try:
            self.root.after(delay, self._mobile_punch_autosync_tick)
        except Exception:
            pass

    def show_mobile_punch_report(self):
        """تقرير البصمة عبر الموبايل — ضمن مركز التقارير"""
        self.clear_content()
        header = tk.Frame(self.content_frame, bg='#0F766E', height=110)
        header.pack(fill=tk.X); header.pack_propagate(False)
        tf = tk.Frame(header, bg='#0F766E'); tf.pack(side=tk.LEFT, padx=30, pady=20)
        tk.Label(tf, text="📍", font=('Segoe UI', 30), bg='#0F766E').pack(side=tk.LEFT, padx=(0, 15))
        tt = tk.Frame(header, bg='#0F766E'); tt.pack(side=tk.LEFT, pady=5)
        tk.Label(tt, text="Mobile GPS Punch Report", font=('Segoe UI', 22, 'bold'), bg='#0F766E', fg='white').pack(anchor='w')
        tk.Label(tt, text="تقرير البصمة عبر الموبايل — يُدمج مع بصمة الوجه في سجل الحضور نفسه (أول دخول / آخر انصراف)",
                 font=('Segoe UI', 11), bg='#0F766E', fg='#99F6E4').pack(anchor='w', pady=(4, 0))
        bf = tk.Frame(header, bg='#0F766E'); bf.pack(side=tk.RIGHT, padx=30, pady=25)
        tk.Button(bf, text="← Back", font=('Segoe UI', 9, 'bold'), bg='#2563EB', fg='white', relief=tk.FLAT, padx=18, pady=8,
                  command=self.show_reports_page).pack(side=tk.LEFT, padx=5)

        content = tk.Frame(self.content_frame, bg=self.colors['bg'])
        content.pack(fill=tk.BOTH, expand=True, padx=20, pady=15)

        # ── Filters ──────────────────────────────────────────────────────
        flt = tk.Frame(content, bg='white', highlightbackground='#E2E8F0', highlightthickness=1)
        flt.pack(fill=tk.X, pady=(0, 10))
        today = date.today()
        v_from = tk.StringVar(value=today.replace(day=1).strftime("%d/%m/%Y"))
        v_to = tk.StringVar(value=today.strftime("%d/%m/%Y"))
        v_emp = tk.StringVar()
        v_res = tk.StringVar(value="All")
        v_type = tk.StringVar(value="All")
        def lab(txt, col):
            tk.Label(flt, text=txt, font=('Segoe UI', 10), bg='white', fg='#334155').grid(row=0, column=col, padx=(12, 4), pady=10)
        lab("From / من", 0); tk.Entry(flt, textvariable=v_from, width=12, font=('Segoe UI', 10), relief=tk.SOLID, bd=1).grid(row=0, column=1)
        lab("To / إلى", 2); tk.Entry(flt, textvariable=v_to, width=12, font=('Segoe UI', 10), relief=tk.SOLID, bd=1).grid(row=0, column=3)
        lab("Employee / موظف", 4); tk.Entry(flt, textvariable=v_emp, width=22, font=('Segoe UI', 10), relief=tk.SOLID, bd=1).grid(row=0, column=5)
        lab("Result", 6); ttk.Combobox(flt, textvariable=v_res, values=["All", "OK", "Rejected"], width=10, state='readonly').grid(row=0, column=7)
        lab("Type", 8); ttk.Combobox(flt, textvariable=v_type, values=["All", "in", "out"], width=7, state='readonly').grid(row=0, column=9)

        # ── Summary ──────────────────────────────────────────────────────
        summ = tk.Label(content, text="", font=('Segoe UI', 10, 'bold'), bg=self.colors['bg'], fg='#0F766E', anchor='w')
        tk.Label(content, text="Double-click a row to view the employee's face photo  |  اضغط مرتين على السطر لعرض صورة الوجه",
                 font=('Segoe UI', 9), bg=self.colors['bg'], fg='#64748B', anchor='w').pack(fill=tk.X)
        summ.pack(fill=tk.X, pady=(0, 6))

        # ── Table ────────────────────────────────────────────────────────
        tframe = tk.Frame(content, bg='white', relief=tk.RIDGE, bd=2)
        tframe.pack(fill=tk.BOTH, expand=True)
        sy = ttk.Scrollbar(tframe); sy.pack(side=tk.RIGHT, fill=tk.Y)
        cols = ("date", "time", "clock", "name", "dept", "type", "dist", "acc", "result", "photo")
        tree = ttk.Treeview(tframe, columns=cols, show='headings', yscrollcommand=sy.set)
        sy.config(command=tree.yview)
        for c, h, w, a in [("date", "Date", 95, 'center'), ("time", "Time", 65, 'center'), ("clock", "Clock No", 75, 'center'),
                           ("name", "Employee", 240, 'w'), ("dept", "Department", 110, 'center'), ("type", "Type", 60, 'center'),
                           ("dist", "Distance (m)", 90, 'center'), ("acc", "GPS ± m", 70, 'center'), ("result", "Result / السبب", 280, 'w'), ("photo", "Photo", 60, 'center')]:
            tree.heading(c, text=h); tree.column(c, width=w, anchor=a)
        tree.pack(fill=tk.BOTH, expand=True)
        photo_urls = {}

        def open_photo(_e=None):
            sel = tree.selection()
            if not sel:
                return
            url = photo_urls.get(sel[0], "")
            if not url:
                messagebox.showinfo("Photo", "لا توجد صورة لهذه البصمة\nNo photo for this punch"); return
            vals = tree.item(sel[0], "values")
            try:
                import urllib.request, io
                from PIL import Image, ImageTk
                raw = urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "MODO-HR"}), timeout=30).read()
                img = Image.open(io.BytesIO(raw)); img.thumbnail((480, 480))
                w = tk.Toplevel(self.root); w.title("📷 %s — %s %s" % (vals[3], vals[0], vals[1])); w.configure(bg='white')
                w._img = ImageTk.PhotoImage(img)
                tk.Label(w, image=w._img, bg='white').pack(padx=12, pady=12)
                tk.Label(w, text="%s  |  %s  |  %s %s  |  %s" % (vals[2], vals[3], vals[0], vals[1], vals[5]),
                         font=('Segoe UI', 11, 'bold'), bg='white', fg='#0F766E').pack(pady=(0, 10))
                tk.Button(w, text="🌐 Open in browser", bg='#3B82F6', fg='white', relief=tk.FLAT, padx=12, pady=5,
                          command=lambda: __import__("webbrowser").open(url)).pack(pady=(0, 12))
            except Exception:
                import webbrowser
                webbrowser.open(url)
        tree.bind("<Double-1>", open_photo)
        tree.tag_configure('ok', foreground='#065F46'); tree.tag_configure('bad', foreground='#991B1B')

        rows_cache = []

        def _pd(sv):
            try:
                return datetime.strptime(sv.strip(), "%d/%m/%Y").date()
            except Exception:
                return None

        def load():
            tree.delete(*tree.get_children()); rows_cache.clear()
            d1, d2 = _pd(v_from.get()), _pd(v_to.get())
            q = v_emp.get().strip().lower()
            n_ok = n_bad = 0
            for e in (getattr(self.db, "mobile_punch_log", []) or []):
                ed = _pd(self.db._mp_norm_date(e.get("date") or str(e.get("timestamp", ""))[:10]))
                if d1 and ed and ed < d1:
                    continue
                if d2 and ed and ed > d2:
                    continue
                ok = e.get("result") == "ok"
                if v_res.get() == "OK" and not ok:
                    continue
                if v_res.get() == "Rejected" and ok:
                    continue
                if v_type.get() != "All" and e.get("type") != v_type.get():
                    continue
                name = e.get("name", "") or ""
                if q and q not in name.lower() and q not in str(e.get("clock_no", "")).lower():
                    continue
                emp = self.db.employees.get(e.get("emp_id", ""))
                dept = e.get("dept") or (self.db._mp_dept_name(emp) if emp else "")
                acc = e.get("accuracy")
                try:
                    acc_s = "%.0f" % float(acc) if acc not in (None, "") else ""
                except (TypeError, ValueError):
                    acc_s = str(acc)
                row = (ed.strftime("%d/%m/%Y") if ed else e.get("date", ""), e.get("time") or self.db._mp_norm_time(str(e.get("timestamp", ""))[11:]),
                       e.get("clock_no", ""), name, dept, e.get("type", ""), e.get("distance_m", ""), acc_s,
                       "OK" if ok else e.get("reason", ""), "📷" if e.get("photo") else "", e.get("photo", ""))
                rows_cache.append(row)
                n_ok += ok; n_bad += (not ok)
            photo_urls.clear()
            for row in sorted(rows_cache, key=lambda r: (_pd(r[0]) or date.min, r[1]), reverse=True):
                iid = tree.insert('', 'end', values=row[:10], tags=('ok' if row[8] == "OK" else 'bad',))
                photo_urls[iid] = row[10]
            summ.config(text="Total: %d   |   ✅ Accepted: %d   |   ❌ Rejected: %d" % (n_ok + n_bad, n_ok, n_bad))

        def sync_now():
            ok, msg, n = self.db.sync_mobile_punches_from_gsheet()
            (messagebox.showinfo if ok else messagebox.showerror)("Sync", msg)
            load()

        def export_excel():
            if not rows_cache:
                messagebox.showwarning("Export", "لا توجد بيانات لتصديرها"); return
            path = ask_save_path("mobile_punch_report.xlsx", parent=self.root)
            if not path:
                return
            try:
                from openpyxl import Workbook
                from openpyxl.styles import Font, PatternFill, Alignment
                wb = Workbook(); ws = wb.active; ws.title = "Mobile Punch"
                heads = ["Date", "Time", "Clock No", "Employee", "Department", "Type", "Distance (m)", "GPS ± m", "Result", "Photo URL"]
                ws.append(heads)
                for c in ws[1]:
                    c.font = Font(bold=True, color="FFFFFF"); c.fill = PatternFill("solid", fgColor="0F766E"); c.alignment = Alignment(horizontal='center')
                for r in sorted(rows_cache, key=lambda r: (_pd(r[0]) or date.min, r[1])):
                    ws.append(list(r[:9]) + [r[10]])
                for i, w in enumerate([12, 8, 10, 32, 14, 7, 13, 9, 50, 40], 1):
                    ws.column_dimensions[chr(64 + i)].width = w
                wb.save(path)
                messagebox.showinfo("Export", "تم التصدير:\n" + path)
            except Exception as ex:
                messagebox.showerror("Export", str(ex))

        btns = tk.Frame(flt, bg='white'); btns.grid(row=0, column=10, padx=12)
        tk.Button(btns, text="🔍 Apply", font=('Segoe UI', 9, 'bold'), bg='#3B82F6', fg='white', relief=tk.FLAT, padx=12, pady=5, command=load).pack(side=tk.LEFT, padx=3)
        tk.Button(btns, text="🔄 Sync from Google", font=('Segoe UI', 9, 'bold'), bg='#0F766E', fg='white', relief=tk.FLAT, padx=12, pady=5, command=sync_now).pack(side=tk.LEFT, padx=3)
        tk.Button(btns, text="📤 Excel", font=('Segoe UI', 9, 'bold'), bg='#10B981', fg='white', relief=tk.FLAT, padx=12, pady=5, command=export_excel).pack(side=tk.LEFT, padx=3)
        tk.Button(btns, text="📅 Attendance Report", font=('Segoe UI', 9), bg='#64748B', fg='white', relief=tk.FLAT, padx=12, pady=5,
                  command=lambda: self.display_report("attendance")).pack(side=tk.LEFT, padx=3)
        load()

    def show_face_enrollments(self):
        """نافذة اعتماد/رفض بصمات الوجه المسجّلة من الموبايل"""
        w = tk.Toplevel(self.root); w.title("🧑 Face Enrollments — اعتماد الوجوه"); w.geometry("900x520"); w.configure(bg='white')
        tk.Label(w, text="أول بصمة لكل موظف (مع تفعيل التحقق) تسجّل وجهه بحالة Pending. افتح الصورة وتأكد أنه صاحب الرقم ثم اعتمد.\n"
                         "Approved = البصمات التالية تُقبل فقط إذا طابق الوجه · Rejected/Reset = يُعاد التسجيل في البصمة التالية",
                 font=('Segoe UI', 9), bg='#F0FDFA', fg='#115E59', justify='right', padx=10, pady=8).pack(fill=tk.X)
        f = tk.Frame(w, bg='white'); f.pack(fill=tk.BOTH, expand=True, padx=10, pady=8)
        cols = ("emp", "name", "status", "enrolled", "decided")
        tree = ttk.Treeview(f, columns=cols, show='headings', height=14)
        for c, h, wd in [("emp", "Clock No", 80), ("name", "Employee", 260), ("status", "Status", 90), ("enrolled", "Enrolled", 140), ("decided", "Decided", 140)]:
            tree.heading(c, text=h); tree.column(c, width=wd, anchor='center' if c != 'name' else 'w')
        sb = ttk.Scrollbar(f, orient='vertical', command=tree.yview); tree.configure(yscrollcommand=sb.set)
        tree.pack(side=tk.LEFT, fill=tk.BOTH, expand=True); sb.pack(side=tk.LEFT, fill=tk.Y)
        tree.tag_configure('Pending', foreground='#B45309'); tree.tag_configure('Approved', foreground='#065F46'); tree.tag_configure('Rejected', foreground='#991B1B')
        photos = {}
        v_filter = tk.StringVar(value="Pending")

        def load():
            tree.delete(*tree.get_children()); photos.clear()
            try:
                res = self.db.gsheet_request("pull_faces", {"status": "" if v_filter.get() == "All" else v_filter.get()})
            except Exception as ex:
                messagebox.showerror("Faces", str(ex), parent=w); return
            for r in res.get("rows", []):
                iid = tree.insert('', 'end', values=(r.get("emp_id"), r.get("name"), r.get("status"), r.get("enrolled"), r.get("decided")), tags=(r.get("status"),))
                photos[iid] = r.get("photo", "")

        def view_photo(_e=None):
            sel = tree.selection()
            if not sel or not photos.get(sel[0]):
                messagebox.showinfo("Photo", "لا توجد صورة", parent=w); return
            url = photos[sel[0]]; vals = tree.item(sel[0], "values")
            try:
                import urllib.request, io
                from PIL import Image, ImageTk
                raw = urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "MODO-HR"}), timeout=30).read()
                img = Image.open(io.BytesIO(raw)); img.thumbnail((420, 420))
                pw = tk.Toplevel(w); pw.title("%s — %s" % (vals[0], vals[1])); pw.configure(bg='white')
                pw._img = ImageTk.PhotoImage(img); tk.Label(pw, image=pw._img, bg='white').pack(padx=10, pady=10)
            except Exception:
                import webbrowser; webbrowser.open(url)
        tree.bind("<Double-1>", view_photo)

        def decide(status):
            sel = tree.selection()
            if not sel:
                messagebox.showwarning("Faces", "اختر موظفًا", parent=w); return
            vals = tree.item(sel[0], "values")
            if status == "Reset" and not messagebox.askyesno("Reset", "حذف الوجه المسجّل للموظف %s ليُعاد تسجيله في البصمة التالية؟" % vals[0], parent=w):
                return
            try:
                self.db.gsheet_request("set_face_status", {"emp_id": vals[0], "status": status, "note": getattr(self, "current_user", "admin")})
                self.db.log_activity("Face enrollment " + status, "%s (%s)" % (vals[1], vals[0]), category="attendance", user=getattr(self, "current_user", "admin"))
                load()
            except Exception as ex:
                messagebox.showerror("Faces", str(ex), parent=w)

        b = tk.Frame(w, bg='white'); b.pack(fill=tk.X, padx=10, pady=(0, 10))
        ttk.Combobox(b, textvariable=v_filter, values=["Pending", "Approved", "Rejected", "All"], width=10, state='readonly').pack(side=tk.LEFT)
        tk.Button(b, text="🔄 Refresh", bg='#94A3B8', fg='white', relief=tk.FLAT, padx=12, pady=6, command=load).pack(side=tk.LEFT, padx=6)
        tk.Button(b, text="📷 View photo", bg='#3B82F6', fg='white', relief=tk.FLAT, padx=12, pady=6, command=view_photo).pack(side=tk.LEFT)
        tk.Button(b, text="✅ Approve", bg='#10B981', fg='white', relief=tk.FLAT, padx=14, pady=6, font=('Segoe UI', 9, 'bold'), command=lambda: decide("Approved")).pack(side=tk.LEFT, padx=6)
        tk.Button(b, text="❌ Reject", bg='#EF4444', fg='white', relief=tk.FLAT, padx=14, pady=6, command=lambda: decide("Rejected")).pack(side=tk.LEFT)
        tk.Button(b, text="🔁 Reset face", bg='#F59E0B', fg='white', relief=tk.FLAT, padx=14, pady=6, command=lambda: decide("Reset")).pack(side=tk.LEFT, padx=6)
        load()

    def publish_mobile_payslips(self, month, year):
        """نشر قسائم راتب شهر معيّن إلى جوجل شيت ليراها كل موظف من هاتفه (راتبه فقط)"""
        rows = self.get_monthly_report_data(month=int(month), year=int(year))
        ids = list(getattr(self, "_last_report_emp_ids", []) or [])
        out = []
        for i, r in enumerate(rows):
            eid = ids[i] if i < len(ids) else ""
            if not eid:
                continue
            r = list(r)
            out.append([eid, r[1], r[2]] + r[3:18])
        n = self.db.publish_payslips_to_gsheet(int(month), int(year), out)
        try:
            self.db.log_activity("Payslips published to mobile", "%02d/%d — %d employees" % (int(month), int(year), n),
                                 category="payroll", user=getattr(self, "current_user", "admin"))
        except Exception:
            pass
        return n

