        tk.Label(g1, text="API Key / المفتاح", font=('Arial', 10), bg='white', fg='#334155').grid(row=1, column=0, sticky='w', pady=6, padx=(0, 8))
        tk.Entry(g1, textvariable=v_key, font=('Arial', 10), width=30, relief=tk.SOLID, bd=1).grid(row=1, column=1, sticky='w', pady=6)
        tk.Label(g1, text="Auto-sync every (min) / مزامنة كل", font=('Arial', 10), bg='white', fg='#334155').grid(row=1, column=2, sticky='w', padx=(30, 8))
