        tk.Label(g1, text="Employee page URL / رابط صفحة الموظفين", font=('Arial', 10), bg='white', fg='#334155').grid(row=2, column=0, sticky='w', pady=6, padx=(0, 8))
        tk.Entry(g1, textvariable=v_page, font=('Arial', 10), width=80, relief=tk.SOLID, bd=1).grid(row=2, column=1, columnspan=3, sticky='w', pady=6)
        tk.Label(g1, text="(صفحة index.html المستضافة خارج جوجل — اتركه فارغًا لاستخدام رابط السكريبت نفسه)", font=('Arial', 8), bg='white', fg='#94A3B8').grid(row=3, column=1, columnspan=3, sticky='w')

