        sig_hr_var   = tk.StringVar()

        sig_style = {'font': ('Arial', 10), 'width': 22, 'relief': 'solid', 'bd': 1}

        sig_emp_entry  = tk.Entry(content, textvariable=sig_emp_var,  **sig_style)
        sig_head_entry = tk.Entry(content, textvariable=sig_head_var, **sig_style)
        sig_hr_entry   = tk.Entry(content, textvariable=sig_hr_var,   **sig_style)

        sig_emp_entry .grid(row=row, column=0, sticky='w', padx=6, pady=4)
        sig_head_entry.grid(row=row, column=1, sticky='w', padx=6, pady=4)
        sig_hr_entry  .grid(row=row, column=2, sticky='w', padx=6, pady=4)
