        for col in range(3):
            tk.Frame(content, bg='#94A3B8', height=1).grid(
                row=row, column=col, sticky='ew', padx=6, pady=(0, 12))
        row += 1

        # ─── ACTION BUTTONS ───
        btn_outer = tk.Frame(card, bg='#F8FAFC', relief='flat', bd=0)
        btn_outer.pack(fill=tk.X)
        btn_outer.configure(highlightbackground='#E2E8F0', highlightthickness=1)

        btn_frame = tk.Frame(btn_outer, bg='#F8FAFC')
        btn_frame.pack(pady=18, padx=30, anchor='center')

        def save_leave():
            if not selected_emp_id.get():
                messagebox.showerror("Error | Error", "Please enter a valid employee code")
                return
            if not start_date_var.get() or not end_date_var.get():
                messagebox.showerror("Error | Error", "Please fill in leave dates")
                return

            leave_id = self.db.next_seq_id("L", self.db.get_all_leaves(), "leave_id", 3)
            leave_type_clean = leave_type_var.get().split("|")[1].strip() if "|" in leave_type_var.get() else leave_type_var.get()

            leave = Leave(leave_id, selected_emp_id.get(), leave_type_clean,
                         start_date_var.get(), end_date_var.get(),
                         reason_var.get(), "Pending")

            success, message = self.db.add_leave(leave)
            if success:
                messagebox.showinfo("✅ Saved", f"Leave request saved successfully\n{message}")
                self.show_leaves_page()
            else:
                messagebox.showerror("Error", message)

        def print_leave():
            if not selected_emp_id.get():
                messagebox.showwarning("Notice", "Please select an employee first")
                return
            self.print_leave_request_form({
                'emp_id':      selected_emp_id.get(),
                'name':        emp_name_var.get(),
                'dept':        emp_dept_var.get(),
                'position':    emp_pos_var.get(),
                'leave_type':  leave_type_var.get(),
                'start_date':  start_date_var.get(),
                'end_date':    end_date_var.get(),
                'return_date': return_date_var.get(),
                'days':        days_var.get(),
                'reason':      reason_var.get(),
                'status':      'Pending',
                'sig_emp':     sig_emp_var.get(),
                'sig_head':    sig_head_var.get(),
                'sig_hr':      sig_hr_var.get(),
                'print_date':  datetime.now().strftime("%d/%m/%Y %H:%M"),
            })

        tk.Button(btn_frame, text="💾  Save", font=('Arial', 12, 'bold'),
                 bg='#10B981', fg='white', bd=0, padx=28, pady=11,
                 cursor='hand2', relief='flat', command=save_leave).pack(side=tk.LEFT, padx=10)

        tk.Button(btn_frame, text="🖨️  Print", font=('Arial', 12, 'bold'),
                 bg='#3B82F6', fg='white', bd=0, padx=28, pady=11,
                 cursor='hand2', relief='flat', command=print_leave).pack(side=tk.LEFT, padx=10)

        tk.Button(btn_frame, text="❌  Cancel", font=('Arial', 12, 'bold'),
                 bg='#EF4444', fg='white', bd=0, padx=28, pady=11,
                 cursor='hand2', relief='flat', command=self.show_leaves_page).pack(side=tk.LEFT, padx=10)

