        # Event handlers
        def on_select(event):
            for emp in self.db.employees.values():
                if emp.name == emp_var.get():
                    basic_var.set(format_number(emp.salary))
                    emp_id_lbl.config(text=f"ID: {emp.emp_id}")
                    d = self.db.departments.get(emp.department)
                    dept_lbl.config(text=f"Department: {d.name if d else 'N/A'}")
                    break

        emp_combo.bind('<<ComboboxSelected>>', on_select)

        def calculate_net_salary(*args):
            try:
                basic = float(basic_var.get() or 0)
                service_charge_value = float(service_var.get() or 0)
                allowances = float(allow_var.get() or 0)
                deductions = float(ded_var.get() or 0)
                _s = getattr(self.db, 'insurance_settings', {"min": 2700, "max": 16700})
                insurance_base = min(float(basic or 0), float(_s.get("max", 16700) or 16700))
                insurance = round(insurance_base * 0.11, 2)

                # Service charge = input number x basic salary (e.g. 1 x 5000 = 5000)
                service_charge = round(basic * service_charge_value, 2)
                salary_before_tax = basic + service_charge

                tax = 0
                taxable_amount = salary_before_tax - 5000 - insurance

                if taxable_amount > 0:
                    if taxable_amount <= 1250:
                        tax = round(taxable_amount * 0.10, 2)
                    else:
                        tax = round(1250 * 0.10, 2)
                        taxable_amount -= 1250
                        if taxable_amount <= 1250:
                            tax += round(taxable_amount * 0.15, 2)
                        else:
                            tax += round(1250 * 0.15, 2)
                            taxable_amount -= 1250
                            if taxable_amount <= 10833.33:
                                tax += round(taxable_amount * 0.20, 2)
                            else:
                                tax += round(10833.33 * 0.20, 2)
                                taxable_amount -= 10833.33
                                tax += round(taxable_amount * 0.225, 2)

                net_salary = round_to_nearest_5(salary_before_tax - tax - insurance - deductions)

                svc_lbl.config(text=f"Service: {service_charge:.2f}")
                tax_lbl.config(text=f"Tax: {tax:.2f}")
                ins_lbl.config(text=f"Insurance: {insurance:.2f}")
                net_lbl.config(text=f"Net: {net_salary:.2f}")
            except ValueError:
                svc_lbl.config(text="Service: --")
                tax_lbl.config(text="Tax: --")
                ins_lbl.config(text="Insurance: --")
                net_lbl.config(text="Net: --")

        basic_var.trace("w", calculate_net_salary)
        service_var.trace("w", calculate_net_salary)
        allow_var.trace("w", calculate_net_salary)
        ded_var.trace("w", calculate_net_salary)

        def save_payroll():
            if not emp_var.get() or not basic_var.get():
                messagebox.showerror("Error", "Please fill in all required fields")
                return

            try:
                basic_salary = float(basic_var.get())
                service_charge_percent = float(service_var.get() or 0)
                allowances = float(allow_var.get() or 0)
                deductions = float(ded_var.get() or 0)
                _s = getattr(self.db, 'insurance_settings', {"min": 2700, "max": 16700})
                insurance_base = min(float(basic_salary or 0), float(_s.get("max", 16700) or 16700))
                insurance = round(insurance_base * 0.11, 2)
            except ValueError:
                messagebox.showerror("Error", "Values must be numbers")
                return

            selected_name = emp_var.get()
            emp_id = None
            for emp in self.db.employees.values():
                if emp.name == selected_name:
                    emp_id = emp.emp_id
                    break

            if not emp_id:
                messagebox.showerror("Error", "Employee not found")
                return

            # Service charge = input number x basic salary (e.g. 1 x 5000 = 5000)
            service_charge = round(basic_salary * float(service_var.get() or 0), 2)
            salary_before_tax = basic_salary + service_charge

            tax = 0
            taxable_amount = salary_before_tax - 5000 - insurance

            if taxable_amount > 0:
                if taxable_amount <= 1250:
                    tax = round(taxable_amount * 0.10, 2)
                else:
                    tax = round(1250 * 0.10, 2)
                    taxable_amount -= 1250
                    if taxable_amount <= 1250:
                        tax += round(taxable_amount * 0.15, 2)
                    else:
                        tax += round(1250 * 0.15, 2)
                        taxable_amount -= 1250
                        if taxable_amount <= 10833.33:
                            tax += round(taxable_amount * 0.20, 2)
                        else:
                            tax += round(10833.33 * 0.20, 2)
                            taxable_amount -= 10833.33
                            tax += round(taxable_amount * 0.225, 2)

            net_salary = round_to_nearest_5(salary_before_tax - tax - insurance - deductions)
            payroll_id = self.db.next_seq_id("P", self.db.get_all_payrolls(), "payroll_id", 3)

            month_num = month_names_en.index(month_var.get()) + 1  # Convert name to number
            payroll = Payroll(payroll_id, emp_id, month_num, int(year_var.get()),
                             basic_salary, allowances, deductions, net_salary, service_charge, tax)

            success, message = self.db.add_payroll(payroll)
            if success:
                # ── Auto-archive this month's snapshot ──────────────────────
                self._archive_monthly_snapshot(month_num, int(year_var.get()))
                # ────────────────────────────────────────────────────────────
                messagebox.showinfo("Success", message)
                self.show_monthly_report_page()
            else:
                messagebox.showerror("Error", message)

        # Buttons
        btn_frame = tk.Frame(card, bg='white')
        btn_frame.pack(pady=20)

        save_btn = tk.Button(btn_frame, text="💾 Save Payroll", font=('Arial', 11, 'bold'),
                  bg='#10B981', fg='white', bd=0, padx=30, pady=10,
                  cursor='hand2', command=save_payroll)
