    def show_advance_details(self, advance_id):
        """عرض تفاصيل Advancesة"""
        advances = self.db.get_all_advances()
        advance = next((a for a in advances if a.advance_id == advance_id), None)

        if not advance:
            messagebox.showerror("Error", "Advance not found")
            return

        # إنشاء نافذة التفاصيل
        details_window = tk.Toplevel(self.root)
        details_window.title(f"Advance Details - {advance_id}")
        details_window.geometry("400x400")
        details_window.configure(bg="#f0f0f0")

        # إطار التفاصيل
        frame = ttk.Frame(details_window, padding=20)
        frame.pack(fill=tk.BOTH, expand=True)

        # عرض البيانات
        ttk.Label(frame, text="Advance No.:", font=("Arial", 10, "bold")).grid(row=0, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=advance.advance_id).grid(row=0, column=1, sticky=tk.W, pady=5)

        employee = self.db.get_employee(advance.emp_id)
        emp_name = (employee.name if employee else advance.emp_id)
        ttk.Label(frame, text="Employee:", font=("Arial", 10, "bold")).grid(row=1, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=f"{emp_name} ({advance.emp_id})").grid(row=1, column=1, sticky=tk.W, pady=5)

        ttk.Label(frame, text="Amount:", font=("Arial", 10, "bold")).grid(row=2, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=f"{advance.amount} EGP").grid(row=2, column=1, sticky=tk.W, pady=5)

        ttk.Label(frame, text="Date:", font=("Arial", 10, "bold")).grid(row=3, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=advance.date).grid(row=3, column=1, sticky=tk.W, pady=5)

        ttk.Label(frame, text="Reason:", font=("Arial", 10, "bold")).grid(row=4, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=advance.reason or "N/A").grid(row=4, column=1, sticky=tk.W, pady=5)

        ttk.Label(frame, text="Status:", font=("Arial", 10, "bold")).grid(row=5, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=advance.status).grid(row=5, column=1, sticky=tk.W, pady=5)

        ttk.Label(frame, text="Repaid Amount:", font=("Arial", 10, "bold")).grid(row=6, column=0, sticky=tk.W, pady=5)
        ttk.Label(frame, text=f"{advance.repaid_amount} EGP").grid(row=6, column=1, sticky=tk.W, pady=5)

        # أزرار التحكم
        btn_frame = ttk.Frame(frame)
        btn_frame.grid(row=7, column=0, columnspan=2, pady=20)

        if advance.status == "Pending":
            ttk.Button(btn_frame, text="Approve",
                      command=lambda: self.update_advance_status(advance_id, "Approved", details_window)).pack(side=tk.LEFT, padx=5)
            ttk.Button(btn_frame, text="Reject",
                      command=lambda: self.update_advance_status(advance_id, "Rejected", details_window)).pack(side=tk.LEFT, padx=5)

        ttk.Button(btn_frame, text="Close",
                  command=details_window.destroy).pack(side=tk.LEFT, padx=5)

    def update_advance_status(self, advance_id, status, parent_window=None):
        """تحديث حالة Advancesة"""
        success, message = self.db.update_advance_status(advance_id, status)
        if success:
            messagebox.showinfo("Success", message)
            if parent_window:
                parent_window.destroy()
            self.load_advances_data()
        else:
            messagebox.showerror("Error", message)

