        def search_emp(*args):
            code = code_var.get().strip()
            emp = self.db.get_employee(code)
            if emp:
                emp_name_var.set(emp.name or "")
                dept = self.db.departments.get(emp.department)
                emp_dept_var.set(dept.name if dept else emp.department)
                emp_pos_var.set(emp.position or "—")
                nat_id_var.set(getattr(emp, 'national_id', '') or "")
                ins_num_var.set(getattr(emp, 'insurance_number', '') or "")
                emp_addr_var.set(getattr(emp, 'address', '') or "")
                emp_phone_var.set(emp.phone or ""); emp_salary_var.set(str(emp.salary) if emp.salary else "")
                selected_emp_id.set(emp.emp_id); code_entry.config(fg='#059669')
                if emp.contract_start_date: old_start_var.set(emp.contract_start_date)
                if emp.contract_end_date:   old_end_var.set(emp.contract_end_date)
            else:
                emp_name_var.set("⚠ Not Found"); emp_dept_var.set("—"); emp_pos_var.set("—")
                selected_emp_id.set(""); code_entry.config(fg='#DC2626')

        code_var.trace('w', search_emp)

        info_bg = '#F0FDFE'
