        def update_renewal():
            if not selected_emp_id.get():
                messagebox.showerror("خطأ", "الرجاء إدخال كود موظف صحيح"); return
            if not new_start_var.get() or not new_end_var.get():
                messagebox.showerror("خطأ", "الرجاء إدخال تاريخ بداية ونهاية العقد الجديد"); return
            renewal.emp_id       = selected_emp_id.get()
            renewal.old_start    = old_start_var.get(); renewal.old_end = old_end_var.get()
            renewal.new_start    = new_start_var.get(); renewal.new_end = new_end_var.get()
            renewal.renewal_date = renewal_date_var.get()
            emp = self.db.get_employee(selected_emp_id.get())
            if emp:
                emp.contract_start_date   = parse_date_input(new_start_var.get())
                emp.contract_end_date     = parse_date_input(new_end_var.get())
                emp.contract_renewal_date = parse_date_input(renewal_date_var.get())
            success, message = self.db.update_contract_renewal(renewal)
            if success:
                messagebox.showinfo("✅ Updated", message); self.show_contract_renewal_page()
            else:
                messagebox.showerror("Error", message)

