    def show_add_penalty_dialog(self):
        """Show Add Penalty - redesigned modern UI"""
        self.clear_content()
        HDR = '#991B1B'
        found_emp = {'obj': None}

        # ══════════════════════════════════════════════════════════════════
        # HEADER — gradient-style dark red bar
        # ══════════════════════════════════════════════════════════════════
        top = tk.Frame(self.content_frame, bg=HDR, height=70)
        top.pack(fill=tk.X); top.pack_propagate(False)

        icon_c = tk.Frame(top, bg='#7F1D1D', width=70, height=70)
        icon_c.pack(side=tk.LEFT); icon_c.pack_propagate(False)
        tk.Label(icon_c, text="⚠", font=('Segoe UI', 26), bg='#7F1D1D', fg='#FCA5A5'
                 ).place(relx=0.5, rely=0.5, anchor='center')

        tb = tk.Frame(top, bg=HDR)
        tb.pack(side=tk.LEFT, padx=20, pady=14)
        tk.Label(tb, text="ADD PENALTY", font=('Segoe UI', 17, 'bold'),
                 bg=HDR, fg='white').pack(anchor='w')
        tk.Label(tb, text="Add a new employee penalty record",
                 font=('Segoe UI', 9), bg=HDR, fg='#FECACA').pack(anchor='w')

        tk.Button(top, text="  ← Back  ", font=('Segoe UI', 9, 'bold'),
                  bg='#7F1D1D', fg='white', relief=tk.FLAT, bd=0,
                  padx=16, pady=8, cursor='hand2',
                  command=self.show_penalties_page
                  ).pack(side=tk.RIGHT, padx=25, pady=18)

        # ══════════════════════════════════════════════════════════════════
        # SCROLLABLE OUTER AREA
        # ══════════════════════════════════════════════════════════════════
        bg_outer = tk.Frame(self.content_frame, bg='#F1F5F9')
        bg_outer.pack(fill=tk.BOTH, expand=True)

        canvas = tk.Canvas(bg_outer, bg='#F1F5F9', highlightthickness=0)
        vsb = tk.Scrollbar(bg_outer, orient='vertical', command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        vsb.pack(side=tk.RIGHT, fill=tk.Y)
        canvas.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

        scroll_frame = tk.Frame(canvas, bg='#F1F5F9')
        sw = canvas.create_window((0, 0), window=scroll_frame, anchor='nw')

        def _on_cf(e): canvas.configure(scrollregion=canvas.bbox('all'))
        def _on_cv(e): canvas.itemconfig(sw, width=e.width)
        scroll_frame.bind('<Configure>', _on_cf)
        canvas.bind('<Configure>', _on_cv)

        def _mousewheel(e):
            canvas.yview_scroll(int(-1 * (e.delta / 120)), "units")
        def _mousewheel_linux_up(e):
            canvas.yview_scroll(-1, "units")
        def _mousewheel_linux_down(e):
            canvas.yview_scroll(1, "units")

        def _bind_mousewheel(e=None):
            canvas.bind_all('<MouseWheel>',     _mousewheel)
            canvas.bind_all('<Button-4>',       _mousewheel_linux_up)
            canvas.bind_all('<Button-5>',       _mousewheel_linux_down)
        def _unbind_mousewheel(e=None):
            canvas.unbind_all('<MouseWheel>')
            canvas.unbind_all('<Button-4>')
            canvas.unbind_all('<Button-5>')

        canvas.bind('<Enter>', _bind_mousewheel)
        canvas.bind('<Leave>', _unbind_mousewheel)
        scroll_frame.bind('<Enter>', _bind_mousewheel)
        scroll_frame.bind('<Leave>', _unbind_mousewheel)

        # ── Two-column layout ────────────────────────────────────────────
        cols = tk.Frame(scroll_frame, bg='#F1F5F9', padx=30, pady=20)
        cols.pack(fill=tk.BOTH, expand=True)
        cols.columnconfigure(0, weight=1)
        cols.columnconfigure(1, weight=1)

        # ═══════════════════════════════════════════════════════════════
        # HELPER: create a styled card section
        # ═══════════════════════════════════════════════════════════════
        def make_card(parent, row, col, title, icon, hdr_bg, hdr_fg, colspan=1):
            card = tk.Frame(parent, bg='white',
                            highlightbackground='#E2E8F0', highlightthickness=1)
            card.grid(row=row, column=col, columnspan=colspan,
                      sticky='nsew', padx=8, pady=8)
            bar = tk.Frame(card, bg=hdr_bg, height=38)
            bar.pack(fill=tk.X); bar.pack_propagate(False)
            tk.Label(bar, text=f"  {icon}  {title}",
                     font=('Segoe UI', 10, 'bold'),
                     bg=hdr_bg, fg=hdr_fg).pack(side=tk.LEFT, padx=10, pady=8)
            body = tk.Frame(card, bg='white', padx=20, pady=16)
            body.pack(fill=tk.BOTH, expand=True)
            return body

        # ═══════════════════════════════════════════════════════════════
        # HELPER: styled field row
        # ═══════════════════════════════════════════════════════════════
        def field_row(parent, row, label, var, readonly=False,
                      entry_bg='white', fg_label='#374151', combo_vals=None):
            tk.Label(parent, text=label, font=('Segoe UI', 9, 'bold'),
                     bg='white', fg=fg_label, anchor='e'
                     ).grid(row=row, column=0, sticky='e', pady=7, padx=(0, 12))

            border = tk.Frame(parent, bg='#CBD5E1',
                              highlightbackground='#CBD5E1', highlightthickness=1)
            border.grid(row=row, column=1, sticky='ew', pady=7)

            if combo_vals:
                w = ttk.Combobox(border, textvariable=var, values=combo_vals,
                                 font=('Segoe UI', 10), state='readonly', width=26)
                w.pack(padx=1, pady=1, fill=tk.X)
            else:
                state = 'readonly' if readonly else 'normal'
                rb = '#F8FAFC' if not readonly else entry_bg
                w = tk.Entry(border, textvariable=var,
                             font=('Segoe UI', 10), relief=tk.FLAT,
                             bd=0, state=state,
                             readonlybackground=entry_bg,
                             bg=rb, fg='#1E293B', width=28)
                w.pack(padx=6, pady=5, fill=tk.X)

                def _focus_in(e, f=border):
                    if state == 'normal':
                        f.config(bg='#3B82F6')
                def _focus_out(e, f=border):
                    f.config(bg='#CBD5E1')
                w.bind('<FocusIn>',  _focus_in)
                w.bind('<FocusOut>', _focus_out)
            return w

        # ════════════════════════════════════════════════════════════════
        # LEFT COLUMN — Employee Search
        # ════════════════════════════════════════════════════════════════
        emp_body = make_card(cols, 0, 0, "EMPLOYEE — Search by Code",
                             "👤", '#1E3A5F', 'white')
        emp_body.columnconfigure(0, minsize=140)
        emp_body.columnconfigure(1, weight=1)

        code_var = tk.StringVar()
        code_entry = field_row(emp_body, 0, "Employee Code:", code_var)

        # search button beside entry
        def _do_search(*_):
            code = code_var.get().strip()
            emp  = self.db.get_employee(code) if code else None
            found_emp['obj'] = emp
            if emp:
                dept_obj  = self.db.departments.get(emp.department)
                dept_name = dept_obj.name if dept_obj else (emp.department or "—")
                lbl_name.config(text=f"  👤  {emp.name}", fg='#166534')
                lbl_dept.config(text=f"  🏢  {dept_name}", fg='#166534')
                lbl_pos.config(text=f"  💼  {emp.position or '—'}", fg='#166534')
                result_card.config(bg='#F0FDF4',
                                   highlightbackground='#4ADE80')
                for w in (lbl_name, lbl_dept, lbl_pos): w.config(bg='#F0FDF4')
            else:
                lbl_name.config(text="  ⚠  Code not found" if code else "  —  Name", fg='#991B1B')
                lbl_dept.config(text="  —  Department", fg='#6B7280')
                lbl_pos.config(text="  —  Position",  fg='#6B7280')
                result_card.config(bg='#FFF1F2',
                                   highlightbackground='#FCA5A5')
                for w in (lbl_name, lbl_dept, lbl_pos): w.config(bg='#FFF1F2')

        code_var.trace_add("write", _do_search)

        result_card = tk.Frame(emp_body, bg='#F0FDF4',
                               highlightbackground='#4ADE80', highlightthickness=1)
        result_card.grid(row=1, column=0, columnspan=2, sticky='ew', pady=(6, 0))

        lbl_name = tk.Label(result_card, text="  —  Name",
                            font=('Segoe UI', 10, 'bold'), bg='#F0FDF4',
                            fg='#166534', anchor='w')
        lbl_name.pack(fill=tk.X, padx=4, pady=(8, 2))
        lbl_dept = tk.Label(result_card, text="  —  Department",
                            font=('Segoe UI', 9), bg='#F0FDF4',
                            fg='#166534', anchor='w')
        lbl_dept.pack(fill=tk.X, padx=4, pady=2)
        lbl_pos  = tk.Label(result_card, text="  —  Position",
                            font=('Segoe UI', 9), bg='#F0FDF4',
                            fg='#166534', anchor='w')
        lbl_pos.pack(fill=tk.X, padx=4, pady=(2, 8))

        code_entry.focus_set()

        # ════════════════════════════════════════════════════════════════
