        dt_body.columnconfigure(0, minsize=140)
        dt_body.columnconfigure(1, weight=1)

        date_var = tk.StringVar(value=date.today().strftime("%d/%m/%Y"))
        field_row(dt_body, 0, "Date:", date_var)

