        def save_penalty():
            emp = found_emp['obj']
            if not emp:
                messagebox.showerror("Error", "Please enter a valid employee code"); code_entry.focus_set(); return
            if not amount_var.get().strip():
                messagebox.showerror("Error", "Please enter the amount"); return
            try:
                amount = float(amount_var.get())
            except ValueError:
                messagebox.showerror("Error", "Amount must be a number"); return
            dur = 0
            try: dur = int(duration_var.get()) if duration_var.get() else 0
            except: pass

            # حساب الخصم الإضافي للغياب
            additional = 0.0
            occ = 0
            if penalty_type_var.get() == "Absence":
                additional, occ = _calc_additional_penalty(emp, dur)

            penalty_id = self.db.next_seq_id("PE", self.db.get_all_penalties(), "penalty_id", 3)
            pen = Penalty(penalty_id, emp.emp_id, amount, date_var.get(),
                          reason_var.get(), "Pending", penalty_type_var.get(), dur,
                          additional_penalty=additional, absence_occurrence=occ,
                          time=time_var.get().strip())
            ok, msg = self.db.add_penalty(pen)
            if ok:
                if penalty_type_var.get() == "Absence" and additional > 0:
                    messagebox.showinfo("Done ✅",
                        f"{msg}\n\n"
                        f"📊 Absence #{occ}\n"
                        f"  Basic deduction: {amount:.2f} EGP  → transferred to 'Absent' column\n"
                        f"  Additional penalty: {additional:.2f} EGP  → transferred to 'Penalty' column")
                else:
                    messagebox.showinfo("Done", msg)
                self.show_penalties_page()
            else:
                messagebox.showerror("Error", msg)

        def print_penalty():
            emp = found_emp['obj']
