    def generate_employee_report(self):
        """Generate Employee Report in PDF/Excel/CSV"""
        month, year = get_month_year_filter_gui(self.root)
        if month is None or not year:
            return

        options = []
        if PDF_AVAILABLE:
            options.append("PDF")
        if EXCEL_AVAILABLE:
            options.append("Excel")
        options.append("CSV")

        if not options:
            messagebox.showerror("Error", "No export options available")
            return

        choice = messagebox.askquestion("Export Format",
            "Do you want PDF format?" if "PDF" in options else "Do you want Excel format?")

        file_ext = "pdf" if choice == 'yes' and PDF_AVAILABLE else ("xlsx" if EXCEL_AVAILABLE else "csv")
        default_filename = f"Employee_Report_{month}_{year}.{file_ext}"
        file_path = ask_save_path(default_filename, "حفظ التقرير / Save Report")

        if not file_path:
            return

        try:
            headers = ["Emp Code", "Name", "Department", "Position", "Basic Salary", "Hire Date", "Email الإلكتروني", "Phone",
                     "Family Name", "Mother's Name", "Birth Date", "Qualification", "تاريخ Qualification", "Military Status",
                     "National ID", "تاريخ بطاقة الهوية", "Address", "City", "Contract Type", "بداية الcontract", "نهاية الcontract",
                     "بدل Transport", "بدل Service", "Incentives", "Deductions"]
            data = [headers]

            for emp in self.db.employees.values():
                try:
                    hire_dt = datetime.strptime(emp.hire_date, "%d/%m/%Y") if emp.hire_date else None
                    if month != "All":
                        if hire_dt and not date_in_payroll_period(hire_dt, int(month), int(year)):
                            continue
                    else:
                        if hire_dt and hire_dt.year != int(year):
                            continue
                except:
                    pass

                dept = self.db.departments.get(emp.department)
                dept_name = dept.name if dept else "N/A"
                data.append([
                    (getattr(emp, 'bank_code', '') or emp.emp_id),
                    emp.name,
                    dept_name,
                    emp.position,
                    str(format_number(emp.salary)),
                    emp.hire_date,
                    emp.email,
                    emp.phone,
                    emp.family_name,
                    emp.mother_name,
                    emp.birth_date,
                    emp.qualification,
                    emp.qualification_date,
                    emp.military_service_status,
                    emp.national_id,
                    emp.national_id_issue_date,
                    emp.address,
                    emp.city,
                    emp.contract_type,
                    emp.contract_start_date,
                    emp.contract_end_date,
                    str(emp.transportation),
                    str(emp.service_allowance),
                    str(emp.incentives),
                    str(emp.deductions)
                ])

            if file_path.endswith('.pdf') and PDF_AVAILABLE:
                success, msg = generate_pdf_report("Employee Report", headers, data, file_path)
            elif file_path.endswith('.xlsx') and EXCEL_AVAILABLE:
                success, msg = generate_excel_report("Employee Report", headers, data, file_path)
            else:
                with open(file_path, 'w', newline='', encoding='utf-8-sig') as f:
                    writer = csv.writer(f)
                    writer.writerows(data)
                success, msg = True, f"CSV report saved to:\n{file_path}"

            if success:
                messagebox.showinfo("Success", msg)
            else:
                messagebox.showerror("Error", msg)

        except Exception as e:
            messagebox.showerror("Error", f"Error generating report:\n{str(e)}")

    def generate_attendance_report(self):
        """Generate Attendance Report in PDF/Excel/CSV"""
        month, year = get_month_year_filter_gui(self.root)
        if month is None or not year:
            return

        choice = messagebox.askquestion("Export Format",
            "Do you want PDF format?" if PDF_AVAILABLE else "Do you want Excel format?")

        file_ext = "pdf" if choice == 'yes' and PDF_AVAILABLE else ("xlsx" if EXCEL_AVAILABLE else "csv")
        default_filename = f"Attendance_Report_{month}_{year}.{file_ext}"
        file_path = ask_save_path(default_filename, "حفظ التقرير / Save Report")

        if not file_path:
            return

        try:
            month_names = {"01": "January", "02": "February", "03": "March", "04": "April",
                           "05": "May", "06": "June", "07": "July", "08": "August",
                           "09": "September", "10": "October", "11": "November", "12": "December"}
            month_name = month_names.get(str(month).zfill(2), str(month))
            headers = ["Employee ID", "Name", "Date", "Check In", "Check Out", "Duration", "Status"]
            data = [headers]

            for att in self.db.attendance:
                try:
                    att_date = datetime.strptime(att.date, "%d/%m/%Y")
                    if month != "All":
                        if att_date.month != int(month) or att_date.year != int(year):
                            continue
                    else:
                        if att_date.year != int(year):
                            continue
                except:
                    continue

                emp = self.db.employees.get(att.emp_id)
                emp_name = (emp.name if emp else "N/A")
                duration = att.get_duration()
                data.append([
                    att.emp_id,
                    emp_name,
                    att.date,
                    att.check_in,
                    att.check_out,
                    duration if duration else "--:--",
                    self.db.get_attendance_display_status(att)
                ])

            report_title = f"Attendance Report - {month_name}/{year}" if month != "All" else f"Attendance Report - {year}"
            if file_path.endswith('.pdf') and PDF_AVAILABLE:
                success, msg = generate_pdf_report(report_title, headers, data, file_path)
            elif file_path.endswith('.xlsx') and EXCEL_AVAILABLE:
                # Export Excel as a per-department grid (In/Out per day, one sheet per department)
                success, msg = self._export_attendance_by_department_excel(month, year, file_path)
            else:
                with open(file_path, 'w', newline='', encoding='utf-8-sig') as f:
                    writer = csv.writer(f)
                    writer.writerows(data)
                success, msg = True, f"CSV report saved to:\n{file_path}"

            if success:
                messagebox.showinfo("Success", msg)
            else:
                messagebox.showerror("Error", msg)

        except Exception as e:
            messagebox.showerror("Error", f"Error generating report:\n{str(e)}")

    def _export_attendance_by_department_excel(self, month, year, file_path):
        """Export the attendance report as a per-department grid workbook.

        Layout (one worksheet per department, ordered alphabetically):
          • Row 1: 'ID' + 'Employee Name' + one merged header per day
            ("01-Jun", "02-Jun", …) + three summary headers
            ("Off Days", "Missed punches", "Valid attendance days").
          • Row 2: 'In' / 'Out' / 'hours' sub-headers under each day.
          • One row per employee.  For each day:
              - both punches present  → In time, Out time, work hours
                (e.g. 8:41:00) shown in the 'hours' cell.
              - exactly one punch      → the punch + '-' + 'mp' (missed
                punch, red) merged note.
              - no punch, Day Off      → 'off' (green) merged across the day.
              - no punch, approved leave→ short leave code (teal) merged.
              - no record at all        → left blank.
          • Per-employee summary columns count the Off Days, Missed punches
            and Valid attendance days.
          • Two footer rows ('Off days' / 'missed punches') count, per day
            column, how many employees were off / had a missed punch, plus a
            department grand total in the matching summary column.
        Day columns span the full selected month (01 .. last day of the
        month).  When 'All' months are selected, columns span 01 .. the last
        day that has any record (or 31 if none).
        """
        if not EXCEL_AVAILABLE:
            return False, "Excel library (openpyxl) not installed."
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
            from openpyxl.utils import get_column_letter
            import calendar

            sel_year = int(year)
            sel_month = None if str(month) == "All" else int(month)

            # ---- 1) Merge punches per (employee, day) for the selected period
            # punches[emp_id][day] = [check_in, check_out, status, date_str]
            punches = {}
            max_day = 0
            for att in self.db.attendance:
                dt = att.date_key()
                if dt == datetime.max:
                    continue
                if sel_month is not None:
                    if dt.month != sel_month or dt.year != sel_year:
                        continue
                else:
                    if dt.year != sel_year:
                        continue
                day = dt.day
                rec = punches.setdefault(att.emp_id, {}).setdefault(
                    day, ["", "", "", att.date])
                if not rec[0] and (att.check_in or "").strip():
                    rec[0] = att.check_in
                if not rec[1] and (att.check_out or "").strip():
                    rec[1] = att.check_out
                # remember a meaningful status (Day Off / Absent / leave-ish)
                st = (att.status or "").strip()
                if st and st != "Present":
                    rec[2] = st
                if not rec[3]:
                    rec[3] = att.date
                if day > max_day:
                    max_day = day
            if sel_month is not None:
                max_day = calendar.monthrange(sel_year, sel_month)[1]
            elif max_day == 0:
                max_day = 31

            # ---- 2) Group employees by department NAME (sorted by name)
            by_dept = {}
            for e in self.db.employees.values():
                d = self.db.departments.get(e.department)
                dname = d.name if d else (e.department or "Unassigned")
                by_dept.setdefault(dname, []).append(e)
            if not by_dept:
                return False, "No employees/departments found to export."

            # Month abbreviation for the day headers ("01-Jun")
            mon_abbr = calendar.month_abbr[sel_month] if sel_month else ""

            # Short codes for leave types (so a leave day is not mistaken for off)
            LEAVE_CODE = {
                "Annual": "AL", "Sick Leave": "SL",
                "Insurance Sick Leave": "ISL", "Emergency": "EL",
                "Unpaid": "UL", "Maternity": "ML", "Bereavement": "BL",
            }

            def _duration_hms(cin, cout):
                """Return work duration as 'H:MM:SS' (or '' if invalid)."""
                t_in = Attendance._parse_time(cin)
                t_out = Attendance._parse_time(cout)
                if not t_in or not t_out:
                    return ""
                diff = (t_out.hour * 60 + t_out.minute) - (t_in.hour * 60 + t_in.minute)
                if diff < 0:
                    diff += 24 * 60
                if diff <= 0 or diff > 24 * 60:
                    return ""
                return f"{diff // 60}:{diff % 60:02d}:00"

            # Today's date — future days (in the current month) stay blank,
            # because the employee simply has not arrived yet.
            _today = datetime.now().date()

            def _no_punch_kind(emp_id, dstr):
                """Resolve a punch-less day to a leave code or 'off' (Day Off)."""
                lt = self.db._approved_leave_type_on(emp_id, dstr)
                if lt and lt != "Day Off":
                    return ("leave", "", "", LEAVE_CODE.get(lt, lt))
                return ("off", "", "", "off")

            def _classify(rec, emp, the_date):
                """Return (kind, in_txt, out_txt, hours_txt).
                kind ∈ {'valid','mp','off','leave','blank'}.

                Rule:
                  • both punches            → valid (In/Out/work hours)
                  • exactly one punch       → mp (missed punch)
                  • no punch at all         → Day Off ('off'); if the day is
                    covered by an approved leave, the leave code is shown
                    instead.
                  • a future day (current month, not yet reached) is left
                    blank — the employee has not come yet, so it is NOT a Day
                    Off.
                `the_date` is the real date of this column (None in 'All' mode,
                where future days cannot be told apart, so empty days stay
                blank)."""
                if rec is not None:
                    cin, cout, status, dstr = rec[0], rec[1], rec[2], rec[3]
                    if cin and cout:
                        return ("valid", Attendance.to_24h(cin),
                                Attendance.to_24h(cout), _duration_hms(cin, cout))
                    if cin or cout:
                        return ("mp",
                                Attendance.to_24h(cin) if cin else "-",
                                Attendance.to_24h(cout) if cout else "-",
                                "mp")
                    # punch-less record: a future date is still blank — even if
                    # a Day Off record was pre-created for it — the employee
                    # has not arrived yet.
                    if the_date is not None and the_date > _today:
                        return ("blank", "", "", "")
                    return _no_punch_kind(emp.emp_id, dstr)   # off / leave
                # ── no record at all ──────────────────────────────────────
                if the_date is None:
                    return ("blank", "", "", "")              # 'All' months mode
                if the_date > _today:
                    return ("blank", "", "", "")              # future day → blank
                # any past / present day with no punch → Day Off (or leave)
                return _no_punch_kind(emp.emp_id, the_date.strftime("%d/%m/%Y"))

            # ---- 3) Styling -------------------------------------------------
            THIN = Side(style="thin", color="BFBFBF")
            BORDER = Border(left=THIN, right=THIN, top=THIN, bottom=THIN)
            DAY_HDR_FILL = PatternFill("solid", fgColor="DCE6F1")   # light blue
            SUM_HDR_FILL = PatternFill("solid", fgColor="DCE6F1")
            IN_FILL = PatternFill("solid", fgColor="EBF1DE")        # light green
            OUT_FILL = PatternFill("solid", fgColor="F2DCDB")       # light red
            HRS_FILL = PatternFill("solid", fgColor="FFFFFF")       # white

            HDR_FONT = Font(name="Calibri", bold=True, size=10)
            NAME_FONT = Font(name="Calibri", bold=False, size=10)
            TIME_FONT = Font(name="Calibri", bold=False, size=9, color="1F3864")
            HRS_FONT = Font(name="Calibri", bold=False, size=9, color="C55A11")
            OFF_FONT = Font(name="Calibri", bold=True, size=9, color="548235")
            MP_FONT = Font(name="Calibri", bold=True, size=9, color="C00000")
            LEAVE_FONT = Font(name="Calibri", bold=True, size=9, color="2E75B6")
            SUM_FONT = Font(name="Calibri", bold=True, size=10)
            FOOT_FONT = Font(name="Calibri", bold=True, size=10, color="7030A0")

            CTR = Alignment(horizontal="center", vertical="center")
            LEFT = Alignment(horizontal="left", vertical="center")

            wb = Workbook()
            wb.remove(wb.active)
            used_names = set()

            def _sheet_name(n):
                for ch in '[]:*?/\\':
                    n = n.replace(ch, " ")
                n = n.strip()[:31] or "Sheet"
                base, i = n, 1
                while n in used_names:
                    i += 1
                    suf = f" ({i})"
                    n = base[:31 - len(suf)] + suf
                used_names.add(n)
                return n

            # Column geometry
            #   col 1 = ID, col 2 = Name
            #   day d → In = 3+(d-1)*3 , Out = +1 , hours = +2
            #   summary → Off Days / Missed punches / Valid attendance days
            sum_start = 3 + max_day * 3
            col_off, col_miss, col_valid = sum_start, sum_start + 1, sum_start + 2
            last_col = col_valid

            for dname in sorted(by_dept):
                emps = sorted(by_dept[dname], key=lambda x: (x.name or "").lower())
                ws = wb.create_sheet(_sheet_name(dname))

                # ---- Header rows 1 & 2 ----
                ws.cell(1, 1, "ID")
                ws.merge_cells(start_row=1, start_column=1, end_row=2, end_column=1)
                ws.cell(1, 2, "Employee Name")
                ws.merge_cells(start_row=1, start_column=2, end_row=2, end_column=2)
                for d in range(1, max_day + 1):
                    base = 3 + (d - 1) * 3
                    label = f"{d:02d}-{mon_abbr}" if mon_abbr else f"{d:02d}"
                    ws.cell(1, base, label)
                    ws.merge_cells(start_row=1, start_column=base,
                                   end_row=1, end_column=base + 2)
                    ws.cell(2, base, "In")
                    ws.cell(2, base + 1, "Out")
                    ws.cell(2, base + 2, "hours")
                ws.cell(1, col_off, "Off Days")
                ws.cell(1, col_miss, "Missed punches")
                ws.cell(1, col_valid, "Valid attendance days")
                for c in (col_off, col_miss, col_valid):
                    ws.merge_cells(start_row=1, start_column=c, end_row=2, end_column=c)

                # per-day footer tallies
                day_off_count = [0] * (max_day + 1)
                day_mp_count = [0] * (max_day + 1)
                tot_off = tot_miss = tot_valid = 0

                # ---- Employee rows ----
                r = 3
                for e in emps:
                    ws.cell(r, 1, e.emp_id)
                    ws.cell(r, 2, e.name)
                    emp_days = punches.get(e.emp_id, {})
                    n_off = n_miss = n_valid = 0
                    for d in range(1, max_day + 1):
                        base = 3 + (d - 1) * 3
                        if sel_month is not None:
                            try:
                                the_date = datetime(sel_year, sel_month, d).date()
                            except ValueError:
                                the_date = None
                        else:
                            the_date = None
                        kind, itxt, otxt, htxt = _classify(emp_days.get(d), e, the_date)
                        ci = ws.cell(r, base, itxt)
                        co = ws.cell(r, base + 1, otxt)
                        ch = ws.cell(r, base + 2, htxt)
                        ci.alignment = CTR; ci.border = BORDER; ci.fill = IN_FILL
                        co.alignment = CTR; co.border = BORDER; co.fill = OUT_FILL
                        ch.alignment = CTR; ch.border = BORDER; ch.fill = HRS_FILL
                        ci.font = TIME_FONT; co.font = TIME_FONT
                        if kind == "valid":
                            ch.font = HRS_FONT
                            n_valid += 1
                        elif kind == "mp":
                            ch.font = MP_FONT
                            n_miss += 1
                            day_mp_count[d] += 1
                        elif kind == "off":
                            # merge In/Out/hours and show 'off' centred
                            ws.merge_cells(start_row=r, start_column=base,
                                           end_row=r, end_column=base + 2)
                            ci.value = "off"; ci.font = OFF_FONT
                            n_off += 1
                            day_off_count[d] += 1
                        elif kind == "leave":
                            ws.merge_cells(start_row=r, start_column=base,
                                           end_row=r, end_column=base + 2)
                            ci.value = htxt; ci.font = LEAVE_FONT
                        # blank → leave cells empty

                    # summary cells
                    so = ws.cell(r, col_off, n_off)
                    sm = ws.cell(r, col_miss, n_miss)
                    sv = ws.cell(r, col_valid, n_valid)
                    for cc in (so, sm, sv):
                        cc.alignment = CTR; cc.border = BORDER; cc.font = SUM_FONT
                    # ID / Name styling
                    idc = ws.cell(r, 1); idc.alignment = CTR; idc.border = BORDER; idc.font = NAME_FONT
                    nmc = ws.cell(r, 2); nmc.alignment = LEFT; nmc.border = BORDER; nmc.font = NAME_FONT
                    ws.row_dimensions[r].height = 15

                    tot_off += n_off; tot_miss += n_miss; tot_valid += n_valid
                    r += 1

                # ---- Footer rows: 'Off days' and 'missed punches' ----
                foot_off_row = r
                foot_mp_row = r + 1
                ws.cell(foot_off_row, 2, "Off days")
                ws.cell(foot_mp_row, 2, "missed punches")
                for d in range(1, max_day + 1):
                    base = 3 + (d - 1) * 3
                    # off-days tally (merged & centred under the day)
                    fo = ws.cell(foot_off_row, base, day_off_count[d])
                    ws.merge_cells(start_row=foot_off_row, start_column=base,
                                   end_row=foot_off_row, end_column=base + 2)
                    fo.alignment = CTR; fo.font = FOOT_FONT; fo.border = BORDER
                    # missed-punch tally
                    fm = ws.cell(foot_mp_row, base, day_mp_count[d])
                    ws.merge_cells(start_row=foot_mp_row, start_column=base,
                                   end_row=foot_mp_row, end_column=base + 2)
                    fm.alignment = CTR; fm.font = FOOT_FONT; fm.border = BORDER
                # grand totals in the matching summary columns
                go = ws.cell(foot_off_row, col_off, tot_off)
                gm = ws.cell(foot_mp_row, col_miss, tot_miss)
                gv = ws.cell(foot_off_row, col_valid, tot_valid)
                for cc in (go, gm, gv):
                    cc.alignment = CTR; cc.font = FOOT_FONT; cc.border = BORDER
                for cc in (ws.cell(foot_off_row, 2), ws.cell(foot_mp_row, 2)):
                    cc.font = FOOT_FONT; cc.alignment = LEFT; cc.border = BORDER

                # ---- Header styling ----
                for cc in (ws.cell(1, 1), ws.cell(1, 2)):
                    cc.font = HDR_FONT; cc.alignment = CTR; cc.border = BORDER; cc.fill = SUM_HDR_FILL
                for d in range(1, max_day + 1):
                    base = 3 + (d - 1) * 3
                    hd = ws.cell(1, base)
                    hd.font = HDR_FONT; hd.alignment = CTR; hd.border = BORDER; hd.fill = DAY_HDR_FILL
                    hi = ws.cell(2, base); hi.font = HDR_FONT; hi.alignment = CTR; hi.border = BORDER; hi.fill = IN_FILL
                    ho = ws.cell(2, base + 1); ho.font = HDR_FONT; ho.alignment = CTR; ho.border = BORDER; ho.fill = OUT_FILL
                    hh = ws.cell(2, base + 2); hh.font = HDR_FONT; hh.alignment = CTR; hh.border = BORDER; hh.fill = DAY_HDR_FILL
                for c in (col_off, col_miss, col_valid):
                    hc = ws.cell(1, c)
                    hc.font = HDR_FONT; hc.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
                    hc.border = BORDER; hc.fill = SUM_HDR_FILL

                # ---- Column widths / row heights / view ----
                ws.column_dimensions["A"].width = 6
                ws.column_dimensions["B"].width = 28
                for d in range(1, max_day + 1):
                    base = 3 + (d - 1) * 3
                    ws.column_dimensions[get_column_letter(base)].width = 9
                    ws.column_dimensions[get_column_letter(base + 1)].width = 9
                    ws.column_dimensions[get_column_letter(base + 2)].width = 8
                ws.column_dimensions[get_column_letter(col_off)].width = 7
                ws.column_dimensions[get_column_letter(col_miss)].width = 9
                ws.column_dimensions[get_column_letter(col_valid)].width = 11
                ws.row_dimensions[1].height = 22
                ws.row_dimensions[2].height = 16
                ws.freeze_panes = "C3"
                ws.sheet_view.showGridLines = False

            if not wb.sheetnames:
                wb.create_sheet("Attendance")
            wb.save(file_path)
            return True, f"Attendance (by department) saved to:\n{file_path}"
        except Exception as e:
            import traceback
            return False, f"Error generating Excel report:\n{str(e)}\n\n{traceback.format_exc()}"

    def generate_department_report(self):
        """إنشاء Departments Report - with PDF/Excel support"""
        month, year = get_month_year_filter_gui(self.root)
        if month is None or not year:
            return

        # Determine available formats
        options = []
        if PDF_AVAILABLE:
            options.append("PDF")
        if EXCEL_AVAILABLE:
            options.append("Excel")
        options.append("CSV")

        if not options:
            messagebox.showerror("Error", "No export options available")
            return

        # Ask user for format
        choice = messagebox.askquestion("Export Format",
            "Do you want PDF format?" if "PDF" in options else "Do you want Excel format?")

        file_ext = "pdf" if choice == 'yes' and PDF_AVAILABLE else ("xlsx" if EXCEL_AVAILABLE else "csv")
