    def generate_leave_report(self):
        """إنشاء Leaves Report - with PDF/Excel support"""
        month, year = get_month_year_filter_gui(self.root)
        if month is None or not year:
            return

        # Determine available formats
        options = []
        if PDF_AVAILABLE:
            options.append("PDF")
        if EXCEL_AVAILABLE:
            options.append("Excel")
        options.append("CSV")

        if not options:
            messagebox.showerror("Error", "No export options available")
            return

        # Ask user for format
        choice = messagebox.askquestion("Export Format",
            "Do you want PDF format?" if "PDF" in options else "Do you want Excel format?")

        file_ext = "pdf" if choice == 'yes' and PDF_AVAILABLE else ("xlsx" if EXCEL_AVAILABLE else "csv")
        month_str = str(month).zfill(2) if month != "All" else "All"
        default_filename = f"Leaves_Report_{month_str}_{year}.{file_ext}"
        file_path = ask_save_path(default_filename, "حفظ التقرير / Save Report")

        if not file_path:
            return

        try:
            headers = ["Emp Code", "Employee Name", "Leave Type", "Start Date", "End Date", "Days", "Reason", "Status"]
            data = [headers]

            for leave in self.db.leaves:
                try:
                    start_date = datetime.strptime(leave.start_date, "%d/%m/%Y")
                    if month != "All":
                        if not date_in_payroll_period(start_date, int(month), int(year)):
                            continue
                    else:
                        if start_date.year != int(year):
                            continue
                except:
                    continue

                emp = self.db.employees.get(leave.emp_id)
                emp_name = (emp.name if emp else "N/A")
                try:
                    try:
                        s = datetime.strptime(leave.start_date, "%d/%m/%Y").date()
                        e_ = datetime.strptime(leave.end_date, "%d/%m/%Y").date()
                    except Exception:
                        s = datetime.strptime(leave.start_date, "%Y-%m-%d").date()
                        e_ = datetime.strptime(leave.end_date, "%Y-%m-%d").date()
                    leave_days_count = (e_ - s).days + 1
                except Exception:
                    leave_days_count = ""
                data.append([
                    leave.emp_id,
                    emp_name,
                    leave.leave_type,
                    leave.start_date,
                    leave.end_date,
                    leave_days_count,
                    leave.reason,
                    leave.status
                ])

            report_title = f"Leaves Report - {month_str}/{year}"

            if file_path.endswith('.pdf') and PDF_AVAILABLE:
                success, msg = generate_pdf_report(report_title, headers, data, file_path)
            elif file_path.endswith('.xlsx') and EXCEL_AVAILABLE:
                success, msg = generate_excel_report(report_title, headers, data, file_path)
            else:
                with open(file_path, 'w', newline='', encoding='utf-8-sig') as f:
                    writer = csv.writer(f)
                    writer.writerows(data)
                success, msg = True, f"تم الحفظ / Saved:\n{file_path}"

            if success:
                messagebox.showinfo("Success", msg)
            else:
                messagebox.showerror("Error", msg)

        except Exception as e:
            messagebox.showerror("Error", f"حدث Error أثناء إنشاء الReport:\n{str(e)}")

