    def generate_monthly_report(self):
        """إنشاء Report المرتبات Monthي (Monthly Salary Report) - with PDF/Excel support"""
        month, year = get_month_year_filter_gui(self.root)
        if month is None or not year:
            return

        # Determine available formats
        options = []
        if PDF_AVAILABLE:
            options.append("PDF")
        if EXCEL_AVAILABLE:
            options.append("Excel")
        options.append("CSV")

        if not options:
            messagebox.showerror("Error", "No export options available")
            return

        # Ask user for format
        choice = messagebox.askquestion("Export Format",
            "Do you want PDF format?" if "PDF" in options else "Do you want Excel format?")

        file_ext = "pdf" if choice == 'yes' and PDF_AVAILABLE else ("xlsx" if EXCEL_AVAILABLE else "csv")
        month_str = str(month).zfill(2) if month != "All" else "All"
        default_filename = f"Monthly_Salary_Report_{month_str}_{year}.{file_ext}"
        file_path = ask_save_path(default_filename, "حفظ التقرير / Save Report")

        if not file_path:
            return

        try:
            headers = ["Bank Code", "Name", "Department", "Basic", "transport", "Allowances",
                      "service", "amount", "insurance", "penalty", "advance", "tax", "net"]
            data = [headers]

            for emp in self.db.employees.values():
                # Filter by hire date month/year
                try:
                    hire_dt = None
                    if emp.hire_date:
                        try:
                            hire_dt = datetime.strptime(emp.hire_date, "%d/%m/%Y")
                        except:
                            try:
                                hire_dt = datetime.strptime(emp.hire_date, "%Y-%m-%d")
                            except:
                                pass

                    if month != "All":
                        if hire_dt and not date_in_payroll_period(hire_dt, int(month), int(year)):
                            continue
                    else:
                        if hire_dt and hire_dt.year != int(year):
                            continue
                except:
                    pass

                dept_name = self.db.departments.get(emp.department, Department("", "N/A")).name

                # Calculate Salary بعد Service = Salary الاساسي + Transport + Allowances + Service
                service_charge = emp.service_allowance
                salary_after_service = emp.salary + emp.transportation + emp.allowances + service_charge

                # --- Tax / Insurance flags from employee data ---
                _raw_tis = (getattr(emp, 'tax_insurance_status', 'both') or 'both').strip().lower()
                _tis_map = {'both': 'both', 'tax only': 'tax_only', 'tax_only': 'tax_only',
                            'insurance only': 'insurance_only', 'insurance_only': 'insurance_only',
                            'neither': 'none', 'none': 'none'}
                tax_ins_status = _tis_map.get(_raw_tis, 'both')
                apply_insurance = tax_ins_status in ('both', 'insurance_only')
                apply_tax = tax_ins_status in ('both', 'tax_only')

                # حساب التأمينات (11% from Max Base) - فقط إذا كان الموظف يدفع تأمين
                if apply_insurance:
                    _s = getattr(self.db, 'insurance_settings', {"min": 2700, "max": 16700})
                    insurance_base = min(float(emp.salary or 0), float(_s.get("max", 16700) or 16700))
                    insurance = round(insurance_base * 0.11, 2)
                    num_spouses = int(emp.number_of_spouses) if emp.number_of_spouses else 0
                    num_children = int(emp.number_of_children) if emp.number_of_children else 0
                    marital = (emp.marital_status or "Single").strip().lower()
                    if marital in ("single",):
                        health_insurance = 0.0
                    else:
                        health_insurance = round(insurance_base * (num_spouses * 0.03 + num_children * 0.01), 2)
                else:
                    insurance = 0.0
                    health_insurance = 0.0

                # حساب Penalties (الموافق عليها)
                penalties = sum(p.amount for p in self.db.penalties if p.emp_id == emp.emp_id and p.status == "Approved")

                # حساب Advances (الموافق عليها)
                advances = sum(a.amount for a in self.db.advances if a.emp_id == emp.emp_id and a.status == "Approved")

                # حساب الضرائب - فقط إذا كان الموظف يدفع ضريبة
                if apply_tax:
                    taxable_amount = salary_after_service - 5000 - insurance
                    tax = 0
                    if taxable_amount > 0:
                        if taxable_amount <= 1250:
                            tax = round(taxable_amount * 0.10, 2)
                        else:
                            tax = round(1250 * 0.10, 2)
                            taxable_amount -= 1250
                            if taxable_amount <= 1250:
                                tax += round(taxable_amount * 0.15, 2)
                            else:
                                tax += round(1250 * 0.15, 2)
                                taxable_amount -= 1250
                                if taxable_amount <= 10833.33:
                                    tax += round(taxable_amount * 0.20, 2)
                                else:
                                    tax += round(10833.33 * 0.20, 2)
                                    taxable_amount -= 10833.33
                                    if taxable_amount > 0:
                                        tax += round(taxable_amount * 0.225, 2)
                else:
                    tax = 0.0

                # حساب صافي المرتب
                net_salary = round_to_nearest_5(salary_after_service - insurance - health_insurance - advances - penalties - tax - emp.deductions)

                data.append([
                    emp.emp_id,
                    emp.name,
                    dept_name,
                    format_number(emp.salary),
                    format_number(emp.transportation),
                    format_number(emp.allowances),
                    format_number(service_charge),
                    format_number(salary_after_service),
                    format_number(insurance),
                    format_number(penalties),
                    format_number(advances),
                    format_number(tax),
                    format_number(net_salary)
                ])

            report_title = f"Monthly Salary Report - {month_str}/{year}"

            if file_path.endswith('.pdf') and PDF_AVAILABLE:
                success, msg = generate_pdf_report(report_title, headers, data, file_path)
            elif file_path.endswith('.xlsx') and EXCEL_AVAILABLE:
                success, msg = generate_excel_report(report_title, headers, data, file_path)
            else:
                with open(file_path, 'w', newline='', encoding='utf-8-sig') as f:
                    writer = csv.writer(f)
                    writer.writerows(data)
                success, msg = True, f"تم الحفظ / Saved:\n{file_path}"

            if success:
                messagebox.showinfo("Success", msg)
            else:
                messagebox.showerror("Error", msg)

        except Exception as e:
            messagebox.showerror("Error", f"Error generating report:\n{str(e)}")
