    def export_monthly_page_to_excel(self):
        """Export monthly report to Excel"""
        if not self._ensure_excel():
            return
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, Alignment, PatternFill, Border, Side
            from openpyxl.utils import get_column_letter
            import os

            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            file_path = ask_save_path(f"Monthly_Salary_Report_{timestamp}.xlsx", "حفظ التقرير Excel / Save Report")
            if not file_path:
                return

            tree = None
            for child in self.content_frame.winfo_children():
                if hasattr(child, 'winfo_children'):
                    for sub in child.winfo_children():
                        if hasattr(sub, 'get_children'):
                            tree = sub
                            break
                if tree:
                    break

            wb = Workbook()
            ws = wb.active
            ws.title = "Monthly Salary Report"

            hf = Font(bold=True, color='FFFFFF', size=12)
            hf_fill = PatternFill(start_color='1E3A5F', end_color='1E3A5F', fill_type='solid')
            ha = Alignment(horizontal='center', vertical='center')
            border = Border(left=Side(style='thin'), right=Side(style='thin'),
                          top=Side(style='thin'), bottom=Side(style='thin'))

            ws.merge_cells('A1:H1')
            ws['A1'] = "Monthly Salary Report"
            ws['A1'].font = Font(bold=True, size=18, color='1E3A5F')
            ws['A1'].alignment = Alignment(horizontal='center')
            ws.row_dimensions[1].height = 35
            ws.merge_cells('A2:H2')
            ws['A2'] = "MODO HR"
            ws['A2'].font = Font(size=11, color='64748B')
            ws['A2'].alignment = ha
            ws.row_dimensions[2].height = 25
            ws.merge_cells('A3:H3')
            ws['A3'] = f"Generated: {datetime.now().strftime('%d/%m/%Y %H:%M:%S')}"
            ws['A3'].font = Font(size=10, color='94A3B8')
            ws['A3'].alignment = ha
            ws.row_dimensions[3].height = 20
            ws.append([])

            headers = ["Bank Code", "Name", "Department", "Basic", "Transport", "Allowances",
                      "Service", "Amount", "Insurance", "Health Ins.", "Penalty", "Advance", "Tax", "Net"]

            for col, h in enumerate(headers, 1):
                c = ws.cell(row=5, column=col)
                c.value = h
                c.font = hf
                c.fill = hf_fill
                c.alignment = ha
                c.border = border

            row_idx = 6
            if tree:
                # اجمع كل الصفوف أولاً ثم رتّبها حسب ترتيب الأقسام الثابت (مثل الصورة)
                _tree_rows = [list(tree.item(item)['values']) for item in tree.get_children()]
                _tree_rows.sort(key=lambda r: _dept_rank(r[2] if len(r) > 2 else ''))
                for vals in _tree_rows:
                    for col_idx, val in enumerate(vals, 1):
                        c = ws.cell(row=row_idx, column=col_idx)
                        vv = str(val).strip()
                        try:
                            if vv and vv.replace(',','').replace('.','').isdigit():
                                c.value = float(vv.replace(',',''))
                                c.number_format = '#,##0'
                            else:
                                c.value = vv
                        except:
                            c.value = vv
                        c.alignment = Alignment(horizontal='center')
                        c.border = border
                    row_idx += 1
            else:
                for emp in sorted(
                    self.db.employees.values(),
                    key=lambda e: (
                        _dept_rank((self.db.departments.get(e.department).name
                                    if self.db.departments.get(e.department) else "N/A")),
                        (getattr(e, 'bank_code', '') or e.emp_id or ''),
                    )
                ):
                    dept = self.db.departments.get(emp.department)
                    dept_name = dept.name if dept else "N/A"
                    svc = emp.service_allowance
                    sal = emp.salary + emp.transportation + emp.allowances + svc
                    _s = getattr(self.db, 'insurance_settings', {"min": 2700, "max": 16700})
                    _ins_base = min(float(emp.salary or 0), float(_s.get("max", 16700) or 16700))
                    ins = round(_ins_base * 0.11, 2)
                    # Health insurance: 3% per spouse + 1% per child
                    _num_sp = int(emp.number_of_spouses) if emp.number_of_spouses else 0
                    _num_ch = int(emp.number_of_children) if emp.number_of_children else 0
                    _marital = (emp.marital_status or "Single").strip().lower()
                    health_ins = 0.0 if _marital == "single" else round(_ins_base * (_num_sp * 0.03 + _num_ch * 0.01), 2)
                    pen = sum(p.amount for p in self.db.penalties if p.emp_id == emp.emp_id and p.status == "Approved")
                    adv = sum(a.amount for a in self.db.advances if a.emp_id == emp.emp_id and a.status == "Approved")
                    tax = 0
                    tx = sal - 5000 - ins
                    if tx > 0:
                        if tx <= 1250:
                            tax = round(tx * 0.10, 2)
                        else:
                            tax = round(1250 * 0.10, 2)
                            tx -= 1250
                            if tx <= 1250:
                                tax += round(tx * 0.15, 2)
                            else:
                                tax += round(1250 * 0.15, 2)
                                tx -= 1250
                                if tx <= 10833.33:
                                    tax += round(tx * 0.20, 2)
                                else:
                                    tax += round(10833.33 * 0.20, 2)
                                    tx -= 10833.33
                                    if tx > 0:
                                        tax += round(tx * 0.225, 2)
                    net = round_to_nearest_5(sal - ins - health_ins - adv - pen - tax - emp.deductions)
                    vals = [(getattr(emp, 'bank_code', '') or emp.emp_id), emp.name, dept_name, emp.salary,
                           emp.transportation, emp.allowances, svc, sal,
                           ins, health_ins, pen, adv, tax, net]
                    for col_idx, val in enumerate(vals, 1):
                        c = ws.cell(row=row_idx, column=col_idx)
                        c.value = val
                        c.alignment = Alignment(horizontal='center')
                        c.border = border
                        if isinstance(val, (int, float)):
                            c.number_format = '#,##0'
                    if row_idx % 2 == 0:
                        for ci in range(1, 15):
                            ws.cell(row=row_idx, column=ci).fill = PatternFill(
                                start_color='F8FAFC', fill_type='solid')
                    row_idx += 1

            ws.append([])
            mr = ws.max_row + 1
            ws.merge_cells(f'A{mr}:N{mr}')
            ws[f'A{mr}'].value = f"Total Records: {row_idx - 6}"
            ws[f'A{mr}'].font = Font(size=10, color='64748B', italic=True)
            ws[f'A{mr}'].alignment = Alignment(horizontal='center')

            for col in range(1, 15):
                ws.column_dimensions[get_column_letter(col)].width = 18
            ws.page_setup.orientation = 'landscape'
            ws.page_setup.fitToPage = True
            ws.page_setup.fitToWidth = 1

            wb.save(file_path)
            messagebox.showinfo("Success", f"تم الحفظ / Saved:\n{file_path}")
        except Exception as e:
            messagebox.showerror("Error", f"Excel export error: {str(e)}")

    def _save_monthly_page_report(self, export_type, orientation):
        """Save report as PDF or send to printer"""
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, landscape, portrait
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
        from reportlab.lib.enums import TA_CENTER
        import os

        headers = ["Bank Code", "Name", "Department", "Basic", "Transport", "Allowances",
                  "Service", "Amount", "Insurance", "Penalty", "Advance", "Tax", "Net"]
        data = []
        for child in self.content_frame.winfo_children():
            if hasattr(child, 'winfo_children'):
                for sub in child.winfo_children():
                    if hasattr(sub, 'get_children'):
                        for item in sub.get_children():
                            vals = sub.item(item)['values']
                            if vals:
                                data.append(vals)
                        break
                if data:
                    break

        if not data:
            messagebox.showerror("Error", "No table data found")
            return

        if export_type == 'print':
            try:
                import tempfile, win32api
                temp_file = os.path.join(tempfile.gettempdir(), f"Monthly_{datetime.now().strftime('%Y%m%d_%H%M%S')}.pdf")
                page_size = landscape(A4)
                doc = SimpleDocTemplate(temp_file, pagesize=page_size, topMargin=15, bottomMargin=15, leftMargin=15, rightMargin=15)
                elements = self._build_pdf_elements("Monthly Salary Report", headers, data, "landscape", page_size)
                doc.build(elements)
                win32api.ShellExecute(0, "print", temp_file, None, ".", 0)
                messagebox.showinfo("Success", "Report sent to printer!")
            except ImportError:
                messagebox.showerror("Error", "win32api not available")
            except Exception as e:
                messagebox.showerror("Error", f"Print error: {str(e)}")
        elif export_type == 'pdf':
            try:
                import subprocess
                timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
                save_path = ask_save_path(f"Monthly_Salary_Report_{timestamp}.pdf", "حفظ التقرير PDF / Save Report")
                if not save_path:
                    return
                page_size = landscape(A4)
                doc = SimpleDocTemplate(save_path, pagesize=page_size, topMargin=15, bottomMargin=15, leftMargin=15, rightMargin=15)
                elements = self._build_pdf_elements("Monthly Salary Report", headers, data, "landscape", page_size)
                doc.build(elements)
                try:
                    subprocess.Popen(f'explorer /select,"{save_path}"', creationflags=0x08000000)
                except Exception:
                    pass
                messagebox.showinfo("Success", f"تم الحفظ / Saved:\n{save_path}")
            except Exception as e:
                messagebox.showerror("Error", f"PDF error: {str(e)}")

    def _build_pdf_elements(self, title, headers, data, orientation, page_size):
        from reportlab.lib import colors
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.platypus import Table, TableStyle, Paragraph, Spacer
        from reportlab.lib.enums import TA_CENTER

        elements, pw = [], page_size[0] - 40
        add_logo_to_pdf(elements)

        header_bg = Table([['']], colWidths=[pw])
        header_bg.setStyle(TableStyle([('BACKGROUND', (0,0), (-1,-1), colors.HexColor('#1E3A8A'))]))
        elements.append(header_bg)

        title_para = Paragraph(f"<b>{title}</b>", ParagraphStyle('Title', fontSize=22, textColor=colors.HexColor('#1E3A8A'), alignment=TA_CENTER, fontName='Helvetica-Bold'))
        title_table = Table([[title_para]], colWidths=[pw])
        title_table.setStyle(TableStyle([('BACKGROUND', (0,0), (-1,-1), colors.white)]))
        elements.append(title_table)

        elements.append(Paragraph(f"Generated: {datetime.now().strftime('%d/%m/%Y %H:%M:%S')}", ParagraphStyle('Subtitle', fontSize=11, textColor=colors.gray, alignment=TA_CENTER)))
        elements.append(Spacer(1, 20))

        elements.append(Paragraph(f"Period: {orientation}", ParagraphStyle('Subtitle', fontSize=10, textColor=colors.HexColor('#3B82F6'), alignment=TA_CENTER)))
        elements.append(Spacer(1, 15))

        _hs4 = ParagraphStyle('_hs4', fontSize=7, leading=9, alignment=TA_CENTER,
                              textColor=colors.white, fontName='Helvetica-Bold', wordWrap='LTR')
        _cs4 = ParagraphStyle('_cs4', fontSize=6, leading=8, alignment=TA_CENTER, wordWrap='LTR')
        def _p4(text, style):
            t = str(text).strip() if text is not None else ' '
            return Paragraph(t if t else ' ', style)

        raw_data = [headers] + data
        nc = len(headers)
        table_data = []
        for ri4, row4 in enumerate(raw_data):
            st4 = _hs4 if ri4 == 0 else _cs4
            table_data.append([_p4(cell, st4) for cell in row4])

        table = Table(table_data, colWidths=[pw/nc]*nc, repeatRows=1)
        ts = TableStyle([
            ('BACKGROUND', (0,0), (-1,0), colors.HexColor('#1E3A8A')),
            ('TEXTCOLOR', (0,0), (-1,0), colors.white),
            ('ALIGN', (0,0), (-1,-1), 'CENTER'),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ('FONTNAME', (0,0), (-1,0), 'Helvetica-Bold'),
            ('FONTSIZE', (0,0), (-1,0), 7),
            ('BOTTOMPADDING', (0,0), (-1,0), 8),
            ('TOPPADDING', (0,0), (-1,0), 8),
            ('FONTNAME', (0,1), (-1,-1), 'Helvetica'),
            ('FONTSIZE', (0,1), (-1,-1), 6),
            ('BOTTOMPADDING', (0,1), (-1,-1), 5),
            ('TOPPADDING', (0,1), (-1,-1), 5),
            ('GRID', (0,0), (-1,-1), 0.5, colors.HexColor('#CBD5E1')),
        ])
        for i in range(2, len(table_data)):
            if i % 2 == 0:
                ts.add('BACKGROUND', (0,i), (-1,i), colors.HexColor('#F8FAFC'))
        table.setStyle(ts)
        elements.append(table)
        elements.append(Spacer(1, 15))

        ft = ParagraphStyle('Footer', fontSize=6, textColor=colors.gray, alignment=TA_CENTER)
        elements.append(Paragraph(f"Total: {len(data)} records | MODO HR", ft))
        return elements

    def export_data(self):
        """تصدير جميع البيانات - user chooses location"""
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        filename = f"HR_Data_Export_{timestamp}.json"
