    def import_data(self):
        """Import Data"""
        import_type = messagebox.askquestion("Import Type",
            "هل تريد استيراد موظفين من Excel؟\n\nاختر 'Yes' لـ Excel\nاختر 'No' لـ JSON")

        if import_type == 'yes':
            self.import_employees_from_excel()
            return

        file_path = filedialog.askopenfilename(
            filetypes=[("JSON files", "*.json"), ("All files", "*.*")],
            title="Import Data"
        )

        if not file_path:
            return

        if messagebox.askyesno("Confirm", "This will replace current data. Continue?"):
            try:
                import shutil
                shutil.copy(file_path, self.db.data_file)
                self.db.load_data()
                messagebox.showinfo("Success", "Done Import Data successfully")
                self.show_home()
            except Exception as e:
                messagebox.showerror("Error", f"حدث Error أثناء Import Data:\n{str(e)}")

    def import_employees_from_excel_simple(self):
        """استيراد Employees من File Excel (simple version)"""
        file_path = filedialog.askopenfilename(
            filetypes=[("Excel files", "*.xlsx *.xls"), ("All files", "*.*")],
            title="اختر File Excel للموظفين"
        )

        if not file_path:
            return

        try:
            from openpyxl import load_workbook

            wb = load_workbook(file_path)
            ws = wb.active

            headers = [cell.value for cell in ws[1]]

            required_cols = ['emp_id', 'name', 'department', 'position', 'salary', 'hire_date']
            col_map = {}
            for col_name in required_cols:
                for i, header in enumerate(headers):
                    if header and col_name.lower() in str(header).lower():
                        col_map[col_name] = i + 1
                        break

            if 'emp_id' not in col_map or 'name' not in col_map:
                messagebox.showerror("Error", "File does not contain emp_id or name columns")
                return

            imported_count = 0
            skipped_count = 0

            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or not row[0]:
                    continue

                emp_id = str(row[col_map['emp_id'] - 1]) if col_map.get('emp_id') else None
                name = str(row[col_map['name'] - 1]) if col_map.get('name') else ""
                department = str(row[col_map['department'] - 1]) if col_map.get('department') else ""
                position = str(row[col_map['position'] - 1]) if col_map.get('position') else ""
                salary = float(row[col_map['salary'] - 1]) if col_map.get('salary') and row[col_map['salary'] - 1] else 0
                hire_date = str(row[col_map['hire_date'] - 1]) if col_map.get('hire_date') else ""

                if not emp_id or not name:
                    skipped_count += 1
                    continue

                dept_id = None
                for d in self.db.departments.values():
                    if d.name == department:
                        dept_id = d.dept_id
                        break
                if not dept_id and department:
                    dept_id = self.db.next_seq_id("D", self.db.departments.values(), "dept_id", 3)
                    new_dept = Department(dept_id, department)
                    self.db.departments[dept_id] = new_dept

                if emp_id in self.db.employees:
                    skipped_count += 1
                    continue

                emp = Employee(emp_id, name, dept_id or "", position, salary, hire_date)
                self.db.employees[emp_id] = emp
                imported_count += 1

            self.db.save_data()
            messagebox.showinfo("Success", f"Imported {imported_count} موظف successfully\nDone تخطي {skipped_count} سجل")
            self.show_employees_page()

        except ImportError:
            messagebox.showerror("Error", "يرجى تثبيت مكتبة openpyxl\npip install openpyxl")
        except Exception as e:
            messagebox.showerror("Error", f"حدث Error أثناء Import Data:\n{str(e)}")

    def import_departments_from_excel(self):
        """استيراد الأقسام من File Excel - Import Departments from Excel"""
        file_path = filedialog.askopenfilename(
            filetypes=[("Excel files", "*.xlsx *.xls"), ("All files", "*.*")],
            title="اختر File Excel للأقسام | Choose Departments Excel File"
        )
        if not file_path:
            return

        try:
            from openpyxl import load_workbook

            wb = load_workbook(file_path)
            ws = wb.active

            headers = [cell.value for cell in ws[1]]

            col_map = {}
            for i, header in enumerate(headers):
                if header:
                    h_lower = str(header).lower().strip()
                if h_lower in ['dept_id', 'department_id', 'department code', 'code']:
                    col_map['dept_id'] = i + 1
                elif h_lower in ['name', 'department', 'department_name', 'department name']:
                    col_map['name'] = i + 1

            if 'name' not in col_map:
                messagebox.showerror("Error", "File does not contain department name column")
                return

            imported_count = 0
            skipped_count = 0

            for row in ws.iter_rows(min_row=2, values_only=True):
                if not row or not row[0]:
                    continue

                dept_id = str(row[col_map['dept_id'] - 1]) if 'dept_id' in col_map and row[col_map['dept_id'] - 1] else ""
                dept_name = str(row[col_map['name'] - 1]) if col_map.get('name') else ""

                if not dept_name:
                    skipped_count += 1
                    continue

                if not dept_id:
                    dept_id = self.db.next_seq_id("D", self.db.departments.values(), "dept_id", 3)

                if dept_id in self.db.departments:
                    skipped_count += 1
                    continue

                dept = Department(dept_id, dept_name)
                self.db.departments[dept_id] = dept
                imported_count += 1

            self.db.save_data()
            messagebox.showinfo("Success", f"Imported {imported_count} قسم successfully\nDone تخطي {skipped_count} سجل")
            self.show_departments_page()

        except ImportError:
            messagebox.showerror("Error", "يرجى تثبيت مكتبة openpyxl\npip install openpyxl")
        except Exception as e:
            messagebox.showerror("Error", f"حدث Error أثناء Import Data:\n{str(e)}")

