    def import_evaluations_from_excel(self):
        """استيراد بيانات الevaluation من File Excel - Import Evaluations from Excel"""
        file_path = filedialog.askopenfilename(
            filetypes=[("Excel files", "*.xlsx *.xls"), ("All files", "*.*")],
            title="اختر File Excel للevaluationات | Choose Evaluations Excel File"
        )
        if not file_path:
            return

        try:
            from openpyxl import load_workbook
        except ImportError:
            messagebox.showerror("Error", "يرجى تثبيت مكتبة openpyxl\npip install openpyxl")
            return

        try:
            wb = load_workbook(file_path)
            ws = wb.active
            headers = [str(cell.value).strip().lower() if cell.value else "" for cell in ws[1]]

            # Map column names to indices (1-based)
            def find_col(*names):
                for name in names:
                    for i, h in enumerate(headers):
                        if name.lower() in h:
                            return i
                return None

            col_empid   = find_col("emp_id", "employee_id", "employee id", "empid", "كود")
            col_date    = find_col("eval_date", "date", "تاريخ")
            col_comments= find_col("comments", "Notes", "notes")
            col_sup_notes = find_col("supervisor", "مشرف", "supervisor_notes")
            col_prob    = find_col("probation")
            col_6m      = find_col("6 month", "6month", "after_6")
            col_1y      = find_col("1 year", "1year", "after_1")

            # Factor score columns - match by factor key or label
            factor_col_map = {}
            for factor in Evaluation.JOB_FACTORS:
                key = factor["key"]
                label = factor["label"].lower()
                c = find_col(key, label)
                if c is not None:
                    factor_col_map[key] = c

            if col_empid is None:
                messagebox.showerror("Error",
                    "لم يDone العثور على عمود emp_id في الFile\n"
                    "Column 'emp_id' not found in file.\n\n"
                    "Required columns:\n"
                    "emp_id, eval_date, [attitude, job_knowledge, quantity_of_work,\n"
                    " quality_of_work, team_work, attendance, hospitality,\n"
                    " appearance, initiative, communication]")
                return

            imported = 0
            skipped  = 0
            errors   = []

            for row_idx, row in enumerate(ws.iter_rows(min_row=2, values_only=True), start=2):
                if not row or row[col_empid] is None:
                    continue

                emp_id = str(row[col_empid]).strip()
                if not self.db.get_employee(emp_id):
                    errors.append(f"Row {row_idx}: Employee '{emp_id}' not found - skipped")
                    skipped += 1
                    continue

                eval_date = str(row[col_date]).strip() if col_date is not None and row[col_date] else date.today().strftime("%d/%m/%Y")
                comments  = str(row[col_comments]).strip() if col_comments is not None and row[col_comments] else ""
                sup_notes = str(row[col_sup_notes]).strip() if col_sup_notes is not None and row[col_sup_notes] else ""
                prob      = bool(row[col_prob]) if col_prob is not None and row[col_prob] else False
                m6        = bool(row[col_6m])   if col_6m  is not None and row[col_6m]   else False
                y1        = bool(row[col_1y])   if col_1y  is not None and row[col_1y]   else True

                scores = {}
                for factor in Evaluation.JOB_FACTORS:
                    key = factor["key"]
                    ci = factor_col_map.get(key)
                    if ci is not None and row[ci] is not None:
                        try:
                            val = int(float(str(row[ci])))
                            scores[key] = max(0, min(5, val))
                        except:
                            scores[key] = 0
                    else:
                        scores[key] = 0

                # Calculate grade from scores
                total = sum(factor["weight"] * scores.get(factor["key"], 0)
                            for factor in Evaluation.JOB_FACTORS)
                pct = (total / Evaluation.TOTAL_MAX) * 100 if Evaluation.TOTAL_MAX > 0 else 0
                if pct >= 90:   grade = "Excellent"
                elif pct >= 75: grade = "Very Good"
                elif pct >= 60: grade = "Good"
                elif pct >= 50: grade = "Acceptable"
                else:           grade = "Poor"

                eval_id = self.db.next_seq_id("E", self.db.evaluations, "eval_id", 3)
                evaluation = Evaluation(eval_id, emp_id, grade, eval_date, comments,
                                        eval_type="level5",
                                        probation_period=prob,
                                        after_6_months=m6,
                                        after_1_year=y1,
                                        supervisor_notes=sup_notes,
                                        scores=scores)
                self.db.evaluations.append(evaluation)
                imported += 1

            self.db.save_data()

            msg = f"✅ Imported {imported} evaluation successfully\nSuccessfully imported {imported} evaluations."
            if skipped:
                msg += f"\n⚠ Done تخطي {skipped} صف (موظف not found)"
            if errors:
                msg += "\n\nتفاصيل:\n" + "\n".join(errors[:5])
                if len(errors) > 5:
                    msg += f"\n... and {len(errors)-5} more"
            messagebox.showinfo("Import Complete", msg)
            self.show_evaluation_page()

        except Exception as e:
            messagebox.showerror("Error", f"حدث Error أثناء Import Data:\n{str(e)}")

